#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PAYLOAD_SEGMENTS 10
#define BUFFER_SIZE_LIMIT 4096

typedef struct {
    int interface_id;
    time_t timestamp;
    struct {
        unsigned char checksum[2];
        int priority;
    } payload[MAX_PAYLOAD_SEGMENTS];
} NICP_Packet;

NICP_Packet* initialize_nicp_packet_array(int num_packets, size_t max_total_size) {
    if (num_packets <= 0 || max_total_size <= 0) return NULL;

    size_t packet_size = sizeof(NICP_Packet);
    size_t total_size = num_packets * packet_size;

    if (total_size > max_total_size) return NULL;

    NICP_Packet* packets = (NICP_Packet*)aligned_alloc(64, total_size);
    if (!packets) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_packets; ++i) {
        packets[i].interface_id = rand();
        packets[i].timestamp = time(NULL);

        for (int j = 0; j < MAX_PAYLOAD_SEGMENTS; ++j) {
            packets[i].payload[j].checksum[0] = rand() % 256;
            packets[i].payload[j].checksum[1] = rand() % 256;
            packets[i].payload[j].priority = rand() % 10;
        }
    }

    return packets;
}

void free_nicp_packet_array(NICP_Packet* packets) {
    if (packets) free(packets);
}
