        if (!records[i]) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        records[i]->value = i * 2; // Example value assignment
    }
}

void free_memory(long *offsets, int *keys, record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
}

int serialize_records(record **records, size_t count, FILE *file) {
    if (!fwrite(&count, sizeof(size_t), 1, file)) return -1;
    for (size_t i = 0; i < count; ++i) {
        if (!fwrite(records[i], sizeof(record), 1, file)) return -1;
    }
    return 0;
}

int deserialize_records(record **records, size_t *count, FILE *file) {
    if (!fread(count, sizeof(size_t), 1, file)) return -1;
    records = realloc(records, *count * sizeof(record *));
    for (size_t i = 0; i < *count; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        if (!fread(records[i], sizeof(record), 1, file)) return -1;
    }
    return 0;
}
