#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

typedef struct ip_node {
    char hostname[256];
    struct sockaddr_in ip;
    struct ip_node *next;
} ip_node_t;

ip_node_t* dns_resolve(const char *hostname, int timeout_ms);
void free_ip_list(ip_node_t **head);

int main() {
    ip_node_t *result = dns_resolve("example.com", 1000);
    if (result) {
        printf("IP Address: %s\n", inet_ntoa(result->ip.sin_addr));
        free_ip_list(&result);
    } else {
        printf("DNS resolution failed.\n");
    }
    return 0;
}

ip_node_t* dns_resolve(const char *hostname, int timeout_ms) {
    struct addrinfo hints, *res, *p;
    ip_node_t *head = NULL, *tail = NULL;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        ip_node_t *new_node = malloc(sizeof(ip_node_t));
        if (!new_node) {
            freeaddrinfo(res);
            fprintf(stderr, "Memory allocation failed.\n");
            return head;
        }
        new_node->next = NULL;
        memcpy(&new_node->ip, p->ai_addr, sizeof(struct sockaddr_in));

        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    freeaddrinfo(res);
    return head;
}

void free_ip_list(ip_node_t **head) {
    ip_node_t *current, *next;
    current = *head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
