#include <stdio.h>
#include <stdlib.h>

#define MAX_INT 2147483647
#define MIN_INT -2147483648

int* read_integers(int *count) {
    int *array = (int*)malloc(10000 * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int num;
    *count = 0;
    while (*count < 10000 && scanf("%d", &num) == 1) {
        if (num < MIN_INT || num > MAX_INT) {
            fprintf(stderr, "Invalid integer: %d\n", num);
            free(array);
            exit(EXIT_FAILURE);
        }
        array[(*count)++] = num;
    }

    return array;
}

int find_largest(int *array, int count) {
    if (count < 10) {
        printf("Too few numbers\n");
        exit(EXIT_SUCCESS);
    }

    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void free_memory(int *array) {
    free(array);
}

int main() {
    int count, *array = read_integers(&count);
    int largest = find_largest(array, count);
    printf("Largest number: %d\n", largest);
    free_memory(array);
    return 0;
}
