#include <stdlib.h>
#include <pthread.h>

#define MAX_LOG_MSG_LEN 2048

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

void log_message(LogLevel level, const char *fmt, ...) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    va_list args;
    FILE *log_file = fopen("error_log.txt", "a");

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    // Lock the mutex before writing to ensure thread safety
    switch (level) {
        case LOG_INFO:
            fprintf(log_file, "[INFO] ");
            break;
        case LOG_WARNING:
            fprintf(log_file, "[WARNING] ");
            break;
        case LOG_ERROR:
            fprintf(log_file, "[ERROR] ");
            break;
    }

    va_start(args, fmt);
    vsnprintf(log_message_buffer, MAX_LOG_MSG_LEN, fmt, args);
    va_end(args);

    fprintf(log_file, "%s\n", log_message_buffer);

    pthread_mutex_unlock(&mutex);
    fclose(log_file);
}

int main() {
    // Example usage
    log_message(LOG_ERROR, "An error occurred: %d", 404);
    return 0;
}
