bool validate_oauth2_token(const char *json_string) {
    struct json_object *parsed_json = json_tokener_parse(json_string);
    if (!parsed_json || !json_object_is_type(parsed_json, json_type_object)) {
        json_object_put(parsed_json);
        return false;
    }

    struct json_object *access_token, *expires_in, *token_type, *refresh_token = NULL;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) &&
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) &&
        json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        if (json_object_is_type(access_token, json_type_string) &&
            json_object_is_type(expires_in, json_type_int) &&
            json_object_is_type(token_type, json_type_string) &&
            strcmp(json_object_get_string(token_type), "Bearer") == 0) {
            int expires_in_value = json_object_get_int(expires_in);
            if (expires_in_value > 0) {
                // Additional processing for cryptographic operations
                json_object_put(parsed_json);
                return true;
            }
        }
    }

    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token)) {
        if (!json_object_is_type(refresh_token, json_type_string)) {
            json_object_put(parsed_json);
            return false;
        }
    }

    json_object_put(parsed_json);
    return false;
}
