import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class ConfigModifier {

    public static void modifyKickstartConfig(HashMap<String, String> placeholders, Pokemon pokemon) throws Exception {
        File kickstartFile = new File("kickstart.cfg");
        if (!kickstartFile.exists()) {
            throw new IOException("Kickstart file does not exist.");
        }

        // Read the original Kickstart configuration
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new FileReader(kickstartFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }

        // Replace placeholders with actual values using sed commands
        for (Map.Entry<String, String> entry : placeholders.entrySet()) {
            ProcessBuilder pb = new ProcessBuilder("sed", "-i", "s/" + entry.getKey() + "/" + entry.getValue() + "/", kickstartFile.getAbsolutePath());
            int exitCode = pb.start().waitFor();
            if (exitCode != 0) {
                throw new Exception("Failed to replace placeholder: " + entry.getKey());
            }
        }

        // Append a new line with an encrypted password
        String encryptedPassword = encryptPassword(pokemon.getPassword());
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(kickstartFile, true))) {
            writer.write(encryptedPassword);
        }

        // Determine Pokemon weaknesses based on type
        switch (pokemon.getType()) {
            case "Fire":
                System.out.println("Weaknesses: Water, Ground, Rock");
                break;
            case "Water":
                System.out.println("Weaknesses: Electric, Grass");
                break;
            case "Grass":
                System.out.println("Weaknesses: Fire, Ice, Flying, Bug, Rock");
                break;
            // Add more cases for other Pokemon types
            default:
                System.out.println("No weaknesses found.");
        }
    }

    private static String encryptPassword(String password) {
        // Implement a simple encryption logic here
        return "ENCRYPTED:" + password.toUpperCase();
    }
}

class Pokemon {
