#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

EVP_CIPHER_CTX* encrypt_file(const char* file_path, const char* command_line_option) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fclose(file);
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    const EVP_CIPHER* cipher = EVP_aes_256_cbc(); // Example cipher
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to initialize cipher\n");
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(key, sizeof(key))) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to generate key\n");
        return NULL;
    }
    if (!RAND_bytes(iv, sizeof(iv))) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to generate IV\n");
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to initialize cipher with key and IV\n");
        return NULL;
    }

    unsigned char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        int len;
        if (!EVP_EncryptUpdate(ctx, NULL, &len, buffer, (int)bytes_read)) {
            fclose(file);
            EVP_CIPHER_CTX_free(ctx);
            fprintf(stderr, "Failed to update cipher with data\n");
            return NULL;
        }
    }

    if (ferror(file)) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Error reading file\n");
        return NULL;
    }

    int len;
    if (!EVP_EncryptFinal_ex(ctx, buffer, &len)) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to finalize cipher\n");
        return NULL;
    }

    fclose(file);

    unsigned char* output = malloc(len + 1);
    memcpy(output, buffer, len);
    output[len] = '\0';

    if (!EVP_EncryptUpdate(ctx, output, &len, NULL, 0)) {
        free(output);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to finalize cipher with padding\n");
        return NULL;
    }

    memcpy(output + len, buffer, len);
    output[len + len] = '\0';

    EVP_CIPHER_CTX_free(ctx);

    return (EVP_CIPHER_CTX*)output; // Cast for demonstration purposes
}
