namespace Logging {
    enum Level { DEBUG, INFO, WARN, ERROR };

    class Logger {
    public:
        static void setLevel(Level level) { currentLevel = level; }
        static void log(Level level, const std::string& message) {
            if (level >= currentLevel) {
                logStream << "[" << getLevelName(level) << "] " << message << "\n";
                logFile << "[" << getLevelName(level) << "] " << message << "\n";
            }
        }

    private:
        Logger() {}
        ~Logger() {}

        static Level currentLevel;
        static std::stringstream logStream;
        static std::ofstream logFile;

        static const char* getLevelName(Level level) {
            switch (level) {
                case DEBUG: return "DEBUG";
                case INFO: return "INFO";
                case WARN: return "WARN";
                case ERROR: return "ERROR";
                default: return "UNKNOWN";
            }
        }

        static void initialize() {
            logFile.open("server.log", std::ios_base::app);
        }
    };

    Level Logger::currentLevel = INFO;
    std::stringstream Logger::logStream;
    std::ofstream Logger::logFile;

    void initLogger() {
        Logger::initialize();
    }

    static Logger loggerInstance; // Ensures the logger is initialized at program start
}

int main() {
    Logging::initLogger();

    Logging::Logger::setLevel(Logging::DEBUG);
    Logging::Logger::log(Logging::DEBUG, "This is a debug message.");
    Logging::Logger::log(Logging::INFO, "This is an info message.");
    Logging::Logger::log(Logging::WARN, "This is a warning message.");
    Logging::Logger::log(Logging::ERROR, "This is an error message.");

    return 0;
}
