using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class HttpClientBatchProcessor
{
    private readonly int _maxConcurrentRequests;
    private readonly TimeSpan _timeout;

    public HttpClientBatchProcessor(int maxConcurrentRequests, TimeSpan timeout)
    {
        _maxConcurrentRequests = maxConcurrentRequests;
        _timeout = timeout;
    }

    public async Task<(List<string> Responses, List<Exception> Errors)> ProcessRequestsAsync(List<string> urls, CancellationToken cancellationToken, HttpClient client)
    {
        var responses = new List<string>();
        var errors = new List<Exception>();

        using (var semaphoreSlim = new SemaphoreSlim(_maxConcurrentRequests))
        {
            var tasks = new List<Task>();

            foreach (var url in urls)
            {
                await semaphoreSlim.WaitAsync(cancellationToken);
                tasks.Add(ProcessRequestAsync(url, cancellationToken, client, semaphoreSlim, responses, errors));
            }

            await Task.WhenAll(tasks);
        }

        return (responses, errors);
    }

    private async Task ProcessRequestAsync(string url, CancellationToken cancellationToken, HttpClient client, SemaphoreSlim semaphoreSlim, List<string> responses, List<Exception> errors)
    {
        try
        {
            using (var request = new HttpRequestMessage(HttpMethod.Get, url))
            {
                var response = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken);
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync(cancellationToken);
                responses.Add(content);
            }
        }
        catch (Exception ex)
        {
            errors.Add(ex);
        }
        finally
        {
            semaphoreSlim.Release();
        }
    }
}
