public class GameConfig
{
    public int TileSize { get; set; } = 32;
    public int WorldWidth { get; set; } = 100;
    public int WorldHeight { get; set; } = 100;
    public float CameraSpeed { get; set; } = 5f;
    public bool EnableFogOfWar { get; set; } = false;
    public bool EnableDynamicLighting { get; set; } = false;
}

public class GameWorld
{
    private GameConfig _config;

    public GameWorld(GameConfig config)
    {
        _config = config;
        InitializeGameWorld();
    }

    private void InitializeGameWorld()
    {
        // Initialize game world based on config settings
        Console.WriteLine($"Tile Size: {_config.TileSize}");
        Console.WriteLine($"World Dimensions: {_config.WorldWidth}x{_config.WorldHeight}");
        Console.WriteLine($"Camera Speed: {_config.CameraSpeed}");
        if (_config.EnableFogOfWar)
        {
            Console.WriteLine("Fog of War Enabled");
        }
        if (_config.EnableDynamicLighting)
        {
            Console.WriteLine("Dynamic Lighting Enabled");
        }
    }
}

public class JsonConfigLoader
{
    public GameConfig LoadConfig(string filePath)
    {
        try
        {
            using (var reader = new System.IO.StreamReader(filePath))
            {
                string json = reader.ReadToEnd();
                return JsonConvert.DeserializeObject<GameConfig>(json);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading config: {ex.Message}");
            return new GameConfig(); // Return default values
        }
    }
}

public class Program
{
    public static void Main()
    {
        JsonConfigLoader loader = new JsonConfigLoader();
        GameConfig config = loader.LoadConfig("config.json");

        GameWorld gameWorld = new GameWorld(config);
    }
}
