using System;
using System.Collections.Generic;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class TemplatesController : ControllerBase
{
    private static readonly Dictionary<string, Template> templates = new Dictionary<string, Template>();

    [HttpPost]
    public IActionResult CreateTemplate([FromBody] Template template)
    {
        if (templates.ContainsKey(template.Id))
        {
            return BadRequest("Template already exists.");
        }

        templates[template.Id] = template;
        return CreatedAtAction(nameof(GetTemplate), new { id = template.Id }, template);
    }

    [HttpPut("{id}")]
    public IActionResult UpdateTemplate(string id, [FromBody] Template updatedTemplate)
    {
        if (!templates.ContainsKey(id))
        {
            return NotFound();
        }

        templates[id] = updatedTemplate;
        return NoContent();
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteTemplate(string id)
    {
        if (!templates.ContainsKey(id))
        {
            return NotFound();
        }

        templates.Remove(id);
        return NoContent();
    }

    [HttpGet]
    public IActionResult GetTemplates(
        string type = null,
        DateTime? creationDateFrom = null,
        DateTime? creationDateTo = null,
        int pageNumber = 1,
        int pageSize = 10,
        string orderBy = "Id",
        bool descending = false)
    {
        var filteredTemplates = templates.Values
            .Where(t => (string.IsNullOrEmpty(type) || t.Type == type) &&
                       (!creationDateFrom.HasValue || t.CreationDate >= creationDateFrom.Value) &&
                       (!creationDateTo.HasValue || t.CreationDate <= creationDateTo.Value))
            .OrderByDescending(t => orderBy, descending)
            .Skip((pageNumber - 1) * pageSize)
            .Take(pageSize);

        return Ok(filteredTemplates);
    }
}

public class Template
{
    public string Id { get; set; }
    public string Type { get; set; }
    public DateTime CreationDate { get; set; }
}
