using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;

public static class XmlParser
{
    public static List<XElement> GetElementsByName(string filePath, string elementName, string namespaceUri = null)
    {
        try
        {
            var settings = new XmlReaderSettings
            {
                CheckCharacters = false,
                IgnoreWhitespace = true,
                IgnoreComments = true,
                DtdProcessing = DtdProcessing.Parse
            };

            using (var reader = XmlReader.Create(filePath, settings))
            {
                var doc = XDocument.Load(reader);
                var query = namespaceUri != null 
                    ? doc.Descendants(XName.Get(elementName, namespaceUri)) 
                    : doc.Descendants(elementName);

                return query.ToList();
            }
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to parse XML file", ex);
        }
    }
}
