<?php
class UserAccountManager {
    private $db;
    private $rateLimiter;

    public function __construct($db, $rateLimiter) {
        $this->db = $db;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleUserRequest() {
        if ($this->rateLimiter->isRateLimited($_SERVER['REMOTE_ADDR'])) {
            return json_encode(['message' => 'error']);
        }

        $data = $_REQUEST;

        if (!isset($data['name']) || !isset($data['email']) || !isset($data['password'])) {
            return json_encode(['message' => 'error']);
        }

        $id = isset($data['id']) ? intval($data['id']) : null;
        $name = htmlspecialchars($data['name']);
        $email = filter_var($data['email'], FILTER_SANITIZE_EMAIL);
        $password = password_hash($data['password'], PASSWORD_DEFAULT);

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return json_encode(['message' => 'error']);
        }

        if ($id) {
            if (isset($data['sub_action']) && $data['sub_action'] === 'delete') {
                // Delete user account
                $stmt = $this->db->prepare("UPDATE users SET is_active = 0 WHERE id = ?");
                $stmt->bind_param("i", $id);
                $stmt->execute();
            } else {
                // Update user account
                $stmt = $this->db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
                $stmt->bind_param("sssi", $name, $email, $password, $id);
                $stmt->execute();
            }
        } else {
            // Create new user account
            $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
            $stmt->bind_param("sss", $name, $email, $password);
            $stmt->execute();
        }

        if ($stmt->affected_rows > 0) {
            $logMessage = "User action: " . ($id ? 'Update' : 'Create') . " | User ID: " . ($id ?? null);
            file_put_contents('user_log.txt', $logMessage . PHP_EOL, FILE_APPEND);

            return json_encode(['message' => 'success']);
        } else {
            return json_encode(['message' => 'error']);
        }
    }
}
?>
