import java.io.*;
import java.nio.file.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class StateLoader {
    private final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private final Properties config = new Properties();
    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);

    public StateLoader(String configFilePath) throws IOException {
        loadConfig(configFilePath);
    }

    private void loadConfig(String filePath) throws IOException {
        try (InputStream input = new FileInputStream(filePath)) {
            config.load(input);
        }
    }

    public MoSTState loadState(String fileName) {
        if (cache.containsKey(fileName)) {
            return cache.get(fileName);
        }

        Path path = Paths.get(config.getProperty("file.path", "default/path"));
        File file = path.toFile();
        try {
            if (!Files.isRegularFile(file) || !Files.exists(path)) {
                logger.warn("File does not exist or is not a regular file: {}", path);
                return null;
            }

            Path tempPath = Files.createTempFile("state", ".tmp");
            try (InputStream in = new FileInputStream(file);
                 OutputStream out = new FileOutputStream(tempPath.toFile())) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = in.read(buffer)) != -1) {
                    out.write(buffer, 0, bytesRead);
                }
            }

            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(tempPath.toFile()))) {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    MoSTState state = (MoSTState) obj;
                    cache.put(fileName, state);
                    logger.info("State loaded successfully from: {}", path);
                    return state;
                } else {
                    logger.warn("Loaded object is not an instance of MoSTState");
                }
            } finally {
                Files.deleteIfExists(tempPath);
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Error loading state file: {}", path, e);
            return null;
        }

        return null;
    }

    public void invalidateCache() {
        cache.clear();
    }
}
```

