["```javascript
const scriptMetadata = [
  { url: 'https://example.com/script1.js', integrity: 'sha256-xyz...', timeout: 5000 },
  { url: 'https://example.com/script2.js', integrity: 'sha256-abc...', timeout: 3000 }
];

const loadedScripts = new Set();

function loadScript(script) {
  return new Promise((resolve, reject) => {
    if (loadedScripts.has(script.url)) {
      resolve();
      return;
    }

    const scriptElement = document.createElement('script');
    scriptElement.src = script.url;
    scriptElement.integrity = script.integrity;
    scriptElement.async = true;

    scriptElement.onload = () => {
      loadedScripts.add(script.url);
      resolve();
    };

    scriptElement.onerror = (error) => {
      reject(new Error(`Failed to load script ${script.url}: ${error}`));
    };

    const timeout = setTimeout(() => {
      document.head.removeChild(scriptElement);
      reject(new Error(`Script ${script.url} timed out after ${script.timeout}ms`));
    }, script.timeout);

    scriptElement.onloadend = () => clearTimeout(timeout);
    document.head.appendChild(scriptElement);
  });
}

function loadScriptsMetadata(metadata) {
  return Promise.all(metadata.map(loadScript));
}

// Usage
loadScriptsMetadata(scriptMetadata)
  .then(() => console.log('All scripts loaded successfully'))
  .catch((error) => console.error(error));
```"]

