class DataHandler {
  constructor() {
    this.data = [];
    this.isPaused = false;
  }

  addData(data) {
    if (!this.isPaused) {
      this.data.push(data);
    }
  }

  pauseStream() {
    this.isPaused = true;
  }

  resumeStream() {
    this.isPaused = false;
  }
}

class GraphManager {
  constructor() {
    this.vertices = [];
    this.edges = [];
  }

  addRandomVertices(count) {
    for (let i = 0; i < count; i++) {
      const vertex = {
        id: Math.random().toString(36).substr(2, 9),
        properties: {}
      };
      for (let j = 0; j < Math.floor(Math.random() * 5); j++) {
        vertex.properties[`prop${j}`] = Math.random();
      }
      this.vertices.push(vertex);
    }
  }

  addRandomEdges(count) {
    for (let i = 0; i < count; i++) {
      const source = this.vertices[Math.floor(Math.random() * this.vertices.length)];
      const target = this.vertices[Math.floor(Math.random() * this.vertices.length)];
      if (source !== target && !this.edges.some(edge => edge.source === source.id && edge.target === target.id)) {
        const edge = {
          id: Math.random().toString(36).substr(2, 9),
          source: source.id,
          target: target.id,
          properties: {}
        };
        for (let j = 0; j < Math.floor(Math.random() * 5); j++) {
          edge.properties[`prop${j}`] = Math.random();
        }
        this.edges.push(edge);
      }
    }
  }

  getGraphData() {
    return { vertices: this.vertices, edges: this.edges };
  }
}

