["```javascript
function copyBytesFromChunks(chunks, startByte, endByte, maxBufferSize = 1024 * 1024, truncateLength = Infinity) {
    let totalBytesToCopy = Math.min(endByte - startByte + 1, truncateLength);
    let copiedData = Buffer.allocUnsafe(totalBytesToCopy);

    let bytesCopied = 0;
    for (let i = 0; i < chunks.length && bytesCopied < totalBytesToCopy; i++) {
        const chunk = chunks[i];
        let startInChunk = Math.max(0, startByte - bytesCopied);
        let endInChunk = Math.min(chunk.length, endByte - bytesCopied + 1);

        if (endInChunk > startInChunk) {
            chunk.copy(copiedData, bytesCopied, startInChunk, endInChunk);
            bytesCopied += endInChunk - startInChunk;
        }
    }

    return copiedData.slice(0, Math.min(bytesCopied, truncateLength));
}

// Example usage:
const chunks = [Buffer.from('Hello'), Buffer.from(' World'), Buffer.from('!')];
const copiedData = copyBytesFromChunks(chunks, 3, 10);
console.log(copiedData.toString()); // Output: 'o Wor'
