['```javascript
function traverseDOM(selector, attributes = {}, maxDepth = Infinity) {
  const report = [];
  let currentDepth = 0;

  function traverse(node) {
    if (currentDepth > maxDepth) return;
    currentDepth++;
    if (node.matches(selector)) {
      const elementInfo = { node, attributes: {} };
      for (const attr in attributes) {
        if (attributes[attr] === node.getAttribute(attr)) {
          elementInfo.attributes[attr] = node.getAttribute(attr);
        }
      }
      report.push(elementInfo);
    }
    for (let i = 0; i < node.children.length; i++) {
      traverse(node.children[i]);
    }
    currentDepth--;
  }

  if (document.body) {
    traverse(document.body);
  }
  return report;
}
