['```php
<?php

function updateUserInfo($userId, $newContactInfo, $lastLoginTimestamp, $lastLoginLocation) {
    // Define API endpoints
    $apiEndpoints = [
        'contact' => 'https://api.example.com/update_contact',
        'login'   => 'https://api.example.com/update_login'
    ];

    $successMessage = [];
    $errorMessage = [];

    foreach ($apiEndpoints as $endpoint => $url) {
        // Simulate rate limiting
        sleep(1);

        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $url);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POST, 1);
            curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
                'user_id' => $userId,
                ($endpoint === 'contact') ? 'new_contact_info' : 'last_login_timestamp',
                ($endpoint === 'contact') ? $newContactInfo : $lastLoginTimestamp
            ]));

            $response = curl_exec($ch);
            if (curl_errno($ch)) {
                throw new Exception(curl_error($ch));
            }

            $responseData = json_decode($response, true);

            if ($responseData['success']) {
                $successMessage[] = "API {$endpoint} for user ID {$userId} was successful.";
            } else {
                $errorMessage[] = "API {$endpoint} for user ID {$userId} failed: " . $responseData['message'];
            }
        } catch (Exception $e) {
            $errorMessage[] = "Error calling API {$endpoint} for user ID {$userId}: " . $e->getMessage();
        }

        curl_close($ch);
    }

    if (!empty($errorMessage)) {
        return json_encode(['success' => false, 'message' => implode(', ', $errorMessage)]);
    } else {
        return json_encode(['success' => true, 'message' => implode(' and ', $successMessage)]);
    }
}

// Example usage:
echo updateUserInfo(123, '{"email":"newemail@example.com"}', time(), 'New York');
?>
