// C# Code for Database Connection and Execution with Retry Logic
using System;
using System.Data.SqlClient;

public class EmployeeFetcher
{
    private readonly string _connectionString;

    public EmployeeFetcher(string connectionString)
    {
        _connectionString = connectionString;
    }

    public void FetchEmployees(int supervisorID, int pageNumber, int pageSize)
    {
        int maxAttempts = 5;
        TimeSpan delay = TimeSpan.FromMilliseconds(100);

        for (int attempt = 1; attempt <= maxAttempts; attempt++)
        {
            try
            {
                using (SqlConnection connection = new SqlConnection(_connectionString))
                {
                    connection.Open();

                    SqlCommand command = new SqlCommand("GetEmployeesBySupervisorID", connection)
                    {
                        CommandType = System.Data.CommandType.StoredProcedure
                    };

                    command.Parameters.AddWithValue("@SupervisorID", supervisorID);
                    command.Parameters.AddWithValue("@PageNumber", pageNumber);
                    command.Parameters.AddWithValue("@PageSize", pageSize);

                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string employeeName = reader.GetString(0);
                            string city = reader.GetString(1);
                            string address = reader.GetString(2);

                            // Process the data
                        }
                    }

                    break; // Success, exit loop
                }
            }
            catch (SqlException ex)
            {
                if (attempt == maxAttempts)
                {
                    throw new Exception("Failed to fetch employees after multiple attempts.", ex);
                }

                System.Threading.Thread.Sleep(delay);
                delay *= 2; // Exponential backoff
            }
        }
    }
}
