<?php

class SecurityUtils {
    private $charset;
    private $hashAlgorithm;

    public function __construct($charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $hashAlgorithm = 'sha256') {
        $this->charset = $charset;
        $this->hashAlgorithm = $hashAlgorithm;
    }

    public function generateRandomString($length) {
        $randomString = '';
        $maxIndex = strlen($this->charset) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charset[random_int(0, $maxIndex)];
        }

        return $randomString;
    }

    public function validateString($string, $pattern) {
        return preg_match($pattern, $string) === 1;
    }

    public function hashPassword($password) {
        return password_hash($password, constant('PASSWORD_' . strtoupper($this->hashAlgorithm)));
    }
}

// Example usage:
$securityUtils = new SecurityUtils();
$password = $securityUtils->generateRandomString(12);
echo "Generated Password: " . $password . "\n";

$hashedPassword = $securityUtils->hashPassword($password);
echo "Hashed Password: " . $hashedPassword . "\n";

$isValid = $securityUtils->validateString($password, '/^[a-zA-Z0-9]{12}$/');
