<?php

class SessionManager {
    private $cache;
    private $rateLimiter;
    private $userService;

    public function __construct(CacheInterface $cache, RateLimiterInterface $rateLimiter, UserServiceInterface $userService) {
        $this->cache = $cache;
        $this->rateLimiter = $rateLimiter;
        $this->userService = $userService;
    }

    public function getUserPreferences($userId): array {
        $key = "user:preferences:$userId";
        if ($this->cache->has($key)) {
            return $this->cache->get($key);
        }

        if ($this->rateLimiter->isRateLimited($userId, 'fetch_preferences')) {
            throw new Exception('Too many requests');
        }

        $preferences = $this->userService->fetchUserPreferencesAsync($userId);

        $this->cache->set($key, $preferences, 3600); // Cache for 1 hour
        return $preferences;
    }

    public function updateUserPreferences($userId, array $newPreferences): void {
        if (isset($newPreferences['email']) || isset($newPreferences['password'])) {
            $this->invalidateSession($userId);
        }

        $this->userService->updateUserPreferencesAsync($userId, $newPreferences);
    }

    private function invalidateSession($userId): void {
        $key = "user:preferences:$userId";
        if ($this->cache->has($key)) {
            $this->cache->delete($key);
        }
    }
}

interface CacheInterface {
    public function has($key): bool;
    public function get($key): array;
    public function set($key, array $value, int $ttl): void;
    public function delete($key): void;
}

interface RateLimiterInterface {
    public function isRateLimited($userId, string $action): bool;
}

interface UserServiceInterface {
    public function fetchUserPreferencesAsync($userId): array;
    public function updateUserPreferencesAsync($userId, array $newPreferences): void;
}
