import json
from datetime import datetime, timezone
import logging

# Setup basic configuration for logging
logging.basicConfig(level=logging.ERROR, filename='log_processor_errors.log')

def process_log_file(file_path):
    try:
        with open(file_path, 'r') as file:
            logs = [json.loads(line) for line in file]
    except FileNotFoundError:
        logging.error(f"File not found: {file_path}")
        return None
    except json.JSONDecodeError:
        logging.error("Invalid JSON format in log file")
        return None

    # Sort logs by timestamp, handling missing timezone information
    try:
        logs.sort(key=lambda x: datetime.fromisoformat(x['timestamp']).replace(tzinfo=timezone.utc))
    except (KeyError, ValueError) as e:
        logging.error(f"Error processing timestamp: {e}")
        return None

    if not logs:
        return 0

    # Extract sequence number from the last valid log entry
    try:
        last_entry = logs[-1]
        sequence_number = last_entry['sequence_number']
    except (KeyError, TypeError):
        logging.error("Malformed or incomplete log entry")
        return None

    return int(sequence_number)
