['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 100
#define WINDOW_SIZE 5

typedef struct Transaction {
    int id;
    time_t timestamp;
    double value;
    struct Transaction* next;
} Transaction;

typedef struct HashTable {
    Transaction* buckets[256];
} HashTable;

Transaction* create_transaction(int id, time_t timestamp, double value) {
    Transaction* new_transaction = (Transaction*)malloc(sizeof(Transaction));
    new_transaction->id = id;
    new_transaction->timestamp = timestamp;
    new_transaction->value = value;
    new_transaction->next = NULL;
    return new_transaction;
}

unsigned int hash_function(int id) {
    return id % 256;
}

void insert_transaction(HashTable* table, Transaction* transaction) {
    unsigned int index = hash_function(transaction->id);
    transaction->next = table->buckets[index];
    table->buckets[index] = transaction;
}

Transaction* find_transaction(HashTable* table, int id) {
    unsigned int index = hash_function(id);
    Transaction* current = table->buckets[index];
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_transaction(HashTable* table, int id) {
    unsigned int index = hash_function(id);
    Transaction* current = table->buckets[index];
    Transaction* previous = NULL;
    while (current != NULL) {
        if (current->id == id) {
            if (previous == NULL) {
                table->buckets[index] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

int process_transaction(HashTable* table, int id, time_t timestamp, double value) {
    if (find_transaction(table, id) != NULL) {
        return -1; // Duplicate transaction
    }

    Transaction* new_transaction = create_transaction(id, timestamp, value);
    insert_transaction(table, new_transaction);

    time_t current_time = time(NULL);
    for (int i = 0; i < 256; i++) {
        Transaction* current = table->buckets[i];
        while (current != NULL) {
            if (current->timestamp + WINDOW_SIZE <= current_time) {
                remove_transaction(table, current->id);
            } else {
                break;
            }
            current = current->next;
        }
    }

    double max_sum = -1;
    int max_id = -1;

    for (int i = 0; i < 256; i++) {
        Transaction* current = table->buckets[i];
        while (current != NULL) {
            double sum = 0;
            int min_id = INT_MAX;
            while (current != NULL && current->timestamp + WINDOW_SIZE > current_time) {
                if (current->value > sum || (current->value == sum && current->id < min_id)) {
                    sum = current->value;
                    min_id = current->id;
                }
                current = current->next;
            }
            if (sum > max_sum) {
                max_sum = sum;
                max_id = min_id;
            } else if (sum == max_sum && min_id < max_id) {
                max_id = min_id;
            }
        }
    }

    return max_id;
}
