using StrategySelector = int(*)(GameContext*);

// Define the GameContext structure
struct GameContext {
    std::vector<int> recentAttacks;
    std::mutex mutex;
    int lastSelectedStrategyIndex;

    GameContext() : lastSelectedStrategyIndex(-1) {}
};

// Function to select combat strategy with cooldown
int SelectCombatStrategy(GameContext* context, StrategySelector selector) {
    static const auto cooldownTime = std::chrono::seconds(9);
    auto now = std::chrono::system_clock::now();

    // Lock the mutex to ensure thread safety
    std::lock_guard<std::mutex> lock(context->mutex);

    int newStrategyIndex = -1;
    if (context->lastSelectedStrategyIndex == -1 || now - context->recentAttacks.back() > cooldownTime) {
        newStrategyIndex = selector(context);
        context->recentAttacks.push_back(now.time_since_epoch().count());
        context->lastSelectedStrategyIndex = newStrategyIndex;
    } else {
        // Reuse the last strategy if not enough time has passed
        newStrategyIndex = context->lastSelectedStrategyIndex;
    }

    std::cout << "Selected Strategy Index: " << newStrategyIndex << std::endl;

    return newStrategyIndex;
}

