using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    public int GetMinValue()
    {
        return _minValue;
    }

    public int GetMaxValue()
    {
        return _maxValue;
    }

    public double GenerateRandomDouble(bool inclusive = true)
    {
        if (inclusive)
            return _random.NextDouble() * (_maxValue - _minValue + 1) + _minValue;
        else
            return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        if (inclusive)
            return _random.Next(_minValue, _maxValue + 1);
        else
            return _random.Next(_minValue, _maxValue);
    }

    public List<int> GenerateUniqueRandomInts(int n)
    {
        if (n < 0 || n > (_maxValue - _minValue + 1))
            throw new ArgumentException("Number of unique integers requested exceeds the range size.");

        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < n)
        {
            uniqueNumbers.Add(GenerateRandomInt(true));
        }

        return new List<int>(uniqueNumbers);
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
