async function asyncReduce(arr, initialAccumulator, reducerCallback) {
    let accumulator = initialAccumulator;

    for (const item of arr) {
        try {
            const additionalMetadata = await fetchAdditionalMetadata(item);
            accumulator = reducerCallback(accumulator, item, additionalMetadata);
        } catch (error) {
            console.error(`Error processing item ${item}:`, error);
            // Handle the error, e.g., skip this item or use a default value
        }
    }

    return accumulator;
}

async function fetchAdditionalMetadata(item) {
    try {
        const response = await fetch(`/api/metadata/${item}`);
        if (!response.ok) {
            throw new Error(`Failed to fetch metadata for item ${item}`);
        }
        return response.json();
    } catch (error) {
        console.error('Failed to fetch additional metadata:', error);
        // Handle the error, e.g., return a default value or rethrow
        throw error;
    }
}

// Example usage:
(async () => {
    const numbers = [10, 20, 30];
    const initialAccumulator = 0;
    const reducerCallback = (acc, item, metadata) => acc + item * metadata.rate;

    try {
        const result = await asyncReduce(numbers, initialAccumulator, reducerCallback);
        console.log('Final accumulator value:', result);
    } catch (error) {
        console.error('Error during reduction:', error);
    }
})();
```

