// Function to safely append a string with a slash or an error message
char* safeAppendOrError(const char* input, size_t maxSize, char** errorMessage) {
    // Check if the input exceeds the maximum allowed size
    if (strlen(input) >= maxSize - 1) {
        // Allocate memory for the error message
        *errorMessage = (char*)malloc(50); // Assume an error message up to 50 characters long
        if (*errorMessage == NULL) {
            return NULL; // Handle memory allocation failure
        }
        strcpy(*errorMessage, "Error: String too large"); // Copy error message to buffer
        return NULL; // Return NULL indicating overflow condition
    }

    // Allocate enough memory for the modified string plus a slash and null terminator
    char* result = (char*)malloc(strlen(input) + 2); // +1 for '/' and +1 for '\0'
    if (result == NULL) {
        return NULL; // Handle memory allocation failure
    }

    strcpy(result, input); // Copy the original string to the new buffer
    strncat(result, "/", 1); // Append a slash

    return result; // Return pointer to the modified string
}

int main() {
    const char* testString = "HelloWorld";
    size_t maxSize = 20;
    char* errorMessage = NULL;

    // Test with safe input
    char* result = safeAppendOrError(testString, maxSize, &errorMessage);
    if (result != NULL) {
        printf("Modified string: %s\n", result);
        free(result); // Free allocated memory
    } else {
        printf("Error message: %s\n", errorMessage);
        free(errorMessage); // Free error message buffer
    }

    // Test with unsafe input (string too long)
    testString = "ThisIsAReallyLongStringThatExceedsTheMaxSize";
    result = safeAppendOrError(testString, maxSize, &errorMessage);
    if (result != NULL) {
        printf("Modified string: %s\n", result);
        free(result); // Free allocated memory
    } else {
        printf("Error message: %s\n", errorMessage);
        free(errorMessage); // Free error message buffer
    }

    return 0;
}
