#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char *line;
    int num_fields;
    pthread_mutex_t lock;
} LineData;

void* process_line(void* arg) {
    LineData *data = (LineData*)arg;
    pthread_mutex_lock(&data->lock);

    // Process the line here
    printf("Processing line: %s", data->line);

    pthread_mutex_unlock(&data->lock);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2] ...\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    LineData data[argc - 1];

    for (int i = 1; i < argc; i++) {
        FILE *file = fopen(argv[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        char line[MAX_LINE_LENGTH];
        while (fgets(line, sizeof(line), file)) {
            data[i - 1].line = strdup(line);
            pthread_mutex_init(&data[i - 1].lock, NULL);

            if (pthread_create(&threads[i - 1], NULL, process_line, &data[i - 1]) != 0) {
                perror("Failed to create thread");
                free(data[i - 1].line);
            }
        }

        fclose(file);
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
        free(data[i].line);
        pthread_mutex_destroy(&data[i].lock);
    }

    return 0;
}
