    int samples_per_pixel;
    int extra_samples_count;
} ImageInfo;

EVP_CIPHER_CTX* parse_tiff_and_crypt(const char* filename, const char* option) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return NULL;
    }

    ImageInfo info;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bits_per_sample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.samples_per_pixel);

    switch (info.bits_per_sample) {
        case 1:
        case 2:
        case 4:
        case 8:
        case 16:
            break;
        default:
            fprintf(stderr, "Unsupported bits per sample: %d\n", info.bits_per_sample);
            TIFFClose(tif);
            return NULL;
    }

    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &info.extra_samples_count);

    EVP_CIPHER_CTX* ctx = NULL;
    if (strcmp(option, "encrypt") == 0) {
        const EVP_CIPHER* cipher = EVP_aes_256_cbc();
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx || !EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
            fprintf(stderr, "Failed to initialize encryption context\n");
            goto cleanup;
        }
    } else if (strcmp(option, "decrypt") == 0) {
        const EVP_CIPHER* cipher = EVP_aes_256_cbc();
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx || !EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv)) {
            fprintf(stderr, "Failed to initialize decryption context\n");
            goto cleanup;
        }
    } else {
        fprintf(stderr, "Unsupported option: %s\n", option);
        goto cleanup;
    }

cleanup:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    TIFFClose(tif);
    return ctx;
}
