char* generateNewFilename(const char* filename, const char* fileType) {
    static char newFilename[256];
    int digitCount = 0;
    int i;

    if (filename == NULL || *filename == '\0') {
        strcpy(newFilename, "default.txt");
        return newFilename;
    }

    // Count the number of alphabetic characters
    for (i = 0; filename[i] != '\0' && digitCount < 128; i++) {
        if (isalpha(filename[i])) {
            digitCount++;
        }
    }

    // Replace invalid characters with underscores
    char tempFilename[256];
    int j;
    for (i = 0, j = 0; filename[i] != '\0' && j < 128; i++) {
        if (isalpha(filename[i]) || isdigit(filename[i])) {
            tempFilename[j++] = filename[i];
        } else {
            tempFilename[j++] = '_';
        }
    }
    tempFilename[j] = '\0';

    // Generate a random number
    srand(time(NULL));
    int randomNumber = rand() % 1000;

    // Construct the new filename
    sprintf(newFilename, "%s%d.%s", tempFilename, digitCount, fileType);

    // Ensure the filename does not exceed the maximum length
    if (strlen(newFilename) > 254) {
        newFilename[254] = '\0';
    }

    return newFilename;
}
