#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[16];
    unsigned char salt[16];
} AESCipher;

AESCipher* aes_init(const char *password) {
    AESCipher *cipher = malloc(sizeof(AESCipher));
    if (!cipher) {
        fprintf(stderr, "Failed to allocate memory for cipher context.\n");
        return NULL;
    }

    // Generate a secure IV
    if (RAND_bytes(cipher->iv, sizeof(cipher->iv)) != 1) {
        fprintf(stderr, "Failed to generate random IV.\n");
        free(cipher);
        return NULL;
    }

    // Derive the encryption key from the password
    unsigned char derived_key[32];
    if (PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, 10000, sizeof(derived_key), derived_key) != 1) {
        fprintf(stderr, "Failed to derive key from password.\n");
        free(cipher);
        return NULL;
    }

    // Initialize the cipher context
    if (!(cipher->ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Failed to create new cipher context.\n");
        free(cipher);
        return NULL;
    }

    // Set up the AES-256-CBC cipher with the derived key and IV
    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, derived_key, cipher->iv) != 1) {
        fprintf(stderr, "Failed to initialize AES-256-CBC cipher.\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    memcpy(cipher->salt, derived_key + 32 - sizeof(cipher->salt), sizeof(cipher->salt));

    return cipher;
}

void aes_cleanup(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}
