['```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

int run_command_background(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process
        int fd_null = open("/dev/null", O_RDWR);
        dup2(fd_null, STDIN_FILENO);
        dup2(fd_null, STDOUT_FILENO);
        dup2(fd_null, STDERR_FILENO);
        close(fd_null);

        struct sigaction sa;
        sa.sa_handler = SIG_DFL;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;

        if (sigaction(SIGCHLD, &sa, NULL) == -1) {
            perror("Failed to set signal handler");
            exit(EXIT_FAILURE);
        }

        int status = system(command);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    } else {
        // Parent process
        return 1;
    }
}
```
This code defines a function `run_command_background` that takes a command string as input and runs it in the background using `fork`. The child process redirects its standard file descriptors to `/dev/null` to avoid inheriting the parent's file descriptors. It also sets up a default signal handler for `SIGCHLD` to prevent the parent from blocking due to zombie processes. If the fork or system call fails, the function returns 0; otherwise, it returns 1 if the command was executed successfully.']

