                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        decryptedMessage = srDecrypt.ReadToEnd();
                    }
                }
            }

            string processedContent = ProcessFile(filePath, decryptedMessage);
            return processedContent;
