using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class StringBatchProcessor
{
    private readonly ConcurrentQueue<string> _inputQueue = new ConcurrentQueue<string>();
    private readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();
    private readonly object _lock = new object();

    public async Task StartProcessingAsync(int batchSize)
    {
        var tasks = new Task[batchSize];
        for (int i = 0; i < batchSize; i++)
        {
            tasks[i] = ProcessBatchAsync();
        }
        await Task.WhenAll(tasks);
    }

    private async Task ProcessBatchAsync()
    {
        while (!_inputQueue.IsEmpty)
        {
            if (_inputQueue.TryDequeue(out string input))
            {
                try
                {
                    string hash = CalculateMd5Hash(input);
                    _hashCache.TryAdd(input, hash);
                }
                catch (Exception ex)
                {
                    // Handle error and retry logic here
                }
            }
        }
    }

    private string CalculateMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            foreach (byte b in hashBytes)
            {
                sb.Append(b.ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public void EnqueueString(string input)
    {
        _inputQueue.Enqueue(input);
    }

    public string GetHash(string input)
    {
        if (_hashCache.TryGetValue(input, out string hash))
        {
            return hash;
        }
        return null;
    }
}

// Usage example:
public class Program
{
    public static async Task Main()
    {
        StringBatchProcessor processor = new StringBatchProcessor();
        // Enqueue strings for processing
        for (int i = 0; i < 1_000_000; i++)
        {
            processor.EnqueueString($"String{i}");
        }

        await processor.StartProcessingAsync(10);

        // Retrieve and print hashes
        for (int i = 0; i < 1_000_000; i++)
        {
            string hash = processor.GetHash($"String{i}");
            Console.WriteLine($"{i}: {hash}");
        }
    }
}
