using System;
using System.IO;
using System.Security.Cryptography;

public class AesCbcDecryption
{
    public static byte[][] DecryptMultiple(byte[] key, byte[] iv, byte[][] ciphertexts)
    {
        var plaintexts = new byte[ciphertexts.Length][];

        for (int i = 0; i < ciphertexts.Length; i++)
        {
            try
            {
                plaintexts[i] = Decrypt(key, iv, ciphertexts[i]);
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }

        return plaintexts;
    }

    private static byte[] Decrypt(byte[] key, byte[] iv, byte[] ciphertext)
    {
        if (!ValidateKeyAndIVLength(key.Length, iv.Length))
        {
            throw new ArgumentException("Invalid key or IV length.");
        }

        if (ciphertext.Length < 16)
        {
            throw new ArgumentException("Ciphertext must be at least 16 bytes long.");
        }

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        csDecrypt.CopyTo(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private static bool ValidateKeyAndIVLength(int keyLength, int ivLength)
    {
        switch (keyLength)
        {
            case 16:
            case 24:
            case 32:
                return ivLength == 16;
            default:
                return false;
        }
    }

    private static void LogError(Exception ex)
    {
        // Custom error logging logic here
        Console.WriteLine($"Error: {ex.Message}");
    }
}
