import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.regex.Pattern;

public class FilenameUtils {
    public static String deserializeAndRenameFile(byte[] serializedData, String newFileType) {
        if (serializedData == null || serializedData.length == 0) {
            return "default.txt";
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(serializedData))) {
            Object obj = ois.readObject();
            Class<?> clazz = obj.getClass();

            // Assuming the object has a method getMetadata() that returns the metadata as a string
            String metadata = (String) clazz.getMethod("getMetadata").invoke(obj);
            int alphabeticCount = metadata.chars()
                                           .filter(Character::isLetter)
                                           .count();

            String originalFilename = clazz.getSimpleName() + ".txt"; // Simplified for example
            if (originalFilename.isEmpty()) {
                return "default.txt";
            }

            String invalidCharsPattern = "[\\\\/:*?\"<>|]";
            String cleanFilename = originalFilename.replaceAll(invalidCharsPattern, "_");
            int newMaxLength = 255 - Integer.toString(alphabeticCount).length() - newFileType.length();
            if (cleanFilename.length() > newMaxLength) {
                cleanFilename = cleanFilename.substring(0, newMaxLength);
            }

            return cleanFilename + "_" + alphabeticCount + "." + newFileType;
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize and rename file: " + e.getMessage(), e);
        }
    }
}
