const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function validateFileTypeAndSize(filePath) {
  const fileType = path.extname(filePath).toLowerCase();
  const fileSize = fs.statSync(filePath).size;

  // Add your file type and size validation logic here
  if (fileType !== '.jpg' && fileType !== '.png') throw new Error('Invalid file type');
  if (fileSize > 5 * 1024 * 1024) throw new Error('File size exceeds limit');
}

async function uploadToCloudStorage(filePath, cloudUrl) {
  // Replace with your actual cloud storage upload logic using a library like AWS SDK
  try {
    const response = await axios.post(cloudUrl, fs.createReadStream(filePath), {
      headers: { 'Content-Type': 'image/jpeg' } // Adjust the content type as needed
    });
    return response.data.url;
  } catch (error) {
    throw new Error(`Upload failed: ${error.message}`);
  }
}

async function uploadFilesConcurrently(filePaths, cloudUrl, maxRetries = 3) {
  const results = [];

  for (const filePath of filePaths) {
    let attempt = 0;
    while (attempt <= maxRetries) {
      try {
        await validateFileTypeAndSize(filePath);
        const uploadedUrl = await uploadToCloudStorage(filePath, cloudUrl);
        results.push(uploadedUrl);
        break; // Success, exit the loop
      } catch (error) {
        if (attempt === maxRetries) {
          console.error(`Failed to upload ${filePath}: ${error.message}`);
        }
        attempt++;
      }
    }
  }

  return results;
}

// Example usage:
const files = ['path/to/image1.jpg', 'path/to/image2.png'];
const cloudUrl = 'https://your-cloud-storage-endpoint.com/upload';
uploadFilesConcurrently(files, cloudUrl)
  .then(urls => console.log('Successfully uploaded:', urls))
  .catch(error => console.error('Error uploading files:', error));
