const { exec } = require('child_process');
const crypto = require('crypto');

function addRandomVerticesAndEdges(databasePath) {
  const randomNumber = Math.floor(Math.random() * 10) + 1;
  let verticesQuery = '';
  let edgesQuery = '';

  for (let i = 0; i < randomNumber; i++) {
    const vertexId = crypto.randomUUID();
    verticesQuery += `CREATE VERTEX Vertex SET name = 'Vertex${i}', id = '${vertexId}';\n`;

    const edgeId = crypto.randomUUID();
    const sourceVertexId = crypto.randomUUID();
    const targetVertexId = crypto.randomUUID();
    edgesQuery += `CREATE EDGE Edge SET id = '${edgeId}', source = '${sourceVertexId}', target = '${targetVertexId}';\n`;
  }

  const query = verticesQuery + edgesQuery;

  exec(`bolt --url bolt://localhost:7687 --user username --password password --database ${databasePath} run "${query}"`, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command: ${error.message}`);
      return;
    }
    if (stderr) {
      console.error(`Stderr: ${stderr}`);
      return;
    }
    console.log(`Successfully added ${randomNumber} vertices and edges to the graph.`);
  });
}

// Example usage:
addRandomVerticesAndEdges('myDatabase');
