use std::env;
use std::fs::{create_dir, create_dir_all};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

lazy_static! {
    static ref ENV_DIR_MUTEX: Mutex<()> = Mutex::new(());
}

fn manage_directory(dir_name: &str) -> Result<PathBuf, String> {
    let mut env_mutex = ENV_DIR_MUTEX.lock().unwrap();
    if let Ok(path) = env::var_os(dir_name) {
        return Ok(PathBuf::from(&path));
    }

    let parent_dir = env::temp_dir();
    let dir_path = parent_dir.join(dir_name);

    // Ensure the directory does not already exist
    if dir_path.exists() {
        return Err(format!("Directory {} already exists", dir_path.display()));
    }

    match create_dir_all(&dir_path) {
        Ok(_) => {
            env::set_var(dir_name, &dir_path);
            Ok(dir_path)
        }
        Err(e) => Err(format!("Failed to create directory: {}", e)),
    }
}

fn main() {
    // Example usage
    if let Ok(path) = manage_directory("my_directory") {
        println!("Directory path: {:?}", path);
    } else {
        println!("Failed to manage directory");
    }
}
```

