import json
from functools import lru_cache
from typing import Any, Callable, Dict, TypeVar

T = TypeVar('T')

class DataModelRegistry:
    _registry: Dict[str, Callable[[Dict], T]] = {}

    @classmethod
    def register(cls, identifier: str, factory: Callable[[Dict], T]):
        cls._registry[identifier] = factory

    @classmethod
    def get_factory(cls, identifier: str) -> Callable[[Dict], T]:
        return cls._registry.get(identifier)

class DataModel:
    def __init__(self, data: Dict):
        self.data = data

    def to_json(self) -> str:
        return json.dumps(self.data)

    @classmethod
    def from_json(cls, json_str: str) -> 'DataModel':
        data = json.loads(json_str)
        return cls(data)

class CategoryManager:
    _category_cache: Dict[str, Dict] = {}

    @staticmethod
    @lru_cache(maxsize=None)
    def get_category_data(category: str) -> Dict:
        # Simulate fetching category data from an external source
        if category not in CategoryManager._category_cache:
            CategoryManager._category_cache[category] = {}
        return CategoryManager._category_cache[category]

class DataManager:
    _data_cache: Dict[str, DataModel] = {}

    @staticmethod
    def register_data_model(identifier: str, factory: Callable[[Dict], T]):
        DataModelRegistry.register(identifier, factory)

    @staticmethod
    def instantiate_data_model(identifier: str, data: Dict) -> Any:
        factory = DataModelRegistry.get_factory(identifier)
        if not factory:
            raise ValueError(f"Factory for {identifier} not found")
        return factory(data)

    @staticmethod
    def get_cached_data_model(key: str) -> Any:
        return DataManager._data_cache.get(key, None)

    @staticmethod
    def set_cached_data_model(key: str, data_model: DataModel):
        DataManager._data_cache[key] = data_model

# Example usage
class User(DataModel):
    pass

DataManager.register_data_model('user', lambda d: User(d))

new_user_json = '{"name": "John", "age": 30}'
new_user = DataManager.instantiate_data_model('user', json.loads(new_user_json))
print(new_user.to_json())

# Simulate caching
cached_user = DataManager.get_cached_data_model('user_123')
if not cached_user:
    user_data = {'name': 'John', 'age': 30}
    new_user = DataManager.instantiate_data_model('user', user_data)
    DataManager.set_cached_data_model('user_123', new_user)

# Simulate updating the registry
def Admin(data: Dict) -> DataModel:
    return DataModel(data)

DataManager.register_data_model('admin', lambda d: Admin(d))
