        json_object_object_get_ex(parsed_json, "maximum_connections", &max_conn_obj)) {

        int port = json_object_get_int(port_obj);
        const char *listen_address = json_object_get_string(listen_addr_obj);
        int max_connections = json_object_get_int(max_conn_obj);

        if (port > 0 && strlen(listen_address) > 0 && max_connections > 0) {
