    private readonly ITemplateService _templateService;

    public TemplateController(ITemplateService templateService)
    {
        _templateService = templateService;
    }

    [HttpPost]
    public async Task<IActionResult> CreateTemplate([FromBody] TemplateDto template)
    {
        var result = await _templateService.CreateTemplate(template);
        if (result.IsSuccessful)
        {
            return CreatedAtAction(nameof(GetTemplate), new { id = result.Template.Id }, result.Template);
        }
        return BadRequest(result.ErrorMessage);
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateTemplate(int id, [FromBody] TemplateDto template)
    {
        var result = await _templateService.UpdateTemplate(id, template);
        if (result.IsSuccessful)
        {
            return NoContent();
        }
        return NotFound(result.ErrorMessage);
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteTemplate(int id)
    {
        var result = await _templateService.DeleteTemplate(id);
        if (result.IsSuccessful)
        {
            return NoContent();
        }
        return NotFound(result.ErrorMessage);
    }

    [HttpGet]
    public async Task<IActionResult> GetTemplates(
        [FromQuery] string type = null,
        [FromQuery] DateTime? startDate = null,
        [FromQuery] DateTime? endDate = null,
        [FromQuery] int pageNumber = 1,
        [FromQuery] int pageSize = 10,
        [FromQuery] string sortBy = "createdAt",
        [FromQuery] bool isDescending = false)
    {
        var result = await _templateService.GetTemplates(type, startDate, endDate, pageNumber, pageSize, sortBy, isDescending);
        if (result.IsSuccessful)
        {
            return Ok(result.Templates);
        }
        return BadRequest(result.ErrorMessage);
    }
}

