{
    Task<ServiceResult<Template>> CreateTemplate(TemplateDto template);
    Task<ServiceResult> UpdateTemplate(int id, TemplateDto template);
    Task<ServiceResult> DeleteTemplate(int id);
    Task<ServiceResult<IEnumerable<Template>>> GetTemplates(string type, DateTime? startDate, DateTime? endDate, int pageNumber, int pageSize, string sortBy, bool isDescending);
}

public class ServiceResult
{
    public bool IsSuccessful { get; set; }
    public string ErrorMessage { get; set; }
    public object Data { get; set; }

    public static ServiceResult Success(object data = null)
    {
        return new ServiceResult { IsSuccessful = true, Data = data };
