import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

public class StringHashProcessor {

    private static final Logger LOGGER = Logger.getLogger(StringHashProcessor.class.getName());
    private static final int MAX_RETRIES = 3;

    public static void processBatch(String[] strings) {
        Set<String> uniqueHashes = new HashSet<>();
        for (String input : strings) {
            try {
                String hash = generateMd5Hash(input);
                if (!uniqueHashes.add(hash)) {
                    boolean retrySuccessful = false;
                    for (int attempt = 1; !retrySuccessful && attempt <= MAX_RETRIES; attempt++) {
                        LOGGER.info("Duplicate hash detected. Retrying... Attempt " + attempt);
                        String newHash = generateMd5Hash(input);
                        if (!uniqueHashes.add(newHash)) {
                            LOGGER.severe("Failed to obtain unique hash after " + MAX_RETRIES + " attempts.");
                        } else {
                            retrySuccessful = true;
                            LOGGER.info("Successfully generated unique hash: " + newHash);
                            break;
                        }
                    }
                } else {
                    LOGGER.info("Unique hash generated: " + hash);
                }
            } catch (Exception e) {
                LOGGER.severe("Error processing string: " + input + ". Error message: " + e.getMessage());
            }
        }
        LOGGER.info("Total unique hashes encountered: " + uniqueHashes.size());
    }

    private static String generateMd5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String[] testStrings = {"test", "example", "test", "anotherTest"};
        processBatch(testStrings);
    }
}
