#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void log_error(const char *message) {
    FILE *log_file = fopen("crypto_library.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int load_cryptographic_primitives(char **algorithms, int num_algorithms) {
    EVP_CIPHER *cipher;
    EVP_MD *digest;
    for (int i = 0; i < num_algorithms; i++) {
        if (strncmp(algorithms[i], "aes-", 4) == 0) {
            int key_length = atoi(&algorithms[i][4]);
            switch (key_length) {
                case 128:
                    cipher = EVP_aes_128_cbc();
                    break;
                case 192:
                    cipher = EVP_aes_192_cbc();
                    break;
                case 256:
                    cipher = EVP_aes_256_cbc();
                    break;
                default:
                    log_error("Unsupported AES key length");
                    return -1;
            }
        } else if (strncmp(algorithms[i], "camellia-", 9) == 0) {
            int key_length = atoi(&algorithms[i][9]);
            switch (key_length) {
                case 128:
                    cipher = EVP_camellia_128_cbc();
                    break;
                case 192:
                    cipher = EVP_camellia_192_cbc();
                    break;
                case 256:
                    cipher = EVP_camellia_256_cbc();
                    break;
                default:
                    log_error("Unsupported Camellia key length");
                    return -1;
            }
        } else if (strncmp(algorithms[i], "md5", 3) == 0) {
            digest = EVP_md5();
        } else if (strncmp(algorithms[i], "sha-1", 5) == 0) {
            digest = EVP_sha1();
        } else if (strncmp(algorithms[i], "sha-224", 7) == 0) {
            digest = EVP_sha224();
        } else if (strncmp(algorithms[i], "sha-256", 7) == 0) {
            digest = EVP_sha256();
        } else if (strncmp(algorithms[i], "sha-384", 7) == 0) {
            digest = EVP_sha384();
        } else if (strncmp(algorithms[i], "sha-512", 7) == 0) {
            digest = EVP_sha512();
        } else {
            log_error("Unsupported cryptographic algorithm");
            return -1;
        }

        if (cipher != NULL) {
            if (!EVP_add_cipher(cipher)) {
                ERR_print_errors_fp(stderr);
                return -1;
            }
        } else if (digest != NULL) {
            if (!EVP_add_digest(digest)) {
                ERR_print_errors_fp(stderr);
                return -1;
            }
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    // Example usage
    char *algorithms[] = {"aes-256-cbc", "md5", "sha-256"};
    int num_algorithms = sizeof(algorithms) / sizeof(algorithms[0]);
    if (load_cryptographic_primitives(algorithms, num_algorithms) != 0) {
        log_error("Failed to load cryptographic primitives");
        return 1;
    }
    // Continue with the rest of your program
    return 0;
}
