#include <stdlib.h>

typedef struct State {
    int index;
    struct State* next;
    int* transitionRules;
} State;

typedef struct FSA {
    int currentState;
    State** states;
    int stateCount;
} FSA;

typedef void* (*Allocator)(size_t size);
typedef void (*Deallocator)(void* ptr);

State* manageFSADynamicStateList(int* states, int numStates, FSA* fsa, int lastStateIndex,
                                 int* currentStateListSize, Allocator allocator, Deallocator deallocator,
                                 int (*validateStateExistence)(int*, int, int),
                                 int (*checkTransitionConsistency)(FSA*, State*, Allocator)) {
    if (lastStateIndex >= *currentStateListSize) {
        State** newStateList = (State**)allocator((lastStateIndex + 1) * sizeof(State*));
        if (!newStateList) return NULL;

        for (int i = 0; i <= lastStateIndex; ++i) {
            newStateList[i] = (State*)allocator(sizeof(State));
            if (!newStateList[i]) {
                for (int j = 0; j < i; ++j) {
                    deallocator(newStateList[j]);
                }
                deallocator(newStateList);
                return NULL;
            }
        }

        memcpy(newStateList, fsa->states, (*currentStateListSize) * sizeof(State*));
        for (int i = *currentStateListSize; i <= lastStateIndex; ++i) {
            newStateList[i] = NULL;
        }

        deallocator(fsa->states);
        fsa->states = newStateList;
        *currentStateListSize = lastStateIndex + 1;
    }

    if (!validateStateExistence(states, numStates, fsa->currentState)) return NULL;

    State* newState = (State*)allocator(sizeof(State));
    if (!newState) return NULL;

    newState->index = states[fsa->currentState];
    newState->next = NULL;
    newState->transitionRules = (int*)allocator(numStates * sizeof(int));
    if (!newState->transitionRules) {
        deallocator(newState);
        return NULL;
    }

    for (int i = 0; i < numStates; ++i) {
        newState->transitionRules[i] = states[fsa->currentState + i];
    }

    fsa->states[newState->index] = newState;

    if (lastStateIndex >= 0 && fsa->states[lastStateIndex]) {
        fsa->states[lastStateIndex]->next = newState;
    } else {
        return NULL; // Handle error: no valid last state
    }

    return newState;
}
