const express = require('express');
const bodyParser = require('body-parser');
const { Pool } = require('pg');

const app = express();
app.use(bodyParser.json());

// PostgreSQL connection pool
const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,
});

// Create a new template
app.post('/templates', async (req, res) => {
  const { name, type, data } = req.body;
  try {
    const result = await pool.query(
      'INSERT INTO templates (name, type, data) VALUES ($1, $2, $3) RETURNING *',
      [name, type, data]
    );
    res.status(201).json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Failed to create template' });
  }
});

// Update an existing template
app.put('/templates/:id', async (req, res) => {
  const { id } = req.params;
  const { name, type, data } = req.body;
  try {
    const result = await pool.query(
      'UPDATE templates SET name = $1, type = $2, data = $3 WHERE id = $4 RETURNING *',
      [name, type, data, id]
    );
    res.status(200).json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Failed to update template' });
  }
});

// Delete a specified template
app.delete('/templates/:id', async (req, res) => {
  const { id } = req.params;
  try {
    await pool.query('DELETE FROM templates WHERE id = $1', [id]);
    res.status(204).send();
  } catch (err) {
    res.status(500).json({ error: 'Failed to delete template' });
  }
});

// Retrieve all templates with optional filtering and pagination
app.get('/templates', async (req, res) => {
  const { type, date, page = 1, limit = 10, orderBy = 'id', orderDirection = 'ASC' } = req.query;
  try {
    let query = 'SELECT * FROM templates';
    if (type || date) {
      query += ' WHERE ';
      if (type) query += `type = $1 AND `;
      if (date) query += `creation_date = $${type ? 2 : 1}::DATE`;
    }
    query += ` ORDER BY ${orderBy} ${orderDirection}`;
    const result = await pool.query(query, [type || null, date || null]);
    res.status(200).json({
      data: result.rows.slice((page - 1) * limit, page * limit),
      total: result.rowCount,
    });
  } catch (err) {
