    // Generate a random IV
    unsigned char iv[16];
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive key from password using PBKDF2-HMAC-SHA256
    unsigned char key[32];
    const char* salt = "salt"; // Replace with a secure random salt for production
    if (!PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), (unsigned char*)salt, strlen(salt), 10000, EVP_aes_256_cbc(), key)) {
        fprintf(stderr, "Failed to derive encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Modify the file extension of the original filename
