using System;
using System.Collections.Generic;
using System.Linq;

public class RandomValueGenerator
{
    private Random _random;
    private int _min;
    private int _max;

    public RandomValueGenerator(int min, int max, int? seed = null)
    {
        if (seed.HasValue) _random = new Random(seed.Value);
        else _random = new Random();

        SetRange(min, max);
    }

    public void SetRange(int min, int max)
    {
        if (min >= max)
        {
            throw new ArgumentException("Invalid range: Min must be less than Max.");
        }
        _min = min;
        _max = max;
    }

    public int GetMinValue() => _min;
    public int GetMaxValue() => _max;

    public double GenerateRandomDouble()
    {
        return _random.NextDouble() * (_max - _min) + _min;
    }

    public int GenerateRandomInt(bool inclusive)
    {
        if (inclusive)
            return _random.Next(_min, _max + 1);
        else
            return _random.Next(_min, _max);
    }

    public List<int> GenerateUniqueRandomInts(int n)
    {
        if (n > (_max - _min))
        {
            throw new ArgumentException("Cannot generate more unique numbers than the range size.");
        }
        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < n)
        {
            int number;
            do
            {
                number = GenerateRandomInt(true);
            } while (!uniqueNumbers.Add(number));
        }
        return uniqueNumbers.ToList();
    }

    public override string ToString()
    {
        return $"Range: {_min} to {_max}";
    }
}
```

