class FileChecksumCalculator:
    @staticmethod
    def calculate_checksum(file_path, algorithm='sha256'):
        if not os.path.isfile(file_path):
            raise ValueError("File path must point to a valid file.")

        hasher = getattr(hashlib, algorithm)()
        chunk_size = 1024 * 1024  # 1 MB chunks

        try:
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    hasher.update(data)
            return hasher.hexdigest()
        except (IOError, PermissionError) as e:
            print(f"An error occurred: {e}")
            return None

    @staticmethod
    def generate_random_integers(n, range_start, range_end):
        if n > (range_end - range_start + 1):
            raise ValueError("Number of unique integers exceeds the possible range size.")

        random.seed()
        numbers = set()
        while len(numbers) < n:
            num = random.randint(range_start, range_end)
            numbers.add(num)

        return list(numbers)

    @staticmethod
    def get_min_max(numbers):
        if not numbers:
