import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class HashProcessor {
    private final List<String> inputStrings;
    private final MessageDigest md5Digest;

    public HashProcessor() throws NoSuchAlgorithmException {
        this.inputStrings = new ArrayList<>();
        this.md5Digest = MessageDigest.getInstance("MD5");
    }

    public void addString(String str) {
        if (str != null && !str.isEmpty()) {
            inputStrings.add(str);
        }
    }

    public List<String> processHashes() {
        List<String> hashes = new ArrayList<>();
        for (String str : inputStrings) {
            byte[] hashBytes = md5Digest.digest(str.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            hashes.add(sb.toString());
        }
        return hashes;
    }

    public static void main(String[] args) {
        try {
            HashProcessor processor = new HashProcessor();
            processor.addString("example1");
            processor.addString("example2");
            List<String> hashes = processor.processHashes();
            for (String hash : hashes) {
                System.out.println(hash);
            }
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
```

