#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    CURLcode result;
    char *data;
    size_t size;
} Response;

Response* perform_http_request(const char* file_path, const char* option) {
    CURL *curl;
    CURLcode res;
    Response *response = (Response*) malloc(sizeof(Response));
    response->result = CURLE_OK;
    response->data = NULL;
    response->size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Accept: */*");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        if (strstr(file_path, "http") == file_path) {
            curl_easy_setopt(curl, CURLOPT_URL, file_path);
        } else {
            char absolute_path[1024];
            snprintf(absolute_path, sizeof(absolute_path), "%s://%s", option, file_path);
            curl_easy_setopt(curl, CURLOPT_URL, absolute_path);
        }

        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

        struct WriteMemoryStruct {
            char *memory;
            size_t size;
        };

        struct WriteMemoryStruct chunk = {NULL, 0};
        response->data = (char*)malloc(1); // will be grown as needed by the realloc above
        response->data[0] = '\0';

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            response->result = res;
        } else {
            response->data = chunk.memory;
            response->size = chunk.size;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return response;
}

size_t write_memory_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct WriteMemoryStruct *mem = (struct WriteMemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        fprintf(stderr, "not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

void free_response(Response *response) {
    if (response != NULL) {
        if (response->data != NULL) {
            free(response->data);
        }
        free(response);
    }
}
