        // Fork failed
        std::cerr << "Failed to fork" << std::endl;
        return 0;
    } else if (pid == 0) {
        // Child process
        // Simulate octree initialization in the background
        for (int i = 0; i < numLeafNodes; ++i) {
            // Simulated work
            sleep(1);
        }
        exit(0); // Exit child process after simulation
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child to complete
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            std::cout << "Octree initialization successful" << std::endl;
            return 1; // Return success
        } else {
            std::cerr << "Octree initialization failed" << std::endl;
            return 0; // Return failure
        }
    }
}
