#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256

char* generateNewFilename(const char* originalFilename, const char* fileType) {
    if (originalFilename == NULL || fileType == NULL) {
        return "default.txt";
    }

    size_t originalLength = strlen(originalFilename);
    size_t fileTypeLength = strlen(fileType);

    if (fileTypeLength > 31) { // Assuming max file extension length is 31 characters
        return "default.txt";
    }

    char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH);
    if (newFilename == NULL) {
        return "default.txt";
    }

    size_t digitsCount = 0;
    for (size_t i = 0; i < originalLength; ++i) {
        if ((originalFilename[i] >= 'a' && originalFilename[i] <= 'z') ||
            (originalFilename[i] >= 'A' && originalFilename[i] <= 'Z')) {
            digitsCount++;
        }
    }

    char timestamp[20];
    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeinfo);

    size_t newFilenameLength = snprintf(newFilename, MAX_FILENAME_LENGTH,
        "%.*s%zu_%d_%s.%s",
        (int)originalLength - digitsCount, originalFilename, digitsCount,
        rand() % 1000, timestamp, fileType);

    if (newFilenameLength >= MAX_FILENAME_LENGTH) {
        free(newFilename);
        return "default.txt";
    }

    for (size_t i = 0; i < newFilenameLength; ++i) {
        if (!isalnum(newFilename[i]) && newFilename[i] != '.') {
            newFilename[i] = '_';
        }
    }

    return newFilename;
}

int main() {
    const char* originalFilename = "example_filename.txt";
    const char* fileType = "log";

    char* newFilename = generateNewFilename(originalFilename, fileType);
    if (newFilename != NULL) {
        printf("Generated Filename: %s\n", newFilename);
        free(newFilename);
    }

    return 0;
}
