import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class StringHasher {
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public List<String> hashStrings(List<String> strings) {
        return strings.parallelStream()
                .mapAsync(this::hashString, executor)
                .collect(Collectors.toList());
    }

    private CompletableFuture<String> hashString(String input) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                MessageDigest digest = MessageDigest.getInstance("MD5");
                byte[] hashBytes = digest.digest(input.getBytes());
                StringBuilder hexString = new StringBuilder();
                for (byte b : hashBytes) {
                    String hex = Integer.toHexString(0xff & b);
                    if (hex.length() == 1) hexString.append('0');
                    hexString.append(hex);
                }
                return hexString.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException("Failed to create MD5 digest", e);
            }
        }, executor);
    }

    public static void main(String[] args) {
        StringHasher hasher = new StringHasher();
        List<String> inputs = List.of("example1", "example2");
        List<String> hashes = hasher.hashStrings(inputs);
        hashes.forEach(System.out::println);
    }
}
```

