            .expireAfterWrite(CACHE_EXPIRATION_TIME, TimeUnit.MILLISECONDS)
            .build();

    public static void main(String[] args) {
        try {
            String latestVersion = getLatestPackageVersion("Windows");
            System.out.println("Latest version for Windows: " + latestVersion);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static String getLatestPackageVersion(String platform) throws IOException, InterruptedException {
        // Check cache first
        String cachedVersion = packageCache.getIfPresent(platform);
        if (cachedVersion != null) {
            return cachedVersion;
        }

        int retries = 0;
        while (retries < MAX_RETRIES) {
            try {
                String versionFromAPI = fetchLatestVersionFromAPI();
                // Validate and update cache
                packageCache.put(platform, versionFromAPI);
                return versionFromAPI;
            } catch (IOException e) {
                if (++retries == MAX_RETRIES) {
                    throw new IOException("Failed to retrieve latest package version after " + MAX_RETRIES + " retries", e);
                }
                // Wait before retrying
                Thread.sleep(1000 * (int)Math.pow(2, retries));
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                throw ie;
            }
        }

        return null; // Should never reach here due to MAX_RETRIES check
    }

    private static String fetchLatestVersionFromAPI() throws IOException {
        URL url = new URL(API_URL);
