typedef struct {
    uint32_t interface_id;
    time_t timestamp;
    int num_payloads;
    // Other fields...
} NicpPacket;

NicpPacket* initialize_packets(int max_packets, size_t max_payload_size) {
    NicpPacket* packets = malloc(max_packets * sizeof(NicpPacket));
    if (packets == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < max_packets; i++) {
        packets[i].interface_id = rand();
        packets[i].timestamp = time(NULL);
        packets[i].num_payloads = rand() % 10 + 1;

        for (int j = 0; j < packets[i].num_payloads; j++) {
            // Generate random checksum and priority level
            packets[i].payloads[j].checksum = rand();
            packets[i].payloads[j].priority = rand() % 5 + 1;
        }
    }

    return packets;
}

void process_string_batch(char* strings[], int num_strings, size_t max_payload_size) {
    MD5_CTX md5_context;
    unsigned char hash[MD5_DIGEST_LENGTH];
    char previous_hash[MD5_DIGEST_LENGTH] = {0};
    int unique_hashes = 0;

    for (int i = 0; i < num_strings; i++) {
        clock_t start_time = clock();
        MD5_Init(&md5_context);
        MD5_Update(&md5_context, strings[i], strlen(strings[i]));
        MD5_Final(hash, &md5_context);

        if (memcmp(previous_hash, hash, MD5_DIGEST_LENGTH) == 0) {
            int retries = 3;
            while (retries > 0) {
                usleep(100000); // Wait before retrying
                MD5_Init(&md5_context);
                MD5_Update(&md5_context, strings[i], strlen(strings[i]));
                MD5_Final(hash, &md5_context);

                if (memcmp(previous_hash, hash, MD5_DIGEST_LENGTH) != 0) {
                    break;
                }
                retries--;
            }

            if (retries == 0) {
                printf("Error: Duplicate hash detected for string %s\n", strings[i]);
                continue;
            }
        }

        memcpy(previous_hash, hash, MD5_DIGEST_LENGTH);
        unique_hashes++;

        clock_t end_time = clock();
        double processing_time = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
        printf("String: %s, Hash: %.2x%.2x%.2x%.2x, Processing Time: %.4f s\n",
               strings[i], hash[0], hash[1], hash[2], hash[3], processing_time);
    }

    printf("Unique hashes encountered: %d\n", unique_hashes);
}
