MoSTState* loadStateFromFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    MoSTState* state = (MoSTState*)malloc(sizeof(MoSTState));
    if (!state) {
        perror("Failed to allocate memory for state object");
        fclose(file);
        return NULL;
    }

    size_t bytesRead = fread(state, sizeof(MoSTState), 1, file);
    if (bytesRead != 1) {
        fprintf(stderr, "Failed to read from file\n");
        free(state);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return state;
}

int findLargestInt(int* array, int size) {
    if (size < 2) {
        printf("Too few numbers\n");
        exit(1);
    }

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void* processInput() {
    int* array = (int*)malloc(MAX_INTS * sizeof(int));
    if (!array) {
        perror("Failed to allocate memory for integer array");
        return NULL;
    }

    int size = 0;
    while (size < MAX_INTS && scanf("%d", &array[size]) == 1) {
        ++size;
    }

    if (size < 2) {
        printf("Too few numbers\n");
        free(array);
        return NULL;
    }

    int largestInt = findLargestInt(array, size);
    printf("Largest integer: %d\n", largestInt);

    MoSTState* state = loadStateFromFile("state.dat");

    free(array);
    return (void*)state;
}
