import java.util.ArrayList;
import java.util.List;

class BackgroundService {
    private boolean isRunning = false;
    private int resourceAllocation;

    public BackgroundService(int resourceAllocation) {
        this.resourceAllocation = resourceAllocation;
    }

    public void start() {
        if (!isRunning) {
            System.out.println("Starting service with resource allocation: " + resourceAllocation);
            isRunning = true;
        }
    }

    public void stop() {
        if (isRunning) {
            System.out.println("Stopping service");
            isRunning = false;
        }
    }

    public boolean checkHealth() {
        // Simulate health check
        return Math.random() > 0.95; // Randomly fail with 5% probability
    }

    public void reportToMonitoringSystem(String message) {
        System.out.println("Reporting to monitoring system: " + message);
    }
}

class ServiceManager {
    private List<BackgroundService> services;
    private int maxResourcePerService;

    public ServiceManager(int maxResourcePerService, int numberOfServices) {
        this.maxResourcePerService = maxResourcePerService;
        services = new ArrayList<>();
        for (int i = 0; i < numberOfServices; i++) {
            services.add(new BackgroundService(maxResourcePerService));
        }
    }

    public void manageServices() {
        while (true) {
            for (BackgroundService service : services) {
                if (!service.checkHealth()) {
                    int newResourceAllocation = calculateNewResourceAllocation();
                    service.stop();
                    service.start();
                    service.reportToMonitoringSystem("Service restarted. New resource allocation: " + newResourceAllocation);
                }
            }
            try {
                Thread.sleep(5000); // Check every 5 seconds
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private int calculateNewResourceAllocation() {
        // Simplified logic to adjust resource allocation based on system load
        return maxResourcePerService + (int) (Math.random() * 10);
    }
}

public class ServiceManagerExample {
    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager(50, 3);
        serviceManager.manageServices();
    }
}
```

This code defines a `BackgroundService` class that simulates a background service with methods to start, stop, check health, and report to a monitoring system. The `ServiceManager` class manages multiple instances of these services, checks their health periodically, and restarts them if they fail. It also dynamically adjusts the resource allocation for each service based on a simplified load calculation.']

