#include <iostream>
#include <vector>
#include <forward_list>
#include <random>
#include <algorithm>

class RandomValueGenerator {
private:
    int minVal;
    int maxVal;
    std::mt19937 generator;

public:
    RandomValueGenerator(int min, int max) : minVal(min), maxVal(max), generator(std::random_device{}()) {
        if (min >= max) throw std::invalid_argument("Invalid range");
    }

    void setSeed(unsigned seed) {
        generator.seed(seed);
    }

    int generateRandomInt(bool inclusive = true) {
        std::uniform_int_distribution<> distribution(minVal, inclusive ? maxVal : maxVal - 1);
        return distribution(generator);
    }

    double generateRandomFloat() {
        std::uniform_real_distribution<double> distribution(static_cast<double>(minVal), static_cast<double>(maxVal));
        return distribution(generator);
    }

    std::vector<int> generateUniqueIntegers(int n) {
        if (n > maxVal - minVal + 1) throw std::invalid_argument("Too many unique integers requested");
        std::vector<int> pool(minVal, maxVal + 1);
        std::shuffle(pool.begin(), pool.end(), generator);
        return std::vector<int>(pool.begin(), pool.begin() + n);
    }

    int getMinValue() const {
        return minVal;
    }

    int getMaxValue() const {
        return maxVal;
    }

    std::string toString() const {
        return "Range: [" + std::to_string(minVal) + ", " + std::to_string(maxVal) + "]";
    }

    static void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
        auto it = list.begin();
        while (it != list.end() && *it != target) ++it;
        if (it != list.end()) it = list.insert_after(it, toInsert);
        else list.push_back(toInsert);
    }
};
