#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_PACKET_SIZE 1024
#define MAX_STRINGS 10000
#define MD5_DIGEST_LENGTH 16

typedef struct {
    unsigned int interface_id;
    time_t timestamp;
    void *payload_segments; // Array of payload segments with checksums and priorities
} NICP_Packet;

void generate_md5(const char *str, unsigned char *digest) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str, strlen(str));
    MD5_Final(digest, &md5);
}

int check_duplicate_hash(unsigned char *hashes[], int count, unsigned char *new_hash) {
    for (int i = 0; i < count; i++) {
        if (memcmp(hashes[i], new_hash, MD5_DIGEST_LENGTH) == 0) {
            return 1;
        }
    }
    return 0;
}

void process_string_batch(const char *strs[], int num_strings, unsigned char **hashes, int *unique_count) {
    for (int i = 0; i < num_strings; i++) {
        unsigned char hash[MD5_DIGEST_LENGTH];
        generate_md5(strs[i], hash);

        if (check_duplicate_hash(hashes, *unique_count, hash)) {
            int retries = 3;
            while (retries > 0) {
                generate_md5(strs[i], hash);
                if (!check_duplicate_hash(hashes, *unique_count, hash)) {
                    break;
                }
                retries--;
            }
            if (retries == 0) {
                printf("Error: Duplicate hash for string '%s'\n", strs[i]);
                continue;
            }
        }

        hashes[*unique_count] = malloc(MD5_DIGEST_LENGTH);
        memcpy(hashes[*unique_count], hash, MD5_DIGEST_LENGTH);
        (*unique_count)++;
    }
}

NICP_Packet *initialize_nicp_packets(int num_packets) {
    size_t total_size = sizeof(NICP_Packet) * num_packets + MAX_PACKET_SIZE * num_packets;
    if (total_size > 1024 * 1024) {
        printf("Error: Packet array exceeds 1MB limit\n");
        return NULL;
    }

    NICP_Packet *packets = malloc(total_size);
    if (!packets) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_packets; i++) {
        packets[i].interface_id = i;
        packets[i].timestamp = time(NULL);
        packets[i].payload_segments = malloc(MAX_PACKET_SIZE * sizeof(void *));
    }

    return packets;
}

void free_nicp_packets(NICP_Packet *packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        free(packets[i].payload_segments);
    }
    free(packets);
}
