import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class HashingService {

    private static final String MD5_ALGORITHM = "MD5";
    private static final String SHA_256_ALGORITHM = "SHA-256";

    public Map<String, String> processStrings(List<String> strings) throws NoSuchAlgorithmException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<Map<String, String>> completionService = new ExecutorCompletionService<>(executor);
        List<Future<Map<String, String>>> futures = new ArrayList<>();

        for (String str : strings) {
            futures.add(completionService.submit(() -> hashString(str)));
        }

        Map<String, String> results = new HashMap<>();
        for (Future<Map<String, String>> future : futures) {
            try {
                results.putAll(future.get());
            } catch (InterruptedException | ExecutionException e) {
                handleProcessingError(e);
            }
        }

        executor.shutdown();
        return results;
    }

    private Map<String, String> hashString(String str) throws NoSuchAlgorithmException {
        MessageDigest md5Digest = MessageDigest.getInstance(MD5_ALGORITHM);
        MessageDigest sha256Digest = MessageDigest.getInstance(SHA_256_ALGORITHM);

        byte[] md5Bytes = md5Digest.digest(str.getBytes());
        byte[] sha256Bytes = sha256Digest.digest(str.getBytes());

        return Map.of(
                "MD5", bytesToHex(md5Bytes),
                "SHA-256", bytesToHex(sha256Bytes)
        );
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void handleProcessingError(Exception e) {
        // Log error details and retry logic here
    }

    public static void main(String[] args) throws NoSuchAlgorithmException {
        HashingService service = new HashingService();
        List<String> strings = List.of("example", "data");
        Map<String, String> results = service.processStrings(strings);
        System.out.println(results);
    }
}
