#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define MAX_BATCH_SIZE 10000

typedef struct {
    int id;
    time_t timestamp;
    char** payload_segments;
} NICP_Packet;

NICP_Packet* init_nicp_packets(int num_packets) {
    if (num_packets > MAX_BATCH_SIZE || num_packets * MAX_PACKET_SIZE > 1024 * 1024) {
        return NULL;
    }

    NICP_Packet* packets = malloc(num_packets * sizeof(NICP_Packet));
    if (!packets) {
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_packets; ++i) {
        packets[i].id = i + 1;
        packets[i].timestamp = time(NULL);
        int payload_size = rand() % 10 + 1;
        packets[i].payload_segments = malloc(payload_size * sizeof(char*));
        for (int j = 0; j < payload_size; ++j) {
            packets[i].payload_segments[j] = malloc(32); // MD5 hash length
            sprintf(packets[i].payload_segments[j], "%x", rand()); // Random checksum
        }
    }

    return packets;
}

void free_nicp_packets(NICP_Packet* packets, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        for (int j = 0; j < 10; ++j) { // Assuming max payload size of 10
            free(packets[i].payload_segments[j]);
        }
        free(packets[i].payload_segments);
    }
    free(packets);
}
