    EVP_CIPHER* ciphers[] = {EVP_aes_128_ecb(), EVP_aes_192_ecb(), EVP_aes_256_ecb(),
                            EVP_camellia_128_ecb(), EVP_camellia_192_ecb(), EVP_camellia_256_ecb()};
    EVP_MD* digests[] = {EVP_md5(), EVP_sha1(), EVP_sha224(), EVP_sha256(), EVP_sha384(), EVP_sha512()};

    // Initialize logging
    FILE* log_file = fopen(log_file_path, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    // Add ciphers and digests with error handling for aliases
    for (int i = 0; i < sizeof(ciphers)/sizeof(EVP_CIPHER*); i++) {
        if (!EVP_add_cipher(ciphers[i])) {
            fprintf(log_file, "Failed to add cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        }
    }
    for (int i = 0; i < sizeof(digests)/sizeof(EVP_MD*); i++) {
        if (!EVP_add_digest(digests[i])) {
            fprintf(log_file, "Failed to add digest: %s\n", ERR_error_string(ERR_get_error(), NULL));
        }
    }

    // Dynamically load enabled algorithms
    for (int i = 0; i < num_algorithms; i++) {
        if (!strcmp(enabled_algorithms[i], "aes_128_ecb")) {
            EVP_add_cipher(EVP_aes_128_ecb());
        } else if (!strcmp(enabled_algorithms[i], "sha256")) {
            EVP_add_digest(EVP_sha256());
        }
    }

    // Implement memory allocation failure handling
    void* ptr = malloc(4097);
    if (!ptr) {
        fprintf(log_file, "Memory allocation failed\n");
        fclose(log_file);
        return;
    }
    free(ptr);

    // Close log file
    fclose(log_file);
}

int main(int argc, char* argv[]) {
    const char* log_file_path = "log.txt";
    const char* enabled_algorithms[] = {"aes_128_ecb", "sha256"};
    int num_algorithms = sizeof(enabled_algorithms)/sizeof(enabled_algorithms[0]);

    integrate_cryptographic_primitives(log_file_path, enabled_algorithms, num_algorithms);
    return 0;
}
