import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class StringHashProcessor {

    private static final int MAX_RETRIES = 3;
    private static final double RETRY_BACKOFF_FACTOR = 2.0;
    private static final long MIN_RETRY_INTERVAL = 100; // milliseconds
    private static final long MAX_RETRY_INTERVAL = 60000; // milliseconds

    public static void processBatch(ExternalDataSource dataSource, boolean debugLogging) {
        ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();
        BlockingQueue<String> queue = new LinkedBlockingQueue<>();
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        int uniqueHashes = 0;
        int totalRetries = 0;

        // Start processing task
        Future<?> future = executorService.submit(() -> {
            try {
                for (String str : dataSource.getStringBatch()) {
                    queue.put(str);
                }
                queue.put(null); // Signal end of data
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        // Start hashing task
        while (true) {
            String str = null;
            try {
                str = queue.take();
                if (str == null) break;

                int retryCount = 0;
                boolean success = false;
                long startTime = System.currentTimeMillis();

                while (!success && retryCount < MAX_RETRIES) {
                    try {
                        String hash = computeMD5(str);
                        if (hashMap.putIfAbsent(hash, str) != null) { // Check for duplicate
                            throw new IllegalStateException("Duplicate hash detected");
                        }
                        uniqueHashes++;
                        success = true;
                    } catch (NoSuchAlgorithmException e) {
                        Thread.sleep((long)(Math.random() * RETRY_BACKOFF_FACTOR * Math.pow(RETRY_BACKOFF_FACTOR, retryCount)));
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                    retryCount++;
                }

                if (!success) {
                    totalRetries += retryCount - 1; // Subtract the initial attempt
                    String errorMessage = "Failed to process string after " + MAX_RETRIES + " retries: " + str;
                    logErrorMessage(errorMessage);
                } else {
                    long processingTime = System.currentTimeMillis() - startTime;
                    if (debugLogging) {
                        logDebugMessage("Processed string \"" + str + "\" in " + processingTime + " ms");
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        try {
            future.get(); // Wait for data source task to complete
        } catch (Exception e) {
            logErrorMessage("Error reading from external data source: " + e.getMessage());
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }

        logInfoMessage("Total unique hashes: " + uniqueHashes);
        logInfoMessage("Total retries: " + totalRetries);

        // Log detailed debug information if requested
        if (debugLogging) {
            for (Map.Entry<String, String> entry : hashMap.entrySet()) {
                logDebugMessage("Unique hash: " + entry.getKey() + ", Original string: " + entry.getValue());
            }
        }
    }

    private static String computeMD5(String str) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(str.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static void logInfoMessage(String message) {
        // Implement logging logic here
    }

    private static void logErrorMessage(String message) {
        // Implement error logging logic here
    }

    private static void logDebugMessage(String message) {
        // Implement debug logging logic here
    }
}

