import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class FilePathProcessor {

    private static final int THRESHOLD = 1000; // Define your threshold here
    private static ConcurrentHashMap<String, String> md5Cache = new ConcurrentHashMap<>();
    private Set<String> knownHashes; // Assume this is updated dynamically

    public List<Integer> processFilePaths(List<String> filePaths) {
        List<Integer> sequenceNumbers = Collections.synchronizedList(new ArrayList<>());

        for (String filePath : filePaths) {
            try {
                String md5Hash = computeMD5(filePath);
                if (knownHashes.contains(md5Hash)) {
                    int sequenceNumber = extractSequenceNumber(filePath);
                    if (sequenceNumber > THRESHOLD) {
                        notifyMonitoringSystem(sequenceNumber, filePath);
                    }
                    sequenceNumbers.add(sequenceNumber);
                }
            } catch (IOException | NoSuchAlgorithmException e) {
                // Handle exceptions gracefully
                System.err.println("Error processing file: " + filePath + ", error: " + e.getMessage());
            }
        }

        Collections.sort(sequenceNumbers);
        return sequenceNumbers;
    }

    private String computeMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        String cachedHash = md5Cache.get(filePath);
        if (cachedHash != null) {
            return cachedHash;
        }

        MessageDigest digest = MessageDigest.getInstance("MD5");
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }

        String md5Hash = bytesToHex(digest.digest());
        md5Cache.put(filePath, md5Hash);
        return md5Hash;
    }

    private int extractSequenceNumber(String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Assuming the sequence number is in the last line
                if (isValidSequenceNumber(line)) {
                    return Integer.parseInt(line);
                }
            }
        }

        throw new IllegalArgumentException("No valid sequence number found in file: " + filePath);
    }

    private boolean isValidSequenceNumber(String line) {
        try {
            int number = Integer.parseInt(line);
            // Add your validation logic here
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private void notifyMonitoringSystem(int sequenceNumber, String filePath) {
        // Implement your monitoring system notification logic here
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
