using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class AdvancedRandomValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private double _precision;

    public AdvancedRandomValueGenerator(int minValue, int maxValue, double precision = 1.0)
    {
        ValidateRange(minValue, maxValue);
        InitializeRandomizer();
        SetRange(minValue, maxValue);
        SetPrecision(precision);
    }

    public void InitializeRandomizer(long? seed = null)
    {
        _random = seed.HasValue ? new Random(seed.Value) : new Random();
    }

    public void SetRange(int minValue, int maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void SetPrecision(double precision)
    {
        if (precision <= 0)
            throw new ArgumentException("Precision must be greater than zero.");
        _precision = precision;
    }

    public int GenerateRandomInteger(bool includeMax = true)
    {
        return includeMax ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
    }

    public double GenerateRandomFloat()
    {
        var randomValue = _random.NextDouble();
        return Math.Round(randomValue * (_maxValue - _minValue) + _minValue, (int)Math.Log10(1.0 / _precision));
    }

    public List<int> GenerateUniqueRandomIntegers(int n)
    {
        if (n > (_maxValue - _minValue + 1))
            throw new ArgumentOutOfRangeException("n", "Cannot generate more unique values than the range size.");
        var result = new List<int>();
        while (result.Count < n)
        {
            int value;
            do
            {
                value = GenerateRandomInteger(true);
            } while (!result.Contains(value));
            result.Add(value);
        }
        return result;
    }

    public void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
    }

    public override string ToString()
    {
        return $"Range: {_minValue}-{_maxValue}, Precision: {_precision}";
    }
}
