public class SecureValueManager
{
    private int seed;
    private Random randomGenerator;

    public SecureValueManager(int seed)
    {
        this.seed = seed;
        this.randomGenerator = new Random(seed);
    }

    public override string ToString()
    {
        return $"Random Range: 0 to {int.MaxValue}";
    }

    public int GenerateRandomInteger()
    {
        return randomGenerator.Next();
    }

    public double GenerateRandomFloat()
    {
        return randomGenerator.NextDouble();
    }

    public List<int> GenerateUniqueRandomIntegers(int n, int rangeMin = 0, int rangeMax = int.MaxValue)
    {
        if (n > rangeMax - rangeMin + 1 || n < 0)
        {
            throw new ArgumentOutOfRangeException("n", "Invalid range for unique integers");
        }

        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < n)
        {
            uniqueNumbers.Add(randomGenerator.Next(rangeMin, rangeMax + 1));
        }
        return uniqueNumbers.ToList();
    }
}
