#include <future>

class DataSampler {
private:
    std::mt19937 generator;
    int minVal, maxVal;
    bool isInteger;

public:
    DataSampler(int min, int max, bool integerType) : minVal(min), maxVal(max), isInteger(integerType) {
        if (integerType && min > max) throw std::invalid_argument("Invalid range for integers.");
        generator.seed(static_cast<unsigned long>(std::chrono::system_clock::now().time_since_epoch().count()));
    }

    void setSeed(int seed) { generator.seed(seed); }

    int getMin() const { return minVal; }
    int getMax() const { return maxVal; }

    std::string toString() const {
        if (isInteger)
            return "DataSampler [Integer Range: " + std::to_string(minVal) + " to " + std::to_string(maxVal) + "]";
        else
            return "DataSampler [Float Range: " + std::to_string(static_cast<double>(minVal) / 100.0) + " to " +
                   std::to_string(static_cast<double>(maxVal) / 100.0) + "]";
    }

    int generateRandom() {
        if (isInteger)
            return std::uniform_int_distribution<int>{minVal, maxVal}(generator);
        else
            return static_cast<int>(std::uniform_real_distribution<>(static_cast<double>(minVal) / 100.0,
                                                                   static_cast<double>(maxVal) / 100.0)(generator) * 100);
    }

    std::vector<int> generateUniqueRandomInts(int n) {
        if (n > (maxVal - minVal + 1)) throw std::invalid_argument("Too many unique values requested.");
        std::set<int> uniqueValues;
        while (uniqueValues.size() < n) {
            int value = generateRandom();
            uniqueValues.insert(value);
        }
        return std::vector<int>(uniqueValues.begin(), uniqueValues.end());
    }

    static void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
        auto it = list.before_begin();
        for (; it != list.end(); ++it) {
            if (*it == target) break;
        }
        if (it == list.end())
            list.push_back(toInsert);
        else
            list.insert_after(it, toInsert);
    }
};
