import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class FilePathProcessor {

    private static final Set<String> knownHashes = new HashSet<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    static {
        // Populate known hashes from a database
        populateKnownHashesFromDatabase();
    }

    public static void processFilePaths(List<String> filePaths) {
        for (String path : filePaths) {
            executorService.submit(() -> {
                try {
                    String md5Hash = computeMD5Hash(path);
                    if (knownHashes.contains(md5Hash)) {
                        System.out.println("Match found for file: " + path);
                    }
                } catch (IOException | NoSuchAlgorithmException e) {
                    e.printStackTrace();
                }
            });
        }
    }

    private static String computeMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        byte[] digest = md.digest();
        BigInteger no = new BigInteger(1, digest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));
        while (hashtext.length() < 32) {
            hashtext.insert(0, '0');
        }
        return hashtext.toString();
    }

    public static CompletableFuture<Integer> extractSequenceNumberAsync(String filePath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return readAndSortFile(filePath);
            } catch (IOException e) {
                e.printStackTrace();
                return null;
            }
        }, executorService).thenApply(FilePathProcessor::extractSequenceNumberFromLastLine);
    }

    private static int readAndSortFile(String filePath) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                lines.add(line);
            }
        }
        Collections.sort(lines);
        return lines.size();
    }

    private static Integer extractSequenceNumberFromLastLine(String lastLine) {
        // Assuming the sequence number is at the end of the line
        String[] parts = lastLine.split("\\s+");
        if (parts.length > 0 && parts[parts.length - 1].matches("\\d+")) {
            return Integer.parseInt(parts[parts.length - 1]);
        }
        return null;
    }

    private static void populateKnownHashesFromDatabase() {
        // Logic to fetch known hashes from a database and add to knownHashes set
    }
}
