public class FileHashProcessor
{
    private ConcurrentDictionary<string, string> knownHashes = new ConcurrentDictionary<string, string>();

    public async Task ProcessFilePathsAsync(string[] filePaths)
    {
        var tasks = filePaths.Select(file => ComputeAndMatchHashAsync(file)).ToList();
        await Task.WhenAll(tasks);
    }

    private async Task ComputeAndMatchHashAsync(string file)
    {
        try
        {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(file))
            {
                var hashBytes = await md5.ComputeHashAsync(stream);
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                if (knownHashes.TryGetValue(hashString, out var knownFile))
                {
                    // Log successful match
                    Console.WriteLine($"Match found: {file} matches {knownFile}");
                }
            }
        }
        catch (Exception ex)
        {
            // Handle I/O or hashing exceptions gracefully
            Console.WriteLine($"Error processing file {file}: {ex.Message}");
        }
    }

    public async Task<int> ReadSortExtractAsync(string filePath)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                var lines = await reader.ReadToEndAsync();
                var sortedLines = lines.Split(new[] { Environment.NewLine }, StringSplitOptions.None).OrderBy(line => line);
                var lastLine = sortedLines.LastOrDefault();

                if (int.TryParse(lastLine, out var sequenceNumber))
                {
                    return sequenceNumber;
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully
            Console.WriteLine($"Error reading or processing file {filePath}: {ex.Message}");
        }

        return -1; // Default value indicating an error
    }

