                    using (var reader = command.ExecuteReader())
                    {
                        return reader;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully
            Console.WriteLine($"Error sending data to database: {ex.Message}");
            return null;
        }
    }

    private string connectionString; // Initialize with actual connection string
