#include <pthread.h>

#define MAX_PACKETS 1024
#define MAX_PAYLOAD_SEGMENTS 32
#define MAX_STRINGS 10000
#define MAX_HASH_LENGTH 32

typedef struct {
    unsigned int interface_id;
    time_t timestamp;
    unsigned char payload[MAX_PAYLOAD_SEGMENTS][128];
    unsigned short checksums[MAX_PAYLOAD_SEGMENTS];
    unsigned char priority_levels[MAX_PAYLOAD_SEGMENTS];
} NicpPacket;

unsigned long hash(const char *str) {
    // Simple hash function for demonstration purposes
    unsigned long h = 0;
    while (*str)
        h = h * 31 + *str++;
    return h;
}

void generate_payload(NicpPacket *packet, int segment_count) {
    srand(time(0));
    for (int i = 0; i < segment_count; ++i) {
        packet->checksums[i] = rand() % UINT_MAX;
        packet->priority_levels[i] = rand() % 256;
        // Simulate payload generation
        memset(packet->payload[i], rand(), sizeof(packet->payload[i]));
    }
}

NicpPacket *initialize_packets(int packet_count, int segment_count) {
    NicpPacket *packets = (NicpPacket *)malloc(packet_count * sizeof(NicpPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        return NULL;
    }
    for (int i = 0; i < packet_count; ++i) {
        packets[i].interface_id = i + 1;
        packets[i].timestamp = time(NULL);
        generate_payload(&packets[i], segment_count);
    }
    return packets;
}

void process_strings(char *strings[], int string_count, NicpPacket **output_packets, int *unique_hash_count) {
    pthread_mutex_t hash_lock = PTHREAD_MUTEX_INITIALIZER;
    unsigned char *hash_table[MAX_HASH_COUNT];
    memset(hash_table, 0, sizeof(hash_table));

    for (int i = 0; i < string_count; ++i) {
        clock_t start_time = clock();
        for (int attempt = 0; attempt < 4; ++attempt) {
            unsigned long str_hash = hash(strings[i]);
            pthread_mutex_lock(&hash_lock);
            if (!hash_table[str_hash % MAX_HASH_LENGTH]) {
                // Simulate MD5 hash generation
                hash_table[str_hash % MAX_HASH_LENGTH] = (unsigned char *)malloc(MAX_HASH_LENGTH);
                memcpy(hash_table[str_hash % MAX_HASH_LENGTH], &str_hash, sizeof(str_hash));
                (*unique_hash_count)++;
                pthread_mutex_unlock(&hash_lock);
                break;
            }
            pthread_mutex_unlock(&hash_lock);
        }
        if (attempt == 3) {
            fprintf(stderr, "Failed to process string: %s\n", strings[i]);
        }
    }

    for (int i = 0; i < MAX_HASH_COUNT; ++i) {
        free(hash_table[i]);
    }
}

int main() {
    NicpPacket *packets;
    char *strings[MAX_STRINGS] = {"string1", "string2", /* ... */};
    int unique_hash_count = 0;

    packets = initialize_packets(MAX_PACKETS, MAX_PAYLOAD_SEGMENTS);
    if (packets) {
        process_strings(strings, MAX_STRINGS, &packets, &unique_hash_count);
        free(packets);
    }

    printf("Unique hashes encountered: %d\n", unique_hash_count);

    return 0;
}
