#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DEFAULT_LINE_LIMIT 80

void print_manpage() {
    printf("Usage: config_tool [OPTIONS] [INPUT_FILE...]\n");
    printf("Options:\n");
    printf("  --manpage        Print detailed usage information.\n");
    printf("  -cs <count>     Specify the number of characters per line limit for validation purposes.\n");
    printf("  -o <output_file> Redirect output to a specified file instead of standard output.\n");
    printf("  -v              Enable verbose mode for additional logging.\n");
}

void validate_line(const char* filename, int line_number, const char* line, int max_length) {
    if (strlen(line) > max_length) {
        fprintf(stderr, "Error in file %s: Line %d exceeds maximum length of %d characters.\n", filename, line_number, max_length);
    }
}

int main(int argc, char* argv[]) {
    int line_limit = DEFAULT_LINE_LIMIT;
    const char* output_file = NULL;
    int verbose_mode = 0;

    // Parse command line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_manpage();
            return 0;
        } else if (strncmp(argv[i], "-cs ", 4) == 0) {
            line_limit = atoi(&argv[i][4]);
        } else if (strncmp(argv[i], "-o ", 3) == 0) {
            output_file = &argv[i][3];
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose_mode = 1;
        } else if (!output_file) {
            output_file = argv[i];
        }
    }

    FILE* outfile = stdout;
    if (output_file) {
        outfile = fopen(output_file, "w");
        if (!outfile) {
            perror("Error opening output file");
            return EXIT_FAILURE;
        }
    }

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0 || strncmp(argv[i], "-cs ", 4) == 0 ||
            strncmp(argv[i], "-o ", 3) == 0 || strcmp(argv[i], "-v") == 0) {
            continue;
        }
        FILE* infile = fopen(argv[i], "r");
        if (!infile) {
            perror("Error opening input file");
            continue;
        }

        int line_number = 1;
        char buffer[4096];
        while (fgets(buffer, sizeof(buffer), infile)) {
            validate_line(argv[i], line_number++, buffer, line_limit);
        }

        fclose(infile);
    }

    if (outfile != stdout) {
        fclose(outfile);
    }

    return 0;
}
