typedef struct {
    time_t timestamp;
    int unique_id;
    double* sensor_readings;
    size_t num_readings;
} TSDRecord;

typedef struct {
    TSDRecord** records;
    size_t count;
    size_t capacity;
} TimeSeriesData;

typedef struct {
    pthread_mutex_t lock;
    TimeSeriesData data;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t initial_capacity) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->data.capacity = initial_capacity;
    pool->data.count = 0;
    pool->data.records = (TSDRecord**)malloc(initial_capacity * sizeof(TSDRecord*));
}

void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->data.count; ++i) {
        free(pool->data.records[i]->sensor_readings);
        free(pool->data.records[i]);
    }
    free(pool->data.records);
    pthread_mutex_destroy(&pool->lock);
}

void* create_record(void* memory_pool, time_t timestamp, int unique_id, double* sensor_readings, size_t num_readings) {
    MemoryPool* pool = (MemoryPool*)memory_pool;
    pthread_mutex_lock(&pool->lock);

    if (pool->data.count >= pool->data.capacity) {
        // Resize the array
        pool->data.capacity *= 2;
        TSDRecord** new_records = (TSDRecord**)realloc(pool->data.records, pool->data.capacity * sizeof(TSDRecord*));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle memory allocation error
        }
        pool->data.records = new_records;
    }

    TSDRecord* record = (TSDRecord*)malloc(sizeof(TSDRecord));
    if (!record) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Handle memory allocation error
    }

    record->timestamp = timestamp;
    record->unique_id = unique_id;
    record->sensor_readings = (double*)malloc(num_readings * sizeof(double));
    if (!record->sensor_readings) {
        free(record);
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Handle memory allocation error
    }

    memcpy(record->sensor_readings, sensor_readings, num_readings * sizeof(double));
    record->num_readings = num_readings;

    pool->data.records[pool->data.count++] = record;
    pthread_mutex_unlock(&pool->lock);
    return record;
}

// Function to process data points and perform statistical analysis
void process_data(MemoryPool* memory_pool, double* sensor_readings, size_t num_readings) {
    // Implementation goes here
}

