        array->records = (TsdRecord **)realloc(array->records, array->capacity * sizeof(TsdRecord *));
    }
    array->records[array->size++] = record;
    pthread_mutex_unlock(&array->lock);
}

void processBatch(TsdArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        // Process each TSD record here
    }
    pthread_mutex_unlock(&array->lock);
}

void cleanUpTsdArray(TsdArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i]->values);
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

