TSDArray* tsd_array_init(size_t initial_capacity) {
    TSDArray* array = (TSDArray*)malloc(sizeof(TSDArray));
    if (!array) return NULL;

    array->records = (TimeSeriesData**)malloc(initial_capacity * sizeof(TimeSeriesData*));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void tsd_array_free(TSDArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i]->values);
        free(array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int tsd_array_add(TSDArray* array, TimeSeriesData* record) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TimeSeriesData** new_records = (TimeSeriesData**)realloc(array->records, new_capacity * sizeof(TimeSeriesData*));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->records = new_records;
        array->capacity = new_capacity;
