void logError(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "ERROR: ");
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
}

Record* generateMD5Hashes(char **keys, int count, unsigned long seed) {
    Record *records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        logError("Failed to allocate memory for records.");
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < count; ++i) {
        records[i].key = strdup(keys[i]);
        if (!records[i].key) {
            logError("Failed to duplicate key %s", keys[i]);
            // Clean up previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j].key);
            }
            free(records);
            return NULL;
        }

        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, keys[i], strlen(keys[i]));
        MD5_Final(records[i].hash, &md5);
    }

    return records;
}

void serializeRecords(Record *records, int count, FILE *outputFile) {
    for (int i = 0; i < count; ++i) {
        fwrite(&records[i].key, sizeof(char*), strlen(records[i].key) + 1, outputFile);
        fwrite(records[i].hash, sizeof(unsigned char), MD5_DIGEST_LENGTH, outputFile);
    }
}

