}

void* populate_array(void *arg) {
    int *index = (int *) arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(log_file, "Memory allocation failed for element %d\n", *index);
        pthread_exit(NULL);
