    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    if (!validate_structure(pdu)) {
        free(pdu);
        fprintf(log_file, "Validation failed for element %d\n", *index);
        pthread_exit(NULL);
    }
    // Store the pointer to the allocated structure in a shared array
    // (Assuming shared_array and mutex are defined elsewhere)
    pthread_mutex_lock(&mutex);
    shared_array[*index] = pdu;
    pthread_mutex_unlock(&mutex);
    fprintf(log_file, "Successfully allocated element %d\n", *index);
    pthread_exit(NULL);
}

int find_largest_integer(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    int max_value = -1;
    for (int i = 0; i < size; i++) {
        if (validate_structure(array[i])) {
            // Assuming RX_UE_INFORMATION_TAG is the integer value to compare
            if (array[i]->RX_UE_INFORMATION_TAG > max_value) {
                max_value = array[i]->RX_UE_INFORMATION_TAG;
            }
