    pthread_mutex_init(&result.lock, NULL);
    result.head = NULL;

    int max_concurrent_queries = 5;
    int status = async_dns_resolution(hostnames, num_hostnames, &result, max_concurrent_queries);

    if (status == 0) {
        IP_Address *current = result.head;
        while (current != NULL) {
            printf("Hostname: %s, IP Address: %s\n", current->hostname, inet_ntoa(current->ip));
            current = current->next;
        }
        free_dns_result(&result);
    } else {
        fprintf(stderr, "DNS resolution failed with status: %d\n", status);
    }

    return 0;
}
