#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define MAX_DNS_SERVERS 10
#define RETRY_DELAY_START 1000 // Initial delay in milliseconds
#define RETRY_DELAY_MAX 60000 // Maximum delay in milliseconds

typedef struct {
    u_char ip[4];
} IPAddress;

int resolve_hostname(const char *hostname, IPAddress *ip, const char *dns_servers[], int num_dns_servers) {
    for (int attempt = 0; attempt < 10; attempt++) { // Limiting to 10 attempts
        for (int i = 0; i < num_dns_servers; i++) {
            struct addrinfo hints, *res;
            int status;

            memset(&hints, 0, sizeof(hints));
            hints.ai_family = AF_INET; // Use IPv4
            hints.ai_socktype = SOCK_DGRAM;

            if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
                fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(status));
                continue;
            }

            struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
            memcpy(ip->ip, &(ipv4->sin_addr), sizeof(u_char)*4);

            freeaddrinfo(res);
            return 0; // Success
        }
        usleep(RETRY_DELAY_START << attempt); // Exponential backoff
    }

    fprintf(stderr, "Failed to resolve hostname after multiple attempts.\n");
    return -1; // Failure
}

int main() {
    const char *hostname = "example.com";
    IPAddress ip;
    const char *dns_servers[MAX_DNS_SERVERS] = {"8.8.8.8", "8.8.4.4"};

    if (resolve_hostname(hostname, &ip, dns_servers, 2) == 0) {
        printf("Resolved IP: %d.%d.%d.%d\n", ip.ip[0], ip.ip[1], ip.ip[2], ip.ip[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
```

