    SensorData **sensor_array = (SensorData **)malloc(N * sizeof(SensorData *));
    if (!sensor_array) {
        fprintf(log_file, "Memory allocation failed for sensor array\n");
        return -1;
    }

    int successful_allocations = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    void* allocate_sensor_data(void *arg) {
        int index = *(int *)arg;
        SensorData *sensor = (SensorData *)malloc(sizeof(SensorData));
        if (!sensor) {
            fprintf(log_file, "Memory allocation failed for sensor data at index %d\n", index);
            pthread_exit(NULL);
        }

        pthread_mutex_lock(&lock);
        sensor_array[index] = sensor;
        successful_allocations++;
        pthread_mutex_unlock(&lock);

        // Simulate sensor data processing
        sensor->timestamp = time(NULL);
        sensor->sensor_id = index + 1;
        sensor->anomaly = rand() % 2;

        pthread_exit(NULL);
    }

    pthread_t threads[N];
    int indices[N];
    for (int i = 0; i < N; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, allocate_sensor_data, &indices[i]) != 0) {
            fprintf(log_file, "Failed to create thread %d\n", i);
            return -1;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    if (successful_allocations != N) {
        fprintf(log_file, "Not all sensor data allocations were successful\n");
        return -1;
    }

    // Validate sensor data and calculate average value
    double total_value = 0;
    for (int i = 0; i < N; i++) {
        if (!sensor_array[i] || sensor_array[i]->anomaly) {
            fprintf(log_file, "Invalid sensor data at index %d\n", i);
            return -1;
        }
        total_value += sensor_array[i]->timestamp;
    }

    double average = total_value / N;
    printf("Average sensor value: %.2f\n", average);

    // Free allocated memory
    for (int i = 0; i < N; i++) {
        free(sensor_array[i]);
    }
    free(sensor_array);

    return 0;
}
