#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>

typedef struct {
    CURL *handle;
    char *buffer;
    size_t buffer_size;
} JsonParser;

JsonParser* json_parser_init() {
    JsonParser *parser = (JsonParser*)malloc(sizeof(JsonParser));
    parser->handle = curl_easy_init();
    if (!parser->handle) {
        free(parser);
        return NULL;
    }
    parser->buffer = NULL;
    parser->buffer_size = 0;
    return parser;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    JsonParser *parser = (JsonParser*)userp;
    size_t new_size = size * nmemb;
    if (new_size > parser->buffer_size - 1) {
        char *new_buffer = realloc(parser->buffer, parser->buffer_size + new_size + 1);
        if (!new_buffer) return 0; // Memory allocation failed
        parser->buffer = new_buffer;
        parser->buffer_size += new_size + 1;
    }
    memcpy(&parser->buffer[parser->buffer_size - new_size - 1], contents, new_size);
    parser->buffer[parser->buffer_size] = '\0';
    return new_size;
}

int json_parser_fetch(JsonParser *parser, const char *url) {
    curl_easy_setopt(parser->handle, CURLOPT_URL, url);
    curl_easy_setopt(parser->handle, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(parser->handle, CURLOPT_WRITEDATA, parser);

    CURLcode res = curl_easy_perform(parser->handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    long response_code;
    curl_easy_getinfo(parser->handle, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP error: %ld\n", response_code);
        return -1;
    }

    return 0; // Success
}

void json_parser_cleanup(JsonParser *parser) {
    curl_easy_cleanup(parser->handle);
    free(parser->buffer);
    free(parser);
}
```

