#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int parse_binary_file(const char* input_path, const char* output_path) {
    FILE* infile = fopen(input_path, "rb");
    if (!infile) {
        perror("Failed to open input file");
        return -1;
    }

    fseek(infile, 0, SEEK_END);
    long file_size = ftell(infile);
    fseek(infile, 0, SEEK_SET);

    if (file_size == 0) {
        fprintf(stderr, "Input file size is zero\n");
        fclose(infile);
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS);
    if (!data) {
        perror("Failed to allocate memory for data");
        fclose(infile);
        return -1;
    }

    size_t elements_to_read = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (elements_to_read > MAX_ELEMENTS) {
        fprintf(stderr, "Too many elements in input file\n");
        free(data);
        fclose(infile);
        return -1;
    }

    size_t bytes_read = fread(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), elements_to_read, infile);
    if (bytes_read != elements_to_read) {
        perror("Failed to read data from input file");
        free(data);
        fclose(infile);
        return -1;
    }

    FILE* outfile = fopen(output_path, "wb");
    if (!outfile) {
        perror("Failed to open output file");
        free(data);
        fclose(infile);
        return -1;
    }

    // Populate CRCFLAG values and write to output file
    for (size_t i = 0; i < bytes_read; ++i) {
        data[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Example: random value
        fwrite(&data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, outfile);
    }

    fclose(outfile);
    free(data);
    fclose(infile);

    return 0;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, (void*)parse_binary_file, (void*)"input.bin", "output.bin") != 0) {
        perror("Failed to create thread");
        return -1;
    }

    pthread_join(thread, NULL);

    return 0;
}
