    if (num_records <= 0 || min_value > max_value || limit < 0) {
        return NULL;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));
    int total_value = 0;

    for (int i = 0; i < num_records; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        if (total_value + value > limit) {
            break;
        }
        offsets[i] = (long)i * sizeof(record);
        keys[i] = value;
        records[i].value = value;
        total_value += value;
    }

    // Handle insufficient memory
    if (i < num_records) {
        int count = i + 1 - num_records;
        for (int j = i; j >= 0 && count > 0; j--) {
            offsets[j] -= (long)count * sizeof(record);
            records[j].value -= count;
            count--;
        }
    }

    free(offsets);
    free(keys);

    return records;
}

