#define MAX_PACKETS 1000000

typedef struct {
    uint8_t src_mac[6];
    uint8_t dst_mac[6];
} MAC_HEADER;

typedef struct {
    uint16_t type;
    char payload[];
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD *payload;
} MAC_PACKET;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

MAC_PACKET *allocate_packets(int num_packets, size_t min_payload_size, size_t max_payload_size) {
    if (num_packets > MAX_PACKETS || num_packets <= 0) {
        return NULL; // Handle edge cases
    }

    MAC_PACKET *packets = (MAC_PACKET *)malloc(num_packets * sizeof(MAC_PACKET));
    if (!packets) {
        return NULL; // Handle out-of-memory condition
    }

    for (int i = 0; i < num_packets; ++i) {
        pthread_mutex_lock(&mutex);
        size_t payload_size = min_payload_size + rand() % (max_payload_size - min_payload_size + 1);
        packets[i].payload = (MAC_PAYLOAD *)malloc(sizeof(MAC_PAYLOAD) + payload_size);
        if (!packets[i].payload) {
            // Handle out-of-memory condition
            for (int j = 0; j < i; ++j) {
                free(packets[j].payload);
            }
            free(packets);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        pthread_mutex_unlock(&mutex);

        // Populate header and payload here
    }

    return packets;
}

void deallocate_packets(MAC_PACKET *packets, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}
