typedef enum {
    FORMAT_BINARY,
    FORMAT_JSON
} DataFormat;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
} ThreadSafeList;

void initialize_list(ThreadSafeList *list) {
    memset(list, 0, sizeof(*list));
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(ThreadSafeList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->lock);
}

int add_element(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }
    list->data[list->count++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(ThreadSafeList *list, DataFormat format, char *buffer, size_t buffer_size) {
    pthread_mutex_lock(&list->lock);
    if (format == FORMAT_BINARY) {
        // Implement binary serialization logic here
        // Example: memcpy(buffer, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else if (format == FORMAT_JSON) {
        // Implement JSON serialization logic here
        // Example: snprintf(buffer, buffer_size, "[...]");
    }
    pthread_mutex_unlock(&list->lock);
}

void* producer_thread(void *arg) {
    ThreadSafeList *list = (ThreadSafeList *)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(*element));
        if (!element) break; // Out of memory
        // Populate element with data
        add_element(list, element);
        usleep(1000); // Simulate data generation frequency
    }
    return NULL;
}

void* consumer_thread(void *arg) {
    ThreadSafeList *list = (ThreadSafeList *)arg;
    while (1) {
        pthread_mutex_lock(&list->lock);
        if (list->count > 0) {
            NFAPI_CRC_INDICATION_PDU_T *element = list->data[--list->count];
            // Process element
            free(element);
        }
        pthread_mutex_unlock(&list->lock);
        usleep(500); // Simulate data processing frequency
    }
    return NULL;
}

int main() {
    ThreadSafeList list;
    initialize_list(&list);

    pthread_t producer, consumer;
    pthread_create(&producer, NULL, producer_thread, &list);
    pthread_create(&consumer, NULL, consumer_thread, &list);

    pthread_join(producer, NULL);
    pthread_join(consumer, NULL);

    destroy_list(&list);
    return 0;
}
