        for (int j = 0; j < 6; j++) {
            packet->header.sourceMAC[j] = rand() % 256;
            packet->header.destinationMAC[j] = rand() % 256;
        }

        // Set random Ethernet frame type
        packet->header.type = (rand() % 3) + 1; // Example types: IPv4, ARP, ICMP

        // Generate random payload length within a specified range
        int payload_length = (rand() % (1500 - 68)) + 68; // Min Payload Length: 68 bytes for Ethernet Header
        packet->payload.data[0] = payload_length;

        // Populate the payload with random data
        for (int j = 1; j < payload_length; j++) {
            packet->payload.data[j] = rand() % 256;
        }
    }

    return NULL;
}

