#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    FAILURE
} Status;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t mutex;
} PoolAllocator;

Status init_pool_allocator(PoolAllocator* allocator, size_t initial_size) {
    allocator->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!allocator->pool) {
        return FAILURE;
    }
    allocator->allocated_size = initial_size;
    allocator->used_count = 0;
    pthread_mutex_init(&allocator->mutex, NULL);
    return SUCCESS;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(PoolAllocator* allocator) {
    pthread_mutex_lock(&allocator->mutex);
    if (allocator->used_count >= allocator->allocated_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(allocator->pool, 2 * allocator->allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&allocator->mutex);
            return NULL;
        }
        allocator->pool = new_pool;
        allocator->allocated_size *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* result = &allocator->pool[allocator->used_count++];
    pthread_mutex_unlock(&allocator->mutex);
    return result;
}

void free_pool_allocator(PoolAllocator* allocator) {
    pthread_mutex_destroy(&allocator->mutex);
    free(allocator->pool);
}

Status generate_crc_indications(PoolAllocator* allocator, size_t N) {
    if (N > MAX_ELEMENTS) {
        return FAILURE;
    }

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(allocator);
        if (!pdu) {
            return FAILURE;
        }
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = (uint16_t)rand();
        pdu->CRCFLAG = (uint8_t)(rand() % 256);
    }

    return SUCCESS;
}

int main() {
    srand(time(NULL));
    PoolAllocator allocator;
    if (init_pool_allocator(&allocator, 100) != SUCCESS) {
        fprintf(stderr, "Failed to initialize pool allocator\n");
        return EXIT_FAILURE;
    }

    size_t N = 5000; // Example value
    if (generate_crc_indications(&allocator, N) != SUCCESS) {
        fprintf(stderr, "Failed to generate CRC indications\n");
        free_pool_allocator(&allocator);
        return EXIT_FAILURE;
    }

    free_pool_allocator(&allocator);
    return EXIT_SUCCESS;
}
