    int id;
    GRAPH_PROPERTIES* properties;
    // Other vertex data...
} GRAPH_VERTEX;

typedef struct GRAPH_EDGE {
    int from, to;
    // Other edge data...
} GRAPH_EDGE;

GRAPH_VERTEX* vertices = NULL;
GRAPH_EDGE* edges = NULL;
int numVertices = 0, numEdges = 0;
pthread_mutex_t graphMutex = PTHREAD_MUTEX_INITIALIZER;

void populateGraphWithRandomElements(int vertexCount, int edgeCount) {
    pthread_mutex_lock(&graphMutex);

    if (vertexCount > MAX_ELEMENTS || edgeCount > MAX_ELEMENTS) {
        pthread_mutex_unlock(&graphMutex);
        return; // Handle error: too many elements
    }

    vertices = realloc(vertices, vertexCount * sizeof(GRAPH_VERTEX));
    edges = realloc(edges, edgeCount * sizeof(GRAPH_EDGE));

    if (!vertices || !edges) {
        pthread_mutex_unlock(&graphMutex);
        return; // Handle memory allocation failure
    }

    srand(time(NULL));

    for (int i = 0; i < vertexCount; ++i) {
        vertices[i].id = i;
        vertices[i].properties = malloc(sizeof(GRAPH_PROPERTIES));
        if (!vertices[i].properties) {
            pthread_mutex_unlock(&graphMutex);
            return; // Handle memory allocation failure
        }
        vertices[i].properties->size = rand() % 100 + 1; // Random size between 1 and 100
    }

    for (int i = 0; i < edgeCount; ++i) {
        edges[i].from = rand() % vertexCount;
        edges[i].to = rand() % vertexCount;
    }

    numVertices = vertexCount;
    numEdges = edgeCount;

    pthread_mutex_unlock(&graphMutex);
}
