void compute_checksum(const char* file_path, char* digest_hex, unsigned int* digest_size) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        fclose(file);
        perror("Failed to create EVP MD context");
        return;
    }

    const EVP_MD* md_type = EVP_sha256(); // You can change this to EVP_md5() for MD5
    if (!EVP_DigestInit_ex(ctx, md_type, NULL)) {
        EVP_MD_CTX_free(ctx);
        fclose(file);
        perror("Failed to initialize digest");
        return;
    }

    unsigned char buffer[CHUNK_SIZE];
    size_t bytesRead;

    while ((bytesRead = fread(buffer, 1, CHUNK_SIZE, file)) > 0) {
        if (!EVP_DigestUpdate(ctx, buffer, bytesRead)) {
            EVP_MD_CTX_free(ctx);
            fclose(file);
            perror("Failed to update digest");
            return;
        }
    }

    if (ferror(file)) {
        EVP_MD_CTX_free(ctx);
        fclose(file);
        perror("Error reading file");
        return;
    }

    *digest_size = EVP_MD_size(md_type);
    if (!EVP_DigestFinal_ex(ctx, (unsigned char*)digest_hex, digest_size)) {
        EVP_MD_CTX_free(ctx);
        fclose(file);
        perror("Failed to finalize digest");
        return;
    }

    EVP_MD_CTX_free(ctx);
    fclose(file);
}

int main() {
    int n = 10; // Example value
    NFAPI_CRC_INDICATION_PDU_T* list = create_and_populate_nfaapi_list(n);

    char digest_hex[65]; // Enough space for SHA-256 hex string
    unsigned int digest_size;
    compute_checksum("path_to_your_file", digest_hex, &digest_size);

    printf("Checksum: %.*s\n", (int)digest_size * 2, digest_hex);

    free(list);
    return 0;
}
