    if (!file) return NULL;

    unsigned char* buffer = (unsigned char*)malloc(chunk_size);
    unsigned char hash[EVP_MAX_MD_SIZE];
    int hash_len;

    EVP_MD_CTX* md_ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(md_ctx, evp_md, NULL);

