    EVP_MD_CTX_free(md_ctx);

    free(buffer);
    fclose(file);

    unsigned char* digest = (unsigned char*)malloc(hash_len * 2 + 1);
    for (int i = 0; i < hash_len; i++) {
        snprintf((char*)&digest[i * 2], 3, "%02x", hash[i]);
