#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <openssl/md5.h>
#include <pthread.h>

#define MAX_FILE_PATH_LENGTH 256
#define DEFAULT_CHUNK_SIZE 4096

typedef struct {
    int RNTI;
    // Other necessary fields for NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate random CRCFLAG
unsigned char generate_random_crcflag() {
    return (unsigned char)rand();
}

// Function to compute checksum using SHA-256 algorithm
void compute_sha256_checksum(const char *file_path, unsigned char *output_buffer) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    char buffer[DEFAULT_CHUNK_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        SHA256_Update(&sha256, buffer, bytes_read);
    }

    fclose(file);
    SHA256_Final(output_buffer, &sha256);
}

// Function to compute checksum using MD5 algorithm
void compute_md5_checksum(const char *file_path, unsigned char *output_buffer) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[DEFAULT_CHUNK_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    fclose(file);
    MD5_Final(output_buffer, &md5);
}

// Main function to generate list of NFAPI_CRC_INDICATION_PDU_T structures and compute checksum
int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file_path> <hash_algorithm>\n", argv[0]);
        return 1;
    }

    const char *file_path = argv[1];
    const char *hash_algorithm = argv[2];
    unsigned char output_buffer[SHA256_DIGEST_LENGTH];

    NFAPI_CRC_INDICATION_PDU_T crc_indication_pdu;
    crc_indication_pdu.RNTI = 1234; // Example RNTI value

    if (strcmp(hash_algorithm, "sha256") == 0) {
        compute_sha256_checksum(file_path, output_buffer);
    } else if (strcmp(hash_algorithm, "md5") == 0) {
        compute_md5_checksum(file_path, output_buffer);
    } else {
        fprintf(stderr, "Unsupported hash algorithm: %s\n", hash_algorithm);
        return 1;
    }

    // Print the hexadecimal digest of the computed checksum
    printf("Checksum: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", output_buffer[i]);
    }
    printf("\n");

    return 0;
}
