        snprintf(packets[i].dest_ip, sizeof(packets[i].dest_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        packets[i].src_port = (unsigned short)(rand() % 65536);
        packets[i].dst_port = (unsigned short)(rand() % 65536);

        int payload_length = rand() % max_payload_size;
        for (int j = 0; j < payload_length; j++) {
            packets[i].payload[j] = (char)('a' + rand() % ('z' - 'a' + 1));
        }
        packets[i].payload[payload_length] = '\0';
    }

    return packets;
}

