MAC_PDU* dynamic_list[MAX_LIST_SIZE];
int list_size = 0;
pthread_mutex_t global_mutex;

void init_dynamic_list() {
    pthread_mutex_init(&global_mutex, NULL);
}

int allocate_mac_pdu(int header_size, int info_size) {
    if (list_size >= MAX_LIST_SIZE) return -1;

    MAC_PDU* new_pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!new_pdu) return -1;

    pthread_mutex_init(&new_pdu->mutex, NULL);

    // Allocate memory for MAC_HEADER and TRANSPORT_FORMAT_INFO based on configuration
    new_pdu->header = (MAC_HEADER){0};
    new_pdu->payload = (MAC_PAYLOAD){0};
    new_pdu->info.SEQUENCE_NUMBER = 0;
    new_pdu->info.SCHEDULE_REQUEST = 0;

    pthread_mutex_lock(&global_mutex);
    dynamic_list[list_size++] = new_pdu;
    pthread_mutex_unlock(&global_mutex);

    return list_size - 1;
}

void cleanup_unused_structures() {
    for (int i = 0; i < list_size; ++i) {
        if (dynamic_list[i]) {
            pthread_mutex_lock(&dynamic_list[i]->mutex);
            // Free or recycle the structure
            free(dynamic_list[i]);
            dynamic_list[i] = NULL;
            pthread_mutex_unlock(&dynamic_list[i]->mutex);
