#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 4096

typedef struct {
    FILE *log_file;
    pthread_mutex_t mutex;
    int log_level;
} Logger;

Logger logger = {NULL, PTHREAD_MUTEX_INITIALIZER, LOG_INFO};

void init_logger(const char *filename, int level) {
    logger.log_file = fopen(filename, "a");
    if (logger.log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    logger.log_level = level;
}

void safe_log(const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&logger.mutex);
    if (vsnprintf(NULL, 0, format, args) < MAX_LOG_SIZE) {
        vfprintf(logger.log_file, format, args);
        fprintf(logger.log_file, "\n");
        fflush(logger.log_file);
    } else {
        fprintf(stderr, "Log message too large\n");
    }
    va_end(args);

    pthread_mutex_unlock(&logger.mutex);
}

void log_message(int level, const char *format, ...) {
    if (level >= logger.log_level) {
        va_list args;
        va_start(args, format);
        safe_log(format, args);
        va_end(args);
    }
}
```
