import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class ConfigModifier {

    public static void modifyKickstartConfig(HashMap<String, String> placeholders, Pokemon pokemon) throws IOException, InterruptedException {
        File configFile = new File("kickstart.cfg");
        FileWriter writer = new FileWriter(configFile);

        for (Map.Entry<String, String> entry : placeholders.entrySet()) {
            String command = "sed -i 's/" + entry.getKey() + "/" + entry.getValue() + "/' kickstart.cfg";
            Process process = Runtime.getRuntime().exec(command);
            if (process.waitFor() != 0) {
                throw new IOException("Error occurred while replacing placeholder: " + entry.getKey());
            }
        }

        String weaknesses = getWeaknesses(pokemon);
        writer.write(weaknesses);

        writer.close();
    }

    private static String getWeaknesses(Pokemon pokemon) throws IOException, InterruptedException {
        String command = "getPokemonType.sh " + pokemon.getType() + " " + pokemon.getName();
        Process process = Runtime.getRuntime().exec(command);
        process.waitFor();

        return new String(process.getInputStream().readAllBytes());
    }

    private static String getMD5Hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hash = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("MD5 hashing algorithm not found.");
            return null;
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            HashMap<String, String> placeholders = new HashMap<>();
            placeholders.put("${USERNAME}", "admin");
            placeholders.put("${PASSWORD}", "password123");

            Pokemon pokemon = new Pokemon("Fire", "Pikachu");

            modifyKickstartConfig(placeholders, pokemon);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    static class Pokemon {
        private String type;
        private String name;

        public Pokemon(String type, String name) {
            this.type = type;
            this.name = name;
        }

        public String getType() {
            return type;
        }

        public String getName() {
            return name;
        }
    }
}
