#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_CAPACITY 1024

typedef struct {
    char data[MAX_CAPACITY];
    size_t used;
    pthread_mutex_t mutex;
} ThreadSafeStore;

void init_store(ThreadSafeStore *store) {
    store->used = 0;
    pthread_mutex_init(&store->mutex, NULL);
}

int store_data(ThreadSafeStore *store, const char *data, size_t len) {
    if (len > MAX_CAPACITY - store->used) return -1; // Check for capacity limit
    pthread_mutex_lock(&store->mutex);
    memcpy(store->data + store->used, data, len);
    store->used += len;
    pthread_mutex_unlock(&store->mutex);
    return 0;
}

void compact_store(ThreadSafeStore *store) {
    pthread_mutex_lock(&store->mutex);
    memmove(store->data, store->data + (MAX_CAPACITY - store->used), store->used);
    pthread_mutex_unlock(&store->mutex);
}

int backup_store(const ThreadSafeStore *store, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;
    fwrite(store->data, 1, store->used, file);
    fclose(file);
    return 0;
}

int restore_store(ThreadSafeStore *store, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;
    fseek(file, 0, SEEK_END);
    size_t len = ftell(file);
    fseek(file, 0, SEEK_SET);
    pthread_mutex_lock(&store->mutex);
    if (len > MAX_CAPACITY) {
        fclose(file);
        return -1; // File too large
    }
    fread(store->data, 1, len, file);
    store->used = len;
    pthread_mutex_unlock(&store->mutex);
    fclose(file);
    return 0;
}
