use std::sync::{Arc, Mutex};

struct APIClient {
    client: Client,
    cache: Arc<Mutex<HashMap<String, Value>>>,
}

impl APIClient {
    fn new() -> Self {
        APIClient {
            client: Client::new(),
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn fetch_and_process_data(&self, url: &str, schema: Option<&Value>) -> Result<Value, reqwest::Error> {
        // Validate URL and make request
        let response = self.client.get(url).send().await?;
        let status = response.status();
        log_request!(url, status);

        if !status.is_success() {
            return Err(reqwest::Error::from(status));
        }

        // Cache the response
        let json_response: Value = from_str(&response.text().await?)?;
        let key = format!("{}{}", url, schema.map_or("".to_string(), |s| s.to_string()));
        self.cache.lock().unwrap().insert(key.clone(), json_response.clone());
        log_cache!(key);

        // Parse and validate JSON data
        let parsed_data: Value = if let Some(schema) = schema {
            validate_and_transform(&json_response, schema)?
        } else {
            json_response
        };

        Ok(parsed_data)
    }
}

fn log_request(url: &str, status: reqwest::StatusCode) {
    println!("Request to {} resulted in status {}", url, status);
}

fn log_cache(key: &str) {
    println!("Cached response for key {}", key);
}

