#include <vector>
#include <algorithm>

void replaceOrInsert(std::vector<int>& vec, int target, int newVal, bool isSorted = false) {
    if (isSorted) {
        auto it = std::find(vec.begin(), vec.end(), target);
        if (it != vec.end()) {
            *it = newVal;
        } else {
            vec.insert(std::lower_bound(vec.begin(), vec.end(), newVal), newVal);
        }
    } else {
        auto it = std::find(vec.begin(), vec.end(), target);
        if (it != vec.end()) {
            *it = newVal;
        } else {
            vec.push_back(newVal);
        }
    }
}
