        switch (level) {
            case LogLevel::DEBUG:
                return "[DEBUG] ";
            case LogLevel::INFO:
                return "[INFO]  ";
            case LogLevel::WARNING:
                return "[WARN]  ";
            case LogLevel::ERROR:
