using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class GameEngineInitializer
{
    private JObject _config;
    private ILogger _logger;

    public GameEngineInitializer(ILogger logger)
    {
        _logger = logger;
        LoadConfig("config.json");
    }

    private void LoadConfig(string filePath)
    {
        try
        {
            string configText = File.ReadAllText(filePath);
            _config = JObject.Parse(configText);
            _logger.LogInfo("Configuration loaded successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to load configuration: {ex.Message}");
        }
    }

    public void InitializeGame()
    {
        if (_config == null)
        {
            _logger.LogError("Configuration is not initialized.");
            return;
        }

        try
        {
            int worldWidth = (int)_config["WorldWidth"];
            int worldHeight = (int)_config["WorldHeight"];
            int playerX = (int)_config["PlayerStart"]["X"];
            int playerY = (int)_config["PlayerStart"]["Y"];
            float gravity = (float)_config["Physics"]["Gravity"];

            _logger.LogInfo($"Initializing game with dimensions: {worldWidth}x{worldHeight}");
            _logger.LogInfo($"Player starting position: ({playerX}, {playerY})");
            _logger.LogInfo($"Physics parameters: Gravity = {gravity}");

            // Initialize game world and player
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error initializing game: {ex.Message}");
        }
    }

    public void UpdateConfig(string key, JToken value)
    {
        try
        {
            _config[key] = value;
            SaveConfig("config.json");
            ApplyConfigChanges();
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to update configuration: {ex.Message}");
        }
    }

    private void SaveConfig(string filePath)
    {
        try
        {
            string configText = _config.ToString();
            File.WriteAllText(filePath, configText);
            _logger.LogInfo("Configuration saved successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to save configuration: {ex.Message}");
        }
    }

    private void ApplyConfigChanges()
    {
        // Logic to apply configuration changes dynamically
        _logger.LogInfo("Applying configuration changes...");
        InitializeGame();
    }
}

public interface ILogger
{
    void LogInfo(string message);
    void LogError(string message);
}

public class ConsoleLogger : ILogger
{
    public void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    public void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}
```

