using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Xml.Linq;

public class ElementNotFoundException : Exception
{
    public ElementNotFoundException(string message) : base(message) { }
}

public static class XmlParser
{
    private static Dictionary<string, XDocument> cache = new Dictionary<string, XDocument>();
    private static readonly object cacheLock = new object();

    public static List<XElement> GetElementsByName(string filePath, string elementName, string namespaceUri = null, bool usePrefix = false)
    {
        XDocument document;
        lock (cacheLock)
        {
            if (!cache.ContainsKey(filePath))
            {
                try
                {
                    document = XDocument.Load(filePath);
                    cache[filePath] = document;
                }
                catch (XmlException ex)
                {
                    LogError($"Failed to load XML document: {ex.Message}", filePath, ex.LineNumber, ex.LinePosition);
                    return new List<XElement>();
                }
            }
            else
            {
                document = cache[filePath];
            }
        }

        var elements = new List<XElement>();

        try
        {
            var query = namespaceUri != null ? document.Descendants(XName.Get(elementName, namespaceUri)) : document.Descendants(elementName);

            if (usePrefix)
            {
                query = from el in document.Descendants()
                        where el.Name.LocalName == elementName && el.Name.NamespaceName.Contains(namespaceUri)
                        select el;
            }

            elements.AddRange(query);
        }
        catch (Exception ex)
        {
            LogError($"XPath evaluation error: {ex.Message}", filePath, 0, 0);
        }

        if (elements.Count > 1)
        {
            throw new ElementNotFoundException("Multiple elements with the given name were found.");
        }

        return elements;
    }

    private static void LogError(string message, string filePath, int lineNumber, int linePosition)
    {
        Console.WriteLine($"{DateTime.Now}: ERROR [{filePath}]: {message} (Line {lineNumber}, Position {linePosition})");
    }
}
