<?php

class UserManager {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function manageUserAccount() {
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'] ?? '';
        $email = $_REQUEST['email'] ?? '';
        $password = $_REQUEST['password'] ?? '';
        $sub_action = $_REQUEST['sub_action'] ?? '';

        try {
            switch ($sub_action) {
                case 'create':
                    $this->createUser($id, $name, $email, $password);
                    break;
                case 'update':
                    $this->updateUser($id, $name, $email, $password);
                    break;
                case 'suspend':
                    $this->suspendUser($id);
                    break;
                case 'delete':
                    $this->deleteUser($id);
                    break;
                default:
                    throw new Exception('Invalid sub_action provided');
            }
        } catch (Exception $e) {
            error_log('Error: ' . $e->getMessage());
            http_response_code(500);
            echo json_encode(['error' => 'Internal Server Error']);
        }
    }

    private function createUser($id, $name, $email, $password) {
        // Validate input
        if (empty($name) || empty($email) || empty($password)) {
            throw new Exception('Name, email, and password are required');
        }

        // Create user in database
        $stmt = $this->db->prepare("INSERT INTO users (id, name, email, password) VALUES (?, ?, ?, ?)");
        $stmt->execute([$id, $name, $email, password_hash($password, PASSWORD_DEFAULT)]);

        // Cache the new user data
        $this->cache->set('user_' . $id, ['name' => $name, 'email' => $email], 3600);
    }

    private function updateUser($id, $name, $email, $password) {
        // Validate input
        if (empty($name) || empty($email)) {
            throw new Exception('Name and email are required');
        }

        // Update user in database
        $stmt = $this->db->prepare("UPDATE users SET name = ?, email = ? WHERE id = ?");
        $stmt->execute([$name, $email, $id]);

        // Cache the updated user data
        $this->cache->set('user_' . $id, ['name' => $name, 'email' => $email], 3600);
    }

    private function suspendUser($id) {
        // Mark user as inactive in database
        $stmt = $this->db->prepare("UPDATE users SET active = 0 WHERE id = ?");
        $stmt->execute([$id]);

        // Invalidate the cached user data
        $this->cache->delete('user_' . $id);
    }

    private function deleteUser($id) {
        // Delete user from database
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
        $stmt->execute([$id]);

        // Invalidate the cached user data
        $this->cache->delete('user_' . $id);
    }
}

// Usage example:
$db = new PDO('mysql:host=localhost;dbname=users', 'username', 'password');
$cache = new Memcached();
$cache->addServer('localhost', 11211);
$userManager = new UserManager($db, $cache);
$userManager->manageUserAccount();
?>
