#define MAX_RNTI 1000
#define RNTI_LIMIT 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_NFAPIS(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *nfapi_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_array) return NULL;

    int rnti_sum = 0;
    for (int i = 0; i < N; i++) {
        nfapi_array[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        nfapi_array[i].RNTI = rand() % MAX_RNTI + 1;
        rnti_sum += nfapi_array[i].RNTI;
        nfapi_array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set to 0 or 1

        if (rnti_sum > RNTI_LIMIT) {
            fprintf(stderr, "RNTI sum exceeds limit. Aborting.\n");
            free(nfapi_array);
            return NULL;
        }
    }

    return nfapi_array;
}

// Additional functions for serialization, caching, tiered storage, etc.
