        return result;
    }

    int num_ues = atoi(request.dynamic_content_updates); // Example: Number of UEs to allocate
    if (num_ues > 10000) {
        fprintf(stderr, "Maximum number of UEs exceeded\n");
        return result;
    }

    RNTIEntry rnti_cache[10000];
    for (int i = 0; i < 10000; i++) {
        rnti_cache[i].rnti = -1;
        rnti_cache[i].reserved = false;
    }

    result.count = num_ues;
    result.crc_indications = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_ues; i++) {
        int rnti = allocate_unique_rnti(rnti_cache, 10000);
        if (rnti == -1) {
            fprintf(stderr, "RNTI allocation failed\n");
            pthread_mutex_unlock(&mutex);
            free(result.crc_indications);
            result.crc_indications = NULL;
            result.count = 0;
            return result;
        }

        // Populate NFAPI_CRC_INDICATION_PDU_T structure
        result.crc_indications[i].rx_ue_information_tag = rnti;
        result.crc_indications[i].crc_indication_rel8_tag.crcflag = rand() % 2 == 0; // Randomly set CRCFLAG

        printf("Allocated RNTI: %d for UE\n", rnti);
    }

    pthread_mutex_unlock(&mutex);

    return result;
}

