import java.io.*;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap;

public class StateLoader {

    private static final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static Properties config = new Properties();
    private static long lastModifiedTimestamp = 0;
    private static String filePath;
    private static int versionThreshold;
    private static Thread backgroundWorker;

    public static void init(String configFile) {
        try (InputStream input = new FileInputStream(configFile)) {
            config.load(input);
            filePath = config.getProperty("file.path");
            versionThreshold = Integer.parseInt(config.getProperty("version.threshold"));
            loadStateFromCache();
            startBackgroundWorker();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static MoSTState loadState() {
        try {
            File file = new File(filePath);
            if (file.lastModified() > lastModifiedTimestamp || cache.isEmpty()) {
                synchronized (cache) {
                    if (!cache.isEmpty() && file.lastModified() <= lastModifiedTimestamp) {
                        return cache.get("current");
                    }
                    MoSTState state = loadFromFile(file);
                    if (state != null && state.getVersion() >= versionThreshold) {
                        cache.put("current", state);
                        lastModifiedTimestamp = file.lastModified();
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return cache.get("current");
    }

    private static MoSTState loadFromFile(File file) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return null;
    }

    private static void startBackgroundWorker() {
        backgroundWorker = new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(Long.parseLong(config.getProperty("background.worker.interval")));
                    loadStateFromCache();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        backgroundWorker.start();
    }

    private static void loadStateFromCache() {
        MoSTState state = loadFromFile(new File(filePath));
        if (state != null && state.getVersion() >= versionThreshold) {
            cache.put("current", state);
            lastModifiedTimestamp = new File(filePath).lastModified();
        }
    }
}
```

