function runTests(moduleName, testCases, setupFunction, teardownFunction) {
    testCases.forEach(testCase => {
        console.log(`Testing module: ${moduleName}, test case: ${testCase.label}`);

        let moduleToTest;
        try {
            moduleToTest = require(moduleName);
        } catch (e) {
            try {
                moduleToTest = require(`./fallback-path/${moduleName}`);
            } catch (err) {
                console.error(`Failed to load module or fallback path for ${moduleName}`);
                return;
            }
        }

        let asyncSetupPromise;
        if (testCase.asyncSetup) {
            asyncSetupPromise = new Promise((resolve, reject) => {
                setupFunction(() => {
                    resolve();
                }, () => {
                    reject('Async setup failed');
                });
            });
        } else {
            try {
                setupFunction();
            } catch (e) {
                console.error(`Setup function failed for test case: ${testCase.label}`);
                return;
            }
        }

        asyncSetupPromise.then(() => {
            if (testCase.requires && testCase.requires.length > 0) {
                testCase.requires.forEach(requireName => {
                    try {
                        require(requireName);
                    } catch (e) {
                        console.error(`Failed to load required module ${requireName}`);
                    }
                });
            }

            try {
                testCase.f();
            } catch (error) {
                console.error(`Test case failed: ${testCase.label}, error:`, error);
            } finally {
                teardownFunction();
                blueslip.reset(); // Reset mocking library after test completes
            }
        }).catch(error => {
            console.error('Async setup process failed:', error);
            teardownFunction();
        });
    });
}
