function categorizeEventReferences(documentText) {
  const eventTypes = {
    wars: /(?:war|battle|conflict)/gi,
    treaties: /(?:treaty|pact|alliance)/gi,
    inventions: /(?:invention|discovery|creation)/gi
  };

  const subEventTypes = {
    wars: {
      conquests: /(?:conquest|takeover|subjugation)/gi,
      skirmishes: /(?:skirmish|engagement|clash)/gi,
      sieges: /(?:siege|besiege|starvation)/gi
    },
    treaties: {
      alliances: /(?:alliance|union|compact)/gi,
      peace Treaties: /(?:peace treaty|treaty of peace|armistice)/gi,
      trade Agreements: /(?:trade agreement|pact|compact)/gi
    },
    inventions: {
      mechanicalInventions: /(?:mechanical invention|engine|machine)/gi,
      scientificBreakthroughs: /(?:scientific breakthrough|discovery|invention)/gi,
      architecturalAchievements: /(?:architectural achievement|building|structure)/gi
    }
  };

  const result = {
    wars: { conquests: 0, skirmishes: 0, sieges: 0 },
    treaties: { alliances: 0, peaceTreaties: 0, tradeAgreements: 0 },
    inventions: { mechanicalInventions: 0, scientificBreakthroughs: 0, architecturalAchievements: 0 }
  };

  const words = documentText.split(/\W+/).filter(Boolean);

  for (const word of words) {
    for (const [eventType, eventTypeRegex] of Object.entries(eventTypes)) {
      if (eventTypeRegex.test(word)) {
        for (const [subEventType, subEventTypeRegex] of Object.entries(subEventTypes[eventType])) {
          if (subEventTypeRegex.test(word)) {
            result[eventType][subEventType]++;
            break;
          }
        }
        break;
      }
    }
  }

  return result;
}
