const express = require('express');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

class ResourceService {
    constructor() {
        this.resources = [];
    }

    validate(data) {
        if (!data.name || !data.description || !data.status) {
            throw new Error('Invalid data provided');
        }
    }

    save(data) {
        // Save the resource to a database
        this.resources.push(data);
    }

    get(resourceId) {
        return this.resources.find(res => res.resource_id === resourceId);
    }

    delete(resourceId) {
        this.resources = this.resources.filter(res => res.resource_id !== resourceId);
    }
}

const resourceService = new ResourceService();

app.post('/resource', function(req, res) {
    try {
        const data = req.body;
        resourceService.validate(data);

        if (data.resource_id) {
            // Update existing resource
            const existingResource = resourceService.get(data.resource_id);
            if (!existingResource) throw new Error('Resource not found');

            Object.assign(existingResource, data);
        } else {
            // Create new resource
            data.resource_id = Date.now(); // Simple ID generation for demonstration
            resourceService.save(data);
        }

        res.json({ message: 'success' });
    } catch (error) {
        res.status(400).json({ message: error.message });
    }
});

app.delete('/resource/:id', function(req, res) {
    try {
        const resourceId = parseInt(req.params.id);
        resourceService.delete(resourceId);
        res.json({ message: 'success' });
    } catch (error) {
        res.status(400).json({ message: error.message });
    }
});

app.listen(3000, function() {
    console.log('Server is running on port 3000');
});
