class DataGraphManager {
    constructor() {
        this.graph = {};
        this.isPaused = false;
        this.dataQueue = [];
    }

    pauseDataCollection() {
        this.isPaused = true;
    }

    resumeDataCollection() {
        this.isPaused = false;
        this.processQueuedData();
    }

    addVertex(id, properties) {
        if (!this.graph[id]) {
            this.graph[id] = { ...properties };
        }
    }

   .addEdge(fromId, toId, properties) {
        if (this.graph[fromId] && this.graph[toId]) {
            this.graph[fromId][toId] = { ...properties };
        }
    }

    queueData(data) {
        if (!this.isPaused) {
            this.processData(data);
        } else {
            this.dataQueue.push(data);
        }
    }

    processData(data) {
        // Implement data processing logic here
    }

    processQueuedData() {
        while (this.dataQueue.length > 0 && !this.isPaused) {
            const data = this.dataQueue.shift();
            this.processData(data);
        }
    }
}

// Example usage:
const manager = new DataGraphManager();
manager.addVertex('A', { color: 'red' });
manager.addEdge('A', 'B', { weight: 10 });

manager.pauseDataCollection();
manager.queueData({ type: 'vertex', id: 'C', properties: { color: 'blue' } });
manager.queueData({ type: 'edge', fromId: 'A', toId: 'C', properties: { weight: 5 } });

manager.resumeDataCollection();
