function traverseDOM(selector, maxDepth = Infinity) {
  const result = [];
  let currentDepth = 0;

  function traverse(node) {
    if (currentDepth >= maxDepth) return;
    currentDepth++;
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.matches(selector)) {
        result.push({ node, attributes: Array.from(node.attributes).reduce((acc, attr) => ({ ...acc, [attr.name]: attr.value }), {}) });
