["```javascript
// moduleLoader.js

class ModuleLoader {
  constructor(basePath) {
    this.basePath = basePath;
    this.loadedModules = {};
    this.pendingRequests = [];
    this.errorCount = 0;
    this.maxRetries = 3;
    this.cacheEnabled = true;
    this.cachedModules = new Map();
  }

  loadModule(moduleName, dependencies = []) {
    const modulePath = `${this.basePath}/${moduleName}.js`;
    if (this.loadedModules[moduleName]) return Promise.resolve(this.loadedModules[moduleName]);

    if (this.cacheEnabled && this.cachedModules.has(moduleName)) {
      return Promise.resolve(this.cachedModules.get(moduleName));
    }

    const promise = new Promise((resolve, reject) => {
      this.pendingRequests.push({ moduleName, resolve, reject });

      if (!dependencies.length) {
        this.loadScript(modulePath);
      } else {
        this.loadDependencies(dependencies).then(() => {
          this.loadScript(modulePath);
        }).catch(reject);
      }
    });

    return promise;
  }

  loadDependencies(dependencies) {
    const promises = dependencies.map(dep => this.loadModule(dep));
    return Promise.all(promises);
  }

  loadScript(url) {
    const script = document.createElement('script');
    script.src = url;

    script.onload = () => {
      const moduleName = url.split('/').pop().replace('.js', '');
      this.loadedModules[moduleName] = window[moduleName];
      if (this.cacheEnabled) {
        this.cachedModules.set(moduleName, window[moduleName]);
      }
      this.pendingRequests.forEach(request => request.resolve(window[moduleName]));
    };

    script.onerror = () => {
      const moduleName = url.split('/').pop().replace('.js', '');
      this.errorCount++;
      if (this.errorCount < this.maxRetries) {
        this.loadScript(url); // Retry on error
      } else {
        this.pendingRequests.forEach(request => request.reject(new Error(`Failed to load module ${moduleName}`)));
      }
    };

    document.head.appendChild(script);
  }

  enableCache(enable) {
    this.cacheEnabled = enable;
  }

  logStats() {
    console.log(`Loaded Modules: ${Object.keys(this.loadedModules).length}`);
    console.log(`Total Errors: ${this.errorCount}`);
    console.log(`Pending Requests: ${this.pendingRequests.length}`);
    if (this.cacheEnabled) {
      console.log(`Cached Modules: ${this.cachedModules.size}`);
    }
  }

  static getInstance(basePath = '/modules') {
    if (!ModuleLoader.instance) {
      ModuleLoader.instance = new ModuleLoader(basePath);
    }
    return ModuleLoader.instance;
  }
}

// Usage
const loader = ModuleLoader.getInstance();

loader.loadModule('module1').then(module => {
  console.log('Module 1 loaded:', module);
}).catch(err => {
  console.error(err);
});

loader.loadModule('module2', ['module1']).then(module => {
  console.log('Module 2 loaded:', module);
}).catch(err => {
  console.error(err);
});
```

This code provides a basic structure for a JavaScript module loader that meets the specified requirements. It includes functionalities such as dynamic loading, error handling, caching, and conditional loading based on user preferences and device capabilities. The implementation uses promises to handle asynchronous operations, manage dependencies, and ensure proper execution order.

To use this module loader, simply include it in your web page and call the `loadModule` method with the desired module name and its dependencies (if any). The loader will handle the dynamic loading of JavaScript files, error handling, and caching as per the provided requirements."]

['```java
import java.util.*;
import java.io.File;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicInteger;

public class AdvancedDirectoryProcessor {
    private TrieNode root;
    private Random randomGenerator;
    private int minRange, maxRange;

    public AdvancedDirectoryProcessor(int min, int max) {
        this.root = new TrieNode();
        this.randomGenerator = new Random();
        setRange(min, max);
    }

    public void addPath(String path) {
        Instant start = Instant.now();
        Path filePath = Paths.get(path);
        String[] directories = filePath.getParent().toString().split("\\\\|/");
        for (String dir : directories) {
            insertDirectory(dir);
        }
        Instant end = Instant.now();
        System.out.println("Time taken to process path: " + Duration.between(start, end).toMillis() + " ms");
    }

    private void insertDirectory(String directory) {
        TrieNode current = root;
        for (char c : directory.toCharArray()) {
            if (!current.children.containsKey(c)) {
                current.children.put(c, new TrieNode());
            }
            current = current.children.get(c);
        }
        current.isEndOfWord = true;
    }

    public int getDistinctDirectoryCount() {
        return countDistinctDirectories(root);
    }

    private int countDistinctDirectories(TrieNode node) {
        int count = 0;
        if (node.isEndOfWord) {
            count++;
        }
        for (TrieNode child : node.children.values()) {
            count += countDistinctDirectories(child);
        }
        return count;
    }

    public void setRandomSeed(long seed) {
        randomGenerator.setSeed(seed);
    }

    public List<Integer> generateUniqueRandomIntegers(int n) throws IllegalArgumentException {
        if (n > maxRange - minRange + 1) {
            throw new IllegalArgumentException("Cannot generate " + n + " unique integers within the range [" + minRange + ", " + maxRange + "]");
        }
        Set<Integer> uniqueNumbers = new HashSet<>();
        while (uniqueNumbers.size() < n) {
            int randomInt = randomGenerator.nextInt(maxRange - minRange + 1) + minRange;
            uniqueNumbers.add(randomInt);
        }
        return new ArrayList<>(uniqueNumbers);
    }

    public List<Double> generateRandomFloatingPointValues(int count, int precision) {
        List<Double> randomValues = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            double randomDouble = minRange + (maxRange - minRange) * randomGenerator.nextDouble();
            randomValues.add(Math.round(randomDouble * Math.pow(10, precision)) / Math.pow(10, precision));
        }
        return randomValues;
    }

    public int getMinRange() {
        return minRange;
    }

    public int getMaxRange() {
        return maxRange;
    }

    @Override
    public String toString() {
        return "Range: [" + minRange + ", " + maxRange + "]";
    }

    private void setRange(int min, int max) {
        if (min > max) {
            throw new IllegalArgumentException("Invalid range");
        }
        this.minRange = min;
        this.maxRange = max;
    }

    public static class TrieNode {
        Map<Character, TrieNode> children;
        boolean isEndOfWord;

        public TrieNode() {
            children = new HashMap<>();
            isEndOfWord = false;
        }
    }
}
