require_once 'message_queue.php';

class UserDataProcessor {
    private $apiClients;
    private $cacheLayer;
    private $logger;
    private $recommendationEngine;
    private $messageQueue;

    public function __construct() {
        $this->apiClients = new APIClientCollection();
        $this->cacheLayer = new CacheLayer();
        $this->logger = new Logger();
        $this->recommendationEngine = new RecommendationEngine();
        $this->messageQueue = new MessageQueue();
    }

    public function processUserRecommendations($userId) {
        $userData = $this->fetchUserData($userId);
        if ($userData) {
            $recommendations = $this->generateRecommendations($userData);
            $this->storeRecommendationsInCache($userId, $recommendations);
            $this->messageQueue->enqueueMessage(['type' => 'RECOMMENDATIONS', 'data' => ['user_id' => $userId, 'recommendations' => $recommendations]]);
        }
    }

    private function fetchUserData($userId) {
        for ($i = 0; $i < 3; $i++) { // Retry up to 2 times if rate limit hit
            try {
                $userData = $this->apiClients->getPrimaryClient()->fetchUserData($userId);
                return $userData;
            } catch (RateLimitException $e) {
                sleep(1); // Wait for a second before retrying
            } catch (\Exception $e) {
                $this->logger->logError("Failed to fetch user data: " . $e->getMessage());
            }
        }

        return null; // Return null if all attempts fail
    }

    private function generateRecommendations($userData) {
        $previousFeedback = $this->cacheLayer->getPreviousUserFeedback($userData['user_id']);
        return $this->recommendationEngine->generatePersonalizedRecommendations($userData, $previousFeedback);
    }

    private function storeRecommendationsInCache($userId, $recommendations) {
        try {
            $this->cacheLayer->storeRecommendations($userId, $recommendations);
        } catch (Exception $e) {
            $this->logger->logError("Failed to cache recommendations: " . $e->getMessage());
        }
    }
}

$processor = new UserDataProcessor();
$processor->processUserRecommendations(12345);

?>
