#[derive(Clone)]
struct GrpcClient {
    channel: Channel,
    timeout: Duration,
    retries: u32,
    metadata_headers: HashMap<String, String>,
}

impl GrpcClient {
    fn new(channel: Channel, timeout: Duration, retries: u32, metadata_headers: HashMap<String, String>) -> Self {
        GrpcClient {
            channel,
            timeout,
            retries,
            metadata_headers,
        }
    }

    async fn update_config(&mut self, timeout: Option<Duration>, retries: Option<u32>, metadata_headers: Option<HashMap<String, String>>) {
        if let Some(timeout) = timeout {
            self.timeout = timeout;
        }
        if let Some(retries) = retries {
            self.retries = retries;
        }
        if let Some(metadata_headers) = metadata_headers {
            self.metadata_headers = metadata_headers;
        }
    }

    async fn call_service(&self, request: RequestType) -> Result<ResponseType, Status> {
        for _ in 0..=self.retries {
            let mut call = MyServiceClient::new(self.channel.clone()).my_method(request.clone());
            call = call.metadata(self.metadata_headers.clone());
            call = call.deadline(chrono::Utc::now() + self.timeout);
            match call.await {
                Ok(response) => return Ok(response),
                Err(e) if e.code() == Code::DeadlineExceeded || e.code() == Code::Aborted => continue,
                Err(e) => return Err(e),
            }
        }
        Err(Status::aborted("Max retries reached"))
    }
}

