use std::time::{Instant};
use memusage;
use icehook::{SyncLazy, hook_error};
use rustc_driver::{catch_with_exit_code};
use log::{info, error};
use tokio::net::TcpStream;
use futures::FutureExt;
use parking_lot::Mutex;
use crossbeam_queue::SegQueue;
use std::sync::{atomic::{AtomicBool, Ordering}, Arc};

// Function to compile a Rust project
fn compile_project(project_id: &str) -> Result<String, String> {
    // Measure the time taken for the compilation process
    let start_time = Instant::now();

    // Record memory usage before and after compilation
    let initial_memory_usage = memusage::get_resident_set_size();

    // Install an ice hook for efficient error handling
    let sync_lazy = SyncLazy::new(|| {
        hook_error(|err| {
            error!("Compilation error: {:?}", err);
        })
    });

    // Catch errors during compilation and log them
    catch_with_exit_code(|_| {
        // Simulate the compilation process
        info!("Compiling project {}...", project_id);
        Ok(())
    }).map_err(|e| format!("Compilation failed: {}", e))?;

    let end_time = Instant::now();
    let duration = end_time.duration_since(start_time);
    let final_memory_usage = memusage::get_resident_set_size();

    // Log compilation details
    info!("Compilation of project {} completed in {:?}", project_id, duration);
    info!("Initial memory usage: {} bytes", initial_memory_usage);
    info!("Final memory usage: {} bytes", final_memory_usage);

    Ok(format!("Project {} compiled successfully", project_id))
}
