<?php
// Define the function to update user profiles
function updateUserProfile($userId, $newContactInfo, $lastLoginTimestamp, $lastLoginLocation) {
    // Define an array of API endpoints
    $apiEndpoints = [
        'updateContact' => 'https://api.example.com/updateContact',
        'updateLastLogin' => 'https://api.example.com/updateLastLogin'
    ];

    // Initialize an array to store the results of each API call
    $results = [];

    // Loop through each API endpoint and make a request to update user profile data
    foreach ($apiEndpoints as $endpoint => $url) {
        // Make a cURL request to the API endpoint with the updated user profile data
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, [
            'userId' => $userId,
            'data' => $endpoint === 'updateContact' ? $newContactInfo : [
                'lastLoginTimestamp' => $lastLoginTimestamp,
                'lastLoginLocation' => $lastLoginLocation
            ]
        ]);

        // Execute the cURL request and store the response in an array
        $results[$endpoint] = curl_exec($ch);

        // Check if there was an error during the API call
        if (curl_errno($ch)) {
            // Log the error and add a failure message to the results array
            error_log('API call to ' . $url . ' failed: ' . curl_error($ch));
            $results[$endpoint] = ['success' => false, 'message' => curl_error($ch)];
        } else {
            // Check if the API call was successful and add a success message to the results array
            if ($endpoint === 'updateContact') {
                $results[$endpoint] = json_decode($results[$endpoint], true);
                $results[$endpoint]['success'] = $results[$endpoint]['status'] === 'success';
                $results[$endpoint]['message'] = $results[$endpoint]['status'];
            } else {
                $results[$endpoint] = ['success' => true, 'message' => 'Last login updated successfully'];
            }
        }

        // Close the cURL session
        curl_close($ch);
    }

    // Return a detailed success message or error report based on the completion of all API operations
    if (array_reduce($results, function ($carry, $item) { return $carry && $item['success']; }, true)) {
        return ['success' => true, 'message' => 'User profile updated successfully', 'data' => $results];
    } else {
        return ['success' => false, 'message' => 'Failed to update user profile', 'errors' => array_filter($results, function ($item) { return !$item['success']; })];
    }
}
?>
