func establishSecureConnection(clientCertPath, clientKeyPath string) (*neo4j.Driver, error) {
	tlsConfig := &tls.Config{
		Certificates: []tls.Certificate{},
		InsecureSkipVerify: false,
	}
	certPEMBlock, err := ioutil.ReadFile(clientCertPath)
	if err != nil {
		return nil, err
	}
	keyPEMBlock, err := ioutil.ReadFile(clientKeyPath)
	if err != nil {
		return nil, err
	}
	tlsCert, err := tls.X509KeyPair(certPEMBlock, keyPEMBlock)
	if err != nil {
		return nil, err
	}
	tlsConfig.Certificates = append(tlsConfig.Certificates, tlsCert)

	httpClient := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: tlsConfig,
		},
	}

	driver, _, err := neo4j.NewDriver("bolt+s://neo4j.example.com", neo4j.BasicAuth("username", "password", ""), neo4j.WithHTTPClient(httpClient))
	if err != nil {
		return nil, err
	}
	return driver, nil
}

