func addVerticesAndEdges(driver neo4j.Driver, numVertices int, vertexProps map[string]interface{}) error {
	session := driver.NewSession(neo4j.SessionConfig{AccessMode: neo4j.AccessModeWrite})
	defer session.Close()

	for i := 0; i < numVertices; i++ {
		_, err := session.Run("CREATE (v:Node {props})", map[string]interface{}{"props": vertexProps})
		if err != nil {
			return err
		}
	}

	return nil
}

func addEdges(driver neo4j.Driver, numEdges int, edgeProps map[string]interface{}) error {
	session := driver.NewSession(neo4j.SessionConfig{AccessMode: neo4j.AccessModeWrite})
	defer session.Close()

	for i := 0; i < numEdges; i++ {
		_, err := session.Run("MATCH (a:Node), (b:Node) WHERE id(a) < id(b) CREATE (a)-[:REL {props}]->(b)", map[string]interface{}{"props": edgeProps})
		if err != nil {
			return err
		}
	}

	return nil
}

func main() {
