<?php

class UserService {
    private $db;
    private $authServices;

    public function __construct($db, $authServices) {
        $this->db = $db; // Primary user database connection
        $this->authServices = $authServices; // Array of external authentication service instances
    }

    public function updatePassword($userId, $newPassword) {
        try {
            $this->validatePasswordStrength($newPassword);
            $this->updateUserPasswordInDatabase($userId, $newPassword);
            $this->notifyExternalAuthenticationServices($userId, $newPassword);

            // Log successful password update
            error_log("Password updated successfully for user ID: " . $userId);
        } catch (\Exception $e) {
            // Handle exceptions gracefully and log them
            error_log("Failed to update password for user ID " . $userId . ": " . $e->getMessage());
            throw new \Exception("Failed to update password", 500);
        }
    }

    private function validatePasswordStrength($password) {
        // Implement password strength validation logic here
        if (strlen($password) < 8 || !preg_match('/[a-z]/', $password) || !preg_match('/[A-Z]/', $password) || !preg_match('/\d/', $password)) {
            throw new \InvalidArgumentException("Password must be at least 8 characters long and include at least one uppercase, one lowercase, and one digit.");
        }
    }

    private function updateUserPasswordInDatabase($userId, $newPassword) {
        // Update password in the database with transactional integrity
        try {
            $this->db->beginTransaction();
            $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
            $stmt->execute([$newPassword, $userId]);
            $this->db->commit();
        } catch (\Exception $e) {
            // Handle database exceptions and rollback transaction
            if ($this->db->inTransaction()) {
                $this->db->rollBack();
            }
            throw new \RuntimeException("Failed to update user password in database", 500);
        }
    }

    private function notifyExternalAuthenticationServices($userId, $newPassword) {
        foreach ($this->authServices as $service) {
            try {
                $service->updateUserPassword($userId, $newPassword);
            } catch (\Exception $e) {
                // Handle external service exceptions and retry logic
                error_log("Failed to notify " . get_class($service) . " about password change for user ID: " . $userId . ": " . $e->getMessage());
            }
        }
    }

    public function __destruct() {
        // Cleanup resources if necessary
    }
}
```

