#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SLIDING_WINDOW_MINUTES 15
#define MAX_HIGH_PRIORITY_EVENTS 200
#define MAX_CONCURRENT_EVENTS 10000

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    struct Event* next;
} Event;

typedef struct HashTable {
    Event** buckets;
    size_t size;
} HashTable;

typedef struct EventManager {
    HashTable* eventTable;
    Event* queue[MAX_CONCURRENT_EVENTS];
    int front, rear;
    int highPriorityCount;
    int highestPriorityLevel;
    int highestPriorityEventID;
} EventManager;

unsigned long customHash(int id) {
    return (unsigned long)id * 2654435769; // Example hash function
}

EventManager* createEventManager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    manager->eventTable = (HashTable*)malloc(sizeof(HashTable));
    manager->eventTable->size = MAX_CONCURRENT_EVENTS;
    manager->eventTable->buckets = (Event**)calloc(MAX_CONCURRENT_EVENTS, sizeof(Event*));
    manager->front = manager->rear = -1;
    manager->highPriorityCount = 0;
    manager->highestPriorityLevel = -1;
    manager->highestPriorityEventID = -1;
    return manager;
}

void enqueue(EventManager* manager, Event* event) {
    if (manager->rear == MAX_CONCURRENT_EVENTS - 1) {
        printf("Queue is full\n");
        return;
    }
    manager->queue[++manager->rear] = event;
}

Event* dequeue(EventManager* manager) {
    if (manager->front == manager->rear) {
        printf("Queue is empty\n");
        return NULL;
    }
    return manager->queue[++manager->front];
}

void processEvent(EventManager* manager, Event* newEvent) {
    time_t now = time(NULL);
    int hashIndex = customHash(newEvent->id) % MAX_CONCURRENT_EVENTS;

    // Evict old events
    while (manager->queue[manager->front] != NULL && difftime(now, manager->queue[manager->front]->timestamp) > SLIDING_WINDOW_MINUTES * 60) {
        Event* evicted = dequeue(manager);
        free(evicted);
    }

    // Check for duplicates and update highest priority
    if (manager->eventTable->buckets[hashIndex] != NULL) {
        Event* current = manager->eventTable->buckets[hashIndex];
        while (current != NULL) {
            if (current->id == newEvent->id) {
                return; // Duplicate event, ignore
            }
            if (current->priority > newEvent->priority || (current->priority == newEvent->priority && current->id < newEvent->id)) {
                manager->highestPriorityLevel = current->priority;
                manager->highestPriorityEventID = current->id;
            }
            current = current->next;
        }
    }

    // Add new event and update hash table
    Event* newNode = (Event*)malloc(sizeof(Event));
    *newNode = *newEvent;
    newNode->next = manager->eventTable->buckets[hashIndex];
    manager->eventTable->buckets[hashIndex] = newNode;

    // Update queue and priority count
    enqueue(manager, newNode);
    if (newNode->priority > MAX_HIGH_PRIORITY_EVENTS) {
        printf("High-priority event limit exceeded\n");
        return;
    }
    manager->highPriorityCount++;

    // Update highest priority info
    if (newEvent->priority > manager->highestPriorityLevel || (newEvent->priority == manager->highestPriorityLevel && newEvent->id < manager->highestPriorityEventID)) {
        manager->highestPriorityLevel = newEvent->priority;
        manager->highestPriorityEventID = newEvent->id;
    }
}

void destroyEventManager(EventManager* manager) {
    for (int i = 0; i < MAX_CONCURRENT_EVENTS; ++i) {
        Event* current = manager->eventTable->buckets[i];
        while (current != NULL) {
            Event* next = current->next;
            free(current);
            current = next;
        }
    }
    free(manager->eventTable->buckets);
    free(manager->eventTable);
    free(manager);
}

int getHighestPriority(EventManager* manager, int* eventID) {
    *eventID = manager->highestPriorityEventID;
    return manager->highestPriorityLevel;
}
```

This code provides a basic structure for managing a real-time event feed with the specified requirements. The `EventManager` struct handles the storage and processing of events, while helper functions manage the queue, hash table, and concurrency control. The `customHash` function is an example of a custom hash function; you should replace it with your own implementation as needed.']

