    std::atomic<int> sumOfValues;
    std::mutex cacheMutex;
    std::unordered_map<int, record*> cache;

public:
    RecordManager(int limit) : sumOfValues(0) {
        // Initialize arrays and perform memory allocation
    }

    ~RecordManager() {
        // Free allocated memory
    }

    bool addRecord(int value, long offset) {
        if (sumOfValues + value > limit || records.size() >= 100000) return false;
        record* newRecord = new record{value, offset};
        records.push_back(newRecord);
        sumOfValues += value;
        updateCache(value, offset);
        return true;
    }

    void updateRecord(int index, int newValue) {
        if (index >= 0 && index < records.size()) {
            int oldValue = records[index]->value;
            sumOfValues -= oldValue;
            sumOfValues += newValue;
            records[index]->value = newValue;
            updateCache(newValue - oldValue, records[index]->offset);
        }
    }

    void removeRecord(int index) {
        if (index >= 0 && index < records.size()) {
            int valueToRemove = records[index]->value;
            sumOfValues -= valueToRemove;
            delete records[index];
            records.erase(records.begin() + index);
            updateCache(-valueToRemove, records[index]->offset);
        }
    }

    record* getRecord(int key) {
        if (key >= 0 && key < keys.size()) {
            std::lock_guard<std::mutex> lock(cacheMutex);
