import asyncio
import aiohttp
from tenacity import retry, stop_after_attempt, wait_exponential

class UserProfileTransformer:
    def __init__(self, max_concurrent_requests=10):
        self.session = aiohttp.ClientSession()
        self.max_concurrent_requests = max_concurrent_requests
        self.transformers = {}

    async def add_transformer(self, key, transformer_function):
        self.transformers[key] = transformer_function

    @retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2))
    async def fetch_data(self, url):
        try:
            async with self.session.get(url) as response:
                return await response.json()
        except aiohttp.ClientError as e:
            raise Exception(f"Failed to fetch data from {url}: {e}")

    async def transform_user_profile(self, user_profile):
        transformed = {}
        for key, transformer in self.transformers.items():
            try:
                transformed[key] = await transformer(user_profile)
            except Exception as e:
                print(f"Error applying transformer for {key}: {e}")
        return transformed

    async def process_profiles(self, profiles):
        tasks = []
        semaphore = asyncio.Semaphore(self.max_concurrent_requests)

        async def process_profile(profile):
            async with semaphore:
                return await self.transform_user_profile(profile)

        for profile in profiles:
            task = asyncio.create_task(process_profile(profile))
            tasks.append(task)
            if len(tasks) % 10 == 0:  # Batch processing to avoid overwhelming the event loop
                results = await asyncio.gather(*tasks, return_exceptions=True)
                tasks.clear()
                for result in results:
                    if isinstance(result, Exception):
                        print(f"Error during processing: {result}")

        remaining_results = await asyncio.gather(*tasks, return_exceptions=True)
        for result in remaining_results:
            if isinstance(result, Exception):
                print(f"Error during final processing: {result}")

        return [r for r in remaining_results if not isinstance(r, Exception)]

# Example usage and test cases
async def fetch_avatar(user_profile):
    url = user_profile.get('avatar_url')
    if url:
        data = await transformer.fetch_data(url)
        return {'avatar': data['url']}
    return {'avatar': None}

async def fetch_social_media(user_profile):
    url = user_profile.get('social_media_url')
    if url:
        data = await transformer.fetch_data(url)
        return {'social_media': {link['type']: link['url'] for link in data['links']}}
    return {'social_media': {}}

# Initialize the transformer
transformer = UserProfileTransformer()
await transformer.add_transformer('avatar', fetch_avatar)
await transformer.add_transformer('social_media', fetch_social_media)

# Example profiles
profiles = [
    {'name': 'Alice', 'avatar_url': 'https://example.com/avatar1.json'},
    {'name': 'Bob', 'social_media_url': 'https://example.com/social2.json'},
]

# Process profiles
transformed_profiles = await transformer.process_profiles(profiles)
print(transformed_profiles)
