#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_FIELDS 1024
#define MAX_LINE_LENGTH 8192

typedef struct {
    char *filename;
    FILE *file;
    pthread_t thread;
    int error_count;
} FileHandler;

void* process_file(void* arg) {
    FileHandler *fh = (FileHandler*)arg;
    char line[MAX_LINE_LENGTH];
    double sum = 0.0, avg = 0.0;
    int field_count = 0, numeric_fields = 0;

    while (fgets(line, sizeof(line), fh->file)) {
        char *field = strtok(line, "\t");
        while (field != NULL) {
            if (strspn(field, "0123456789.-+eE") == strlen(field)) {
                sum += atof(field);
                numeric_fields++;
            }
            field_count++;
            field = strtok(NULL, "\t");
        }

        if (numeric_fields >= 2) {
            avg = sum / numeric_fields;
            printf("%.*s\t%.6f\n", MAX_LINE_LENGTH - 15, line, avg);
        } else {
            printf("%s", line);
        }

        field_count = 0;
        numeric_fields = 0;
        sum = 0.0;
    }

    fclose(fh->file);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename> [<filename> ...]\n", argv[0]);
        return 1;
    }

    FileHandler fh[MAX_FIELDS];
    int file_count = 0;

    for (int i = 1; i < argc; i++) {
        fh[file_count].filename = argv[i];
        fh[file_count].file = fopen(argv[i], "r");
        if (fh[file_count].file == NULL) {
            perror("Error opening file");
            fh[file_count].error_count++;
            continue;
        }
        pthread_create(&fh[file_count].thread, NULL, process_file, &fh[file_count]);
        file_count++;
    }

    for (int i = 0; i < file_count; i++) {
        pthread_join(fh[i].thread, NULL);
    }

    return 0;
}
