import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class FileDeletionExecutor {
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY = 500; // milliseconds
    private static final long MAX_CUMULATIVE_RETRY_TIMEOUT = 10000; // milliseconds

    public static void main(String[] args) {
        if (args.length == 0) {
            System.err.println("Usage: java FileDeletionExecutor <file1> [<file2> ...]");
            System.exit(1);
        }

        List<String> filesToDelete = Arrays.asList(args);

        ExecutorService executor = Executors.newCachedThreadPool();
        long startRetryTime = System.currentTimeMillis();

        for (String file : filesToDelete) {
            int attempt = 0;
            while (attempt < MAX_RETRIES) {
                if (deleteFile(file, executor)) {
                    System.out.println("File deleted successfully: " + file);
                    break;
                } else {
                    attempt++;
                    long elapsedTime = System.currentTimeMillis() - startRetryTime;
                    if (elapsedTime > MAX_CUMULATIVE_RETRY_TIMEOUT) {
                        System.err.println("Maximum retry timeout reached for file: " + file);
                        break;
                    }
                    try {
                        Thread.sleep(RETRY_DELAY * (1 << attempt));
                    } catch (InterruptedException e) {
                        System.err.println("Thread interrupted while waiting to retry deletion of file: " + file);
                        break;
                    }
                }
            }
        }

        executor.shutdown();
    }

    private static boolean deleteFile(String filePath, ExecutorService executor) {
        Path path = Paths.get(filePath);

        if (!Files.exists(path)) {
            System.err.println("File does not exist: " + filePath);
            return false;
        }

        Future<Boolean> future = executor.submit(() -> {
            try {
                Files.delete(path);
                return true;
            } catch (IOException e) {
                System.err.println("Failed to delete file: " + filePath + ", error: " + e.getMessage());
                return false;
            }
        });

        try {
            return future.get(5, TimeUnit.SECONDS); // 5 seconds timeout
        } catch (TimeoutException e) {
            System.err.println("Command execution timed out for file: " + filePath);
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Error during command execution for file: " + filePath + ", error: " + e.getMessage());
        }

        return false;
    }
}
```

