using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using System.IO;
using Newtonsoft.Json.Linq;

public class UserDataProcessor
{
    private readonly string _connectionString;
    private readonly ConcurrentQueue<JObject> _recordQueue = new ConcurrentQueue<JObject>();
    private int _totalRecordsProcessed = 0;
    private int _validRecordsInserted = 0;
    private List<string> _approvedCities = GetApprovedCities();

    public UserDataProcessor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public void ProcessFilesInDirectory(string directoryPath, int batchSize = 1000)
    {
        foreach (var file in Directory.GetFiles(directoryPath, "*.json"))
        {
            try
            {
                ProcessFile(file, batchSize);
            }
            catch (Exception ex)
            {
                LogError($"Error processing file {file}: {ex.Message}");
            }
        }
    }

    private void ProcessFile(string filePath, int batchSize)
    {
        using (var reader = new StreamReader(filePath))
        using (var jsonReader = new JsonTextReader(reader))
        {
            var serializer = new JsonSerializer();
            while (jsonReader.Read())
            {
                if (jsonReader.TokenType == JsonToken.StartObject)
                {
                    _recordQueue.Enqueue(JObject.Load(jsonReader));
                }
            }

            ProcessBatch(batchSize);
        }
    }

    private void ProcessBatch(int batchSize)
    {
        int processed = 0;
        while (_recordQueue.TryDequeue(out var record) && processed < batchSize)
        {
            try
            {
                if (ValidateRecord(record))
                {
                    InsertIntoDatabase(record);
                    _validRecordsInserted++;
                }
                LogInfo($"Processed record: {record}");
            }
            catch (Exception ex)
            {
                LogError($"Validation error for record {record}: {ex.Message}");
            }

            processed++;
            _totalRecordsProcessed++;
        }
    }

    private bool ValidateRecord(JObject record)
    {
        // Implement validation logic here
        var email = (string)record["email"];
        var age = (int)record["age"];
        var location = (string)record["location"];

        return IsValidEmail(email) && age >= 18 && age <= 90 && _approvedCities.Contains(location);
    }

    private bool IsValidEmail(string email)
    {
        // Implement email validation logic here
        return System.Text.RegularExpressions.Regex.IsMatch(email, @"^\w+([-+.']\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$");
    }

    private void InsertIntoDatabase(JObject record)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var command = new SqlCommand("INSERT INTO Users (Name, Email, Age, Location) VALUES (@Name, @Email, @Age, @Location)", connection);
            command.Parameters.AddWithValue("@Name", record["name"]);
            command.Parameters.AddWithValue("@Email", record["email"]);
            command.Parameters.AddWithValue("@Age", record["age"]);
            command.Parameters.AddWithValue("@Location", record["location"]);
            command.ExecuteNonQuery();
        }
    }

    private List<string> GetApprovedCities()
    {
        // Implement dynamic schema update logic here
        return new List<string> { "New York", "Los Angeles", "Chicago" };
    }

    private void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"ERROR: {message}");
    }
}
```

