use tokio::task;
use openssl::symm::{Cipher, Crypter, Mode};
use std::env;

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <base64_encrypted_message> <key> <iv>", args[0]);
        return;
    }

    let encrypted_message = &args[1];
    let key = &args[2];
    let iv = &args[3];

    match decrypt_message(encrypted_message, key, iv).await {
        Ok(decrypted_message) => println!("Decrypted message: {}", decrypted_message),
        Err(e) => eprintln!("Error decrypting message: {}", e),
    }
}

async fn decrypt_message(encrypted_message: &str, key: &str, iv: &str) -> Result<String, Box<dyn std::error::Error>> {
    let encrypted_bytes = base64::decode(encrypted_message)?;
    let key_bytes = hex::decode(key)?;
    let iv_bytes = hex::decode(iv)?;

    let mut crypter = Crypter::new(Cipher::des_ede3_cbc(), Mode::Decrypt, &key_bytes, Some(&iv_bytes), None)?;
    crypter.pad(true);

    let mut decrypted_bytes = vec![0; encrypted_bytes.len()];
    let count = crypter.update(&encrypted_bytes, &mut decrypted_bytes)?;

    decrypted_bytes.truncate(count);
    Ok(String::from_utf8(decrypted_bytes)?)
}
