using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class StringBatchProcessor
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private const int MaxRetries = 5;

    public async Task ProcessBatchAsync(string[] inputStrings)
    {
        var tasks = inputStrings.Select(ProcessStringAsync).ToArray();
        await Task.WhenAll(tasks);
    }

    private async Task ProcessStringAsync(string inputString)
    {
        try
        {
            if (!_cache.TryGetValue(inputString, out var cachedHash))
            {
                var metadata = await GetMetadataFromApiAsync(inputString);
                var hash = ComputeMd5Hash($"{inputString}{metadata}");
                _cache.TryAdd(inputString, hash);
            }
            Console.WriteLine($"Processed: {inputString} Hash: {_cache[inputString]}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error processing {inputString}: {ex.Message}");
        }
    }

    private async Task<string> GetMetadataFromApiAsync(string inputString)
    {
        var retryCount = 0;
        while (retryCount < MaxRetries)
        {
            try
            {
                var response = await _httpClient.GetAsync($"https://api.example.com/metadata?input={inputString}");
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
            }
            catch { }

            retryCount++;
            await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
        }
        throw new InvalidOperationException("Failed to retrieve metadata from API after multiple retries.");
    }

    private string ComputeMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }
}
