    public byte[] Decrypt(byte[][] ciphertexts, byte[] key, byte[] iv, PaddingMode padding = PaddingMode.PKCS7)
    {
        if (key.Length != 16 && key.Length != 24 && key.Length != 32)
            throw new ArgumentException("Key length must be 16, 24, or 32 bytes.");

        List<byte> plaintexts = new List<byte>();

        foreach (var ciphertext in ciphertexts)
        {
            if (ciphertext.Length < 16)
                throw new ArgumentException("Ciphertexts must be at least 16 bytes long.");

            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;
                aesAlg.Padding = padding;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] plaintext = new byte[ciphertext.Length];
                        int bytesRead = csDecrypt.Read(plaintext, 0, plaintext.Length);
                        plaintexts.AddRange(plaintext.Take(bytesRead));
                    }
                }
            }
        }

        return plaintexts.ToArray();
    }

    public void CustomExceptionHandler(Exception ex)
    {
