const axios = require('axios');
const AWS = require('aws-sdk');

const s3 = new AWS.S3();

async function uploadFile(url) {
  try {
    const response = await axios.get(url, { responseType: 'stream' });
    const params = {
      Bucket: 'your-bucket-name',
      Key: `uploads/${Math.random().toString(36).substring(2, 15)}`, // Unique key for each file
      Body: response.data,
    };
    await s3.upload(params).promise();
    return `https://s3.amazonaws.com/your-bucket-name/${params.Key}`;
  } catch (error) {
    console.error(`Failed to upload ${url}:`, error.message);
    throw error;
  }
}

async function batchUpload(urls, batchSize = 50) {
  const results = [];
  for (let i = 0; i < urls.length; i += batchSize) {
    const batch = urls.slice(i, i + batchSize);
    const promises = batch.map(uploadFile);
    try {
      const uploads = await Promise.all(promises);
      results.push(...uploads);
      await new Promise(resolve => setTimeout(resolve, 100)); // Rate limiting
    } catch (error) {
      console.error('Batch upload failed:', error.message);
      return [];
    }
  }
  return results;
}

async function processFiles(urls) {
  const maxRetries = 3;
  let attempts = 0;
  while (attempts < maxRetries) {
    try {
      return await batchUpload(urls);
    } catch (error) {
      console.error('Processing failed. Retrying...');
      attempts++;
      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempts))); // Exponential backoff
    }
  }
  throw new Error('Max retries exceeded. Processing failed.');
}
