const { exec } = require('child_process');
const fs = require('fs');

function executeShellCommandWithFSA(command, states, numStates, fsa, lastStateIndex, stateListSize) {
  return new Promise((resolve, reject) => {
    try {
      exec(command, (error, stdout, stderr) => {
        if (error) {
          reject(error);
          return;
        }

        let nextStateIndex = fsa.length;
        for (let i = 0; i < numStates; i++) {
          const newState = states[i];
          if (!fsa.some(state => state === newState)) {
            fsa.push(newState);
            nextStateIndex++;
          }
        }

        if (nextStateIndex > lastStateIndex) {
          fsa[lastStateIndex].next = fsa.slice(lastStateIndex + 1, nextStateIndex);
        }

        resolve({ output: stdout, updatedStates: fsa });
      });
    } catch (error) {
      reject(error);
    }
  });
}
