use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::path::PathBuf;
use std::io;

type NodeId = String;
type DirName = String;
type Path = PathBuf;

struct DistributedFileSystem {
    state: Arc<Mutex<HashMap<NodeId, HashMap<DirName, Path>>>>,
}

impl DistributedFileSystem {
    fn new() -> Self {
        DistributedFileSystem {
            state: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn manage_directory(&self, node_id: NodeId, dir_name: DirName) -> Result<Path, io::Error> {
        let mut global_state = self.state.lock().unwrap();

        // Check if the directory already exists
        if let Some(path) = global_state.get(&node_id).and_then(|dirs| dirs.get(&dir_name)) {
            return Ok(path.clone());
        }

        // Attempt to create a new directory with a unique name
        let mut local_state = global_state.entry(node_id).or_insert_with(HashMap::new());
        let mut attempt = 0;
        loop {
            let unique_dir_name = format!("{}_{:03}", dir_name, attempt);
            if !local_state.contains_key(&unique_dir_name) {
                break;
            }
            attempt += 1;
        }

        // Simulate directory creation (this part should be replaced with actual system calls)
        let new_path = Path::new(format!("/shared_dirs/{}", unique_dir_name).as_str());
        local_state.insert(unique_dir_name, new_path.clone());

        // Set the environment variable to the path of the newly created directory
        std::env::set_var(&unique_dir_name, new_path);

        Ok(new_path)
    }
}

fn main() {
    let fs = DistributedFileSystem::new();
    match fs.manage_directory("node1".to_string(), "data_dir".to_string()) {
        Ok(path) => println!("Directory created at: {:?}", path),
        Err(e) => eprintln!("Failed to create directory: {}", e),
    }
}
