#define MAX_FILENAME_LENGTH 256

typedef struct {
    int file_count;
    int max_user_ids;
    int min_user_ids;
    double total_duration;
} Summary;

void process_file(const char* filename, Summary* summary) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[1024];
    int unique_user_ids = 0;
    double total_duration = 0;

    while (fgets(line, sizeof(line), file)) {
        // Implement logic to parse log lines and update counters
        // Example: Extract user ID and event duration from the line
        // unique_user_ids++;
        // if (valid_numeric_entry(event_duration)) {
        //     total_duration += event_duration;
        // }
    }

    fclose(file);

    summary->file_count++;
    summary->max_user_ids = (summary->max_user_ids > unique_user_ids) ? summary->max_user_ids : unique_user_ids;
    summary->min_user_ids = (summary->min_user_ids < unique_user_ids) ? summary->min_user_ids : unique_user_ids;
    summary->total_duration += total_duration;
}

void process_directory(const char* directory, Summary* summary) {
    DIR* dir = opendir(directory);
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        char filepath[MAX_FILENAME_LENGTH];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, ent->d_name);

        struct stat file_stat;
        if (lstat(filepath, &file_stat) != 0) {
            perror("Error getting file statistics");
            continue;
        }

        if (S_ISREG(file_stat.st_mode)) {
            process_file(filepath, summary);
        } else if (S_ISLNK(file_stat.st_mode)) {
            // Handle symbolic links if necessary
            printf("Symbolic link encountered: %s\n", filepath);
        }
    }

    closedir(dir);
}

void print_help() {
    printf("Usage: log_summary [OPTIONS]\n");
    printf("Options:\n");
    printf("  -d, --directory DIR   Specify a different directory for processing\n");
    printf("  --help               Display comprehensive documentation about the program's usage and options\n");
}

int main(int argc, char* argv[]) {
    if (argc > 1 && strcmp(argv[1], "--help") == 0) {
        print_help();
        return 0;
    }

    const char* directory = ".";
    if (argc > 2 && (strcmp(argv[1], "-d") == 0 || strcmp(argv[1], "--directory") == 0)) {
        directory = argv[2];
    }

    Summary summary = {0};
    process_directory(directory, &summary);

    printf("Total files processed: %d\n", summary.file_count);
    printf("Max unique user IDs: %d\n", summary.max_user_ids);
    printf("Min unique user IDs: %d\n", summary.min_user_ids);
    if (summary.file_count > 0) {
        printf("Average event duration: %.2f\n", summary.total_duration / summary.file_count);
    }

    return 0;
}
