void generateCRCIndications(int numUEs, NFAPI_CRC_INDICATION_PDU_T** pduList) {
    static const unsigned int maxRNTI = 65536; // Example maximum RNTI value
    static unsigned int currentRNTI = 1;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (numUEs > maxRNTI - currentRNTI) {
        fprintf(stderr, "Error: Not enough unique RNTIs available for the requested number of UEs.\n");
        return;
    }

    *pduList = malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pduList == NULL) {
        perror("Memory allocation failed");
        return;
    }

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < numUEs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*pduList)[i];
        // Populate RX_UE_INFORMATION_TAG and RNTI
        pdu->rnti = currentRNTI++;
        // Populate CRC_INDICATION_REL8_TAG with a random CRCFLAG
        pdu->crcFlag = rand() % 2; // Assuming CRCFLAG is a boolean or small integer type

        if (currentRNTI >= maxRNTI) {
            currentRNTI = 1; // Reset RNTI for next call
        }
    }

    pthread_mutex_unlock(&mutex);
}

void freeCRCIndications(NFAPI_CRC_INDICATION_PDU_T* pduList, int numUEs) {
    free(pduList);
}
