} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} UE_CRCS;

NFAPI_CRC_INDICATION_PDU_T* generateCRCIndications(int numUes, int *numAllocated) {
    NFAPI_CRC_INDICATION_PDU_T *indicationList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indicationList) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random RNTI generation

    int rntiPool[] = {1, 2, 3, /* ... */ 65535}; // Example RNTI pool
    int uniqueRNTIsUsed = 0;

    for (int i = 0; i < numUes; ++i) {
        if (uniqueRNTIsUsed >= sizeof(rntiPool)/sizeof(rntiPool[0])) {
            // Fallback mechanism for pseudo-unique RNTI
            indicationList[i].RX_UE_INFORMATION_TAG = i + 1;
            indicationList[i].RNTI = -1 * (i + 1); // Negative value indicates pseudo-unique
        } else {
            indicationList[i].RX_UE_INFORMATION_TAG = rntiPool[uniqueRNTIsUsed];
            ++uniqueRNTIsUsed;
        }

        indicationList[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    *numAllocated = numUes;
    return indicationList;
}

