void freeRadioBearerManager(NFPRadioBearerManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->bearers);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int allocateBearer(NFPRadioBearerManager *manager, NFAPI_RLC_BEARER_CONFIG_T *config) {
    pthread_mutex_lock(&manager->lock);
    if (manager->allocated_count >= manager->max_count && manager->free_id_count == 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No more bearers can be allocated
    }

    int id = (manager->free_id_count > 0) ? manager->free_ids[--manager->free_id_count] : manager->allocated_count++;
    config->logical_channel_id = id;
    config->rlc_instance_id = id % 256; // Example reuse strategy
    config->pdcp_sn_size = 12;
    config->pdcp_ctxt_status = 0;

    pthread_mutex_unlock(&manager->lock);
    return id;
}

void deallocateBearer(NFPRadioBearerManager *manager, int logical_channel_id) {
    pthread_mutex_lock(&manager->lock);
    if (logical_channel_id < manager->allocated_count) {
        manager->free_ids[manager->free_id_count++] = logical_channel_id;
    }
    pthread_mutex_unlock(&manager->lock);
}
