#define INITIAL_CAPACITY 1024
#define LOAD_FACTOR 0.75

typedef struct record {
    int value;
    long offset;
    int* key_ptr;
} Record;

typedef struct hash_table {
    size_t capacity;
    size_t size;
    Record** buckets;
    int* keys; // Array of keys for quick retrieval
} HashTable;

unsigned long custom_hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

void init_record(Record* rec, int value, long offset, int* key_ptr) {
    rec->value = value;
    rec->offset = offset;
    rec->key_ptr = key_ptr;
}

HashTable* create_hash_table() {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->capacity = INITIAL_CAPACITY;
    ht->size = 0;
    ht->buckets = (Record**)calloc(ht->capacity, sizeof(Record*));
    ht->keys = (int*)calloc(ht->capacity, sizeof(int));
    if (!ht->buckets || !ht->keys) {
        free(ht);
        return NULL;
    }

    srand(time(NULL));
    return ht;
}

void insert_record(HashTable* ht, int value, long offset, int key) {
    if ((double)ht->size / ht->capacity >= LOAD_FACTOR) {
        // Resize logic here
    }

    size_t index = custom_hash(key, ht->capacity);
    while (ht->buckets[index]) index = (index + 1) % ht->capacity;

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return;

    int* key_ptr = malloc(sizeof(int));
    if (!key_ptr) {
        free(new_record);
        return;
    }

    *key_ptr = key;
    init_record(new_record, value, offset, key_ptr);

    ht->buckets[index] = new_record;
    ht->keys[ht->size++] = key;
}

void iterate_and_randomize_records(HashTable* ht, int min_value, int max_value) {
    for (size_t i = 0; i < ht->size; ++i) {
        Record* rec = ht->buckets[i];
        if (rec) {
            rec->value = rand() % (max_value - min_value + 1) + min_value;
        }
    }
}

void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Record* rec = ht->buckets[i];
        if (rec) {
            free(rec->key_ptr);
            free(rec);
        }
    }

    free(ht->keys);
    free(ht->buckets);
    free(ht);
}
