#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <memory>

class ConcurrentHashMap {
public:
    struct Entry {
        std::string key;
        int value;
    };

private:
    std::unordered_map<std::string, int> map_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;

public:
    bool extend(const Entry& entry) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (map_.find(entry.key) != map_.end()) {
            return false; // Key already exists
        }
        map_[entry.key] = entry.value;
        cv_.notify_one();
        return true;
    }

    bool remove(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (map_.find(key) == map_.end()) {
            return false; // Key does not exist
        }
        map_.erase(key);
        cv_.notify_one();
        return true;
    }

    bool get(const std::string& key, int& value) const {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return false; // Key does not exist
        }
        value = it->second;
        return true;
    }

    size_t size() const {
        std::unique_lock<std::mutex> lock(mutex_);
        return map_.size();
    }
};

bool extendHashMapWithConcurrency(ConcurrentHashMap& hashMap, const ConcurrentHashMap::Entry& entry) {
    try {
        hashMap.extend(entry);
        return true;
    } catch (...) {
        return false; // Handle exceptions and maintain consistency
    }
}

int main() {
    ConcurrentHashMap hashMap;
    ConcurrentHashMap::Entry entry = {"example", 42};

    if (extendHashMapWithConcurrency(hashMap, entry)) {
        std::cout << "Extension successful!" << std::endl;
    } else {
        std::cout << "Extension failed." << std::endl;
    }

    return 0;
}
