} UDPPacket;

UDPPacket* create_udp_packets(int num_packets, int max_payload_size) {
    UDPPacket *packets = (UDPPacket *)malloc(num_packets * sizeof(UDPPacket));
    if (packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_packets; i++) {
        packets[i].src_port = rand() % 65535;
        packets[i].dest_port = rand() % 65535;
        int payload_size = rand() % max_payload_size;
        packets[i].payload = (char *)malloc(payload_size);
        if (packets[i].payload == NULL) {
            fprintf(stderr, "Memory allocation failed for packet %d\n", i);
            return NULL;
        }
        // Populate payload with random data
        memset(packets[i].payload, 'A' + rand() % 26, payload_size);
    }

    return packets;
}

void free_udp_packets(UDPPacket *packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        free(packets[i].payload);
    }
    free(packets);
}

int main() {
    const int num_packets = 10;
    const int max_payload_size = 256;

    UDPPacket *packets = create_udp_packets(num_packets, max_payload_size);
    if (packets != NULL) {
        // Use the packets
        free_udp_packets(packets, num_packets);
    }

    return 0;
}
