#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STATS 10000
#define STACK_THRESHOLD 100

typedef struct {
    int RSSI;
    float SINR;
    double BER;
} PHYSICAL_LAYER_STATS;

typedef struct {
    PHYSICAL_LAYER_STATS stats;
    uint32_t CELL_ID;
    time_t TIME_STAMP;
} LTEPHY_STATS_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = fopen("lte_stats_log.txt", "a");

LTEPHY_STATS_T* generate_statistics(int count) {
    if (count <= 0 || count > MAX_STATS) {
        fprintf(stderr, "Invalid input count: %d\n", count);
        return NULL;
    }

    LTEPHY_STATS_T *stats;
    if (count < STACK_THRESHOLD) {
        stats = alloca(sizeof(LTEPHY_STATS_T) * count);
    } else {
        stats = malloc(sizeof(LTEPHY_STATS_T) * count);
        if (!stats) {
            fprintf(stderr, "Failed to allocate memory for %d statistics\n", count);
            return NULL;
        }
    }

    pthread_mutex_lock(&mutex);
    time_t current_time;
    for (int i = 0; i < count; i++) {
        stats[i].stats.RSSI = rand() % 100;
        stats[i].stats.SINR = (float)rand() / RAND_MAX * 20.0 - 5.0;
        stats[i].stats.BER = (double)rand() / RAND_MAX;
        stats[i].CELL_ID = rand() % 1000;
        time(&current_time);
        stats[i].TIME_STAMP = current_time;

        fprintf(log_file, "Thread ID: %lu, RSSI: %d, SINR: %.2f, BER: %.6f, CELL_ID: %u, TIME_STAMP: %s",
                pthread_self(), stats[i].stats.RSSI, stats[i].stats.SINR,
                stats[i].stats.BER, stats[i].CELL_ID, ctime(&current_time));
    }
    pthread_mutex_unlock(&mutex);

    return stats;
}

void free_statistics(LTEPHY_STATS_T *stats, int count) {
    if (count >= STACK_THRESHOLD) {
        // Allocated on stack, no need to free
    } else {
        free(stats);
    }
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    LTEPHY_STATS_T **generated_stats = malloc(sizeof(LTEPHY_STATS_T *) * 10);

    for (int i = 0; i < 10; i++) {
        int count = rand() % 50 + 1;
        generated_stats[i] = generate_statistics(count);
        if (!generated_stats[i]) {
            fprintf(stderr, "Failed to generate statistics for thread %d\n", i);
            return 1;
        }
    }

    // Simulate processing
    for (int i = 0; i < 10; i++) {
        free_statistics(generated_stats[i], rand() % 50 + 1);
    }

    free(generated_stats);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);

    return 0;
}
