using System;
using System.Collections.Generic;
using System.Linq;

public class AdvancedRandomValueGenerator
{
    private Random random;
    private int minValue;
    private int maxValue;

    public AdvancedRandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Min value must be less than max value.");
        this.minValue = minValue;
        this.maxValue = maxValue;
        random = new Random();
    }

    public void SetSeed(long seed)
    {
        random = new Random(seed);
    }

    public int GetMinValue()
    {
        return minValue;
    }

    public int GetMaxValue()
    {
        return maxValue;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public List<int> GenerateUniqueRandomIntegers(int count)
    {
        if (count > (maxValue - minValue + 1))
            throw new ArgumentException("Count exceeds the range size.");

        var result = new HashSet<int>(count);
        while (result.Count < count)
        {
            result.Add(random.Next(minValue, maxValue + 1));
        }
        return result.ToList();
    }

    public double GenerateRandomDouble(double min, double max, int precision)
    {
        var range = max - min;
        var randomValue = min + (random.NextDouble() * range);
        return Math.Round(randomValue, precision);
    }
}
