using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;

public class SecureValueManager : IDisposable
{
    private RandomNumberGenerator rng;
    private RNGCryptoServiceProvider rngCsp;
    private Aes aes;
    private Camellia camellia;
    private MD5 md5;
    private SHA1 sha1;
    private SHA224 sha224;
    private SHA256 sha256;
    private SHA384 sha384;
    private SHA512 sha512;
    private ILogger logger;
    private IPerformanceMetrics performanceMetrics;

    public SecureValueManager(string seed = null)
    {
        rng = new RNGCryptoServiceProvider();
        rngCsp = new RNGCryptoServiceProvider();
        aes = Aes.Create();
        camellia = Camellia.Create();
        md5 = MD5.Create();
        sha1 = SHA1.Create();
        sha224 = SHA224.Create();
        sha256 = SHA256.Create();
        sha384 = SHA384.Create();
        sha512 = SHA512.Create();

        if (seed != null)
            rngCsp.Seed = Convert.FromBase64String(seed);

        logger = new Logger("log.txt");
        performanceMetrics = new PerformanceMetrics("performance_metrics.txt");
    }

    public int GenerateRandomInt(int min, int max)
    {
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        return BitConverter.ToInt32(randomBytes, 0) % (max - min + 1) + min;
    }

    public double GenerateRandomFloat(double min, double max)
    {
        byte[] randomBytes = new byte[8];
        rng.GetBytes(randomBytes);
        ulong randomNumber = BitConverter.ToUInt64(randomBytes, 0);
        return (randomNumber / ulong.MaxValue) * (max - min) + min;
    }

    public List<int> GenerateUniqueRandomInts(int count, int rangeStart, int rangeEnd)
    {
        if (count > (rangeEnd - rangeStart + 1))
            throw new ArgumentException("Count cannot be greater than the range size.");

        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < count)
        {
            uniqueNumbers.Add(GenerateRandomInt(rangeStart, rangeEnd));
        }

        return new List<int>(uniqueNumbers);
    }

    public byte[] Encrypt(byte[] data, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    cs.Write(data, 0, data.Length);
                }
                return ms.ToArray();
            }
        }
    }

    public byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream ms = new MemoryStream(encryptedData))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] result = new byte[encryptedData.Length];
                    int bytesRead = cs.Read(result, 0, result.Length);
                    Array.Resize(ref result, bytesRead);
                    return result;
                }
            }
        }
    }

    public void Dispose()
    {
        rng.Dispose();
        rngCsp.Dispose();
        aes.Dispose();
        camellia.Dispose();
        md5.Dispose();
        sha1.Dispose();
        sha224.Dispose();
        sha256.Dispose();
        sha384.Dispose();
        sha512.Dispose();
    }
}
