    pthread_mutex_lock(&mutex);
    srand(time(NULL));

    for (int i = 0; i < num_stats; i++) {
        snprintf(stats_array[i].tag, sizeof(stats_array[i].tag), "PHYSICAL_LAYER_STATS");
        stats_array[i].CELL_ID = rand() % 100;
        time(&stats_array[i].TIME_STAMP);
        stats_array[i].stats.RSSI = rand() % 100;
        stats_array[i].stats.SINR = (float)(rand() % 20) / 2.0f;
        stats_array[i].stats.BER = (float)(rand() % 100) / 1000.0f;
    }

    pthread_mutex_unlock(&mutex);

    *error_code = 0; // Success
    return stats_array;
}

void free_stats(LTEPHY_STATS_T* stats_array, int stack_allocated) {
    if (stack_allocated)
        free((LTEPHY_STATS_T[stack_allocated])stats_array);
    else
        free(stats_array);
}

int main() {
    int num_stats = 1500;
    LTEPHY_STATS_T *stats;
    int error_code;

    stats = generate_stats(num_stats, &error_code);
    if (error_code != 0) {
        fprintf(stderr, "Error generating statistics: %d\n", error_code);
        return 1;
    }

    // Use the generated statistics...

    free_stats(stats, 0);

    return 0;
}
```

