#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STATS 10000
#define STACK_THRESHOLD 500

typedef struct {
    int RSSI;
    float SINR;
    float BER;
} PHY_STATS;

typedef struct {
    char tag[20];
    int CELL_ID;
    time_t TIME_STAMP;
    PHY_STATS stats;
} LTEPHY_STATS_T;

void generate_stats(LTEPHY_STATS_T *stats, int count) {
    for (int i = 0; i < count; ++i) {
        strcpy(stats[i].tag, "PHYSICAL_LAYER_STATS");
        stats[i].CELL_ID = rand() % 100;
        time(&stats[i].TIME_STAMP);
        stats[i].stats.RSSI = rand() % 50 - 30; // Random RSSI between -30 and 20
        stats[i].stats.SINR = (float)rand() / RAND_MAX * 15 + 10; // SINR between 10 and 25
        stats[i].stats.BER = (float)rand() / RAND_MAX * 0.05; // BER between 0 and 0.5
    }
}

void* thread_entry(void* arg) {
    int count = *(int*)arg;
    LTEPHY_STATS_T stats[count];

    if (count > STACK_THRESHOLD) {
        LTEPHY_STATS_T *heap_stats = malloc(sizeof(LTEPHY_STATS_T) * count);
        if (!heap_stats) {
            perror("Failed to allocate memory for statistics");
            return NULL;
        }

        generate_stats(heap_stats, count);

        // Free heap allocated memory
        free(heap_stats);
    } else {
        generate_stats(stats, count);
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    int counts[] = {500, 2000, 8000, 3000}; // Example counts for demonstration

    srand(time(NULL));

    for (size_t i = 0; i < sizeof(counts) / sizeof(int); ++i) {
        if (pthread_create(&threads[i], NULL, thread_entry, &counts[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
