import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class StringHashProcessor {

    private static final int MAX_RETRIES = 3;
    private static final long TIMEOUT_THRESHOLD = 10; // milliseconds
    private static Map<String, Long> hashProcessingTimes = new HashMap<>();
    private static Set<String> uniqueHashes = new HashSet<>();

    public static void processBatch(String[] batch) {
        for (String str : batch) {
            String md5Hash = generateMD5(str);
            if (md5Hash == null) continue;
            recordProcessingTime(md5Hash, System.currentTimeMillis() - hashProcessingTimes.get(str));
            if (!uniqueHashes.add(md5Hash)) {
                int retries = 0;
                while (retries < MAX_RETRIES && !uniqueHashes.add(md5Hash)) {
                    md5Hash = generateMD5(str);
                    recordProcessingTime(md5Hash, System.currentTimeMillis() - hashProcessingTimes.get(str));
                    retries++;
                }
                if (!uniqueHashes.add(md5Hash)) {
                    logError("Duplicate MD5 hash detected after " + MAX_RETRIES + " retries: " + md5Hash);
                }
            }
        }
        logInfo("Unique hashes encountered: " + uniqueHashes.size());
    }

    private static String generateMD5(String str) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(str.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logError("Failed to generate MD5 hash: " + e.getMessage());
            return null;
        }
    }

    private static void recordProcessingTime(String hash, long processingTime) {
        if (!hashProcessingTimes.containsKey(hash)) {
            hashProcessingTimes.put(hash, System.currentTimeMillis());
        }
        if (processingTime > TIMEOUT_THRESHOLD) {
            logWarning("High processing time detected for hash: " + hash + ", time: " + processingTime + " ms");
        }
    }

    private static void logInfo(String message) {
        // Log message to third-party logging service
    }

    private static void logError(String message) {
        // Log error message to third-party logging service
    }

    private static void logWarning(String message) {
        // Log warning message to third-party logging service
    }
}
