import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.PriorityBlockingQueue;

public class StringHashProcessor {

    private static final int MAX_RETRIES = 3;
    private static final long TIMEOUT = 10; // milliseconds

    public static void processStrings(PriorityBlockingQueue<String> queue) {
        Set<String> uniqueHashes = new HashSet<>();
        MessageDigest md = null;

        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to initialize MD5 digest", e);
        }

        while (!Thread.currentThread().isInterrupted()) {
            try {
                String input = queue.poll(TIMEOUT, TimeUnit.MILLISECONDS);
                if (input == null) continue;

                int retries = 0;
                boolean success = false;

                while (retries < MAX_RETRIES && !success) {
                    long startTime = System.currentTimeMillis();
                    byte[] hashBytes = md.digest(input.getBytes());
                    String hash = bytesToHex(hashBytes);

                    if (!uniqueHashes.contains(hash)) {
                        uniqueHashes.add(hash);
                        // Log processing time
                        System.out.println("Processed in " + (System.currentTimeMillis() - startTime) + "ms");
                        success = true;
                    } else {
                        retries++;
                        Thread.sleep(100); // Delay before retrying
                    }
                }

                if (!success) {
                    // Log error message for duplicate hash detection
                    System.err.println("Failed to process string: Duplicate MD5 hash detected after " + MAX_RETRIES + " attempts");
                }

            } catch (InterruptedException | NoSuchAlgorithmException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        System.out.println("Unique hashes encountered: " + uniqueHashes.size());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public interface EventListener {
        void onEvent(String event);
    }

    public static void main(String[] args) {
        PriorityBlockingQueue<String> queue = new PriorityBlockingQueue<>();
        // Populate the queue with strings from external data source
        processStrings(queue);
    }
}
