public class FileHashProcessor {

    private static final int BATCH_SIZE = 1024; // Maximum size of a batch in bytes
    private static final int MAX_CONCURRENCY = 8; // Maximum number of concurrent threads
    private static final int RETRY_COUNT = 3; // Number of retries for failed requests

    private Set<String> knownHashes;
    private ExecutorService executorService;

    public FileHashProcessor(Set<String> initialKnownHashes) {
        this.knownHashes = new HashSet<>(initialKnownHashes);
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENCY);
    }

    public void processFiles(List<String> filePaths, Map<String, String> knownHashesDatabaseUrl,
                             Predicate<String> filterByExtension, long minSize, long maxSize) {
        List<Future<Void>> futures = new ArrayList<>();

        for (String path : filePaths) {
            if (!filterByExtension.test(path)) continue;
            File file = new File(path);
            if (file.isFile() && (minSize <= file.length() && file.length() <= maxSize)) {
                futures.add(executorService.submit(() -> processFile(file, knownHashesDatabaseUrl)));
            } else if (file.isDirectory()) {
                for (File subFile : file.listFiles()) {
                    if (!filterByExtension.test(subFile.getPath())) continue;
                    if (subFile.isFile() && (minSize <= subFile.length() && subFile.length() <= maxSize)) {
                        futures.add(executorService.submit(() -> processFile(subFile, knownHashesDatabaseUrl)));
                    }
                }
            }
        }

        for (Future<Void> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executorService.shutdown();
    }

    private void processFile(File file, Map<String, String> knownHashesDatabaseUrl) {
        byte[] fileContent = readFile(file);
        if (fileContent != null) {
            String hash = computeMD5Hash(fileContent);
            if (knownHashes.contains(hash)) {
                retrieveMetadataFromDatabase(file.getPath(), knownHashesDatabaseUrl.get(hash));
            }
        }
    }

    private byte[] readFile(File file) {
        try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(file))) {
            return bis.readNBytes((int) Math.min(BATCH_SIZE, file.length()));
        } catch (IOException e) {
            System.err.println("Error reading file: " + file.getPath());
            return null;
        }
    }

    private String computeMD5Hash(byte[] data) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(data);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            System.err.println("Error computing MD5 hash");
            return null;
        }
    }

    private void retrieveMetadataFromDatabase(String filePath, String databaseUrl) {
        // Implement logic to retrieve metadata from the database
        // Handle retries and throttling as needed
    }

    public void updateKnownHashes(Set<String> newHashes) {
        synchronized (knownHashes) {
            knownHashes.addAll(newHashes);
        }
    }

    private void logSuccessfulMatch(String filePath, String hash, Map<String, String> metadata) {
        System.out.println("File: " + filePath + ", Hash: " + hash + ", Metadata: " + metadata);
    }
}
