import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class FileProcessor {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Map<String, String> cache = new ConcurrentHashMap<>();
    private final long cacheTimeoutMillis;
    private final Callback callback;
    private final double threshold;

    public FileProcessor(long cacheTimeoutMillis, Callback callback, double threshold) {
        this.cacheTimeoutMillis = cacheTimeoutMillis;
        this.callback = callback;
        this.threshold = threshold;
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(this::cleanCache, 0, 60, TimeUnit.SECONDS);
    }

    public List<Long> processFiles(List<String> filePaths) {
        return filesToProcess(filePaths)
                .map(this::processFile)
                .flatMap(List::stream)
                .sorted()
                .filter(n -> n >= threshold)
                .collect(Collectors.toList());
    }

    private List<Future<List<Long>>> filesToProcess(List<String> filePaths) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        return filePaths.stream()
                .map(path -> CompletableFuture.supplyAsync(() -> processFile(path), executor))
                .collect(Collectors.toList());
    }

    private List<Long> processFile(String filePath) {
        Path path = Path.of(filePath);
        try {
            String md5Hash = getMd5Hash(path);
            if (cache.containsKey(md5Hash)) {
                return parseSequenceNumbers(path, cache.get(md5Hash));
            }
            // Fetch from distributed cache
            String cachedMd5Hash = fetchFromCache(md5Hash);
            cache.put(md5Hash, cachedMd5Hash);
            return parseSequenceNumbers(path, cachedMd5Hash);
        } catch (IOException | NoSuchAlgorithmException e) {
            handleException(e);
            return Collections.emptyList();
        }
    }

    private String getMd5Hash(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        Files.lines(path).forEach(digest::update);
        byte[] hashBytes = digest.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private String fetchFromCache(String md5Hash) {
        // Implement cache fetching logic
        return "known_md5_hash"; // Placeholder
    }

    private List<Long> parseSequenceNumbers(Path path, String md5Hash) throws IOException {
        long sequenceNumber = Long.parseLong(Files.lines(path).reduce((a, b) -> b).orElse(""));
        if (sequenceNumber >= threshold) {
            callback.notify(sequenceNumber);
        }
        return Collections.singletonList(sequenceNumber);
    }

    private void cleanCache() {
