import concurrent.futures
import requests
from hashlib import sha256
import logging

# Initialize logger
logging.basicConfig(level=logging.INFO)

def download_and_verify(url, reference_hash):
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()

        # Calculate SHA-256 hash of the resource
        hasher = sha256()
        for chunk in response.iter_content(chunk_size=8192):
            hasher.update(chunk)

        if hasher.hexdigest() == reference_hash:
            return True, url
        else:
            return False, url

    except requests.RequestException as e:
        logging.error(f"Failed to download {url}: {e}")
        return None, url

def fetch_metadata(url):
    try:
        response = requests.get(f"https://api.example.com/metadata?url={url}")
        response.raise_for_status()
        return response.json()

    except requests.RequestException as e:
        logging.error(f"Failed to fetch metadata for {url}: {e}")
        return None

def process_urls_concurrently(urls, reference_hashes, concurrency_level):
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency_level) as executor:
        future_to_url = {executor.submit(download_and_verify, url, hash): url for url, hash in zip(urls, reference_hashes)}

        for future in concurrent.futures.as_completed(future_to_url):
            url = future_to_url[future]
            try:
                match, verified_url = future.result()
                if match:
                    metadata = fetch_metadata(verified_url)
                    results.append((url, metadata))
            except Exception as e:
                logging.error(f"Error processing {url}: {e}")

    return results

# Example usage
urls = ["http://example.com/image.jpg", "http://example.com/video.mp4"]
reference_hashes = ["sha256_hash_for_image", "sha256_hash_for_video"]
results = process_urls_concurrently(urls, reference_hashes, concurrency_level=10)
print(results)
```

