#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char name[256];
    char type[100];
    time_t creation_date;
} Template;

typedef struct {
    Template **templates;
    int count;
    int capacity;
    pthread_mutex_t lock;
} TemplateManager;

TemplateManager* create_template_manager() {
    TemplateManager *manager = malloc(sizeof(TemplateManager));
    manager->templates = NULL;
    manager->count = 0;
    manager->capacity = 10;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_template_manager(TemplateManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->templates[i]);
    }
    free(manager->templates);
    free(manager);
}

Template* create_template(const char *name, const char *type) {
    Template *template = malloc(sizeof(Template));
    strncpy(template->name, name, sizeof(template->name) - 1);
    strncpy(template->type, type, sizeof(template->type) - 1);
    template->creation_date = time(NULL);
    return template;
}

void add_template(TemplateManager *manager, Template *template) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->templates = realloc(manager->templates, manager->capacity * sizeof(Template*));
    }
    manager->templates[manager->count++] = template;
    pthread_mutex_unlock(&manager->lock);
}

void update_template(TemplateManager *manager, const char *name, const char *type) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->templates[i]->name, name) == 0) {
            strcpy(manager->templates[i]->type, type);
            time(&manager->templates[i]->creation_date);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void delete_template(TemplateManager *manager, const char *name) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->templates[i]->name, name) == 0) {
            free(manager->templates[i]);
            for (int j = i; j < manager->count - 1; j++) {
                manager->templates[j] = manager->templates[j + 1];
            }
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

Template** get_templates(TemplateManager *manager, const char *type_filter, time_t date_filter, int *count) {
    pthread_mutex_lock(&manager->lock);
    int filtered_count = 0;
    for (int i = 0; i < manager->count; i++) {
        if ((type_filter == NULL || strcmp(manager->templates[i]->type, type_filter) == 0) &&
            (date_filter == -1 || manager->templates[i]->creation_date >= date_filter)) {
            filtered_count++;
        }
    }
    *count = filtered_count;
    Template **filtered_templates = malloc(filtered_count * sizeof(Template*));
    int j = 0;
    for (int i = 0; i < manager->count; i++) {
        if ((type_filter == NULL || strcmp(manager->templates[i]->type, type_filter) == 0) &&
            (date_filter == -1 || manager->templates[i]->creation_date >= date_filter)) {
            filtered_templates[j++] = manager->templates[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return filtered_templates;
}

void archive_old_templates(TemplateManager *manager, time_t retention_policy) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (difftime(time(NULL), manager->templates[i]->creation_date) > retention_policy) {
            free(manager->templates[i]);
            for (int j = i; j < manager->count - 1; j++) {
                manager->templates[j] = manager->templates[j + 1];
            }
            manager->count--;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
