// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int num_pdus) {
    if (num_pdus <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_pdus; i++) {
        pdu_list[i].rx_ue_information_tag.value = rand(); // Random RX_UE_INFORMATION_TAG
        pdu_list[i].rnti = rand() % 65536; // Random RNTI within valid range
        pdu_list[i].crc_indication_rel8_tag.crcflag = (rand() % 2) ? NFAPI_TRUE : NFAPI_FALSE; // Random CRCFLAG
    }

    return pdu_list;
}

// Function to serialize the list of PDUs into a binary format
int serialize_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int num_pdus, char** serialized_data, size_t* data_size) {
    if (pdu_list == NULL || num_pdus <= 0 || serialized_data == NULL || data_size == NULL) {
        return -1; // Invalid input
    }

    size_t total_size = sizeof(int) + num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *serialized_data = (char*)malloc(total_size);
    if (*serialized_data == NULL) {
        return -2; // Memory allocation failed
    }

    char* ptr = *serialized_data;
    memcpy(ptr, &num_pdus, sizeof(int)); // Store the number of PDUs first
    ptr += sizeof(int);

    for (int i = 0; i < num_pdus; i++) {
        memcpy(ptr, &pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    *data_size = total_size;
    return 0; // Success
}

// Function to deserialize the binary data back into a list of PDUs
NFAPI_CRC_INDICATION_PDU_T* deserialize_pdu_list(const char* serialized_data, size_t data_size, int* num_pdus) {
    if (serialized_data == NULL || data_size <= 0 || num_pdus == NULL) {
        return NULL; // Invalid input
    }

    const char* ptr = serialized_data;
    memcpy(num_pdus, ptr, sizeof(int)); // Extract the number of PDUs first
    ptr += sizeof(int);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < *num_pdus; i++) {
        memcpy(&pdu_list[i], ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    return pdu_list;
}

// Example usage
int main() {
    int num_pdus = 1000;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_and_populate_pdu_list(num_pdus);
    if (pdu_list == NULL) {
        fprintf(stderr, "Failed to create and populate PDU list\n");
        return 1;
    }

    char* serialized_data = NULL;
    size_t data_size;
    int serialize_result = serialize_pdu_list(pdu_list, num_pdus, &serialized_data, &data_size);
    if (serialize_result != 0) {
        fprintf(stderr, "Failed to serialize PDU list\n");
        free(pdu_list);
        return 1;
    }

    // Simulate storage or transmission
    // ...

    int deserialized_num_pdus;
    NFAPI_CRC_INDICATION_PDU_T* deserialized_pdu_list = deserialize_pdu_list(serialized_data, data_size, &deserialized_num_pdus);
    if (deserialized_pdu_list == NULL) {
        fprintf(stderr, "Failed to deserialize PDU list\n");
        free(serialized_data);
        return 1;
    }

    // Clean up
    free(pdu_list);
    free(deserialized_pdu_list);
    free(serialized_data);

    return 0;
}
