typedef enum {
    SERIALIZE,
    DESERIALIZE
} OperationType;

int create_and_manage_pdus(int N, char* serialized_data, size_t* data_size, OperationType operation) {
    int result = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;

    if (operation == SERIALIZE) {
        // Allocate memory for PDUs
        pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            result = -1; // Memory allocation failed
            goto cleanup;
        }

        // Populate PDUs with random data
        srand(time(NULL));
        for (int i = 0; i < N; i++) {
            pdus[i].ue_info = RX_UE_INFORMATION_TAG(rand());
            pdus[i].rnti = rand() % 65536;
            pdus[i].crc_indication.crcflag = (rand() % 2 == 0);
        }

        // Serialize PDUs into binary format
        zip_file_t* file = zip_fopen("pdus.zip", "w", ZIP_FL_ENC_GUESS);
        if (!file) {
            result = -1; // File open failed
            goto cleanup;
        }
        for (int i = 0; i < N; i++) {
            if (zip_file_put(file, (void*)&pdus[i], sizeof(NFAPI_CRC_INDICATION_PDU_T)) != ZIP_OK) {
                result = -1; // Serialization failed
                zip_fclose(file);
                goto cleanup;
            }
        }
        zip_fclose(file);

cleanup:
        free(pdus);
    } else if (operation == DESERIALIZE) {
        // Deserialize binary data into PDUs
        zip_file_t* file = zip_fopen(serialized_data, "r", ZIP_FL_ENC_GUESS);
        if (!file) {
            result = -1; // File open failed
            goto cleanup;
        }
        *data_size = zip_file_getsize(file);
        pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*data_size);
        if (!pdus) {
            result = -1; // Memory allocation failed
            goto cleanup;
        }
        size_t bytes_read = zip_file_get(file, (void*)pdus, *data_size);
        if (bytes_read != *data_size) {
            result = -1; // Deserialization failed
            free(pdus);
            goto cleanup;
        }
        zip_fclose(file);

        // Process PDUs as needed

cleanup:
        free(pdus);
    }

    return result;
}
