#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define DEFAULT_HEADER_SIZE sizeof(MAC_HEADER)
#define DEFAULT_TRANSPORT_FORMAT_INFO_SIZE sizeof(TRANSPORT_FORMAT_INFO)

typedef struct {
    // Define MAC_HEADER fields here
} MAC_HEADER;

typedef struct {
    // Define MAC_PAYLOAD fields here
} MAC_PAYLOAD;

typedef struct {
    uint32_t SEQUENCE_NUMBER;
    bool SCHEDULE_REQUEST;
} TRANSPORT_FORMAT_INFO;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    TRANSPORT_FORMAT_INFO transport_format_info;
} MAC_PDU;

typedef struct {
    MAC_PDU* elements[MAX_ELEMENTS];
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
    bool logging_enabled;
    int log_level;
} DynamicList;

void initDynamicList(DynamicList* list, size_t header_size, size_t transport_format_info_size) {
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->head = 0;
    list->tail = 0;
    list->logging_enabled = false;
    list->log_level = 1;
}

void enableLogging(DynamicList* list, bool enabled) {
    pthread_mutex_lock(&list->mutex);
    list->logging_enabled = enabled;
    pthread_mutex_unlock(&list->mutex);
}

void setLogLevel(DynamicList* list, int level) {
    pthread_mutex_lock(&list->mutex);
    list->log_level = level;
    pthread_mutex_unlock(&list->mutex);
}

MAC_PDU* allocateElement(DynamicList* list, size_t header_size, size_t transport_format_info_size) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    MAC_PDU* element = malloc(header_size + transport_format_info_size);
    if (!element) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    list->elements[list->tail] = element;
    list->tail = (list->tail + 1) % MAX_ELEMENTS;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return element;
}

void freeElement(DynamicList* list, MAC_PDU* element) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = list->head; i != list->tail; i = (i + 1) % MAX_ELEMENTS) {
        if (list->elements[i] == element) {
            free(element);
            list->count--;
            memmove(list->elements + i, list->elements + i + 1, sizeof(MAC_PDU*) * ((list->tail - i - 1 + MAX_ELEMENTS) % MAX_ELEMENTS));
            list->tail = (i + 1) % MAX_ELEMENTS;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void cleanupList(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = list->head; i != list->tail; i = (i + 1) % MAX_ELEMENTS) {
        free(list->elements[i]);
    }
    list->count = 0;
    list->head = 0;
    list->tail = 0;
    pthread_mutex_unlock(&list->mutex);
}
