import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public class CacheManager {
    private static ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private int ttl;
    private int bufferSize;
    private String encryptionKey;

    public CacheManager(int ttl, int bufferSize, String encryptionKey) {
        this.ttl = ttl;
        this.bufferSize = bufferSize;
        this.encryptionKey = encryptionKey;
    }

    ~CacheManager() {
        // Destructor code if needed
    }

    public void put(String key, byte[] data, long timeout) {
        cache.put(key, new CacheEntry(data, System.currentTimeMillis() + timeout));
    }

    public byte[] get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && System.currentTimeMillis() < entry.expiryTime) {
            return decrypt(entry.data);
        } else {
            cache.remove(key);
            return null;
        }
    }

    public void evictExpiredEntries() {
        long currentTime = System.currentTimeMillis();
        cache.entrySet().removeIf(entry -> entry.getValue().expiryTime < currentTime);
    }

    private byte[] encrypt(byte[] data) {
        try {
            SecretKeySpec secretKey = new SecretKeySpec(encryptionKey.getBytes(), "AES");
            IvParameterSpec ivParameterSpec = new IvParameterSpec(encryptionKey.getBytes());
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParameterSpec);
            return cipher.doFinal(data);
        } catch (Exception e) {
            // Handle encryption error
            return null;
        }
    }

    private byte[] decrypt(byte[] data) {
        try {
            SecretKeySpec secretKey = new SecretKeySpec(encryptionKey.getBytes(), "AES");
            IvParameterSpec ivParameterSpec = new IvParameterSpec(encryptionKey.getBytes());
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParameterSpec);
            return cipher.doFinal(data);
        } catch (Exception e) {
            // Handle decryption error
            return null;
        }
    }

    public static void main(String[] args) {
        CacheManager cacheManager = new CacheManager(3600, 4096, "secret");

        String filePath = "path/to/large/file";
        byte[] checksum = computeChecksum(filePath, "SHA-256", cacheManager);

        if (checksum != null) {
            System.out.println("Checksum: " + bytesToHex(checksum));
        } else {
            System.out.println("Failed to compute checksum");
        }
    }

    private static byte[] computeChecksum(String filePath, String algorithm, CacheManager cacheManager) {
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            Path path = Paths.get(filePath);

            if (!Files.exists(path)) {
                System.out.println("File does not exist");
                return null;
            }

            long fileSize = Files.size(path);
            byte[] buffer = new byte[cacheManager.bufferSize];

            try (RandomAccessFile file = new RandomAccessFile(path.toFile(), "r")) {
                for (long offset = 0; offset < fileSize; offset += cacheManager.bufferSize) {
                    int bytesRead = file.read(buffer, 0, (int) Math.min(cacheManager.bufferSize, fileSize - offset));
                    if (bytesRead == -1) {
                        break;
                    }

                    byte[] encryptedData = cacheManager.encrypt(buffer);
                    if (encryptedData != null) {
                        digest.update(encryptedData, 0, bytesRead);
                    } else {
                        return null;
                    }
                }
            }

            return digest.digest();
        } catch (Exception e) {
            // Handle error
            return null;
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

class CacheEntry {
    byte[] data;
    long expiryTime;

    public CacheEntry(byte[] data, long expiryTime) {
        this.data = data;
        this.expiryTime = expiryTime;
    }
}
