import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class HashProcessor {

    private static final int MAX_RETRIES = 5;
    private static final long CONSECUTIVE_HASH_TIMEOUT = 1000; // milliseconds
    private static final int HASH_POOL_SIZE = 100;

    private Set<String> uniqueHashes = Collections.synchronizedSet(new HashSet<>());
    private BlockingQueue<String> stringQueue = new LinkedBlockingQueue<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors() * 2);
    private MessageDigest messageDigest;
    private PriorityQueue<String> priorityQueue = new PriorityQueue<>(Comparator.comparingLong(System::currentTimeMillis));
    private MemoryPool memoryPool;

    public HashProcessor() {
        try {
            this.messageDigest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        this.memoryPool = new MemoryPool(HASH_POOL_SIZE);
    }

    public void startProcessing() {
        executorService.execute(this::processStrings);
        // Add more threads to handle data from the external source
        for (int i = 0; i < Runtime.getRuntime().availableProcessors(); i++) {
            executorService.execute(this::fetchAndEnqueueData);
        }
    }

    private void fetchAndEnqueueData() {
        while (true) {
            try {
                String nextString = fetchDataFromExternalSource();
                if (nextString == null) break;
                priorityQueue.offer(nextString);
            } catch (Exception e) {
                logError("Failed to fetch data from external source", e);
            }
        }
    }

    private void processStrings() {
        while (true) {
            try {
                String string = priorityQueue.poll(5, TimeUnit.MILLISECONDS);
                if (string == null) continue;
                hashAndProcessString(string);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void hashAndProcessString(String input) {
        int retryCount = 0;
        String currentHash = null;

        while (retryCount < MAX_RETRIES) {
            try {
                currentHash = generateSHA256(input);
                if (!uniqueHashes.add(currentHash)) {
                    throw new DuplicateHashException("Duplicate hash detected for string: " + input);
                }
                // Process the hash as required
                break;
            } catch (DuplicateHashException e) {
                retryCount++;
                if (retryCount >= MAX_RETRIES) {
                    logError(e.getMessage());
                    return;
                }
                Thread.sleep(100); // Wait before retrying
            } catch (Exception e) {
                logError("Failed to hash string", e);
                break;
            }
        }

        long processingTime = System.currentTimeMillis() - priorityQueue.peek().hashCode();
        if (processingTime < CONSECUTIVE_HASH_TIMEOUT) {
            Thread.sleep(CONSECUTIVE_HASH_TIMEOUT - processingTime);
        }
    }

    private String generateSHA256(String input) throws Exception {
        byte[] hashBytes = messageDigest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private String fetchDataFromExternalSource() throws Exception {
        // Implement data fetching logic here
        return stringQueue.poll();
    }

    private void logError(String message, Throwable e) {
        // Log the error using a third-party logging service
        System.err.println("ERROR: " + message);
        if (e != null) e.printStackTrace(System.err);
    }

    public int getUniqueHashCount() {
        return uniqueHashes.size();
    }
}

class MemoryPool {
    private byte[] pool;
    private int capacity;

    public MemoryPool(int size) {
        this.capacity = size;
        this.pool = new byte[capacity];
    }

    public synchronized byte[] allocate() {
        // Implement memory allocation logic here
        if (pool.length > 0) {
            byte[] result = Arrays.copyOf(pool, pool.length);
            pool = new byte[0];
            return result;
        }
        throw new OutOfMemoryError("Memory pool exhausted");
    }

    public synchronized void release(byte[] bytes) {
        // Implement memory release logic here
        if (pool.length + bytes.length <= capacity) {
            pool = Arrays.copyOf(pool, pool.length + bytes.length);
            System.arraycopy(bytes, 0, pool, pool.length - bytes.length, bytes.length);
        } else {
            throw new OutOfMemoryError("Memory pool overflow");
        }
    }
}

class DuplicateHashException extends Exception {
    public DuplicateHashException(String message) {
        super(message);
    }
}
