NFAPI_CRC_INDICATION_PDU_T* create_and_initialize_array(int N) {
    if (N <= 0 || N > TOTAL_LIMIT) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        return NULL;
    }

    srand(time(NULL));
    int sum_RNTI = 0;

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = (uint16_t)(sum_RNTI + rand() % MAX_RNTI);
        sum_RNTI = array[i].RNTI;

        if (sum_RNTI > TOTAL_LIMIT) {
            free(array);
            return NULL;
        }

        array[i].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2); // Randomly set CRCFLAG
    }

    return array;
}

