typedef struct {
    // Define the structure for MoSTState
} MoSTState;

MoSTState* load_state(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    MoSTState* state = malloc(sizeof(MoSTState));
    if (state == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t result = fread(state, sizeof(MoSTState), 1, file);
    if (result != 1 || !feof(file)) {
        fprintf(stderr, "Failed to read state from file\n");
        free(state);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return state;
}

int find_largest(int* array, size_t size) {
    int max = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void process_input() {
    const size_t max_size = 50000;
    int* numbers = malloc(max_size * sizeof(int));
    if (numbers == NULL) {
        perror("Memory allocation failed");
        return;
    }

    size_t count = 0;
    while (count < max_size && scanf("%d", &numbers[count]) != EOF) {
        ++count;
    }

    if (count < 100) {
        printf("Too few numbers\n");
        free(numbers);
        return;
    }

    int largest = find_largest(numbers, count);
    printf("Largest number: %d\n", largest);

    MoSTState* state = load_state("state.bin");
    if (state != NULL) {
        // Process the loaded state object
        free(state);
    } else {
        printf("Failed to load state from file\n");
    }

    free(numbers);
}

int main() {
    process_input();
    return 0;
}
