import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ScalableHttpClient {
    private final OkHttpClient client;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private int maxConnections;
    private long backoffBaseTime = 200; // milliseconds
    private double backoffFactor = 1.5;
    private static final int MAX_BACKOFF_TIME = 60000; // 1 minute

    public ScalableHttpClient(int maxConnections) {
        this.maxConnections = maxConnections;
        client = new OkHttpClient.Builder()
                .connectionPool(new ConnectionPool(maxConnections, 5, TimeUnit.MINUTES))
                .build();
    }

    public void sendRequest(Request request, final RequestCallback callback) {
        new Thread(() -> {
            for (int attempt = 0; attempt < Integer.MAX_VALUE; attempt++) {
                try (Response response = client.newCall(request).execute()) {
                    if (response.isSuccessful()) {
                        callback.onSuccess(response);
                        return;
                    } else {
                        handleFailure(callback, attempt);
                    }
                } catch (IOException e) {
                    handleFailure(callback, attempt);
                }
            }
        }).start();
    }

    private void handleFailure(RequestCallback callback, int attempt) {
        long backoffTime = Math.min(backoffBaseTime * Math.pow(backoffFactor, attempt), MAX_BACKOFF_TIME);
        scheduler.schedule(() -> sendRequest(request, callback), backoffTime, TimeUnit.MILLISECONDS);
    }

    public void setMaxConnections(int maxConnections) {
        this.maxConnections = maxConnections;
        client.connectionPool().evictAll();
        client.connectionPool().setMaxIdleConnections(maxConnections, 5, TimeUnit.MINUTES);
    }

    public interface RequestCallback {
        void onSuccess(Response response) throws IOException;
        void onError(IOException e);
    }
}
