import java.util.concurrent.TimeUnit;

public class ServiceManager {

    private ConcurrentHashMap<String, BackgroundService> services = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void startService(String serviceName) {
        if (!services.containsKey(serviceName)) {
            BackgroundService service = new BackgroundService();
            services.put(serviceName, service);
            service.start();
        }
    }

    public void stopService(String serviceName) {
        BackgroundService service = services.get(serviceName);
        if (service != null) {
            service.stop();
            services.remove(serviceName);
        }
    }

    public void monitorAndAdjustServices() {
        scheduler.scheduleAtFixedRate(() -> {
            for (BackgroundService service : services.values()) {
                if (!service.isHealthy()) {
                    restartService(service.getName());
                    sendHealthReport(service);
                }
                adjustResourceAllocation(service);
            }
        }, 0, 5, TimeUnit.MINUTES);
    }

    private void restartService(String serviceName) {
        BackgroundService oldService = services.get(serviceName);
        if (oldService != null) {
            oldService.stop();
            services.remove(serviceName);
        }
        startService(serviceName);
    }

    private void sendHealthReport(BackgroundService service) {
        // Code to send health report to monitoring system
    }

    private void adjustResourceAllocation(BackgroundService service) {
        // Code to adjust resource allocation based on metrics
    }
}

