#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/rand.h>

#define MAX_RNTI_SUM 1000
#define NUM_INSTANCES 10000000

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_init_structures(int N) {
    if (N <= 0 || N > NUM_INSTANCES) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) return NULL;

    uint32_t rnti_sum = 0;
    for (int i = 0; i < N; ++i) {
        if (RAND_bytes((unsigned char*)&structures[i].RX_UE_INFORMATION_TAG, sizeof(structures[i].RX_UE_INFORMATION_TAG)) != 1 ||
            RAND_bytes((unsigned char*)&structures[i].RNTI, sizeof(structures[i].RNTI)) != 1 ||
            RAND_bytes(&structures[i].CRCFLAG, sizeof(structures[i].CRCFLAG)) != 1) {
            free(structures);
            return NULL;
        }
        if (rnti_sum + structures[i].RNTI > MAX_RNTI_SUM) {
            free(structures);
            return NULL;
        }
        rnti_sum += structures[i].RNTI;
    }

    return structures;
}

void* thread_function(void* arg) {
    int N = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* structures = allocate_and_init_structures(N);
    if (structures) {
        // Process structures
        free(structures);
    }
    pthread_exit(NULL);
}

int main() {
    int num_threads = 10;
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        thread_args[i] = i * (NUM_INSTANCES / num_threads);
        pthread_create(&threads[i], NULL, thread_function, &thread_args[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
