TIFFImageData parse_tiff_image(const char* file_path) {
    TIFFImageData image_data = {0};
    TIFF* tif = TIFFOpen(file_path, "r");

    if (tif == NULL) {
        fprintf(stderr, "Error opening TIFF file\n");
        return image_data;
    }

    // Parse TIFF tags
    uint16 bits_per_sample;
    uint16 samples_per_pixel;
    char compression_type[256];
    int thumbnail_width = 0, thumbnail_height = 0;
    int thumbnail_bits_per_sample = 0;
    int extra_samples_count = 0;
    uint16* extra_samples_info = NULL;
    uint8 quality_level = 0;

    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    TIFFGetField(tif, TIFFTAG_COMPRESSION, compression_type, sizeof(compression_type));
    if (TIFFIsTiled(tif)) {
        // Handle tiled TIFFs
    } else {
        // Handle stripped TIFFs
    }

    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        fprintf(stderr, "Unsupported bits per sample: %d\n", bits_per_sample);
        TIFFClose(tif);
        return image_data;
    }

    // Extract thumbnail metadata
    if (TIFFGetField(tif, TIFFTAG_THUMBNAILWIDTH, &thumbnail_width)) {
        TIFFGetField(tif, TIFFTAG_THUMBNAILHEIGHT, &thumbnail_height);
        TIFFGetField(tif, TIFFTAG_THUMBNAILBITSPERSAMPLE, &thumbnail_bits_per_sample);
    }

    // Extract extra samples information
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extra_samples_count, NULL)) {
        extra_samples_info = malloc(extra_samples_count * sizeof(uint16));
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, extra_samples_count, extra_samples_info);
    }

    // Extract JPEG compression quality
    if (strcmp(compression_type, "JPEG") == 0) {
        uint32 jpeg_quality = 0;
        TIFFGetField(tif, TIFFTAG_JPEGQUALITY, &jpeg_quality);
        quality_level = (uint8)jpeg_quality;
    }

    image_data.bits_per_sample = bits_per_sample;
    image_data.samples_per_pixel = samples_per_pixel;
    image_data.compression_type = strdup(compression_type);
    image_data.thumbnail_width = thumbnail_width;
    image_data.thumbnail_height = thumbnail_height;
    image_data.thumbnail_bits_per_sample = thumbnail_bits_per_sample;
    image_data.extra_samples_count = extra_samples_count;
    image_data.extra_samples_info = extra_samples_info;
    image_data.quality_level = quality_level;

    TIFFClose(tif);
    return image_data;
}

// Add cleanup and error handling as needed
