#define MAX_BUFFER_SIZE 4096
#define LOG_FILE "application.log"
#define METRICS_FILE "metrics.log"

typedef struct {
    char* data;
    size_t length;
} DynamicString;

DynamicString* dynamic_string_init() {
    DynamicString* ds = (DynamicString*)malloc(sizeof(DynamicString));
    ds->data = NULL;
    ds->length = 0;
    return ds;
}

void dynamic_string_append(DynamicString* ds, const char* str, size_t len) {
    if (ds->length + len >= MAX_BUFFER_SIZE) {
        fprintf(stderr, "Buffer overflow detected!\n");
        return;
    }
    ds->data = realloc(ds->data, ds->length + len + 1);
    memcpy(ds->data + ds->length, str, len);
    ds->length += len;
    ds->data[ds->length] = '\0';
}

void dynamic_string_free(DynamicString* ds) {
    free(ds->data);
    free(ds);
}

int process_user_profiles(char* profiles[], size_t count, int min_age, int max_age, const char* location) {
    EVP_CIPHER* cipher = EVP_aes_256_cbc();
    EVP_MD* digest = EVP_sha256();

    FILE* log_file = fopen(LOG_FILE, "a");
    FILE* metrics_file = fopen(METRICS_FILE, "a");

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    DynamicString* filtered_profiles = dynamic_string_init();

    for (size_t i = 0; i < count; ++i) {
        struct json_object* profile = json_tokener_parse(profiles[i]);
        if (!profile) {
            fprintf(stderr, "Error parsing JSON\n");
            continue;
        }

        int age;
        const char* loc;
        struct json_object* age_obj, *loc_obj;

        json_object_object_get_ex(profile, "age", &age_obj);
        json_object_object_get_ex(profile, "location", &loc_obj);

        if (!json_object_is_type(age_obj, json_type_int) || !json_object_is_type(loc_obj, json_type_string)) {
            fprintf(stderr, "Invalid profile format\n");
            continue;
        }

        age = json_object_get_int(age_obj);
        loc = json_object_get_string(loc_obj);

        if (age >= min_age && age <= max_age && strcmp(loc, location) == 0) {
            const char* name = json_object_object_get_ex(profile, "name", NULL) ? json_object_get_string(json_object_object_get_ex(profile, "name", NULL)) : "";

            pthread_mutex_lock(&mutex);
            dynamic_string_append(filtered_profiles, "{\"name\": \"", strlen("{\"name\": \""));
            dynamic_string_append(filtered_profiles, name, strlen(name));
            dynamic_string_append(filtered_profiles, "\", \"age\": ", strlen("\", \"age\": "));
            dynamic_string_append(filtered_profiles, json_object_get_string(age_obj), strlen(json_object_get_string(age_obj)));
            dynamic_string_append(filtered_profiles, ", \"location\": \"", strlen(", \"location\": \""));
            dynamic_string_append(filtered_profiles, loc, strlen(loc));
            dynamic_string_append(filtered_profiles, "\"}\n", strlen("\"}\n"));
            pthread_mutex_unlock(&mutex);
        }

        json_object_put(profile);
    }

    // Log metrics and errors
    fprintf(metrics_file, "Total profiles processed: %zu\n", count);
    fprintf(log_file, "Filtered profiles:\n%s\n", filtered_profiles->data);

    dynamic_string_free(filtered_profiles);
    fclose(log_file);
    fclose(metrics_file);
    pthread_mutex_destroy(&mutex);

    EVP_cleanup();
    return 0;
}
