typedef struct {
    int interface_id;
    time_t timestamp;
    int payload_segments[MAX_PAYLOAD_SEGMENTS];
} NICP_Packet;

NICP_Packet* init_nicp_packets(int num_packets) {
    if (num_packets <= 0 || num_packets > 1024) {
        return NULL;
    }

    NICP_Packet* packets = (NICP_Packet*)aligned_alloc(64, num_packets * sizeof(NICP_Packet));
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_packets; i++) {
        packets[i].interface_id = rand() % 1000;
        packets[i].timestamp = time(NULL);
        for (int j = 0; j < MAX_PAYLOAD_SEGMENTS; j++) {
            packets[i].payload_segments[j] = rand();
        }
    }

    return packets;
}

void free_nicp_packets(NICP_Packet* packets, int num_packets) {
    if (packets) {
        aligned_free(packets);
    }
}

int main() {
    int num_packets = 10;
    NICP_Packet* nicp_packets = init_nicp_packets(num_packets);

    if (nicp_packets) {
        // Process packets
        free_nicp_packets(nicp_packets, num_packets);
    }

    return 0;
}
