FSAStateNode* manageFSAStateList(int* states, int numStates, FSA* fsa, int lastStateIndex, int* stateListSize) {
    FSAStateNode* newState = (FSAStateNode*)malloc(sizeof(FSAStateNode));
    if (newState == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newState->stateIndex = states[numStates - 1];
    newState->next = NULL;

    for (int i = 0; i < 256; i++) { // Adjust range based on input symbols
        newState->transitionRules[i] = fsa->currentState->transitionRules[states[numStates - 1]];
    }

    if (lastStateIndex != -1) {
        FSAStateNode* currentLastState = &fsa->currentState;
        while (currentLastState->next != NULL) {
            currentLastState = currentLastState->next;
        }
        currentLastState->next = newState;
    } else {
        fsa->currentState = newState;
    }

    *stateListSize += 1;

    return newState;
}

