int main(int argc, char *argv[]) {
    Config config = { .character_limit = 80, .output_file = NULL, .verbose_mode = 0, .thread_count = 1 };

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s --help -c <count> -o <output_file> -v\n", argv[0]);
            return 0;
        } else if (strncmp(argv[i], "-c ", 3) == 0) {
            config.character_limit = atoi(argv[i] + 3);
        } else if (strncmp(argv[i], "-o ", 3) == 0) {
            config.output_file = argv[i] + 3;
        } else if (strcmp(argv[i], "-v") == 0) {
            config.verbose_mode = 1;
        }
    }

    pthread_t threads[config.thread_count];
    for (int i = 0; i < config.thread_count; i++) {
        pthread_create(&threads[i], NULL, process_file, &config);
    }

    for (int i = 0; i < config.thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
