NICP_Packet* initialize_packets(int num_packets) {
    if (num_packets * sizeof(NICP_Packet) > MAX_PACKET_SIZE) {
        fprintf(stderr, "Error: Packet array size exceeds maximum limit.\n");
        return NULL;
    }

    NICP_Packet* packets = (NICP_Packet*)malloc(num_packets * sizeof(NICP_Packet));
    if (!packets) {
        fprintf(stderr, "Error: Memory allocation failed for packet array.\n");
        return NULL;
    }

    // Initialize packets with unique interface identifiers and timestamps
    for (int i = 0; i < num_packets; ++i) {
        packets[i].interface_id = i + 1;
        packets[i].timestamp = time(NULL);
        // Allocate memory for payload based on configurable number of segments
        packets[i].payload = malloc(sizeof(uint32_t) * 5); // Example: 5 segments
        if (!packets[i].payload) {
            fprintf(stderr, "Error: Memory allocation failed for packet payload.\n");
            free_packets(packets, i);
            return NULL;
        }
    }

    return packets;
}

void free_packets(NICP_Packet* packets, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}

void process_batch_strings(char** strings, int batch_size, uint32_t* unique_hashes) {
    *unique_hashes = 0;
    for (int i = 0; i < batch_size; ++i) {
        char hash[MD5_DIGEST_LENGTH];
        if (!generate_md5_hash(strings[i], hash)) {
            fprintf(stderr, "Error: MD5 hash generation failed for string %d.\n", i);
            continue;
        }

        // Check for duplicate hashes and retry up to three times
        int retries = 0;
        while (hash_exists(*unique_hashes, hash)) {
            if (++retries >= 3) {
                fprintf(stderr, "Error: Duplicate MD5 hash detected for string %d after %d retries.\n", i, retries);
                break;
            }
            if (!generate_md5_hash(strings[i], hash)) {
                fprintf(stderr, "Error: MD5 hash generation failed for string %d.\n", i);
                continue;
            }
        }

        // Update unique hashes count
        *unique_hashes += 1;
    }
}

int main() {
    int num_packets = 1024; // Example: 1024 packets
    NICP_Packet* packets = initialize_packets(num_packets);
    if (!packets) {
        fprintf(stderr, "Error: Failed to initialize packet array.\n");
        return EXIT_FAILURE;
    }

    char* batch[MAX_BATCH_SIZE];
    int batch_size = fill_batch(batch); // Example function to fill the batch
    if (batch_size < 0) {
        fprintf(stderr, "Error: Failed to fill batch of strings.\n");
        free_packets(packets, num_packets);
        return EXIT_FAILURE;
    }

    uint32_t unique_hashes = 0;
    time_t start_time = time(NULL);
    process_batch_strings(batch, batch_size, &unique_hashes);
    time_t end_time = time(NULL);

    printf("Total unique hashes: %u\n", unique_hashes);
    printf("Average processing time per string: %.2f seconds\n", (double)(end_time - start_time) / batch_size);
    printf("Number of retries due to hash conflicts: %d\n", get_retries_count()); // Example function to get retries count

    free_packets(packets, num_packets);

    return EXIT_SUCCESS;
}
