#include <libavformat/avformat.h>
#include <libavcodec/avcodec.h>
#include <libswscale/swscale.h>
#include <pthread.h>

typedef struct {
    AVFormatContext *input_ctx;
    AVCodecContext *encoder_ctx;
    AVStream *input_stream, *output_stream;
    int frame_rate, width, height;
    uint8_t *frame_buffer;
    size_t frame_size;
    int quality;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int pause_flag;
} VideoProcessor;

void* processVideoStream(void* arg) {
    VideoProcessor *processor = (VideoProcessor*)arg;
    AVPacket pkt;
    AVFrame *frame;
    int ret, got_output;

    frame = av_frame_alloc();
    if (!frame)
        return NULL;

    while (1) {
        pthread_mutex_lock(&processor->lock);
        while (processor->pause_flag) {
            pthread_cond_wait(&processor->cond, &processor->lock);
        }
        pthread_mutex_unlock(&processor->lock);

        ret = av_read_frame(processor->input_ctx, &pkt);
        if (ret < 0)
            break;

        if (pkt.stream_index == processor->input_stream->index) {
            ret = avcodec_send_packet(processor->encoder_ctx, &pkt);
            av_packet_unref(&pkt);
            if (ret < 0)
                break;
            while (ret >= 0) {
                ret = avcodec_receive_frame(processor->encoder_ctx, frame);
                if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)
                    break;
                else if (ret < 0) {
                    fprintf(stderr, "Error during decoding\n");
                    goto end;
                }

                // Process frame
                // ...

                av_frame_unref(frame);
            }
        } else {
            av_packet_unref(&pkt);
        }
    }

end:
    av_frame_free(&frame);
    return NULL;
}

int initializeProcessor(VideoProcessor *processor, const char *input_file, const char *output_file, int quality) {
    // Initialize FFmpeg library
    av_register_all();
    avformat_network_init();

    // Open input file
    if (avformat_open_input(&processor->input_ctx, input_file, NULL, NULL) != 0)
        return -1;

    // Find stream information
    if (avformat_find_stream_info(processor->input_ctx, NULL) < 0)
        return -2;

    // Find the first video stream in the input file
    processor->input_stream = av_find_best_stream(processor->input_ctx, AVMEDIA_TYPE_VIDEO, -1, -1, NULL, 0);
    if (processor->input_stream == -1)
        return -3;

    // Allocate a codec context for decoding
    processor->decoder_ctx = avcodec_alloc_context3(NULL);
    if (!processor->decoder_ctx)
        return -4;

    // Copy parameters from input stream to decoder context
    if (avcodec_parameters_to_context(processor->decoder_ctx, processor->input_ctx->streams[processor->input_stream]->codecpar) < 0)
        return -5;

    // Find the decoder for the video stream
    AVCodec *decoder = avcodec_find_decoder(processor->decoder_ctx->codec_id);
    if (!decoder)
        return -6;

    // Open codec
    if (avcodec_open2(processor->decoder_ctx, decoder, NULL) < 0)
        return -7;

    // Allocate a codec context for encoding
    processor->encoder_ctx = avcodec_alloc_context3(decoder);
    if (!processor->encoder_ctx)
        return -8;

    // Set up the encoder parameters based on input stream and quality setting
    // ...

    // Find an appropriate encoder
    AVCodec *encoder = avcodec_find_encoder(processor->encoder_ctx->codec_id);
    if (!encoder)
        return -9;

    // Open codec
    if (avcodec_open2(processor->encoder_ctx, encoder, NULL) < 0)
        return -10;

    // Allocate the output file context
    processor->output_stream = avformat_new_stream(processor->input_ctx, encoder);
    if (!processor->output_stream)
        return -11;

    // Copy parameters from encoder context to stream codec context
    avcodec_parameters_from_context(processor->output_stream->codecpar, processor->encoder_ctx);

    // Open the output file
    if (avformat_open_output(&processor->input_ctx, output_file, NULL, NULL) < 0)
        return -12;

    // Write the stream header
    if (avformat_write_header(processor->input_ctx, NULL) < 0)
        return -13;

    processor->frame_rate = processor->encoder_ctx->framerate.num / processor->encoder_ctx->framerate.den;
    processor->width = processor->encoder_ctx->width;
    processor->height = processor->encoder_ctx->height;
    processor->quality = quality;

    pthread_mutex_init(&processor->lock, NULL);
    pthread_cond_init(&processor->cond, NULL);
    processor->pause_flag = 0;

    return 0;
}

void pauseProcessing(VideoProcessor *processor) {
    pthread_mutex_lock(&processor->lock);
    processor->pause_flag = 1;
    pthread_mutex_unlock(&processor->lock);
}

void resumeProcessing(VideoProcessor *processor) {
    pthread_mutex_lock(&processor->lock);
    processor->pause_flag = 0;
    pthread_cond_signal(&processor->cond);
    pthread_mutex_unlock(&processor->lock);
}

void cleanupProcessor(VideoProcessor *processor) {
    if (processor->input_ctx)
        avformat_close_input(&processor->input_ctx);

    if (processor->decoder_ctx)
        avcodec_free_context(&processor->decoder_ctx);

    if (processor->encoder_ctx)
        avcodec_free_context(&processor->encoder_ctx);

    pthread_mutex_destroy(&processor->lock);
    pthread_cond_destroy(&processor->cond);
}

int main() {
    VideoProcessor processor;
    initializeProcessor(&processor, "input.mp4", "output.mp4", 30);

    pthread_t thread;
    pthread_create(&thread, NULL, processVideoStream, &processor);

    // Simulate user input to pause and resume
    sleep(5);
    pauseProcessing(&processor);
    sleep(2);
    resumeProcessing(&processor);

    pthread_join(thread, NULL);

    cleanupProcessor(&processor);

    return 0;
}
```

This code provides a basic structure for a video processing function using FFmpeg library. It includes initialization, processing loop, and cleanup steps. The actual filtering and encoding logic is left to the developer as it can vary based on specific requirements.']

