using UnityEngine;
using System;

public class DynamicRandomGenerator
{
    private int minRange;
    private int maxRange;
    private int seed;
    private Random random;

    public DynamicRandomGenerator(int min, int max, int seed = 0)
    {
        Initialize(min, max, seed);
    }

    private void Initialize(int min, int max, int seed)
    {
        if (min > max)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }
        this.minRange = min;
        this.maxRange = max;
        this.seed = seed;
        this.random = new Random(seed);
    }

    public int GetRandomIntInclusive()
    {
        return random.Range(minRange, maxRange + 1);
    }

    public int GetRandomIntExclusive()
    {
        return random.Range(minRange, maxRange);
    }

    public float GetRandomFloatInclusive()
    {
        return (float)random.Range(minRange, maxRange + 1) / maxRange;
    }

    public float GetRandomFloatExclusive()
    {
        return (float)random.Range(minRange, maxRange - 1) / (maxRange - 1);
    }

    public override string ToString()
    {
        return $"DynamicRandomGenerator [Min: {minRange}, Max: {maxRange}, Seed: {seed}]";
    }

    public void Reset(int min = 0, int max = 1)
    {
        Initialize(min, max, seed);
    }

    public static int GetStaticRandomIntInclusive(DynamicRandomGenerator generator)
    {
        return generator.GetRandomIntInclusive();
    }

    public static int GetStaticRandomIntExclusive(DynamicRandomGenerator generator)
    {
        return generator.GetRandomIntExclusive();
    }
}
