using System;
using System.Collections.Concurrent;
using System.Linq;

public class DynamicRangeValueGenerator
{
    private ConcurrentDictionary<string, (double Min, double Max, string Distribution)> ranges;
    private Random random;

    public DynamicRangeValueGenerator()
    {
        ranges = new ConcurrentDictionary<string, (double Min, double Max, string Distribution)>();
        random = new Random();
    }

    public void AddRange(string name, double min, double max, string distribution)
    {
        if (ranges.Any(r => Overlaps(r.Value.Min, r.Value.Max, min, max)))
        {
            throw new ArgumentException("New range overlaps with existing ranges.");
        }
        ranges.TryAdd(name, (min, max, distribution));
    }

    public void RemoveRange(string name)
    {
        ranges.TryRemove(name, out _);
    }

    public double GenerateRandomDouble(string rangeName, bool inclusive = true)
    {
        if (!ranges.ContainsKey(rangeName))
            throw new ArgumentException("Range not found.");

        var (min, max, distribution) = ranges[rangeName];
        double value;

        switch (distribution.ToLower())
        {
            case "uniform":
                value = random.NextDouble() * (max - min + (inclusive ? 1 : 0)) + min;
                break;
            case "normal":
                var mean = (min + max) / 2;
                var stdDev = Math.Abs(max - mean) / 3;
                value = NormalDistribution(min, max, mean, stdDev);
                break;
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }

        return value;
    }

    public int GenerateRandomInt(string rangeName, bool inclusive = true)
    {
        if (!ranges.ContainsKey(rangeName))
            throw new ArgumentException("Range not found.");

        var (min, max, distribution) = ranges[rangeName];
        double value;

        switch (distribution.ToLower())
        {
            case "uniform":
                value = random.NextDouble() * (max - min + (inclusive ? 1 : 0)) + min;
                break;
            case "normal":
                var mean = (min + max) / 2;
                var stdDev = Math.Abs(max - mean) / 3;
                value = NormalDistribution(min, max, mean, stdDev);
                break;
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }

        return Convert.ToInt32(value);
    }

    public override string ToString()
    {
        return string.Join(", ", ranges.Select(r => $"{r.Key}: {r.Value.Min}-{r.Value.Max} ({r.Value.Distribution})"));
    }

    private bool Overlaps(double min1, double max1, double min2, double max2)
    {
        return !(max1 < min2 || min1 > max2);
    }

    private double NormalDistribution(double minValue, double maxValue, double mean, double stdDev)
    {
        while (true)
        {
            var value = random.NextDouble() * (maxValue - minValue + 1) + minValue;
            if (value >= minValue && value <= maxValue)
                return value;
        }
    }
}
