    private Random random;
    public int MinInt { get; set; }
    public int MaxInt { get; set; }
    public double MinFloat { get; set; }
    public double MaxFloat { get; set; }

    public ConfigurableRandomGenerator(int minInt, int maxInt, double minFloat, double maxFloat)
    {
        random = new Random();
        MinInt = minInt;
        MaxInt = maxInt;
        MinFloat = minFloat;
        MaxFloat = maxFloat;
    }

    public int GetNextInt(bool inclusive = true)
    {
        return inclusive ? random.Next(MinInt, MaxInt + 1) : random.Next(MinInt, MaxInt);
    }

    public double GetNextDouble(bool inclusive = true)
    {
        if (inclusive)
        {
            var next = random.NextDouble();
            return MinFloat + next * (MaxFloat - MinFloat);
        }
        else
        {
            return random.NextDouble() * (MaxFloat - MinFloat) + MinFloat;
        }
    }

    public void SaveState(string filePath)
    {
        using (FileStream fileStream = new FileStream(filePath, FileMode.Create))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            formatter.Serialize(fileStream, this);
        }
    }

    public static ConfigurableRandomGenerator LoadState(string filePath)
    {
        using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            return (ConfigurableRandomGenerator)formatter.Deserialize(fileStream);
        }
    }

    public override string ToString()
    {
        return $"Seed: {random.GetHashCode()}, MinInt: {MinInt}, MaxInt: {MaxInt}, MinFloat: {MinFloat}, MaxFloat: {MaxFloat}";
