    {
        _seed = seed;
        _minIntRange = minIntRange;
        _maxIntRange = maxIntRange;
        _minFloatRange = minFloatRange;
        _maxFloatRange = maxFloatRange;
        _random = new Random(seed);
    }

    private ConfigurableRandom(SerializationInfo info, StreamingContext context)
    {
        _seed = info.GetInt32("_seed");
        _minIntRange = info.GetInt32("_minIntRange");
        _maxIntRange = info.GetInt32("_maxIntRange");
        _minFloatRange = info.GetSingle("_minFloatRange");
        _maxFloatRange = info.GetSingle("_maxFloatRange");
        _random = new Random(_seed);
    }

    public void GetObjectData(SerializationInfo info, StreamingContext context)
    {
        info.AddValue("_seed", _seed);
        info.AddValue("_minIntRange", _minIntRange);
        info.AddValue("_maxIntRange", _maxIntRange);
        info.AddValue("_minFloatRange", _minFloatRange);
        info.AddValue("_maxFloatRange", _maxFloatRange);
    }

    public int GenerateRandomInt(bool inclusive)
    {
        if (inclusive)
            return _random.Next(_minIntRange, _maxIntRange + 1);
        else
            return _random.Next(_minIntRange, _maxIntRange);
    }

    public float GenerateRandomFloat(bool inclusive)
    {
        if (inclusive)
            return (float)(_random.NextDouble() * (_maxFloatRange - _minFloatRange) + _minFloatRange);
        else
            return (float)(_random.NextDouble() * (_maxFloatRange - _minFloatRange)) + _minFloatRange;
    }

    public void SaveState(string filePath)
    {
        using (FileStream fs = new FileStream(filePath, FileMode.Create))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            formatter.Serialize(fs, this);
        }
    }

    public static ConfigurableRandom LoadState(string filePath)
    {
        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            return (ConfigurableRandom)formatter.Deserialize(fs);
        }
    }

    public override string ToString()
    {
        return $"Seed: {_seed}, Int Range:({_minIntRange}, {_maxIntRange}), Float Range:({_minFloatRange}, {_maxFloatRange})";
    }

    public void ResetToState(ConfigurableRandom state)
    {
        _random = new Random(state._seed);
        _seed = state._seed;
        _minIntRange = state._minIntRange;
        _maxIntRange = state._maxIntRange;
        _minFloatRange = state._minFloatRange;
        _maxFloatRange = state._maxFloatRange;
    }

    public bool IsValidState()
    {
        return _random != null && _seed >= 0 && _minIntRange <= _maxIntRange && _minFloatRange <= _maxFloatRange;
    }
