using System;
using System.Collections.Generic;
using System.IO;

public class ConfigurableRandom
{
    private Random _random;
    private int _seed;
    private (int Min, int Max) _intRange;
    private (float Min, float Max) _floatRange;

    public ConfigurableRandom(int seed = 0, (int Min, int Max) intRange = default, (float Min, float Max) floatRange = default)
    {
        _seed = seed;
        _random = new Random(_seed);
        _intRange = intRange == default ? (1, 100) : intRange;
        _floatRange = floatRange == default ? (0.0f, 1.0f) : floatRange;
    }

    public int GenerateRandomInt(bool inclusive = false)
    {
        return inclusive ? _random.Next(_intRange.Min, _intRange.Max + 1) : _random.Next(_intRange.Min, _intRange.Max);
    }

    public float GenerateRandomFloat(bool inclusive = true)
    {
        if (inclusive) return _random.NextFloat(_floatRange.Min, _floatRange.Max);
        else throw new NotImplementedException("Exclusive float generation not implemented.");
    }

    public override string ToString()
    {
        return $"ConfigurableRandom[Seed: {_seed}, Int Range: ({_intRange.Min}, {_intRange.Max}), Float Range: ({_floatRange.Min}, {_floatRange.Max})]";
    }

    // Persistence methods
    public void SaveToFile(string filePath)
    {
        using (var writer = new StreamWriter(filePath))
        {
            writer.WriteLine($"{_seed},{_intRange.Min},{_intRange.Max},{_floatRange.Min},{_floatRange.Max}");
        }
    }

    public static ConfigurableRandom LoadFromFile(string filePath)
    {
        if (!File.Exists(filePath)) throw new FileNotFoundException("File not found.");
        var lines = File.ReadAllLines(filePath);
        var parts = lines[0].Split(',');
        return new ConfigurableRandom(
            int.Parse(parts[0]),
            (int.Parse(parts[1]), int.Parse(parts[2])),
            (float.Parse(parts[3]), float.Parse(parts[4]))
        );
    }

    // Reset method
    public void Reset(int seed = 0, (int Min, int Max) intRange = default, (float Min, float Max) floatRange = default)
    {
        _seed = seed;
        _random = new Random(_seed);
        _intRange = intRange == default ? (1, 100) : intRange;
        _floatRange = floatRange == default ? (0.0f, 1.0f) : floatRange;
    }

    // Resource management
    ~ConfigurableRandom()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _random = null;
        }
    }
}

// C function for MD5 hash generation
#include <stdio.h>
#include <stdarg.h>
#include <openssl/md5.h>

typedef struct record {
    char* str;
    unsigned char hash[MD5_DIGEST_LENGTH];
} Record;

void generateMD5Hashes(char** strings, int count, int seed) {
    srand(seed);
    for (int i = 0; i < count; ++i) {
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)strings[i], strlen(strings[i]), hash);

        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            printf("Memory allocation failed for string: %s\n", strings[i]);
            va_list args;
            va_start(args, seed);
            // Log error details using snprintf and va_end
            va_end(args);
            return;
        }
        record->str = strings[i];
        memcpy(record->hash, hash, MD5_DIGEST_LENGTH);

        // Serialize records to binary format for storage
    }

    // Free all dynamically allocated memory
}
