using System.Threading.Tasks;

public class ConfigurableResourceAllocator
{
    private Dictionary<string, Resource> _resources = new Dictionary<string, Resource>();
    private object _lock = new object();

    public void AddResource(string name, string type, int minLimit, int maxLimit)
    {
        lock (_lock)
        {
            if (!_resources.ContainsKey(name))
            {
                _resources[name] = new Resource(type, minLimit, maxLimit);
            }
        }
    }

    public bool AllocateResource(string name, AllocationPolicy policy, int amount)
    {
        lock (_lock)
        {
            var resource = _resources[name];
            switch (policy)
            {
                case AllocationPolicy.FirstFit:
                    if (resource.Allocated + amount <= resource.MaxLimit)
                    {
                        resource.Allocated += amount;
                        return true;
                    }
                    break;
                case AllocationPolicy.BestFit:
                    // Implement best-fit logic
                    break;
            }
            return false;
        }
    }

    public bool ReleaseResource(string name, int amount)
    {
        lock (_lock)
        {
            var resource = _resources[name];
            if (resource.Allocated >= amount)
            {
                resource.Allocated -= amount;
                return true;
            }
            return false;
        }
    }

    public void AdjustLimits(string name, int newMinLimit, int newMaxLimit)
    {
        lock (_lock)
        {
            var resource = _resources[name];
            if (resource.Allocated >= newMinLimit && resource.Allocated <= newMaxLimit)
            {
                resource.MinLimit = newMinLimit;
                resource.MaxLimit = newMaxLimit;
            }
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            var result = "ConfigurableResourceAllocator:\n";
            foreach (var resource in _resources.Values)
            {
                result += $"{resource.Name} - Type: {resource.Type}, Allocated: {resource.Allocated}, MinLimit: {resource.MinLimit}, MaxLimit: {resource.MaxLimit}\n";
            }
            return result;
        }
    }

    public enum AllocationPolicy
    {
        FirstFit,
        BestFit
    }

    private class Resource
    {
        public string Name { get; }
        public string Type { get; }
        public int MinLimit { get; set; }
        public int MaxLimit { get; set; }
        public int Allocated { get; set; }

        public Resource(string type, int minLimit, int maxLimit)
        {
            Name = Guid.NewGuid().ToString();
            Type = type;
            MinLimit = minLimit;
            MaxLimit = maxLimit;
            Allocated = 0;
        }
    }
}
