public class CustomRandomGenerator : ICloneable
{
    private Random _random;

    public CustomRandomGenerator(int seed = 0)
    {
        _random = new Random(seed);
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    public int GetNextInt(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        return _random.Next(min, max + 1);
    }

    public double GetNextDouble(double min, double max)
    {
        if (min >= max) throw new ArgumentException("Minimum value must be less than maximum value.");
        return _random.NextDouble() * (max - min) + min;
    }

    public int[] GetNextIntArray(int length, int min, int max)
    {
        if (length <= 0) throw new ArgumentException("Array length must be greater than zero.");
        var result = new int[length];
        for (int i = 0; i < length; i++)
        {
            result[i] = GetNextInt(min, max);
        }
        return result;
    }

    public double[] GetNextDoubleArray(int length, double min, double max)
    {
        if (length <= 0) throw new ArgumentException("Array length must be greater than zero.");
        var result = new double[length];
        for (int i = 0; i < length; i++)
        {
            result[i] = GetNextDouble(min, max);
        }
        return result;
    }

    public string SerializeState()
    {
        using (var stream = new MemoryStream())
        {
            var formatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            formatter.Serialize(stream, _random);
            return Convert.ToBase64String(stream.ToArray());
        }
    }

    public CustomRandomGenerator Clone()
    {
        return (CustomRandomGenerator)this.MemberwiseClone();
    }
}
