    public IntPtr InitializeAes256Cbc(string password)
    {
        byte[] passwordBytes = System.Text.Encoding.UTF8.GetBytes(password);
        byte[] hash = Digest.Create("SHA1").DigestFinal(passwordBytes, out _);

        Cipher cipher = Cipher.CipherInit(Cipher.Algorithm.AES_256_CBC, Cipher.Mode.ECB, hash, null, Cipher.Padding.PKCS7);
        if (cipher == IntPtr.Zero)
        {
            throw new Exception("Failed to initialize AES-256-CBC cipher.");
        }

        return cipher;
    }

    public void Cleanup(IntPtr cipherContext)
    {
        Cipher.CipherCleanup(cipherContext);
    }

    public float GenerateRandomFloat()
    {
        Random random = new Random();
        return minValue + (float)(random.NextDouble() * (maxValue - minValue));
    }

    public int GenerateRandomInt()
    {
        Random random = new Random();
        return random.Next(minValue, maxValue + 1);
    }
