public class CustomRandomGenerator : IDisposable
{
    private Random random;
    private Dictionary<string, byte[]> ipCache = new Dictionary<string, byte[]>();
    private int seed;
    private bool dnsResolutionEnabled = true;
    private IPHostEntry hostEntry;
    private Socket socket;

    public CustomRandomGenerator(int seed)
    {
        this.seed = seed;
        random = new Random(seed);
    }

    public void SetSeed(int seed)
    {
        this.seed = seed;
        random = new Random(seed);
    }

    public float GenerateRandomFloat(float min, float max, bool inclusive = true)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than max");
        float value = random.NextSingle() * (max - min);
        return inclusive ? (value + min) : (value + min + 0.001f);
    }

    public int GenerateRandomInt(int min, int max, bool inclusive = true)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than max");
        int value = random.Next(min, exclusive ? max : max + 1);
        return inclusive ? value : (value + 1);
    }

    public float[] GenerateRandomFloatArray(int length, float min, float max, bool inclusive = true)
    {
        if (length <= 0) throw new ArgumentException("Length must be greater than zero");
        float[] array = new float[length];
        for (int i = 0; i < length; i++)
        {
            array[i] = GenerateRandomFloat(min, max, inclusive);
        }
        return array;
    }

    public int[] GenerateRandomIntArray(int length, int min, int max, bool inclusive = true)
    {
        if (length <= 0) throw new ArgumentException("Length must be greater than zero");
        int[] array = new int[length];
        for (int i = 0; i < length; i++)
        {
            array[i] = GenerateRandomInt(min, max, inclusive);
        }
        return array;
    }

    public string SerializeState()
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine($"Seed: {seed}");
        sb.AppendLine("Current State: " + random.ToString());
        return sb.ToString();
    }

    public byte[] ResolveDns(string hostname)
    {
        if (!dnsResolutionEnabled) throw new InvalidOperationException("DNS resolution is disabled");
        if (ipCache.ContainsKey(hostname)) return ipCache[hostname];

        try
        {
            hostEntry = Dns.GetHostEntry(hostname);
            byte[] ipAddressBytes = hostEntry.AddressList[0].GetAddressBytes();
            ipCache[hostname] = ipAddressBytes;
            return ipAddressBytes;
        }
        catch (Exception ex)
        {
            Console.WriteLine("DNS resolution failed: " + ex.Message);
            return null;
        }
    }

    public void LimitCapabilities()
    {
        // Implement capability limiting logic here
    }

    public void Dispose()
    {
        random.Dispose();
        socket?.Close();
        ipCache.Clear();
    }
}
