public class RandomCipherManager
{
    private int minValue;
    private int maxValue;
    private byte[] iv;
    private Aes aes;

    public RandomCipherManager(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.iv = new byte[16]; // AES block size
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}";
    }

    public ICryptoTransform InitializeAesCipher(string password)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] key = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            aes = Aes.Create();
            aes.KeySize = 256;
            aes.BlockSize = 128; // AES block size
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.GenerateIV();
            this.iv = aes.IV;
            return aes.CreateEncryptor(key, aes.IV);
        }
    }

    public int GenerateRandomInteger()
    {
        RandomNumberGenerator rng = new RNGCryptoServiceProvider();
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        int randomNumber = BitConverter.ToInt32(randomBytes, 0);
        return (randomNumber % (maxValue - minValue + 1)) + minValue;
    }

    public float GenerateRandomFloat()
    {
        RandomNumberGenerator rng = new RNGCryptoServiceProvider();
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        int randomNumber = BitConverter.ToInt32(randomBytes, 0);
        return ((float)randomNumber / int.MaxValue) * (maxValue - minValue) + minValue;
    }

    public void Cleanup()
    {
        aes.Dispose();
    }
}
