public class DynamicRandomGenerator
{
    private int _minValue;
    private int _maxValue;
    private int _seed;
    private Random _random;

    public DynamicRandomGenerator(int minValue = 0, int maxValue = 1, int seed = 0)
    {
        MinValue = minValue;
        MaxValue = maxValue;
        Seed = seed;
        Reset();
    }

    public int MinValue
    {
        get => _minValue;
        set
        {
            if (value >= _maxValue) throw new ArgumentException("Min value must be less than max value.");
            _minValue = value;
        }
    }

    public int MaxValue
    {
        get => _maxValue;
        set
        {
            if (value <= _minValue) throw new ArgumentException("Max value must be greater than min value.");
            _maxValue = value;
        }
    }

    public int Seed
    {
        get => _seed;
        set
        {
            _seed = value;
            Reset();
        }
    }

    private void Reset()
    {
        if (_random != null) _random = null;
        _random = new Random(_seed);
    }

    public int GenerateInt(bool inclusive = true)
    {
        return inclusive ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
    }

    public float GenerateFloat(bool inclusive = false)
    {
        if (inclusive)
        {
            float min = (float)_minValue;
            float max = (float)_maxValue + (UnityEngine.Random.value < Mathf.Epsilon ? 1f : 0f);
            return UnityEngine.Random.Range(min, max);
        }
        else
        {
            return UnityEngine.Random.Range(_minValue, _maxValue);
        }
    }

    public override string ToString()
    {
        return $"DynamicRandomGenerator: MinValue={MinValue}, MaxValue={MaxValue}, Seed={Seed}";
    }

    public static int GenerateInt(DynamicRandomGenerator generator, bool inclusive = true)
    {
        return generator.GenerateInt(inclusive);
    }

    public static float GenerateFloat(DynamicRandomGenerator generator, bool inclusive = false)
    {
        return generator.GenerateFloat(inclusive);
    }
}
