#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <openssl/md5.h>

class StreamingDataProcessor {
public:
    StreamingDataProcessor(const std::string& configPath = "", const std::string& initialPipeline = "");
    ~StreamingDataProcessor();
    void processStream(const std::string& data);
    std::string toString() const;
    bool saveConfig(const std::string& filePath) const;
    bool loadConfig(const std::string& filePath);
    void reset(const std::string& state);
    void releaseResources();

private:
    std::unordered_map<std::string, std::function<void(std::string&)>> transformationPipeline;
    std::vector<std::pair<std::string, std::string>> dataMetrics;
    bool isValidState() const;

    // Helper functions
    static std::string computeMD5(const std::string& str);
};

StreamingDataProcessor::StreamingDataProcessor(const std::string& configPath, const std::string& initialPipeline) {
    if (!configPath.empty()) {
        loadConfig(configPath);
    }
    if (!initialPipeline.empty()) {
        transformationPipeline[initialPipeline] = [](std::string& data) {};
    }
}

StreamingDataProcessor::~StreamingDataProcessor() {
    releaseResources();
}

void StreamingDataProcessor::processStream(const std::string& data) {
    if (isValidState()) {
        for (auto& [_, transform] : transformationPipeline) {
            transform(data);
        }
        dataMetrics.push_back({data, computeMD5(data)});
    } else {
        // Handle invalid state gracefully
    }
}

std::string StreamingDataProcessor::toString() const {
    std::ostringstream oss;
    oss << "Processing Pipeline: ";
    for (const auto& [key, _] : transformationPipeline) {
        oss << key << ", ";
    }
    oss << "\nLatest Data Metrics:\n";
    for (const auto& [data, hash] : dataMetrics) {
        oss << data << ": " << hash << "\n";
    }
    return oss.str();
}

bool StreamingDataProcessor::saveConfig(const std::string& filePath) const {
    std::ofstream file(filePath);
    if (!file.is_open()) {
        // Log error message
        return false;
    }
    for (const auto& [key, _] : transformationPipeline) {
        file << key << "\n";
    }
    return true;
}

bool StreamingDataProcessor::loadConfig(const std::string& filePath) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        // Log error message
        return false;
    }
    std::string line;
    while (getline(file, line)) {
        transformationPipeline[line] = [](std::string& data) {};
    }
    return true;
}

void StreamingDataProcessor::reset(const std::string& state) {
    if (isValidState()) {
        transformationPipeline.clear();
        transformationPipeline[state] = [](std::string& data) {};
        dataMetrics.clear();
    } else {
        // Handle invalid state gracefully
    }
}

void StreamingDataProcessor::releaseResources() {
    // Release all dynamically allocated resources here
}

bool StreamingDataProcessor::isValidState() const {
    // Validate the current state of the processor
    return !transformationPipeline.empty();
}

std::string StreamingDataProcessor::computeMD5(const std::string& str) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str.c_str(), str.length());
    MD5_Final(hash, &md5);
    std::ostringstream oss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        oss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return oss.str();
}
