    private Random _random;
    private int _seed;

    public AdvancedRandomGenerator(int seed = 0)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public void SetSeed(int seed)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public float NextFloat(float min, float max, bool inclusiveMax = true)
    {
        return inclusiveMax ? (float)_random.NextDouble() * (max - min) + min : (float)(_random.NextDouble() * (max - min));
    }

    public int NextInt(int min, int max, bool inclusiveMax = true)
    {
        return inclusiveMax ? _random.Next(min, max + 1) : _random.Next(min, max);
    }

    public void FillArray(float[] array, float min, float max, bool inclusiveMax = true)
    {
        for (int i = 0; i < array.Length; i++)
        {
            array[i] = NextFloat(min, max, inclusiveMax);
        }
    }

    public T[] GetRandomPermutation<T>(T[] inputArray)
    {
        var result = new List<T>(inputArray);
        var random = new Random(_seed); // Use a different seed for each permutation
        int n = result.Count;
        while (n > 1)
        {
            n--;
            int k = _random.Next(n + 1);
            T value = result[k];
            result[k] = result[n];
            result[n] = value;
        }
        return result.ToArray();
    }

    public string Serialize()
    {
        using (var memoryStream = new MemoryStream())
        {
            var binaryFormatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            binaryFormatter.Serialize(memoryStream, this);
            return Convert.ToBase64String(memoryStream.ToArray());
        }
    }

    public static AdvancedRandomGenerator Deserialize(string serializedState)
    {
        using (var memoryStream = new MemoryStream(Convert.FromBase64String(serializedState)))
        {
            var binaryFormatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            return (AdvancedRandomGenerator)binaryFormatter.Deserialize(memoryStream);
        }
    }

    public object Clone()
    {
        return Deserialize(Serialize());
    }

    // Implement weighted random selection and conditional probability adjustments as needed
}
