using System;
using System.Text.Json;

public class RandomValueGenerator
{
    private Random _random;
    private double _minValue;
    private double _maxValue;
    private int _precision;
    private long _seed;

    public RandomValueGenerator(double minValue, double maxValue, int precision = 2, long seed = 0)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _precision = precision;
        _seed = seed;
        _random = new Random(seed);
    }

    public double GenerateRandomDouble()
    {
        return Math.Round(_random.NextDouble() * (_maxValue - _minValue) + _minValue, _precision);
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public void ResetSeed(long newSeed)
    {
        _seed = newSeed;
        _random = new Random(newSeed);
    }

    public string ToJson()
    {
        return JsonSerializer.Serialize(this);
    }

    public override string ToString()
    {
        return $"RandomValueGenerator [Min: {_minValue}, Max: {_maxValue}, Precision: {_precision}, Seed: {_seed}]";
    }
}
