void log_memory_allocation_success(int allocations) {
    FILE *logFile = fopen("allocation_log.txt", "a");
    if (logFile != NULL) {
        fprintf(logFile, "Memory allocation successful. Total allocations: %d\n", allocations);
        fclose(logFile);
    }
}

void log_memory_allocation_failure() {
    FILE *logFile = fopen("allocation_log.txt", "a");
    if (logFile != NULL) {
        fprintf(logFile, "Memory allocation failed.\n");
        fclose(logFile);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indication_pdu(int num_elements) {
    static int allocations = 0;
    static NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    if (num_elements <= 0) {
        return array;
    }

    if ((allocations % RESET_INTERVAL == 0) && (array != NULL)) {
        free(array);
        array = NULL;
    }

    if (array == NULL) {
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            log_memory_allocation_failure();
            return array;
        }
        allocations = 0;
    }

    for (int i = 0; i < num_elements; i++) {
        array[i].RX_UE_INFORMATION.RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate valid RX_UE_INFORMATION_TAG
        array[i].RX_UE_INFORMATION.RNTI = rand() % 1024; // Simulate valid RNTI
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2); // Randomly set CRCFLAG
    }

    allocations += num_elements;
    log_memory_allocation_success(allocations);

    return array;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pduArray = allocate_nfaapi_crc_indication_pdu(10);
