#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define DEFAULT_POOL_SIZE 100

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

typedef struct MemoryPool {
    PoolNode* head;
    PoolNode* tail;
    size_t poolSize;
    size_t allocatedCount;
    int autoResetThreshold;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createPool(size_t initialSize, int autoReset) {
    if (initialSize <= 0 || autoReset < 0) {
        fprintf(stderr, "Invalid configuration parameters. Resetting to defaults.\n");
        initialSize = DEFAULT_POOL_SIZE;
        autoReset = -1;
    }

    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool.\n");
        return NULL;
    }

    pool->head = pool->tail = NULL;
    pool->poolSize = initialSize;
    pool->allocatedCount = 0;
    pool->autoResetThreshold = autoReset;
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize the memory pool with the given size
    for (size_t i = 0; i < initialSize; ++i) {
        PoolNode* newNode = (PoolNode*)malloc(sizeof(PoolNode));
        if (!newNode) {
            fprintf(stderr, "Failed to allocate memory for a new node in the pool.\n");
            freeMemoryPool(pool);
            return NULL;
        }
        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Random RX_UE_INFORMATION_TAG
        newNode->data.RNTI = rand() % 1000; // Random RNTI
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : 0; // Random CRCFLAG
        newNode->next = NULL;

        if (pool->tail) {
            pool->tail->next = newNode;
        } else {
            pool->head = newNode;
        }
        pool->tail = newNode;
    }

    return pool;
}

void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->allocatedCount >= pool->poolSize && pool->autoResetThreshold != -1) {
        resetMemoryPool(pool);
        pool->autoResetThreshold = -1; // Disable auto-reset after full use once
    }

    PoolNode* node = pool->head;
    if (!node) {
        fprintf(stderr, "Memory pool is empty. Allocation failed.\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->head = node->next;
    if (pool->head == NULL) {
        pool->tail = NULL;
    }
    ++pool->allocatedCount;

    pthread_mutex_unlock(&pool->lock);

    return &node->data;
}

void freeToPool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);

    PoolNode* newNode = (PoolNode*)malloc(sizeof(PoolNode));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for a new node in the pool.\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    newNode->data = *(NFAPI_CRC_INDICATION_PDU_T*)ptr;
    newNode->next = NULL;

    if (pool->tail) {
        pool->tail->next = newNode;
    } else {
        pool->head = newNode;
    }
    pool->tail = newNode;
    --pool->allocatedCount;

    pthread_mutex_unlock(&pool->lock);
}

void resetMemoryPool(MemoryPool* pool) {
    PoolNode* current = pool->head;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }
    pool->head = pool->tail = NULL;
    pool->allocatedCount = 0;

    // Re-initialize the memory pool with default size
    for (size_t i = 0; i < DEFAULT_POOL_SIZE; ++i) {
        PoolNode* newNode = (PoolNode*)malloc(sizeof(PoolNode));
        if (!newNode) {
            fprintf(stderr, "Failed to allocate memory for a new node in the pool.\n");
            return;
        }
        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Random RX_UE_INFORMATION_TAG
        newNode->data.RNTI = rand() % 1000; // Random RNTI
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : 0; // Random CRCFLAG
        newNode->next = NULL;

        if (pool->tail) {
            pool->tail->next = newNode;
        } else {
            pool->head = newNode;
        }
        pool->tail = newNode;
    }

    fprintf(stderr, "Memory pool has been reset.\n");
}

void freeMemoryPool(MemoryPool* pool) {
    PoolNode* current = pool->head;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
