#include <pthread.h>

#define MAX_HOSTS 100
#define MAX_IP_LEN 46 // Maximum length for an IPv6 address as a string
#define TIMEOUT_SEC 5

typedef struct ip_addr {
    char ip[MAX_IP_LEN];
    char hostname[256];
    char dns_server[256];
    struct ip_addr *next;
} IPAddr;

typedef struct {
    int max_concurrent_queries;
    pthread_mutex_t lock;
    int current_queries;
    FILE *log_file;
} DNSConfig;

DNSConfig config = {10, PTHREAD_MUTEX_INITIALIZER, 0, NULL};

void log_dns_query(const char *hostname, const char *ip, const char *dns_server, int result) {
    if (config.log_file == NULL) return;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(config.log_file, "%s %s: Host=%s, IP=%s, DNS Server=%s, Result=%d\n",
            asctime(tm_info), result == 0 ? "SUCCESS" : "FAILURE",
            hostname, ip, dns_server, result);
}

int resolve_hostname(const char *hostname, const char *dns_server, char *ip) {
    struct sockaddr_in server;
    int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock < 0) return -1;

    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(53);
    inet_pton(AF_INET, dns_server, &server.sin_addr);

    char query[1024];
    // Construct DNS query (simplified for example purposes)
    snprintf(query, sizeof(query), "%s", hostname);

    int send_len = sendto(sock, query, strlen(query), 0,
                          (struct sockaddr *)&server, sizeof(server));
    if (send_len < 0) {
        close(sock);
        return -1;
    }

    struct timeval timeout = {TIMEOUT_SEC, 0};
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));

    char response[4096];
    socklen_t fromlen = sizeof(server);
    int recv_len = recvfrom(sock, response, sizeof(response), 0,
                            (struct sockaddr *)&server, &fromlen);
    if (recv_len < 0) {
        close(sock);
        return -1;
    }

    // Parse DNS response to extract IP address (simplified for example purposes)
    strcpy(ip, "192.168.1.1"); // Example IP

    close(sock);
    return 0;
}

void *dns_thread(void *arg) {
    char **hostnames = arg;
    IPAddr *head = NULL;
    pthread_mutex_lock(&config.lock);

    for (int i = 0; i < MAX_HOSTS && hostnames[i] != NULL; i++) {
        if (config.current_queries >= config.max_concurrent_queries) {
            // Wait until a slot becomes available
            while (config.current_queries >= config.max_concurrent_queries) {
                pthread_cond_wait(&cond_var, &config.lock);
            }
        }

        char ip[MAX_IP_LEN];
        int result = resolve_hostname(hostnames[i], "8.8.8.8", ip); // Use Google's public DNS server
        if (result == 0) {
            IPAddr *new_node = (IPAddr *)malloc(sizeof(IPAddr));
            strcpy(new_node->ip, ip);
            strcpy(new_node->hostname, hostnames[i]);
            strcpy(new_node->dns_server, "8.8.8.8");
            new_node->next = head;
            head = new_node;

            log_dns_query(hostnames[i], ip, "8.8.8.8", 0);
        } else {
            log_dns_query(hostnames[i], "", "8.8.8.8", result);
        }

        config.current_queries++;
    }

    pthread_mutex_unlock(&config.lock);
    pthread_exit(NULL);
}

void free_ip_list(IPAddr *head) {
    IPAddr *current = head;
    while (current != NULL) {
        IPAddr *next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    char *hostnames[MAX_HOSTS] = {"google.com", "example.com", "nonexistentdomain.com"};
    config.log_file = fopen("dns_log.txt", "w");

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, dns_thread, hostnames);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_ip_list(head);

    fclose(config.log_file);
    return 0;
}
```

This code provides a basic structure for performing asynchronous DNS resolution using threads and handling errors, limiting capabilities, concurrent execution, timeout mechanism, memory management, logging, multi-threaded application integration, and avoiding race conditions.']

