int generate_unique_rnti(int *used_rntis, int max_rnti) {
    srand(time(NULL));
    int rnti;
    for (int i = 0; i < MAX_RNTI_RETRIES; i++) {
        rnti = rand() % max_rnti + 1; // Generate a random RNTI within the valid range
        if (!used_rntis[rnti]) {
            used_rntis[rnti] = 1;
            return rnti;
        }
    }
    fprintf(stderr, "Failed to generate unique RNTI after %d retries\n", MAX_RNTI_RETRIES);
    exit(1); // Exit on failure
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, int max_rnti) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int *used_rntis = calloc(max_rnti + 1, sizeof(int)); // Array to keep track of used RNTIs
    if (!used_rntis) {
        free(array);
        fprintf(stderr, "Memory allocation failed for RNTI tracking\n");
        return NULL;
    }

    int rnti_count = 0;
    while (rnti_count < N) {
        int rnti = generate_unique_rnti(used_rntis, max_rnti);
