#include <stdlib.h>
#include <time.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
} LogEntry;

typedef struct Logger {
    size_t max_entries;
    size_t current_count;
    LogEntry **entries;
    pthread_mutex_t lock;
} Logger;

Logger* create_logger(size_t max_entries) {
    if (max_entries == 0) return NULL;

    Logger *logger = malloc(sizeof(Logger));
    if (!logger) return NULL;

    logger->max_entries = max_entries;
    logger->current_count = 0;
    logger->entries = malloc(max_entries * sizeof(LogEntry*));
    if (!logger->entries) {
        free(logger);
        return NULL;
    }

    pthread_mutex_init(&logger->lock, NULL);

    for (size_t i = 0; i < max_entries; ++i) {
        logger->entries[i] = malloc(sizeof(LogEntry));
        if (!logger->entries[i]) {
            // Free previously allocated entries
            for (size_t j = 0; j < i; ++j) free(logger->entries[j]);
            free(logger->entries);
            free(logger);
            return NULL;
        }
    }

    return logger;
}

void destroy_logger(Logger *logger) {
    if (!logger) return;

    pthread_mutex_lock(&logger->lock);

    for (size_t i = 0; i < logger->current_count; ++i) {
        free(logger->entries[i]->message);
        free(logger->entries[i]);
    }
    free(logger->entries);
    pthread_mutex_unlock(&logger->lock);

    pthread_mutex_destroy(&logger->lock);
    free(logger);
}

void log_message(Logger *logger, LogLevel level, const char *format, ...) {
    if (!logger || !format) return;

    pthread_mutex_lock(&logger->lock);

    if (logger->current_count == logger->max_entries) {
        // Handle full log buffer, e.g., discard the oldest entry
        free(logger->entries[0]->message);
        memmove(logger->entries, logger->entries + 1, (logger->max_entries - 1) * sizeof(LogEntry*));
    }

    LogEntry *entry = logger->entries[logger->current_count];
    time_t now = time(NULL);
    entry->timestamp = now;
    entry->level = level;

    va_list args;
    va_start(args, format);
    vasprintf(&entry->message, format, args);
    va_end(args);

    if (entry->message) {
        ++logger->current_count;
    }

    pthread_mutex_unlock(&logger->lock);
}
```

This code defines a `Logger` structure and provides functions to create, destroy, and log messages. The `log_message` function ensures thread-safe logging by locking the logger during operations. It also handles memory allocation failures and limits the number of log entries based on the configured maximum.']

