#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_RNTI 65535 // Maximum possible RNTI value
#define MAX_RETRIES 10
#define MAX_WAIT_TIME 5 // in seconds
#define CLEANUP_INTERVAL 100
#define MAX_CONCURRENT_THREADS 100

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t resource_available = PTHREAD_COND_INITIALIZER;
uint32_t rnti_pool[MAX_RNTI];
uint32_t rnti_count = 0;
uint32_t total_wait_time = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(uint32_t N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&global_mutex);
    for (uint32_t i = 0; i < N; i++) {
        uint16_t rnti;
        uint8_t retries = MAX_RETRIES;
        while (retries--) {
            if (rnti_count == 0) {
                pthread_cond_wait(&resource_available, &global_mutex);
            }
            pthread_mutex_unlock(&global_mutex);

            rnti = rand() % MAX_RNTI; // Generate a random RNTI
            pthread_mutex_lock(&global_mutex);
            if (!rnti_pool[rnti]) {
                array[i].RX_UE_INFORMATION_TAG = i;
                array[i].RNTI = rnti;
                array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
                rnti_pool[rnti] = 1;
                rnti_count++;
                break;
            }
        }
        if (retries == -1) {
            fprintf(stderr, "Failed to find a unique RNTI after %d retries\n", MAX_RETRIES);
            free(array);
            pthread_mutex_unlock(&global_mutex);
            return NULL;
        }

        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);
        while (rnti_count >= MAX_RNTI && rnti_count < MAX_RNTI + MAX_CONCURRENT_THREADS) {
            pthread_cond_wait(&resource_available, &global_mutex);
        }
        clock_gettime(CLOCK_REALTIME, &end);
        total_wait_time += (end.tv_sec - start.tv_sec);

        if (total_wait_time > MAX_WAIT_TIME) {
            fprintf(stderr, "Total wait time exceeded\n");
            free(array);
            pthread_mutex_unlock(&global_mutex);
            return NULL;
        }
    }
    pthread_mutex_unlock(&global_mutex);

    return array;
}

void cleanup_array(NFAPI_CRC_INDICATION_PDU_T* array, uint32_t N) {
    pthread_mutex_lock(&global_mutex);
    for (uint32_t i = 0; i < N; i++) {
        rnti_pool[array[i].RNTI] = 0;
        rnti_count--;
    }
    pthread_mutex_unlock(&global_mutex);

    free(array);
}

void* worker_thread(void* arg) {
    uint32_t thread_id = *(uint32_t*)arg;
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(10);
    if (array) {
        // Process the array
        cleanup_array(array, 10);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_THREADS];
    uint32_t thread_ids[MAX_CONCURRENT_THREADS];

    for (uint32_t i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            perror("Thread creation failed");
            return 1;
        }
    }

    for (uint32_t i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
