#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_TARGETS 10
#define MAX_LOG_MESSAGE_LENGTH 256

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct LogEntry {
    int id;
    time_t timestamp;
    LogLevel level;
    char *message;
    pthread_mutex_t lock;
} LogEntry;

typedef struct LogTarget {
    void (*log)(const LogEntry *entry);
    void (*cleanup)(void);
    void *config;
} LogTarget;

LogEntry *log_entries[MAX_LOG_ENTRIES];
int log_entry_count = 0;
pthread_mutex_t log_mutex;
LogTarget log_targets[MAX_LOG_TARGETS];

void log_target_console(const LogEntry *entry) {
    pthread_mutex_lock(&entry->lock);
    printf("[%ld] %s: %s\n", entry->timestamp, LogLevelToString(entry->level), entry->message);
    pthread_mutex_unlock(&entry->lock);
}

void log_target_file(const LogEntry *entry) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            return;
        }
    }
    pthread_mutex_lock(&entry->lock);
    fprintf(log_file, "[%ld] %s: %s\n", entry->timestamp, LogLevelToString(entry->level), entry->message);
    fflush(log_file);
    pthread_mutex_unlock(&entry->lock);
}

void init_logging(int max_entries) {
    pthread_mutex_init(&log_mutex, NULL);
    for (int i = 0; i < MAX_LOG_TARGETS; i++) {
        log_targets[i] = (LogTarget){NULL, NULL, NULL};
    }
    log_entry_count = 0;
    for (int i = 0; i < max_entries && i < MAX_LOG_ENTRIES; i++) {
        LogEntry *entry = malloc(sizeof(LogEntry));
        if (!entry) {
            perror("Failed to allocate memory for log entry");
            return;
        }
        entry->id = i;
        entry->timestamp = time(NULL);
        entry->level = LOG_LEVEL_INFO;
        entry->message = malloc(MAX_LOG_MESSAGE_LENGTH);
        if (!entry->message) {
            perror("Failed to allocate memory for log message");
            free(entry);
            return;
        }
        pthread_mutex_init(&entry->lock, NULL);
        log_entries[i] = entry;
    }
}

void add_log_target(void (*log)(const LogEntry *), void (*cleanup)(void), void *config) {
    for (int i = 0; i < MAX_LOG_TARGETS; i++) {
        if (!log_targets[i].log) {
            log_targets[i] = (LogTarget){log, cleanup, config};
            return;
        }
    }
    fprintf(stderr, "Failed to add log target: maximum number of targets reached\n");
}

void log_message(LogLevel level, const char *message) {
    pthread_mutex_lock(&log_mutex);
    for (int i = 0; i < log_entry_count; i++) {
        LogEntry *entry = log_entries[i];
        pthread_mutex_lock(&entry->lock);
        entry->timestamp = time(NULL);
        entry->level = level;
        strncpy(entry->message, message, MAX_LOG_MESSAGE_LENGTH - 1);
        entry->message[MAX_LOG_MESSAGE_LENGTH - 1] = '\0';
        for (int j = 0; j < MAX_LOG_TARGETS; j++) {
            if (log_targets[j].log) {
                log_targets[j].log(entry);
            }
        }
        pthread_mutex_unlock(&entry->lock);
    }
    pthread_mutex_unlock(&log_mutex);
}

void cleanup_logging() {
    for (int i = 0; i < log_entry_count; i++) {
        free(log_entries[i]->message);
        pthread_mutex_destroy(&log_entries[i]->lock);
        free(log_entries[i]);
    }
    for (int i = 0; i < MAX_LOG_TARGETS; i++) {
        if (log_targets[i].cleanup) {
            log_targets[i].cleanup();
        }
    }
    pthread_mutex_destroy(&log_mutex);
}
```

This code provides a basic implementation of a logging system with the specified features. It includes functions for initializing, adding targets, logging messages, and cleaning up the logging system. The actual logging logic is left as an exercise for the junior developer to implement based on the specific requirements of the target platforms and configurations.']

