#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RNTI_POOL_SIZE 1000

typedef struct {
    // Define the structure fields as per NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
} RNTI_POOL_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t array_size;
    size_t next_index;
    pthread_mutex_t mutex;
    sem_t cleanup_semaphore;
} CRC_INDICATION_ARRAY_T;

RNTI_POOL_T rnti_pool = {NULL, 0, 0};
CRC_INDICATION_ARRAY_T crc_indication_array = {NULL, 0, 0};

pthread_mutex_t global_rnti_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t global_cleanup_semaphore = SEM_INIT(NULL, 0, 1);

void init_rnti_pool(size_t size) {
    pthread_mutex_lock(&global_rnti_pool_mutex);
    rnti_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!rnti_pool.pool) {
        fprintf(stderr, "Failed to allocate RNTI pool\n");
        exit(EXIT_FAILURE);
    }
    rnti_pool.pool_size = size;
    pthread_mutex_unlock(&global_rnti_pool_mutex);
}

NFAPI_CRC_INDICATION_PDU_T *get_rnti() {
    sem_wait(&global_cleanup_semaphore);
    pthread_mutex_lock(&global_rnti_pool_mutex);

    if (rnti_pool.used_count == rnti_pool.pool_size) {
        // Wait for resources to become available
        clock_t start = clock();
        while (rnti_pool.used_count == rnti_pool.pool_size && (clock() - start) < 5 * CLOCKS_PER_SEC) {
            sem_wait(&global_cleanup_semaphore);
        }
        if (rnti_pool.used_count == rnti_pool.pool_size) {
            fprintf(stderr, "Failed to get RNTI after waiting\n");
            exit(EXIT_FAILURE);
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &rnti_pool.pool[rnti_pool.used_count++];
    pthread_mutex_unlock(&global_rnti_pool_mutex);
    sem_post(&global_cleanup_semaphore);

    return pdu;
}

void release_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&global_cleanup_semaphore);
    pthread_mutex_lock(&global_rnti_pool_mutex);

    size_t index = (size_t)((char *)pdu - (char *)rnti_pool.pool) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (index < rnti_pool.used_count && &rnti_pool.pool[index] == pdu) {
        rnti_pool.used_count--;
        sem_post(&global_cleanup_semaphore);
        pthread_mutex_unlock(&global_rnti_pool_mutex);
    } else {
        fprintf(stderr, "Invalid RNTI pointer\n");
        exit(EXIT_FAILURE);
    }
}

void init_crc_indication_array(size_t size) {
    crc_indication_array.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_array.array) {
        fprintf(stderr, "Failed to allocate CRC indication array\n");
        exit(EXIT_FAILURE);
    }
    crc_indication_array.array_size = size;
    pthread_mutex_init(&crc_indication_array.mutex, NULL);
    sem_init(&crc_indication_array.cleanup_semaphore, 0, 1);
}

void cleanup_crc_indication_array() {
    while (crc_indication_array.next_index > 0) {
        pthread_mutex_lock(&crc_indication_array.mutex);
        if (crc_indication_array.next_index > 0) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &crc_indication_array.array[--crc_indication_array.next_index];
            release_rnti(pdu);
        }
        pthread_mutex_unlock(&crc_indication_array.mutex);
    }
}

void add_crc_indication(size_t count) {
    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_rnti();
        // Populate pdu with valid data
        pthread_mutex_lock(&crc_indication_array.mutex);
        if (crc_indication_array.next_index >= crc_indication_array.array_size) {
            cleanup_crc_indication_array();
        }
        crc_indication_array.array[crc_indication_array.next_index++] = *pdu;
        pthread_mutex_unlock(&crc_indication_array.mutex);
    }
}

void flush_crc_indication_array() {
    pthread_mutex_lock(&crc_indication_array.mutex);
    cleanup_crc_indication_array();
    crc_indication_array.next_index = 0;
    pthread_mutex_unlock(&crc_indication_array.mutex);
}
