    struct pool_node* next;
} PoolNode;

PoolNode* pool_head = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_pool() {
    for (int i = 0; i < MAX_STRUCTS; i++) {
        PoolNode* new_node = malloc(sizeof(PoolNode));
        if (!new_node) {
            perror("Failed to allocate memory for pool node");
            exit(EXIT_FAILURE);
        }
        new_node->next = pool_head;
        pool_head = new_node;
    }
}

NFAPI_RX_INDICATION_PDU_T* get_from_pool() {
    pthread_mutex_lock(&pool_lock);
    PoolNode* node = pool_head;
    if (node) {
        pool_head = node->next;
    }
    pthread_mutex_unlock(&pool_lock);
    return node ? &node->data : NULL;
}

