#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    uint8_t* additional_data;
    size_t data_size;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList crc_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

int add_entry(RX_UE_INFORMATION_TAG rx_ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_rel8_tag, uint8_t* additional_data, size_t data_size) {
    pthread_mutex_lock(&crc_list.lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Memory allocation failed
    }

    new_node->entry.rx_ue_info_tag = rx_ue_info_tag;
    new_node->entry.rnti = rnti;
    new_node->entry.crc_ind_rel8_tag = crc_ind_rel8_tag;

    new_node->entry.additional_data = (uint8_t*)malloc(data_size);
    if (!new_node->entry.additional_data) {
        free(new_node);
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Memory allocation failed
    }
    memcpy(new_node->entry.additional_data, additional_data, data_size);
    new_node->entry.data_size = data_size;

    Node* current = crc_list.head;
    Node* previous = NULL;

    while (current && current->entry.rnti < rnti) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL) {
        new_node->next = crc_list.head;
        crc_list.head = new_node;
    } else {
        previous->next = new_node;
        new_node->next = current;
    }

    pthread_mutex_unlock(&crc_list.lock);
    return 0; // Entry added successfully
}

int update_entry(RX_UE_INFORMATION_TAG rx_ue_info_tag, CRC_INDICATION_REL8_TAG crc_ind_rel8_tag, uint8_t* additional_data, size_t data_size) {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;

    while (current && (current->entry.rx_ue_info_tag != rx_ue_info_tag || current->entry.crc_ind_rel8_tag != crc_ind_rel8_tag)) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Entry not found
    }

    free(current->entry.additional_data);
    current->entry.additional_data = (uint8_t*)malloc(data_size);
    if (!current->entry.additional_data) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Memory allocation failed
    }
    memcpy(current->entry.additional_data, additional_data, data_size);
    current->entry.data_size = data_size;

    pthread_mutex_unlock(&crc_list.lock);
    return 0; // Entry updated successfully
}

int remove_entry(RX_UE_INFORMATION_TAG rx_ue_info_tag, CRC_INDICATION_REL8_TAG crc_ind_rel8_tag) {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    Node* previous = NULL;

    while (current && (current->entry.rx_ue_info_tag != rx_ue_info_tag || current->entry.crc_ind_rel8_tag != crc_ind_rel8_tag)) {
        previous = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Entry not found
    }

    if (previous == NULL) {
        crc_list.head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->entry.additional_data);
    free(current);

    pthread_mutex_unlock(&crc_list.lock);
    return 0; // Entry removed successfully
}

void destroy_list() {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    while (current) {
        Node* next = current->next;
        free(current->entry.additional_data);
        free(current);
        current = next;
    }
    crc_list.head = NULL;

    pthread_mutex_unlock(&crc_list.lock);
}
