            memmove(entries + i, entries + i + 1, (count - i - 1) * sizeof(NFapi_RLC_PDU_T*));
            count--;
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    fprintf(stderr, "Entry with RNTI %d not found\n", rnti);
    pthread_mutex_unlock(&lock);
}

void compactList() {
    pthread_mutex_lock(&lock);
    NFapi_RLC_PDU_T** temp = (NFapi_RLC_PDU_T**)realloc(entries, count * sizeof(NFapi_RLC_PDU_T*));
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
