#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define INITIAL_BUFFER_SIZE 1024

char* read_file_data(int fd, size_t requested_size, char** error_msg) {
    char* buffer = (char*)malloc(INITIAL_BUFFER_SIZE);
    if (!buffer) {
        *error_msg = "Failed to allocate initial buffer.";
        return NULL;
    }

    ssize_t bytes_read = read(fd, buffer, requested_size);
    if (bytes_read == -1) {
        free(buffer);
        *error_msg = "Error reading from file descriptor.";
        return NULL;
    } else if (bytes_read < requested_size) {
        buffer[bytes_read] = '\0';
        *error_msg = NULL;
        return buffer;
    }

    size_t total_length = bytes_read;
    while (total_length == requested_size) {
        // Resize the buffer if it's full
        char* new_buffer = (char*)realloc(buffer, total_length + INITIAL_BUFFER_SIZE);
        if (!new_buffer) {
            free(buffer);
            *error_msg = "Failed to resize buffer.";
            return NULL;
        }
        buffer = new_buffer;

        bytes_read = read(fd, buffer + total_length, INITIAL_BUFFER_SIZE);
        if (bytes_read == -1) {
            free(buffer);
            *error_msg = "Error reading from file descriptor.";
            return NULL;
        }

        total_length += bytes_read;
    }

    buffer[total_length] = '\0';
    *error_msg = NULL;
    return buffer;
}

int main() {
    int fd = open("example.txt", O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    char* error_msg = NULL;
    char* data = read_file_data(fd, 1024, &error_msg);

    if (data) {
        printf("Data: %s\n", data);
        free(data);
    } else {
        printf("Error: %s\n", error_msg);
        free(error_msg);
    }

    close(fd);
    return 0;
}
