int count_files(const char *dir) {
    DIR *dp;
    struct dirent *ep;
    int file_count = 0;

    dp = opendir(dir);
    if (dp != NULL) {
        while ((ep = readdir(dp)) != NULL) {
            if (!strcmp(ep->d_name, ".") || !strcmp(ep->d_name, ".."))
                continue;
            if (ep->d_type == DT_LNK)
