#define MAX_SESSIONS 1000
#define PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define BATCH_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *session_data[MAX_SESSIONS];
int current_session_count = 0;
time_t last_purge_time = 0;

void* manage_sessions(void* arg) {
    while (1) {
        pthread_mutex_lock(&session_lock);
        if (current_session_count > MAX_SESSIONS / 2) {
            for (int i = 0; i < current_session_count / 2; i++) {
                free(session_data[i]);
                session_data[i] = NULL;
            }
            current_session_count /= 2;
        }
        pthread_mutex_unlock(&session_lock);
        sleep(60); // Purge old sessions every minute
    }
}

void initialize_sessions() {
    pthread_t purge_thread;
    pthread_create(&purge_thread, NULL, manage_sessions, NULL);

    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_data[i] = malloc(PDU_SIZE);
        if (!session_data[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

void populate_pdus() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < BATCH_SIZE; i++) {
        // Populate PDU fields here
        session_data[current_session_count]->ue_info = generate_ue_info();
        session_data[current_session_count]->rnti = get_unique_rnti(session_data, current_session_count);
        session_data[current_session_count]->crc_indication = generate_crc_indication();
        session_data[current_session_count++]->crcflag = rand() % 2;
    }
    pthread_mutex_unlock(&session_lock);
}

int main() {
    initialize_sessions();

    while (1) {
        populate_pdus();
        // Process PDUs here
        sleep(1); // Simulate processing time
    }

    return 0;
}
```']

