            {
                context.Rejected();
                return;
            }
            var registeredClient = await context.OwinContext.Get<ApplicationUserManager>().FindClientIdAsync(clientId);
            if (registeredClient == null)
            {
                context.Rejected();
                return;
            }

            context.Validated();
        }

