        {
            var existingUser = context.Ticket.Identity.Name;
            ApplicationUser user = context.OwinContext.Get<ApplicationUserManager>().FindByName(existingUser);
            if (user == null)
            {
                context.SetError("invalid_grant", "Invalid refresh token.");
                return Task.FromResult<object>(null);
            }

            ClaimsIdentity oAuthIdentity = await userManager.CreateIdentityAsync(user,
               OAuthDefaults.AuthenticationType);

            AuthenticationProperties properties = CreateProperties(user.UserName, user.Email);
            AuthenticationTicket ticket = new AuthenticationTicket(oAuthIdentity, properties);
            context.Issue(ticket);
        }

        public static AuthenticationProperties CreateProperties(string userName, string email)
        {
            var props = new AuthenticationProperties(new Dictionary<string, string>
            {
                { "userName", userName },
                { "email", email }
            });
            return props;
        }
    }
}
