#include <stdlib.h>
#include <pthread.h>
#include "network_stack.h"
#include "data_validation.h"

typedef struct {
    PacketIdentifier id;
    SourceAddress source;
    DestinationAddress destination;
} NetworkLayerHeader;

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    NetworkLayerHeader *buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NetworkBuffer;

NetworkBuffer *createNetworkBuffer() {
    NetworkBuffer *buf = malloc(sizeof(NetworkBuffer));
    if (!buf) return NULL;
    buf->buffer = malloc(INITIAL_BUFFER_SIZE * sizeof(NetworkLayerHeader));
    if (!buf->buffer) {
        free(buf);
        return NULL;
    }
    buf->capacity = INITIAL_BUFFER_SIZE;
    buf->count = 0;
    pthread_mutex_init(&buf->lock, NULL);
    return buf;
}

void destroyNetworkBuffer(NetworkBuffer *buf) {
    pthread_mutex_destroy(&buf->lock);
    free(buf->buffer);
    free(buf);
}

int initializeNetworkBuffer(NetworkBuffer *buf, NetworkLayerHeader packet, DataValidationCallback validatePacket) {
    pthread_mutex_lock(&buf->lock);
    if (buf->count >= buf->capacity) {
        NetworkLayerHeader *newBuffer = realloc(buf->buffer, buf->capacity * 2 * sizeof(NetworkLayerHeader));
        if (!newBuffer) {
            pthread_mutex_unlock(&buf->lock);
            return -1; // Memory allocation failed
        }
        buf->buffer = newBuffer;
        buf->capacity *= 2;
    }
    if (validatePacket(&packet)) {
        buf->buffer[buf->count++] = packet;
        pthread_mutex_unlock(&buf->lock);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&buf->lock);
        return -2; // Validation failed
    }
}

// Example usage:
/*
NetworkBuffer *networkBuf = createNetworkBuffer();
if (networkBuf) {
    NetworkLayerHeader pkt;
    // Initialize pkt with valid data
    if (initializeNetworkBuffer(networkBuf, pkt, validatePacket)) {
        printf("Packet initialized successfully.\n");
    } else {
        printf("Failed to initialize packet.\n");
    }
    destroyNetworkBuffer(networkBuf);
}
*/
```

