void processAndPersistData(unsigned long seed, Record** records, int count, void (*transform)(double*)) {
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }

    srand(seed);
    for (int i = 0; i < count; ++i) {
        transform(&records[i]->value);
        fwrite(records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

void applyLog(const char* message, ...) {
    va_list args;
    va_start(args, message);
    vfprintf(stderr, message, args);
    va_end(args);
}
