using System;

public class CustomRandomGenerator
{
    private Random random;

    public CustomRandomGenerator(long seed = 0)
    {
        random = new Random(seed);
    }

    public double NextDouble(double min, double max, bool inclusiveMax = true)
    {
        if (min >= max) throw new ArgumentException("Invalid range");
        return inclusiveMax ? random.NextDouble() * (max - min) + min : random.NextDouble() * (max - min);
    }

    public int NextInt(int min, int max, bool inclusiveMax = true)
    {
        if (min > max) throw new ArgumentException("Invalid range");
        return inclusiveMax ? random.Next(min, max + 1) : random.Next(min, max);
    }

    public T[] NextArray<T>(int size) where T : IConvertible
    {
        var array = Array.CreateInstance(typeof(T), size);
        for (int i = 0; i < size; ++i)
            if (typeof(T) == typeof(double))
                ((double[])array)[i] = NextDouble(0, double.MaxValue);
            else if (typeof(T) == typeof(int))
                ((int[])array)[i] = NextInt(0, int.MaxValue);
        return (T[])array;
    }

    public string SerializeState()
    {
        // Implement state serialization logic here
        return random.Next().ToString();
    }
}
