public class DnsResolver
{
    private static readonly ConcurrentDictionary<string, string> Cache = new ConcurrentDictionary<string, string>();
    private static readonly object LockObject = new object();

    public static u_char[] Resolve(string hostname)
    {
        lock (LockObject)
        {
            if (!Cache.ContainsKey(hostname))
            {
                var ip = Dns.GetHostEntry(hostname).AddressList[0].GetAddressBytes();
                Cache.TryAdd(hostname, BitConverter.ToString(ip));
            }
            return BitConverter.GetBytes(Convert.ToInt64(Cache[hostname]));
        }
    }

    public static void AddToCache(string hostname, u_char[] ip)
    {
        lock (LockObject)
        {
            if (!Cache.ContainsKey(hostname))
            {
                Cache.TryAdd(hostname, BitConverter.ToString(ip));
            }
        }
    }
}
