std::condition_variable data_available_cv;
bool stop_thread = false;

// Function to fetch weather data from an API
void fetchWeatherData(const std::string& service_url, const std::string& location) {
    // Simulated API call with exponential backoff
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        try {
            Json::Value response = fetchDataFromAPI(service_url + "?location=" + location);
            std::lock_guard<std::mutex> lock(data_mutex);
            weather_data.push_back(response);
            data_available_cv.notify_all();
            return;
        } catch (const std::exception& e) {
            if (attempt == MAX_RETRIES - 1) {
                std::cerr << "Failed to fetch data from " << service_url << ": " << e.what() << std::endl;
            }
            std::this_thread::sleep_for(std::chrono::seconds(static_cast<int>(BACKOFF_FACTOR * std::pow(2, attempt))));
        }
    }
}

// Function to process and analyze weather data
void processData() {
    while (!stop_thread) {
