    // Parse command line arguments
    std::string location = "40.7128,-74.0060"; // Default location (New York)
    int interval = 30; // Default update interval in seconds
    std::string service_url = "https://api.weather.com/data/2.5/weather"; // Default service URL

    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "-l") {
            location = argv[++i];
