int is_valid_buffer_id(char* ids, char id, int count) {
    for (int i = 0; i < count; i++) {
        if (ids[i] == id) {
            return 0;
        }
    }
    return 1;
}

void populate_events(long** timestamps, char** buffer_ids, Event** events, int count, int min_status, int max_status) {
    srand(time(0));
    for (int i = 0; i < count; i++) {
        (*timestamps)[i] = time(NULL);
        do {
            (*buffer_ids)[i] = 'A' + rand() % 26;
        } while (!is_valid_buffer_id(*buffer_ids, (*buffer_ids)[i], i));
        (*events)[i].timestamp = (*timestamps)[i];
        (*events)[i].buffer_id = (*buffer_ids)[i];
        (*events)[i].status = min_status + rand() % (max_status - min_status + 1);
    }
}

int main() {
    int count = 5;
    long* timestamps = malloc(count * sizeof(long));
    char* buffer_ids = malloc(count * sizeof(char));
    Event* events = malloc(count * sizeof(Event));

    populate_events(&timestamps, &buffer_ids, &events, count, 100, 200);

    for (int i = 0; i < count; i++) {
        printf("Event %d: Timestamp = %ld, Buffer ID = %c, Status = %d\n", i + 1, timestamps[i], buffer_ids[i], events[i].status);
    }

    free(timestamps);
    free(buffer_ids);
    free(events);

    return 0;
}
