public class UserManagementSystem : IUserStore<ApplicationUser>, IDisposable
{
    private readonly ApplicationDbContext _context;

    public UserManagementSystem()
    {
        _context = new ApplicationDbContext();
    }

    public Task CreateAsync(ApplicationUser user)
    {
        return _context.Users.AddAsync(user);
    }

    public Task UpdateAsync(ApplicationUser user)
    {
        var existingUser = _context.Users.Find(user.Id);
        if (existingUser != null)
        {
            existingUser.UserName = user.UserName;
            existingUser.Email = user.Email;
            existingUser.PasswordHash = user.PasswordHash;
            // Update other properties as needed
        }
        return Task.FromResult(0);
    }

    public Task DeleteAsync(ApplicationUser user)
    {
        _context.Users.Remove(user);
        return Task.FromResult(0);
    }

    public Task<ApplicationUser> FindByIdAsync(string userId)
    {
        return Task.FromResult(_context.Users.Find(userId));
    }

    public Task<ApplicationUser> FindByNameAsync(string userName)
    {
        return Task.FromResult(_context.Users.FirstOrDefault(u => u.UserName == userName));
    }

    // Additional methods for managing user roles, claims, and more...

    public void Dispose()
    {
        _context.Dispose();
    }
}

public class ApplicationUser : IdentityUser
{
