int session_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* manage_sessions(void* arg) {
    int new_subfram_num = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (session_count < MAX_SESSIONS) {
        frame_configs[session_count].SUBFRAM_NUM = new_subfram_num;
        session_count++;
    } else {
        printf("Maximum sessions reached.\n");
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    int subfram_nums[MAX_SESSIONS] = {1, 2, 3, /* 其他会话配置 */};
    pthread_t threads[MAX_SESSIONS];

    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (pthread_create(&threads[i], NULL, manage_sessions, &subfram_nums[i]) != 0) {
            printf("Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
