import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class BatchHashProcessor {

    private final Map<String, String> cache = new ConcurrentHashMap<>();
    private final File outputDir;

    public BatchHashProcessor(String outputDirPath) {
        this.outputDir = new File(outputDirPath);
        if (!outputDir.exists()) {
            outputDir.mkdirs();
        }
    }

    public void processBatch(String configFilePath) throws IOException, NoSuchAlgorithmException {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String input = line.trim();
                if (!input.isEmpty()) {
                    String md5Hash = computeMD5Hash(input);
                    writeToFile(md5Hash, input);
                }
            }
        }
    }

    private String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        String md5Hash = sb.toString();
        cache.put(input, md5Hash);
        return md5Hash;
    }

    private void writeToFile(String md5Hash, String input) throws IOException {
        File file = new File(outputDir, input + ".md5");
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
            writer.write(md5Hash);
        }
    }

    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java BatchHashProcessor <configFile> <outputDir>");
            return;
        }
        String configFile = args[0];
        String outputDir = args[1];

        try {
            BatchHashProcessor processor = new BatchHashProcessor(outputDir);
            processor.processBatch(configFile);
            System.out.println("Batch processing completed successfully.");
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
