import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class BatchHasher {

    private static final Logger successLogger = LoggerFactory.getLogger("success-logger");
    private static final Logger failureLogger = LoggerFactory.getLogger("failure-logger");
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final BlockingQueue<String> inputQueue;
    private final ExecutorService executorService;
    private final int batchSize;

    public BatchHasher(int batchSize) {
        this.batchSize = batchSize;
        this.inputQueue = new LinkedBlockingQueue<>(batchSize);
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        startProcessing();
    }

    public void processBatch(String configFilePath, String outputDir) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                inputQueue.put(line);
            }
        }
    }

    private void startProcessing() {
        executorService.submit(() -> {
            while (true) {
                List<String> batch = new ArrayList<>();
                try {
                    for (int i = 0; i < batchSize && !inputQueue.isEmpty(); i++) {
                        batch.add(inputQueue.take());
                    }
                    processBatch(batch);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    private void processBatch(List<String> strings) {
        for (String input : strings) {
            try {
                String hash = computeMd5(input);
                cache.putIfAbsent(input, hash);
                writeToFile(hash, outputDir + File.separator + hash.substring(0, 2), input);
                successLogger.info("Processed successfully: {}", input);
            } catch (Exception e) {
                failureLogger.error("Failed to process: {}", input, e);
            }
        }
    }

    private String computeMd5(String string) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(string.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void writeToFile(String hash, String dirPath, String input) throws IOException {
        File dir = new File(dirPath);
        if (!dir.exists() && !dir.mkdirs()) {
            throw new IOException("Failed to create directory: " + dirPath);
        }
        File file = new File(dir, hash.substring(2));
        try (FileWriter writer = new FileWriter(file, true)) {
            writer.write(input + "\n");
        }
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }

    // Extendable interface for integrating with additional external services
    public interface ExternalService {
        void logSuccess(String input);
        void logFailure(String input, Exception e);
    }
}
