import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class HashProcessor {

    private static final Map<String, String> hashCache = new ConcurrentHashMap<>();
    private static Logger logger = LoggerFactory.getLogger(HashProcessor.class);

    public void processBatch(String configFilePath, String outputDirPath, int batchSize) {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(configFilePath));
             BufferedWriter writer = Files.newBufferedWriter(Paths.get(outputDirPath))) {

            String line;
            while ((line = reader.readLine()) != null && batchSize-- > 0) {
                String hash = computeMD5(line);
                if (hash != null) {
                    writer.write(hash + "\n");
                    logger.info("Successfully computed MD5 hash for: " + line);
                } else {
                    logger.error("Failed to compute MD5 hash for: " + line);
                }
            }
        } catch (IOException e) {
            logger.error("I/O error occurred", e);
        }
    }

    private String computeMD5(String input) {
        if (input == null) {
            return null;
        }

        if (hashCache.containsKey(input)) {
            return hashCache.get(input);
        }

        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            hashCache.put(input, sb.toString());
            return sb.toString();
        } catch (Exception e) {
            logger.error("Error computing MD5 hash", e);
            return null;
        }
    }

    // Retry mechanism with exponential backoff
    private void retryWithExponentialBackoff(Runnable task, int maxAttempts) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                task.run();
                break;
            } catch (Exception e) {
                if (attempt == maxAttempts) {
                    logger.error("Task failed after " + maxAttempts + " attempts", e);
                    throw e;
                }
                int sleepTime = (int) Math.pow(2, attempt) * 100; // Exponential backoff
                try {
                    Thread.sleep(sleepTime);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    // Method to integrate with external logging service
    private void logOperation(String operation, boolean success) {
        if (success) {
            logger.info(operation + " completed successfully");
        } else {
            logger.error(operation + " failed");
        }
    }

    // Method to support batch processing with configurable batch sizes
    public void processBatchWithConfigurableSize(String configFilePath, String outputDirPath, int batchSize) {
        // Implement logic here based on the requirements
    }

    // Method to handle large files efficiently without consuming excessive memory or causing performance bottlenecks
    public void processLargeFile(String filePath, String outputDirPath) {
