import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.DigestUtils;

public class HashProcessor {

    private static final int DEFAULT_BATCH_SIZE = 100;
    private static final long CACHE_FLUSH_INTERVAL = 60000; // 1 minute
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_BACKOFF_FACTOR = 2;

    private final Map<String, String> hashCache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private final ScheduledExecutorService cacheFlushScheduler = Executors.newScheduledThreadPool(1);
    private final Logger logger;
    private final ResourceManagementSystem resourceManager;
    private final DiskUsageMonitor diskUsageMonitor;
    private final NetworkConnectionPool networkPool;

    public HashProcessor(Logger logger, ResourceManagementSystem resourceManager, DiskUsageMonitor diskUsageMonitor, NetworkConnectionPool networkPool) {
        this.logger = logger;
        this.resourceManager = resourceManager;
        this.diskUsageMonitor = diskUsageMonitor;
        this.networkPool = networkPool;

        cacheFlushScheduler.scheduleAtFixedRate(this::flushCache, CACHE_FLUSH_INTERVAL, CACHE_FLUSH_INTERVAL);
    }

    public void processBatch(List<String> inputStrings, String outputDirectory, int batchSize) throws IOException {
        if (batchSize <= 0) {
            batchSize = DEFAULT_BATCH_SIZE;
        }

        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (int i = 0; i < inputStrings.size(); i += batchSize) {
            int end = Math.min(i + batchSize, inputStrings.size());
            List<String> subList = inputStrings.subList(i, end);
            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> processBatch(subList, outputDirectory), executorService);
            futures.add(future);
        }

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }

    private void processBatch(List<String> inputStrings, String outputDirectory) {
        for (String input : inputStrings) {
            if (input == null || input.trim().isEmpty()) continue;

            try {
                String hash = computeHash(input);
                writeHashToFile(hash, outputDirectory);
                logger.logSuccess("Computed hash for: " + input);
            } catch (Exception e) {
                logger.logFailure("Failed to compute hash for: " + input, e);
            }
        }
    }

    private String computeHash(String input) throws NoSuchAlgorithmException {
        return DigestUtils.md5Hex(input.getBytes());
    }

    private void writeHashToFile(String hash, String outputDirectory) throws IOException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                // Write to file logic here
                // Example: Files.write(Paths.get(outputDirectory, hash + ".txt"), Collections.singleton(hash));
                break;
            } catch (IOException e) {
                if (diskUsageMonitor.isDiskFull()) {
                    diskUsageMonitor.deferWriteOperations();
                }
                retryCount++;
                try {
                    Thread.sleep((long) Math.pow(RETRY_BACKOFF_FACTOR, retryCount));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new IOException("Interrupted during retry", ie);
                }
            }
        }
    }

    public void shutdown() {
        cacheFlushScheduler.shutdownNow();
        executorService.shutdownNow();
    }
}
