public class HashBatchProcessor {

    private static final int MAX_INPUT_SIZE = 4096;
    private static final int MAX_AUTHENC_INPUT_SIZE = 8192;
    private Map<String, String> hashCache = new HashMap<>();
    private File outputDirectory;

    public HashBatchProcessor(String outputDir) {
        this.outputDirectory = new File(outputDir);
        if (!outputDirectory.exists()) {
            outputDirectory.mkdirs();
        }
    }

    public void processBatch(String configFilePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                processString(line);
            }
        } catch (IOException e) {
            logError("Failed to read configuration file: " + e.getMessage());
            throw e;
        }
    }

    private void processString(String input) throws IOException {
        if (input == null || input.length() > MAX_INPUT_SIZE) {
            return;
        }

        String hash = getHash(input, "MD5");
        saveHashToFile("MD5", hash);

        // Repeat for other hashes...
    }

    private String getHash(String input, String algorithm) throws IOException {
        if (hashCache.containsKey(input + algorithm)) {
            return hashCache.get(input + algorithm);
        }

        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            hashCache.put(input + algorithm, hexString.toString());
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            logError("Unsupported hashing algorithm: " + algorithm + ": " + e.getMessage());
            throw new IOException(e);
        }
    }

    private void saveHashToFile(String algorithm, String hash) throws IOException {
        File outputFile = new File(outputDirectory, algorithm + ".txt");
        try (FileWriter writer = new FileWriter(outputFile, true)) {
            writer.write(hash + "\n");
        } catch (IOException e) {
            logError("Failed to write hash to file: " + e.getMessage());
            throw e;
        }
    }

    private void logError(String message) {
        // Log error message to a specified log file
    }
}
