    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final ConcurrentHashMap<String, Future<?>> processingTasks = new ConcurrentHashMap<>();

    public void processEvent(String eventJson) {
        String eventId = UUID.randomUUID().toString();
        Instant timestamp = Instant.now();

        // Submit task to the executor for asynchronous processing
        Future<?> task = executor.submit(() -> {
            try {
                // Simulate event processing logic here
                System.out.println("Processing event: " + eventId + ", Timestamp: " + timestamp);

                // Simulate API call that might fail
                updateUserProfile(eventId, timestamp);

                // Update progress and estimate completion time
                processingTasks.put(eventId, null);
            } catch (Exception e) {
                // Handle exceptions and retry mechanism
                handleProcessingFailure(eventId, e);
            }
        });

        // Track the processing task
        processingTasks.put(eventId, task);
    }

    private void updateUserProfile(String eventId, Instant timestamp) throws Exception {
        // Simulate external API call
        System.out.println("Updating user profile for event: " + eventId + ", Timestamp: " + timestamp);
        if (Math.random() < 0.1) { // Simulate failure
            throw new Exception("External API call failed");
        }
