        while (retries < maxRetries) {
            try {
                // Retry the processing
                processEvent(eventJson);
                break; // Success, exit loop
            } catch (Exception ex) {
                retries++;
                if (retries >= maxRetries) {
                    // Log final error and take appropriate action
                    System.err.println("Failed to process event: " + eventId + ", Max retries exceeded");
                }
            }
        }
    }

