    pthread_mutex_init(&list->mutex, NULL);
}

int dynamicListAdd(DynamicList* list, NFAPI_SRS_TX_RX_PARAMS_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    DynamicListNode* newNode = (DynamicListNode*)malloc(sizeof(DynamicListNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamicListRemove(DynamicList* list, int index) {
    pthread_mutex_lock(&list->mutex);
    if (index < 0 || index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index
    }
    if (index == 0) {
        DynamicListNode* temp = list->head;
        list->head = list->head->next;
        free(temp);
    } else {
        DynamicListNode* current = list->head;
        for (int i = 0; i < index - 1; i++) {
            current = current->next;
        }
        DynamicListNode* temp = current->next;
        current->next = temp->next;
        free(temp);
    }
    list->count--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamicListGetCount(DynamicList* list) {
    return list->count;
}
