#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int index;
    struct State* next;
    int* transitions;  // Array of target states for each input symbol
} State;

typedef struct FSA {
    int currentState;
    int numStates;
    State** transitionTable;
    void (*logStateChange)(int oldState, int newState);
} FSA;

void* manageDynamicStateList(int* stateArray, int numStates, FSA* fsa, int lastStateIndex, int* currentSize,
                             void* (*allocator)(size_t size), void (*deallocator)(void* ptr),
                             int (*validateStateExistence)(FSA* fsa, State* list),
                             int (*checkTransitionRuleConsistency)(FSA* fsa, State* list),
                             State** updateStateList(FSA* fsa, State* list),
                             void (*logFunction)(int oldState, int newState)) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    State* newList = allocator(*currentSize * sizeof(State));
    if (!newList) {
        pthread_mutex_destroy(&mutex);
        return NULL;
    }

    for (int i = 0; i < numStates; ++i) {
        int stateIndex = stateArray[i];
        if (validateStateExistence(fsa, newList)) {
            deallocator(newList);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
        State* newStateNode = allocator(sizeof(State));
        if (!newStateNode) {
            for (int j = 0; j < i; ++j) {
                deallocator(newList[j].transitions);
                deallocator(&newList[j]);
            }
            deallocator(newList);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
        newStateNode->index = stateIndex;
        newStateNode->transitions = allocator(fsa->numStates * sizeof(int));
        if (!newStateNode->transitions) {
            for (int j = 0; j <= i; ++j) {
                deallocator(newStateNode[j].transitions);
                deallocator(&newStateNode[j]);
            }
            deallocator(newList);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
        // Initialize transitions based on fsa's transition table
        for (int k = 0; k < fsa->numStates; ++k) {
            newStateNode->transitions[k] = fsa->transitionTable[stateIndex][k];
        }

        if (i > 0) {
            pthread_mutex_lock(&mutex);
            newList[i - 1].next = &newList[i];
            pthread_mutex_unlock(&mutex);
        } else {
            lastStateIndex++;
        }
    }
    *currentSize += numStates;
    pthread_mutex_destroy(&mutex);
    return (void*)lastStateIndex;
}
