public class CustomRandomGenerator
{
    private Random random;

    public CustomRandomGenerator(int seed = 0)
    {
        random = new Random(seed);
    }

    public int NextInt(int minValue, int maxValue, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        if (minValue > maxValue) throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        if (!inclusiveMin && !inclusiveMax) return random.Next(minValue + 1, maxValue);
        if (inclusiveMin && !inclusiveMax) return random.Next(minValue, maxValue + 1);
        if (!inclusiveMin && inclusiveMax) return random.Next(minValue + 1, maxValue + 1);
        return random.Next(minValue, maxValue);
    }

    public float NextFloat(float minValue, float maxValue, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        if (minValue > maxValue) throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        if (!inclusiveMin && !inclusiveMax) return random.NextSingle() * (maxValue - minValue) + minValue;
        if (inclusiveMin && !inclusiveMax) return random.NextSingle() * (maxValue - minValue) + minValue;
        if (!inclusiveMin && inclusiveMax) return random.NextSingle() * (maxValue - minValue) + minValue;
        return random.NextSingle() * (maxValue - minValue) + minValue;
    }

    public T[] NextArray<T>(int size, Func<T> valueGenerator)
    {
        var array = new T[size];
        for (var i = 0; i < size; i++)
            array[i] = valueGenerator();
        return array;
    }

    public void SetSeed(int seed)
    {
        random = new Random(seed);
    }

    public string SerializeState()
    {
        // Implement serialization logic
        return Convert.ToString(random.GetHashCode(), 16);
    }
}

public class DnsResolver
{
    private static readonly ConcurrentDictionary<string, IPAddress> cache = new ConcurrentDictionary<string, IPAddress>();
    private static int timeout = 500; // Default timeout in milliseconds

    public static u_char[] ResolveHostname(string hostname)
    {
        try
        {
            if (cache.TryGetValue(hostname, out var ip))
                return ip.GetAddressBytes();

            lock (cache)
            {
                if (!cache.TryGetValue(hostname, out ip))
                {
                    var entry = Dns.GetHostEntryAsync(hostname);
                    entry.Wait();
                    cache.TryAdd(hostname, entry.Result.AddressList[0]);
                    ip = cache[hostname];
                }
            }

            return ip.GetAddressBytes();
        }
        catch (Exception)
        {
            // Handle DNS resolution errors
            throw new Exception("Failed to resolve hostname.");
        }
    }
}

public class NetworkLatencySimulator
{
    private static readonly Random random = new Random();

    public static void SimulateNetworkLatency(int millisecondsDelay)
    {
        Thread.Sleep(random.Next(millisecondsDelay));
    }

    public static int SimulatePacketLoss(double lossRate)
    {
        if (random.NextDouble() < lossRate)
            return 0;
        return 1;
    }
}

