using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;

public class CustomRandomGenerator : IDisposable
{
    private Random _random;
    private List<double> _generatedValues;
    private double _mean;
    private double _standardDeviation;

    public CustomRandomGenerator(int seed = 0)
    {
        _random = new Random(seed);
        _generatedValues = new List<double>();
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
        ClearData();
    }

    public double GenerateDouble(double min, double max, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        double value;
        if (inclusiveMin && inclusiveMax)
            value = _random.NextDouble() * (max - min) + min;
        else if (inclusiveMin)
            value = _random.NextDouble() * (max - min) + min;
        else if (inclusiveMax)
            value = _random.NextDouble() * (max - min) + min;
        else
            value = _random.NextDouble() * (max - min);

        RecordValue(value);
        return value;
    }

    public int GenerateInt(int min, int max, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        int value;
        if (inclusiveMin && inclusiveMax)
            value = _random.Next(min, max + 1);
        else if (inclusiveMin)
            value = _random.Next(min, max + 1);
        else if (inclusiveMax)
            value = _random.Next(min, max);
        else
            value = _random.Next(min, max);

        RecordValue(value);
        return value;
    }

    public double[] GenerateArray(int size, double min, double max, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        if (size <= 0)
            throw new ArgumentException("Size must be greater than zero.");

        var array = new double[size];
        for (int i = 0; i < size; i++)
            array[i] = GenerateDouble(min, max, inclusiveMin, inclusiveMax);

        return array;
    }

    public int[] GenerateIntArray(int size, int min, int max, bool inclusiveMin = true, bool inclusiveMax = false)
    {
        if (size <= 0)
            throw new ArgumentException("Size must be greater than zero.");

        var array = new int[size];
        for (int i = 0; i < size; i++)
            array[i] = GenerateInt(min, max, inclusiveMin, inclusiveMax);

        return array;
    }

    public string SerializeToJson()
    {
        var summary = new
        {
            Seed = _random.Seed,
            Mean = GetMean(),
            StandardDeviation = GetStandardDeviation(),
            Quantiles = GetQuantiles()
        };

        return JsonConvert.SerializeObject(summary, Formatting.Indented);
    }

    private void RecordValue(double value)
    {
        _generatedValues.Add(value);
    }

    private double GetMean()
    {
        if (_generatedValues.Count == 0) return 0;
        return _generatedValues.Average();
    }

    private double GetStandardDeviation()
    {
        if (_generatedValues.Count == 0) return 0;
        var mean = GetMean();
        return Math.Sqrt(_generatedValues.Sum(v => (v - mean) * (v - mean)) / _generatedValues.Count);
    }

    private List<double> GetQuantiles(double[] quantileLevels)
    {
        if (_generatedValues.Count == 0) return new List<double>();

        var sortedValues = _generatedValues.OrderBy(v => v).ToList();
        var quantiles = new List<double>();
        foreach (var level in quantileLevels)
        {
            int index = (int)(sortedValues.Count * level);
            double value = sortedValues[index];
            quantiles.Add(value);
        }

        return quantiles;
    }

    private void ClearData()
    {
        _generatedValues.Clear();
        _mean = 0;
        _standardDeviation = 0;
    }

    public void Dispose()
    {
        _random.Dispose();
    }
}
