#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define COMPACT_THRESHOLD 80

typedef struct NFAPI_RLC_PDU_T {
    uint32_t TX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    void* PDU_DATA;
    size_t PDU_SIZE;
    uint8_t PDUFIELD;
    uint32_t priority;
} NFAPI_RLC_PDU_T;

typedef struct ListEntry {
    NFAPI_RLC_PDU_T data;
    struct ListEntry* next;
} ListEntry;

typedef struct DynamicList {
    ListEntry** entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    size_t peak_memory_usage;
    size_t current_memory_usage;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->entries = (ListEntry**)calloc(MAX_ENTRIES, sizeof(ListEntry*));
    list->size = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->lock, NULL);
    list->peak_memory_usage = 0;
    list->current_memory_usage = 0;
    return list;
}

void free_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        ListEntry* entry = list->entries[i];
        if (entry != NULL) {
            if (entry->data.PDU_DATA != NULL) {
                free(entry->data.PDU_DATA);
                list->current_memory_usage -= entry->data.PDU_SIZE;
            }
            free(entry);
        }
    }
    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}

void add_entry(DynamicList* list, NFAPI_RLC_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&list->lock);
        return;
    }
    ListEntry* entry = (ListEntry*)malloc(sizeof(ListEntry));
    entry->data = data;
    entry->next = NULL;

    size_t insert_index = 0;
    while (insert_index < list->size && list->entries[insert_index]->data.RNTI < data.RNTI) {
        ++insert_index;
    }
    for (size_t i = list->size; i > insert_index; --i) {
        list->entries[i] = list->entries[i - 1];
    }
    list->entries[insert_index] = entry;
    if (data.PDU_DATA != NULL) {
        list->current_memory_usage += data.PDU_SIZE;
        if (list->current_memory_usage > list->peak_memory_usage) {
            list->peak_memory_usage = list->current_memory_usage;
        }
    }
    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

void update_entry(DynamicList* list, NFAPI_RLC_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->data.RNTI == new_data.RNTI) {
            ListEntry* entry = list->entries[i];
            if (entry->data.PDU_DATA != NULL) {
                free(entry->data.PDU_DATA);
                list->current_memory_usage -= entry->data.PDU_SIZE;
            }
            entry->data = new_data;
            if (new_data.PDU_DATA != NULL) {
                entry->data.PDU_SIZE = new_data.PDU_SIZE;
                entry->data.PDU_DATA = malloc(new_data.PDU_SIZE);
                memcpy(entry->data.PDU_DATA, new_data.PDU_DATA, new_data.PDU_SIZE);
                list->current_memory_usage += new_data.PDU_SIZE;
            }
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_entry(DynamicList* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->data.RNTI == RNTI) {
            ListEntry* entry = list->entries[i];
            if (entry->data.PDU_DATA != NULL) {
                free(entry->data.PDU_DATA);
                list->current_memory_usage -= entry->data.PDU_SIZE;
            }
            for (size_t j = i; j < list->size - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->size;
            free(entry);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

