typedef struct LRU_CACHE {
    int capacity, size;
    LRU_CACHE_NODE *head, *tail;
    pthread_mutex_t lock;
} LRU_CACHE;

void initialize_cache(LRU_CACHE *cache, int capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

void add_to_cache(LRU_CACHE *cache, NFAPI_SRS_TX_RX_PARAMS_PDU_T *data) {
    pthread_mutex_lock(&cache->lock);
    LRU_CACHE_NODE *new_node = (LRU_CACHE_NODE *)malloc(sizeof(LRU_CACHE_NODE));
    new_node->data = data;
    new_node->next = NULL;
    if (cache->head == NULL) {
        cache->head = cache->tail = new_node;
        new_node->prev = NULL;
    } else {
        cache->tail->next = new_node;
        new_node->prev = cache->tail;
        cache->tail = new_node;
    }
    if (++(cache->size) > cache->capacity) {
        LRU_CACHE_NODE *temp = cache->head;
        cache->head = cache->head->next;
        if (cache->head != NULL) cache->head->prev = NULL;
        else cache->tail = NULL;
        free(temp);
    }
    pthread_mutex_unlock(&cache->lock);
}

