int allocate_rnti(RNTI_POOL* pool, uint16_t* rnti) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count >= pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // No available RNTIs
    }
    *rnti = pool->pool[pool->used_count++];
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void deallocate_rnti(RNTI_POOL* pool, uint16_t rnti) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used_count; ++i) {
        if (pool->pool[i] == rnti) {
            pool->pool[i] = pool->pool[--pool->used_count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

