NFAPI_CRC_INDICATION_PDU_T* process_file(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* content = (char*)malloc(file_size + 1);
    fread(content, 1, file_size, file);
    fclose(file);

    *size = 0;
    for (int i = 0; i < file_size; i++) {
        if (content[i] == '\n') (*size)++;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    char* line = strtok(content, "\n");
    int index = 0;

    while (line != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[index];
        // Assume fields are separated by spaces
        sscanf(line, "%d %d", &pdu->RX_UE_INFORMATION_TAG, &pdu->RNTI);
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        char* avg_str = strtok(NULL, " ");
        if (avg_str != NULL) {
            int last_field1, last_field2;
            sscanf(avg_str, "%d", &last_field1);
            line = strtok(NULL, "\n");
            sscanf(line, "%d", &last_field2);
            pdu->average = (double)(last_field1 + last_field2) / 2;
        }
        index++;
        line = strtok(NULL, "\n");
    }

    free(content);
    return pdu_list;
}

