typedef struct ResourceBundle {
    char* data;
    size_t size;
    int format;
} ResourceBundle;

ResourceBundle* cache = NULL;

int load_resource_bundle(const char* path, enum ResourceBundleFormat format) {
    if (cache != NULL && cache->format == format) {
        return 0; // Return cached bundle
    }

    FILE* file = fopen(path, "rb");
    if (!file) {
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    size_t size = (size_t)f.tell();
    fseek(file, 0, SEEK_SET);

    char* data = (char*)malloc(size + 1);
    if (!data) {
        fclose(file);
        return -2; // Error allocating memory
    }

    size_t bytesRead = fread(data, 1, size, file);
    if (bytesRead != size) {
        free(data);
        fclose(file);
        return -3; // Error reading file
    }

    data[size] = '\0';
    fclose(file);

    if (cache != NULL) {
        free(cache->data);
    }

    cache = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    cache->data = data;
    cache->size = size;
    cache->format = format;

    return 0; // Success
}

int get_ip_address(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // Error resolving hostname
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);

        if (inet_pton(AF_INET, ipstr, ip_address) > 0) {
            freeaddrinfo(res); // Free the linked list
            return 0; // Success
        }
    }

    freeaddrinfo(res); // Free the linked list
    return -2; // Error finding IP address
}

