import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashProcessor {

    private static final Map<String, String> hashCache = new HashMap<>();
    private static final File outputDir = new File("output");
    private static final Logger logger = LoggerFactory.getLogger(HashProcessor.class);

    public void processBatch(String configFilePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!hashCache.containsKey(line)) {
                    hashCache.put(line, computeHashes(line));
                }
                writeToFile(line, hashCache.get(line));
            }
        } catch (IOException e) {
            logger.error("Error reading configuration file: {}", configFilePath, e);
        }
    }

    private String computeHashes(String input) {
        StringBuilder hashes = new StringBuilder();
        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            hashes.append(bytesToHex(md5.digest(input.getBytes())));
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            hashes.append("|").append(bytesToHex(sha1.digest(input.getBytes())));
            // Add other hash algorithms here
        } catch (NoSuchAlgorithmException e) {
            logger.error("Error computing hash for input: {}", input, e);
        }
        return hashes.toString();
    }

    private void writeToFile(String input, String hashes) {
        File outputFile = new File(outputDir, input + ".hash");
        try (PrintWriter writer = new PrintWriter(outputFile)) {
            writer.println(input);
            writer.println(hashes);
        } catch (FileNotFoundException e) {
            logger.error("Error writing to output file: {}", outputFile.getPath(), e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
