    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    MobileNetworkData *data = (MobileNetworkData*)malloc(sizeof(MobileNetworkData));
    if (!data) {
        perror("Failed to allocate memory for data");
        fclose(file);
        return NULL;
    }
