            free(data);
            fclose(file);
            return NULL;
        }

        for (int i = 0; i < MAX_PDUS && record->records[i] != NULL; ++i) {
            if (!validate_pdu(record, i)) {
                fprintf(stderr, "Invalid PDU checksum at index %d\n", i);
                free(record);
                continue;
            }
            data->records[data->record_count++] = record;
        }
    }

    fclose(file);
    return data;
}

void free_data(MobileNetworkData *data) {
    for (int i = 0; i < data->record_count; ++i) {
        free(data->records[i]);
    }
    free(data);
