public class ApiClient
{
    private readonly HttpClient _httpClient;

    public ApiClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<T> GetDataAsync<T>(string url, int retryCount = 3)
    {
        for (int i = 0; i <= retryCount; i++)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadAsAsync<T>();
            }
            catch when (i == retryCount)
            {
                throw;
            }
            catch
            {
                // Implement exponential backoff here
                await Task.Delay(200 * i);
            }
        }

        throw new InvalidOperationException("Failed to fetch data from API.");
    }
}

public class CustomMembershipAndRoleManager
{
    private readonly MembershipProvider _membershipProvider;
    private readonly RoleProvider _roleProvider;
    private readonly ApiClient _apiClient;

    public CustomMembershipAndRoleManager(MembershipProvider membershipProvider, RoleProvider roleProvider, ApiClient apiClient)
    {
        _membershipProvider = membershipProvider;
        _roleProvider = roleProvider;
        _apiClient = apiClient;
    }

    public async Task<UserData> AuthenticateUserAsync(string username, string password)
    {
        var user = _membershipProvider.GetUser(username, true);
        if (user != null && _membershipProvider.ValidateUser(username, password))
        {
            return new UserData
            {
                Username = user.UserName,
                Roles = _roleProvider.GetRolesForUser(username).ToList()
            };
        }

        throw new InvalidOperationException("Invalid username or password.");
    }

    public async Task UpdateUserDataAsync(string username)
    {
        var userData = await FetchUserDataFromApiAsync(username);
        if (userData != null)
        {
            CacheManager.AddToCache($"UserData_{username}", userData);
        }
    }

    private async Task<UserData> FetchUserDataFromApiAsync(string username)
    {
        try
        {
            return await _apiClient.GetDataAsync<UserData>($"/api/users/{username}");
        }
        catch (Exception ex)
        {
            // Handle connectivity issues and rate limits here
            throw;
        }
    }

    public void InvalidateCache(string username)
    {
        CacheManager.RemoveFromCache($"UserData_{username}");
    }
}

public class UserData
{
