import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

public class ActivityLogService {

    private static final ConcurrentHashMap<String, List<ActivityLogEntry>> activityCache = new ConcurrentHashMap<>();
    private static final AtomicBoolean cacheNeedsRefresh = new AtomicBoolean(false);

    public static List<ActivityLogEntry> fetchUserActivityLog(UserId userId) {
        String apiUrl = System.getenv("ACTIVITY_LOG_API_URL");
        if (cacheNeedsRefresh.getAndSet(true)) {
            refreshCache(apiUrl);
        }
        return activityCache.getOrDefault(userId.toString(), List.of());
    }

    private static void refreshCache(String apiUrl) {
        try {
            List<ActivityLogEntry> updatedLogs = fetchFromApi(apiUrl);
            activityCache.putAll(updatedLogs.stream()
                    .collect(Collectors.groupingBy(ActivityLogEntry::getUserId)));
        } catch (Exception e) {
            // Handle transient failures, log the error and optionally use cached data
            System.err.println("Failed to refresh cache: " + e.getMessage());
        }
    }

    private static List<ActivityLogEntry> fetchFromApi(String apiUrl) throws Exception {
        // Simulate fetching from API
        Thread.sleep(100); // Simulate network latency
        return List.of(new ActivityLogEntry(userId, "Login"), new ActivityLogEntry(userId, "Logout"));
    }
}
