typedef struct {
    uint32_t PacketIdentifier;
    uint32_t SourceAddress;
    uint32_t DestinationAddress;
} NetworkLayerHeader;

typedef struct {
    NetworkLayerHeader* buffer;
    size_t capacity;
    size_t front;
    size_t rear;
    size_t count;
    pthread_mutex_t lock;
} NetworkBuffer;

NetworkBuffer* initializeNetworkBuffer(size_t initial_capacity) {
    NetworkBuffer* buffer = (NetworkBuffer*)malloc(sizeof(NetworkBuffer));
    if (!buffer) {
        log_error("Failed to allocate memory for network buffer");
        return NULL;
    }

    buffer->buffer = (NetworkLayerHeader*)calloc(initial_capacity, sizeof(NetworkLayerHeader));
    if (!buffer->buffer) {
        log_error("Failed to allocate memory for buffer array");
        free(buffer);
        return NULL;
    }

    buffer->capacity = initial_capacity;
    buffer->front = 0;
    buffer->rear = -1;
    buffer->count = 0;

    pthread_mutex_init(&buffer->lock, NULL);

    log_info("Network buffer initialized with capacity %zu", initial_capacity);
    return buffer;
}

void destroyNetworkBuffer(NetworkBuffer* buffer) {
    if (!buffer) return;

    free(buffer->buffer);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);

    log_info("Network buffer destroyed");
}
