public class DynamicRandomGenerator : IDisposable
{
    private int _minRange;
    private int _maxRange;
    private long _seed;
    private Random _random;

    public DynamicRandomGenerator(int minRange, int maxRange, long seed)
    {
        Initialize(minRange, maxRange, seed);
    }

    ~DynamicRandomGenerator()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _random?.Dispose();
            _random = null;
        }
    }

    private void Initialize(int minRange, int maxRange, long seed)
    {
        if (minRange >= maxRange)
        {
            throw new ArgumentException("Max range must be greater than min range.");
        }

        _minRange = minRange;
        _maxRange = maxRange;
        _seed = seed;
        _random = new Random((int)_seed);
    }

    public int GenerateRandomIntInclusive()
    {
        return _random.Next(_minRange, _maxRange + 1);
    }

    public int GenerateRandomIntExclusive()
    {
        return _random.Next(_minRange, _maxRange);
    }

    public float GenerateRandomFloatInclusive()
    {
        return _random.Range((float)_minRange, (float)_maxRange + 1f);
    }

    public float GenerateRandomFloatExclusive()
    {
        return _random.Range((float)_minRange, (float)_maxRange);
    }

    public override string ToString()
    {
        return $"DynamicRandomGenerator with range [{_minRange}, {_maxRange}] and seed {_seed}";
    }

    public void ResetRange(int minRange = 0, int maxRange = 1)
    {
        Initialize(minRange, maxRange, _seed);
    }

    public static int GenerateRandomFromInstance(DynamicRandomGenerator generator)
    {
        if (generator == null)
        {
            throw new ArgumentNullException(nameof(generator));
        }

        return generator.GenerateRandomIntInclusive();
    }
}
