    }

    public override string ToString()
    {
        return $"DynamicRandomGenerator with Range: {_configurations["MinRange"]} to {_configulations["MaxRange"]}";
    }

    public void ResetToDefault()
    {
        Initialize(0, int.MaxValue, Environment.TickCount);
    }

    public static int GenerateInt(DynamicRandomGenerator generator, int min = 0, int max = int.MaxValue)
    {
        return generator._random.Next(min, max + 1);
    }

    public static float GenerateFloat(DynamicRandomGenerator generator, float min = 0.0f, float max = 1.0f)
    {
        return (float)(generator._random.NextDouble() * (max - min)) + min;
    }

