    private static final Map<String, String> packageCache = new ConcurrentHashMap<>();

    public static void updatePackage(String platform) {
        try {
            String latestVersion = fetchLatestVersionFromApi();
            if (latestVersion != null && !latestVersion.equals(getInstalledVersion(platform))) {
                downloadAndInstallPackage(latestVersion, platform);
            }
        } catch (IOException | InterruptedException e) {
            handleException(e);
        }
    }

    private static String fetchLatestVersionFromApi() throws IOException {
        long cacheTime = System.currentTimeMillis();
        if (!packageCache.containsKey("latestVersion") || 
                cacheTime - packageCache.get("cacheTime").toLongValue() > CACHE_EXPIRATION_TIME) {
            URL url = new URL(API_URL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String inputLine;
                StringBuilder response = new StringBuilder();
                while ((inputLine = in.readLine()) != null) {
                    response.append(inputLine);
                }
                packageCache.put("latestVersion", response.toString());
                packageCache.put("cacheTime", String.valueOf(cacheTime));
            }
        }
        return packageCache.get("latestVersion");
    }

    private static void downloadAndInstallPackage(String version, String platform) throws IOException, InterruptedException {
