#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    int frame_info;
    int tx_power_level;
    int channel_configuration;
} LTE_PHY_TX_BUFFER_T;

#define DEFAULT_POOL_SIZE 500

typedef enum {
    BEST_FIT,
    WORST_FIT
} AllocationPolicy;

typedef struct BufferPool {
    LTE_PHY_TX_BUFFER_T *pool;
    size_t size;
    size_t allocated_count;
    pthread_mutex_t lock;
    AllocationPolicy policy;
} BufferPool;

BufferPool* create_buffer_pool(size_t size) {
    if (size == 0) {
        size = DEFAULT_POOL_SIZE;
    }
    BufferPool *pool = (BufferPool*) malloc(sizeof(BufferPool));
    if (!pool) return NULL;
    pool->pool = (LTE_PHY_TX_BUFFER_T*) calloc(size, sizeof(LTE_PHY_TX_BUFFER_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pool->allocated_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->policy = BEST_FIT; // Default policy
    return pool;
}

void destroy_buffer_pool(BufferPool *pool) {
    if (!pool) return;
    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

LTE_PHY_TX_BUFFER_T* allocate_buffer(BufferPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_count == pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    LTE_PHY_TX_BUFFER_T *buffer = &pool->pool[pool->allocated_count++];
    pthread_mutex_unlock(&pool->lock);
    return buffer;
}

void deallocate_buffer(BufferPool *pool, LTE_PHY_TX_BUFFER_T *buffer) {
    pthread_mutex_lock(&pool->lock);
    size_t index = (size_t)(buffer - pool->pool);
    if (index >= pool->allocated_count || pool->pool[index].frame_info == 0) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid deallocation
    }
    buffer->frame_info = 0;
    buffer->tx_power_level = 0;
    buffer->channel_configuration = 0;
    pool->allocated_count--;
    pthread_mutex_unlock(&pool->lock);
}
