#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <dirent.h>
#include <pthread.h>
#include <openssl/md5.h>

#define MAX_LINE_LENGTH 1024
#define DEFAULT_CHAR_LIMIT 80

typedef struct {
    int char_limit;
    const char *output_file;
    int verbose;
    pthread_mutex_t lock;
} Config;

void print_manpage() {
    printf("Usage: config_tool [options] <input_file>\n");
    printf("-cs <count>: Specify the number of characters per line limit for validation purposes.\n");
    printf("-o <output_file>: Redirect output to a specified file instead of standard output.\n");
    printf("-v: Enable verbose mode for additional logging.\n");
}

void *process_file(void *arg) {
    Config *config = (Config *)arg;
    char *filename = ((char **)arg)[1];
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];
    char buffer[MAX_LINE_LENGTH];
    int line_number = 0, exceeded_count = 0;

    pthread_mutex_lock(&config->lock);
    if (config->verbose) {
        printf("Processing file: %s\n", filename);
    }
    pthread_mutex_unlock(&config->lock);

    MD5_Init(&md5);
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        MD5_Update(&md5, buffer, strlen(buffer));
        line_number++;
        if (strlen(buffer) > config->char_limit) {
            exceeded_count++;
            if (config->verbose) {
                printf("Line %d in %s exceeds character limit\n", line_number, filename);
            }
        }
    }

    fclose(file);

    MD5_Final(digest, &md5);
    char checksum[MD5_DIGEST_LENGTH * 2 + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&checksum[i * 2], "%02x", digest[i]);
    }

    pthread_mutex_lock(&config->lock);
    if (config->verbose) {
        printf("File %s processed, lines exceeding limit: %d\n", filename, exceeded_count);
    }
    fprintf(config->output_file ? config->output_file : stdout, "File: %s, Checksum: %s, Lines Exceeding Limit: %d\n", filename, checksum, exceeded_count);
    pthread_mutex_unlock(&config->lock);

    return NULL;
}

int main(int argc, char *argv[]) {
    Config config = {DEFAULT_CHAR_LIMIT, NULL, 0};
    int opt;
    while ((opt = getopt(argc, argv, "cs:o:v")) != -1) {
        switch (opt) {
            case 'c':
                config.char_limit = atoi(optarg);
                break;
            case 'o':
                if (!(config.output_file = fopen(optarg, "w"))) {
                    perror("Error opening output file");
                    return EXIT_FAILURE;
                }
                break;
            case 'v':
                config.verbose = 1;
                break;
            default:
                print_manpage();
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        print_manpage();
        return EXIT_FAILURE;
    }

    if (!strcmp(argv[optind], "--manpage")) {
        print_manpage();
        return EXIT_SUCCESS;
    } else if (!strcmp(argv[optind], "-d")) {
        DIR *dir = opendir(argv[optind + 1]);
        if (!dir) {
            perror("Error opening directory");
            return EXIT_FAILURE;
        }

        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".conf")) {
                pthread_t thread;
                char **args = (char **)malloc(2 * sizeof(char *));
                args[0] = argv[optind + 1];
                args[1] = entry->d_name;
                if (pthread_create(&thread, NULL, process_file, &config)) {
                    perror("Error creating thread");
                    free(args);
                    closedir(dir);
                    return EXIT_FAILURE;
                }
                pthread_detach(thread);
            }
        }

        closedir(dir);
    } else {
        pthread_t thread;
        char **args = (char **)malloc(2 * sizeof(char *));
        args[0] = argv[optind];
        args[1] = NULL;
        if (pthread_create(&thread, NULL, process_file, &config)) {
            perror("Error creating thread");
            free(args);
            return EXIT_FAILURE;
        }
        pthread_join(thread, NULL);
    }

    if (config.output_file) {
        fclose(config.output_file);
    }

    return EXIT_SUCCESS;
}
