#define RECORD_BUFFER_SIZE 16

typedef struct {
    int value;
    char buffer[RECORD_BUFFER_SIZE];
} Record;

int allocate_and_initialize_arrays(int limit, long **offsets, int **keys, Record **records) {
    size_t keys_size = (limit + 1) * sizeof(int);
    size_t offsets_size = (limit + 1) * sizeof(long);
    size_t records_size = (limit + 1) * sizeof(Record);

    *offsets = aligned_alloc(CACHE_LINE_SIZE, offsets_size);
    *keys = aligned_alloc(CACHE_LINE_SIZE, keys_size);
    *records = aligned_alloc(CACHE_LINE_SIZE, records_size);

    if (!*offsets || !*keys || !*records) {
        perror("Memory allocation failed");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    (*keys)[0] = 0;
    for (int i = 1; i <= limit; ++i) {
        (*keys)[i] = (*keys)[i - 1] + i;
    }

    for (int i = 0; i <= limit; ++i) {
        do {
            (*records)[i].value = rand() % 1000;
        } while (i > 0 && (*records)[i].value == (*records)[i - 1].value);
        snprintf((*records)[i].buffer, RECORD_BUFFER_SIZE, "%d", (*records)[i].value);
    }

