    time_t timestamp;
    unsigned int checksum;
    int ref_count;
} Packet;

Packet* create_packet_buffer(int limit) {
    if (limit > MAX_PACKETS) {
        printf("Error: Limit exceeds maximum allowed packets.\n");
        return NULL;
    }

    size_t total_size = sizeof(Packet) * limit;
    Packet* packet_buffer = aligned_alloc(128, total_size); // Align to 128 bytes for cache performance
    if (!packet_buffer) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < limit; i++) {
        packet_buffer[i].sequence_number = i;
        time(&packet_buffer[i].timestamp);
        packet_buffer[i].checksum = rand(); // Random checksum for demonstration
        packet_buffer[i].ref_count = 1;
    }

    return packet_buffer;
}

void destroy_packet_buffer(Packet* buffer, int limit) {
    free(buffer);
}
