#include <string.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    double value;
    char* str;
} Record;

typedef struct Collection {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} Collection;

void init_collection(Collection* coll, size_t initial_capacity) {
    coll->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    coll->count = 0;
    coll->capacity = initial_capacity;
    pthread_mutex_init(&coll->mutex, NULL);
}

void add_record(Collection* coll, Record* record) {
    pthread_mutex_lock(&coll->mutex);
    if (coll->count >= coll->capacity) {
        size_t new_capacity = coll->capacity * 2;
        Record** new_records = (Record**)realloc(coll->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&coll->mutex);
            return;
        }
        coll->records = new_records;
        coll->capacity = new_capacity;
    }
    coll->records[coll->count++] = record;
    pthread_mutex_unlock(&coll->mutex);
}

void destroy_collection(Collection* coll) {
    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->records[i]->str);
        free(coll->records[i]);
    }
    free(coll->records);
    pthread_mutex_destroy(&coll->mutex);
}
