typedef struct {
    int key;
    long offset;
    double value;
    char* str;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    memset(collection->records, 0, initial_capacity * sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->size; ++i) {
            Record* record = collection->records[i];
            free(record->str);
            free(record);
        }
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_record(RecordCollection* collection, int key, long offset, double value, const char* str) {
    if (collection->size >= collection->capacity) {
        Record** new_records = realloc(collection->records, 2 * collection->capacity * sizeof(Record*));
        if (!new_records) return -1;

        collection->records = new_records;
        collection->capacity *= 2;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->key = key;
    record->offset = offset;
    record->value = value;
    record->str = strdup(str);
    if (!record->str) {
        free(record);
        return -1;
    }

    pthread_mutex_lock(&collection->mutex);
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

