#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    double value;
    char *str;
} Record;

typedef struct Node {
    Record data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_record(List *list, Record data) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void free_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Record data = current->data;
        free(data.str);
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
