['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_NETWORKS 100
#define MAC_ADDRESS_LENGTH 18
#define IP_ADDRESS_LENGTH 16

typedef struct {
    char mac_address[MAC_ADDRESS_LENGTH];
    char ip_address[IP_ADDRESS_LENGTH];
    char subnet_mask[IP_ADDRESS_LENGTH];
    char gateway[IP_ADDRESS_LENGTH];
} NICConfig;

typedef struct {
    NICConfig networks[MAX_NETWORKS];
    int active_networks;
    sem_t lock;
    pthread_mutex_t gc_lock;
} NetworkManager;

NetworkManager network_manager;

void initialize_network_manager() {
    memset(&network_manager, 0, sizeof(NetworkManager));
    sem_init(&network_manager.lock, 0, 1);
    pthread_mutex_init(&network_manager.gc_lock, NULL);
}

int add_network(const char *mac, const char *ip, const char *subnet, const char *gateway) {
    sem_wait(&network_manager.lock);
    if (network_manager.active_networks >= MAX_NETWORKS) {
        sem_post(&network_manager.lock);
        return -1; // Network limit reached
    }

    int index = network_manager.active_networks;
    strncpy(network_manager.networks[index].mac_address, mac, MAC_ADDRESS_LENGTH - 1);
    strncpy(network_manager.networks[index].ip_address, ip, IP_ADDRESS_LENGTH - 1);
    strncpy(network_manager.networks[index].subnet_mask, subnet, IP_ADDRESS_LENGTH - 1);
    strncpy(network_manager.networks[index].gateway, gateway, IP_ADDRESS_LENGTH - 1);
    network_manager.active_networks++;
    sem_post(&network_manager.lock);
    return index;
}

void remove_network(int index) {
    sem_wait(&network_manager.lock);
    if (index < 0 || index >= network_manager.active_networks) {
        sem_post(&network_manager.lock);
        return; // Invalid index
    }

    for (int i = index; i < network_manager.active_networks - 1; i++) {
        memcpy(&network_manager.networks[i], &network_manager.networks[i + 1], sizeof(NICConfig));
    }
    network_manager.active_networks--;
    sem_post(&network_manager.lock);
}

void* garbage_collection(void *arg) {
    while (1) {
        pthread_mutex_lock(&network_manager.gc_lock);
        // Implement garbage collection logic here
        pthread_mutex_unlock(&network_manager.gc_lock);
        sleep(60); // Run every 60 seconds
    }
    return NULL;
}

void start_garbage_collection() {
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection, NULL);
}

void dump_networks() {
    sem_wait(&network_manager.lock);
    for (int i = 0; i < network_manager.active_networks; i++) {
        printf("Network %d:\n", i);
        printf("  MAC: %s\n", network_manager.networks[i].mac_address);
        printf("  IP: %s\n", network_manager.networks[i].ip_address);
        printf("  Subnet Mask: %s\n", network_manager.networks[i].subnet_mask);
        printf("  Gateway: %s\n", network_manager.networks[i].gateway);
    }
    sem_post(&network_manager.lock);
}

int main() {
    initialize_network_manager();
    start_garbage_collection();

    add_network("00:1A:2B:3C:4D:5E", "192.168.1.1", "255.255.255.0", "192.168.1.254");
    add_network("AA:BB:CC:DD:EE:FF", "10.0.0.1", "255.0.0.0", "10.0.0.254");

    dump_networks();

    remove_network(0);

    dump_networks();

    return 0;
}
