    char REMOTE_URL[1024];
    int LOCAL_PORT;
    char REQUEST_METHOD[10];
    int RESPONSE_STATUS;
} HTTP_REQUEST_RECORD;

HTTP_REQUEST_RECORD** request_pool = NULL;
int pool_size = N;
pthread_mutex_t lock;
FILE* log_file = NULL;

void* allocate_request_pool() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < pool_size; i++) {
        if (request_pool[i] == NULL) {
            request_pool[i] = malloc(sizeof(HTTP_REQUEST_RECORD));
            if (request_pool[i] == NULL) {
                log_error("Memory allocation failed");
                continue;
            }
            memset(request_pool[i], 0, sizeof(HTTP_REQUEST_RECORD));
            pthread_mutex_unlock(&lock);
            return request_pool[i];
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void deallocate_request_record(HTTP_REQUEST_RECORD* record) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < pool_size; i++) {
        if (request_pool[i] == record) {
            free(request_pool[i]);
            request_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_error(const char* message) {
    fprintf(log_file, "ERROR: %s\n", message);
    fflush(log_file);
}

int main(int argc, char* argv[]) {
    // Initialize log file
    if (argc > 1) {
        log_file = fopen(argv[1], "w");
        if (!log_file) {
            perror("Failed to open log file");
            return EXIT_FAILURE;
        }
    } else {
        log_file = stdout;
    }

    // Allocate request pool
    request_pool = malloc(pool_size * sizeof(HTTP_REQUEST_RECORD*));
    if (request_pool == NULL) {
        log_error("Failed to allocate request pool");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize mutex
    pthread_mutex_init(&lock, NULL);

    // Simulate request handling
    for (int i = 0; i < pool_size; i++) {
        HTTP_REQUEST_RECORD* record = allocate_request_pool();
        if (record == NULL) {
            printf("Failed to allocate request record\n");
            continue;
        }
        record->LOCAL_PORT = i * 100;
        strcpy(record->REQUEST_METHOD, "GET");
        // Handle HTTP request
        deallocate_request_record(record);
    }

    // Clean up
    pthread_mutex_destroy(&lock);
    free(request_pool);
    if (log_file != stdout) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}
