#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_NODES 100
#define MAX_CONCURRENT_IO 5

typedef struct {
    char file_name[256];
    int metadata_size;
    void* metadata;
} FileMetadata;

typedef struct {
    FileMetadata* cache[MAX_NODES];
    int node_count;
    sem_t io_semaphore;
    pthread_mutex_t cache_lock;
    int max_concurrent_io;
} DistributedCache;

int initialize_cache(DistributedCache* cache, int max_concurrent_io) {
    cache->node_count = 0;
    if (sem_init(&cache->io_semaphore, 0, max_concurrent_io) != 0) {
        return -1; // Error initializing semaphore
    }
    pthread_mutex_init(&cache->cache_lock, NULL);
    cache->max_concurrent_io = max_concurrent_io;
    return 0;
}

int add_node(DistributedCache* cache, FileMetadata* metadata) {
    if (cache->node_count >= MAX_NODES) {
        return -1; // Cache full
    }
    sem_wait(&cache->io_semaphore);
    pthread_mutex_lock(&cache->cache_lock);
    cache->cache[cache->node_count++] = metadata;
    pthread_mutex_unlock(&cache->cache_lock);
    sem_post(&cache->io_semaphore);
    return 0;
}

FileMetadata* get_metadata(DistributedCache* cache, const char* file_name) {
    for (int i = 0; i < cache->node_count; ++i) {
        if (strcmp(cache->cache[i]->file_name, file_name) == 0) {
            return cache->cache[i];
        }
    }
    return NULL;
}

int update_metadata(DistributedCache* cache, const char* file_name, void* new_metadata, int metadata_size) {
    for (int i = 0; i < cache->node_count; ++i) {
        if (strcmp(cache->cache[i]->file_name, file_name) == 0) {
            sem_wait(&cache->io_semaphore);
            pthread_mutex_lock(&cache->cache_lock);
            free(cache->cache[i]->metadata); // Free old metadata
            cache->cache[i]->metadata = malloc(metadata_size);
            memcpy(cache->cache[i]->metadata, new_metadata, metadata_size);
            cache->cache[i]->metadata_size = metadata_size;
            pthread_mutex_unlock(&cache->cache_lock);
            sem_post(&cache->io_semaphore);
            return 0; // Metadata updated successfully
        }
    }
    return -1; // File not found in cache
}

void* io_worker(void* arg) {
    DistributedCache* cache = (DistributedCache*)arg;
    while (1) {
        sem_wait(&cache->io_semaphore);
        pthread_mutex_lock(&cache->cache_lock);
        // Perform I/O operation on the metadata (load or save)
        pthread_mutex_unlock(&cache->cache_lock);
        sem_post(&cache->io_semaphore);
    }
}

int main() {
    DistributedCache cache;
    if (initialize_cache(&cache, MAX_CONCURRENT_IO) != 0) {
        fprintf(stderr, "Failed to initialize distributed cache\n");
        return 1;
    }

    // Example usage
    FileMetadata metadata = { .file_name = "example.txt", .metadata_size = sizeof(int), .metadata = malloc(sizeof(int)) };
    add_node(&cache, &metadata);

    // Start I/O workers
    pthread_t io_threads[MAX_CONCURRENT_IO];
    for (int i = 0; i < MAX_CONCURRENT_IO; ++i) {
        pthread_create(&io_threads[i], NULL, io_worker, &cache);
    }

    // Simulate operations
    update_metadata(&cache, "example.txt", &(int){42}, sizeof(int));

    // Clean up
    for (int i = 0; i < MAX_CONCURRENT_IO; ++i) {
        pthread_join(io_threads[i], NULL);
    }
    sem_destroy(&cache.io_semaphore);
    pthread_mutex_destroy(&cache.cache_lock);

    return 0;
}
