int countLines(const char *filePath) {
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return -1;
    }

    size_t fileSize = lseek(fd, 0, SEEK_END);
    if (fileSize == -1) {
        perror("Failed to seek to end of file");
        close(fd);
        return -1;
    }

    char *buffer = mmap(NULL, fileSize, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map file");
        close(fd);
        return -1;
    }

    int lineCount = 0;
    const char *line = buffer;
    while ((line = memchr(line, '\n', fileSize)) != NULL) {
        lineCount++;
        line++; // Move past the newline character
    }

    munmap(buffer, fileSize);
    close(fd);
    return lineCount;
}

double calculateAverageWordLength(const char *line, int caseSensitive) {
    int wordCount = 0, length = 0;
    int inWord = 0;

