#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define constants for error codes
#define ERR_SUCCESS 0
#define ERR_INVALID_INPUT -1
#define ERR_STORAGE_UNAVAILABLE -2
#define ERR_NETWORK_FAILURE -3

// Define the metadata structure
typedef struct {
    char* filename;
    int size;
    // Other metadata fields...
} FileMetadata;

// Define the cache node structure
typedef struct CacheNode {
    FileMetadata metadata;
    struct CacheNode* next;
} CacheNode;

// Define the cache structure
typedef struct {
    pthread_mutex_t lock;  // Mutex for thread-safe operations
    CacheNode* head;
    int max_io_operations_per_node;  // Configuration option
} DistributedCache;

// Function to initialize the distributed cache
int init_cache(DistributedCache* cache, int max_io_operations) {
    memset(cache, 0, sizeof(DistributedCache));
    pthread_mutex_init(&cache->lock, NULL);
    cache->max_io_operations_per_node = max_io_operations;
    return ERR_SUCCESS;
}

// Function to add metadata to the cache
int add_metadata(DistributedCache* cache, FileMetadata metadata) {
    CacheNode* new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        return ERR_INVALID_INPUT;
    }
    memcpy(&new_node->metadata, &metadata, sizeof(FileMetadata));
    pthread_mutex_lock(&cache->lock);
    new_node->next = cache->head;
    cache->head = new_node;
    pthread_mutex_unlock(&cache->lock);
    return ERR_SUCCESS;
}

// Function to retrieve metadata from the cache
int get_metadata(DistributedCache* cache, const char* filename, FileMetadata* result) {
    pthread_mutex_lock(&cache->lock);
    CacheNode* current = cache->head;
    while (current) {
        if (strcmp(current->metadata.filename, filename) == 0) {
            memcpy(result, &current->metadata, sizeof(FileMetadata));
            pthread_mutex_unlock(&cache->lock);
            return ERR_SUCCESS;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->lock);
    return ERR_INVALID_INPUT;
}

// Function to update metadata in the cache
int update_metadata(DistributedCache* cache, FileMetadata new_metadata) {
    CacheNode* current = cache->head;
    while (current) {
        if (strcmp(current->metadata.filename, new_metadata.filename) == 0) {
            pthread_mutex_lock(&cache->lock);
            memcpy(&current->metadata, &new_metadata, sizeof(FileMetadata));
            pthread_mutex_unlock(&cache->lock);
            return ERR_SUCCESS;
        }
        current = current->next;
    }
    return ERR_INVALID_INPUT;
}

// Function to free the cache
void free_cache(DistributedCache* cache) {
    CacheNode* current = cache->head;
    while (current) {
        CacheNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
}
