#include <pthread.h>

#define MAX_ELEMENTS 10000
#define RNTI_LIMIT 1000
#define CACHE_LINE_SIZE 64

typedef struct {
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t allocated;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(CACHE_LINE_SIZE, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->used = 0;
    pool->allocated = initial_size;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
}

void *allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->used == pool->allocated) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &pool->array[pool->used++];
    pthread_mutex_unlock(&pool->mutex);
    return element;
}

void free_to_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = (element - pool->array);
    if (index >= pool->used) {
        fprintf(stderr, "Invalid memory deallocation\n");
        exit(EXIT_FAILURE);
    }
    pool->used--;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
}

void populate_structure(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Populate structure with random data
    element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T* create_array(size_t N, MemoryPool *pool) {
    if (N == 0 || N > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid input size\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(CACHE_LINE_SIZE, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < N; i++) {
        populate_structure(&array[i]);
    }

    return array;
}

void cleanup_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    free(array);
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 1024);

    size_t N = 5000; // Example input size
    NFAPI_CRC_INDICATION_PDU_T *array = create_array(N, &pool);

    if (array) {
        cleanup_array(array, N);
    }

    pthread_mutex_destroy(&pool.mutex);
    pthread_cond_destroy(&pool.cond);

    return 0;
}
