NFAPI_CRC_INDICATION_PDU_T *generateCRCIndications(int numUEs) {
    if (numUEs > MAX_UEs) {
        printf("Error: Too many UEs requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < numUEs; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = i + 1;
        while (1) {
            indications[i].RNTI = rand() % RNTI_RANGE;
            int unique = 1;
            for (int j = 0; j < i; ++j) {
                if (indications[j].RNTI == indications[i].RNTI) {
                    unique = 0;
                    break;
                }
            }
            if (unique) break;
        }
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        indications[i].CRCFLAG = rand() % 2;
    }

    return indications;
}

