#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long key;
    int value;
    struct Record *next;
} Record;

typedef struct RecordManager {
    pthread_mutex_t lock;
    Record *head;
    size_t count;
} RecordManager;

Record* create_record(long key, int value) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->value = value;
    record->next = NULL;
    return record;
}

void add_record(RecordManager *manager, long key, int value) {
    pthread_mutex_lock(&manager->lock);
    Record *new_record = create_record(key, value);
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_record->next = manager->head;
    manager->head = new_record;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

Record* find_record(RecordManager *manager, long key) {
    pthread_mutex_lock(&manager->lock);
    Record *current = manager->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return current;
}

void free_records(Record *record) {
    if (!record) return;
    free_records(record->next);
    free(record);
}

void destroy_record_manager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free_records(manager->head);
    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Serialization and deserialization functions would go here
