#define MAX_SESSIONS 1000
#define RNTI_RANGE 65536

typedef struct {
    uint16_t rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    // Other necessary fields
} SessionData;

NFAPI_CRC_INDICATION_PDU_T* sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int rnti_pool[RNTI_RANGE];
int rnti_index = 0;
int rnti_last_used = -1;

void initialize_rnti_pool() {
    for (int i = 0; i < RNTI_RANGE; i++) {
        rnti_pool[i] = 1;
    }
}

int get_unique_rnti() {
    pthread_mutex_lock(&mutex);
    int attempts = 0;
    while (attempts < RNTI_RANGE) {
        if (rnti_pool[rnti_index]) {
            rnti_pool[rnti_index] = 0;
            rnti_last_used = rnti_index;
            rnti_index = (rnti_index + 1) % RNTI_RANGE;
            pthread_mutex_unlock(&mutex);
            return rnti_index;
        }
        attempts++;
    }
    pthread_mutex_unlock(&mutex);
    // Handle error: No available RNTIs
    return -1;
}

void release_rnti(int rnti) {
    pthread_mutex_lock(&mutex);
    if (rnti_last_used != -1 && rnti == rnti_last_used) {
        rnti_pool[rnti] = 1;
        rnti_last_used = -1;
    }
    pthread_mutex_unlock(&mutex);
}

void* populate_session(void* arg) {
    // Simulate external data source integration
    int rnti = get_unique_rnti();
    if (rnti == -1) {
        // Handle error: No available RNTIs
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!session) {
        // Handle memory allocation failure
        release_rnti(rnti);
        return NULL;
    }

    // Populate session data
    session->rnti = rnti;
    session->crc_flag = rand() % 2;

    pthread_mutex_lock(&mutex);
    sessions[session_count++] = session;
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void terminate_session(int session_id) {
    if (session_id >= 0 && session_id < MAX_SESSIONS) {
        NFAPI_CRC_INDICATION_PDU_T* session = sessions[session_id];
        if (session) {
            release_rnti(session->rnti);
            free(session);
            sessions[session_id] = NULL;
        }
    }
}

int main() {
    initialize_rnti_pool();

    // Example usage
    pthread_t threads[MAX_SESSIONS];
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (pthread_create(&threads[i], NULL, populate_session, NULL) != 0) {
            // Handle thread creation failure
        }
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < session_count; i++) {
        terminate_session(i);
    }

    return 0;
}
