#define MAX_RNTI 65535
#define INITIAL_TABLE_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    uint16_t key; // RNTI
    NFAPI_CRC_INDICATION_PDU_T value;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    int size;
    HashNode** buckets;
} HashTable;

HashTable* createHashTable(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    return table;
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

int hashFunction(uint16_t key, int size) {
    return key % size;
}

void insertHashTable(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    uint16_t key = pdu.RNTI;
    int index = hashFunction(key, table->size);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->key = key;
    newNode->value = pdu;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
}

int lookupHashTable(HashTable* table, uint16_t key, NFAPI_CRC_INDICATION_PDU_T* result) {
    int index = hashFunction(key, table->size);
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            *result = node->value;
            return 1;
        }
        node = node->next;
    }
    return 0;
}

void* manageNFAPIPDUs(void* arg) {
    // Implement NFAPI PDU management logic here
    // Use the provided functions for hash table operations
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, manageNFAPIPDUs, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
