typedef struct {
    char* payload;
    int timestamp;
    int type;
    int source_id;
    // Additional metadata fields can be dynamically added here
} MULTIMEDIA_PACKET_T;

typedef struct {
    void** pool;
    size_t pool_size;
    size_t pool_count;
    pthread_mutex_t mutex;
} MEMORY_POOL_T;

void initialize_memory_pool(MEMORY_POOL_T* pool, size_t initial_size) {
    pool->pool = (void**)malloc(initial_size * sizeof(void*));
    if (!pool->pool) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = initial_size;
    pool->pool_count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void* acquire_from_pool(MEMORY_POOL_T* pool) {
    void* item = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (pool->pool_count > 0) {
        item = pool->pool[--pool->pool_count];
    } else {
        // Reallocate pool if needed
        if (pool->pool_size * 2 > SIZE_MAX / sizeof(void*)) {
            fprintf(stderr, "Memory pool overflow\n");
            exit(EXIT_FAILURE);
        }
        void** new_pool = realloc(pool->pool, pool->pool_size * 2 * sizeof(void*));
        if (!new_pool) {
            perror("Failed to reallocate memory for memory pool");
            exit(EXIT_FAILURE);
        }
        pool->pool = new_pool;
        pool->pool_size *= 2;
    }
    pthread_mutex_unlock(&pool->mutex);
    return item;
}

void release_to_pool(MEMORY_POOL_T* pool, void* item) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->pool_count >= pool->pool_size) {
        fprintf(stderr, "Memory pool overflow\n");
        exit(EXIT_FAILURE);
    }
    pool->pool[pool->pool_count++] = item;
    pthread_mutex_unlock(&pool->mutex);
}

void process_multimedia_packets(MULTIMEDIA_PACKET_T* packets, int packet_count) {
    static MEMORY_POOL_T memory_pool;
    initialize_memory_pool(&memory_pool, 1024);

    for (int i = 0; i < packet_count; ++i) {
        MULTIMEDIA_PACKET_T* packet = acquire_from_pool(&memory_pool);
        if (!packet) {
            fprintf(stderr, "Failed to allocate memory for packet\n");
            continue;
        }

        // Extract metadata from packet
        // ...

        // Process the packet
        // ...

        release_to_pool(&memory_pool, packet);
    }
}
