#define MAX_STATS 10000
#define STACK_THRESHOLD 5000
#define CACHE_LINE_SIZE 64

typedef struct {
    uint32_t TAG;
    uint32_t CELL_ID;
    uint32_t TIME_STAMP;
    int RSSI;
    int SINR;
    double BER;
} LTEPHY_STATS_T;

void* generate_stats(void* arg) {
    LTEPHY_STATS_T* stats = NULL;
    size_t count = *(size_t*)arg;
    size_t i;

    if (count > MAX_STATS || count == 0) {
        perror("Invalid input parameters");
        return NULL;
    }

    if (count <= STACK_THRESHOLD) {
        // Use stack allocation
        LTEPHY_STATS_T stack_stats[MAX_STATS];
        stats = stack_stats;
    } else {
        // Use heap allocation with custom allocator
        stats = (LTEPHY_STATS_T*)malloc(count * sizeof(LTEPHY_STATS_T));
        if (!stats) {
            perror("Memory allocation failed");
            return NULL;
        }
    }

    for (i = 0; i < count; i++) {
        stats[i].TAG = 0x12345678; // Assuming a fixed tag value
        stats[i].CELL_ID = rand() % 1000;
        stats[i].TIME_STAMP = time(NULL);
        stats[i].RSSI = rand() % 100;
        stats[i].SINR = rand() % 20;
        stats[i].BER = (double)(rand() % 100) / 100.0;
    }

    // Log statistics
    printf("Generated %zu statistics\n", count);

    return stats;
}

int main() {
    pthread_t threads[5];
    size_t counts[] = {2000, 3000, 4000, 5000, 6000};
    int i;

    srand(time(NULL));

    for (i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, generate_stats, &counts[i]);
    }

    for (i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
