using System;
using System.Xml.XPath;

public class XMLParser {
    public static XPathNavigator ParseElement(string xml, string elementName) {
        XPathDocument doc = new XPathDocument(xml);
        XPathNavigator navigator = doc.CreateNavigator();

        XPathNodeIterator nodes = navigator.Select($"//{elementName}");
        if (nodes.Count != 1) {
            throw new Exception($"No or multiple elements found with the name '{elementName}'");
        }

        return nodes.Current;
    }
}

class Program {
    static void Main() {
        string xml = "<root><example>Value</example><example>Another Value</example></root>";
        try {
            XPathNavigator node = XMLParser.ParseElement(xml, "example");
            Console.WriteLine(node.Value);
        } catch (Exception ex) {
            Console.WriteLine(ex.Message);
        }
    }
}
