using System;
using System.Collections.Concurrent;
using System.Threading;

public class ResourceManagementSystem
{
    private ConcurrentDictionary<string, ResourcePool> _resourcePools = new ConcurrentDictionary<string, ResourcePool>();
    private static readonly object _lock = new object();

    public void AddResourcePool(string poolName, string resourceType, int minLimit, int maxLimit)
    {
        if (!_resourcePools.TryAdd(poolName, new ResourcePool(resourceType, minLimit, maxLimit)))
        {
            throw new ArgumentException("Resource pool already exists.");
        }
    }

    public bool AllocateResource(string poolName, out Resource allocatedResource)
    {
        lock (_lock)
        {
            if (_resourcePools.TryGetValue(poolName, out var pool))
            {
                return pool.Allocate(out allocatedResource);
            }
        }
        allocatedResource = null;
        return false;
    }

    public void ReleaseResource(Resource resource)
    {
        lock (_lock)
        {
            if (_resourcePools.ContainsKey(resource.PoolName))
            {
                _resourcePools[resource.PoolName].Release(resource);
            }
        }
    }

    public void AdjustLimits(string poolName, int newMinLimit, int newMaxLimit)
    {
        lock (_lock)
        {
            if (_resourcePools.TryGetValue(poolName, out var pool))
            {
                pool.AdjustLimits(newMinLimit, newMaxLimit);
            }
        }
    }

    public ResourcePool GetResourcePool(string poolName)
    {
        _resourcePools.TryGetValue(poolName, out var pool);
        return pool;
    }

    private class ResourcePool
    {
        private readonly string _type;
        private int _currentUsage;
        private readonly int _minLimit;
        private readonly int _maxLimit;
        private Queue<Resource> _availableResources = new Queue<Resource>();

        public ResourcePool(string type, int minLimit, int maxLimit)
        {
            _type = type;
            _minLimit = minLimit;
            _maxLimit = maxLimit;
        }

        public bool Allocate(out Resource allocatedResource)
        {
            if (_currentUsage < _maxLimit && _availableResources.Count > 0)
            {
                allocatedResource = _availableResources.Dequeue();
                Interlocked.Increment(ref _currentUsage);
                return true;
            }
            allocatedResource = null;
            return false;
        }

        public void Release(Resource resource)
        {
            if (_currentUsage > 0 && resource.PoolName == _type)
            {
                Interlocked.Decrement(ref _currentUsage);
                _availableResources.Enqueue(resource);
            }
        }

        public void AdjustLimits(int newMinLimit, int newMaxLimit)
        {
            lock (this)
            {
                if (newMinLimit < _minLimit || newMaxLimit > _maxLimit)
                {
                    throw new ArgumentException("Invalid limit adjustment.");
                }
                _minLimit = newMinLimit;
                _maxLimit = newMaxLimit;
            }
        }
    }

    public class Resource
    {
        public string PoolName { get; set; }

        // Other properties and methods as needed
    }
}
