import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class LogManager {
    private ConcurrentHashMap<String, Logger> loggers = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, LogHandler> handlers = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newSingleThreadExecutor();

    public LogManager() {
        executor.submit(this::backgroundLogLevelAdjustment);
    }

    protected void finalize() throws Throwable {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void configureLogger(String name, LogLevel level) {
        // Implementation for configuring logger
    }

    public static void setGlobalLogLevel(LogLevel level) {
        // Implementation for setting global log level
    }

    public static void addOutputHandler(LogHandler handler) {
        // Implementation for adding new output handler
    }

    private void backgroundLogLevelAdjustment() {
        while (true) {
            // Adjust log levels based on system metrics
            try {
                TimeUnit.MINUTES.sleep(5);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}

interface Logger {
    void log(LogLevel level, String message);
}

enum LogLevel {
    DEBUG, INFO, WARNING, ERROR, CRITICAL
}

interface LogHandler {
    void handleLog(String logMessage);
}

class AsyncLogger implements Logger {
    private final LogHandler handler;

    public AsyncLogger(LogHandler handler) {
        this.handler = handler;
    }

    @Override
    public void log(LogLevel level, String message) {
        // Asynchronously handle log message
        LogManager.getInstance().executor.submit(() -> handler.handleLog(formatLogMessage(level, message)));
    }

    private String formatLogMessage(LogLevel level, String message) {
        // Format log message with timestamp and level
        return "[" + System.currentTimeMillis() + "] " + level + ": " + message;
    }
}

class ConsoleHandler implements LogHandler {
    @Override
    public void handleLog(String logMessage) {
        // Output log message to console
        System.out.println(logMessage);
    }
}

class FileHandler implements LogHandler {
    @Override
    public void handleLog(String logMessage) {
        // Write log message to file
        try (FileWriter writer = new FileWriter("logs.txt", true)) {
            writer.write(logMessage + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
