["```python
import apache_beam as beam
from apache_beam.io import ReadFromText, WriteToText
from apache_beam.options.pipeline_options import PipelineOptions
import json
import csv
import avro.schema
import avro.datafile

class DataFormatDecoder(beam.DoFn):
    def process(self, element):
        if isinstance(element, bytes):
            try:
                yield json.loads(element.decode('utf-8'))
            except json.JSONDecodeError:
                pass
        elif isinstance(element, str):
            try:
                yield json.loads(element)
            except json.JSONDecodeError:
                pass

class DataFormatEncoder(beam.DoFn):
    def process(self, element):
        if isinstance(element, dict):
            yield json.dumps(element)

class FilterData(beam.DoFn):
    def __init__(self, filter_condition):
        self.filter_condition = filter_condition

    def process(self, element):
        if self.filter_condition(element):
            yield element

class AggregateData(beam.DoFn):
    def __init__(self, key_fn, aggregate_fn):
        self.key_fn = key_fn
        self.aggregate_fn = aggregate_fn

    def process(self, element):
        key = self.key_fn(element)
        value = self.aggregate_fn(element)
        yield (key, value)

class TransformData(beam.DoFn):
    def __init__(self, transform_function):
        self.transform_function = transform_function

    def process(self, element):
        yield self.transform_function(element)

def run_data_processing_pipeline(pipeline_options):
    with beam.Pipeline(options=pipeline_options) as p:
        (p
         | 'Read JSON Data' >> ReadFromText('input.json')
         | 'Decode JSON' >> beam.ParDo(DataFormatDecoder())
         | 'Filter Data' >> FilterData(lambda x: x['age'] > 30)
         | 'Aggregate Data' >> AggregateData(lambda x: x['department'], lambda x: x['salary'])
         | 'Transform Data' >> TransformData(lambda x: {**x, 'salary': x['salary'] * 1.1})
         | 'Encode JSON' >> beam.ParDo(DataFormatEncoder())
         | 'Write Output' >> WriteToText('output.json'))

if __name__ == '__main__':
    pipeline_options = PipelineOptions()
    run_data_processing_pipeline(pipeline_options)
```

This code snippet provides a basic structure for developing a modular data processing and transformation library in Python that integrates with Apache Beam. It includes classes for decoding JSON, filtering data, aggregating data, transforming data, and encoding the output back to JSON format. The `run_data_processing_pipeline` function demonstrates how to use these components to process data from an input file, apply transformations, and write the results to an output file. This example can be extended to support other data formats like CSV and Avro, as well as additional processing methods, while maintaining modularity and ease of maintenance."]

