#include <pthread.h>

#define MAX_COUNTERS 1024

typedef struct {
    int RX_GOODPUT;
    int RX_BADPUT;
    int TX_GOODPUT;
    int TX_BADPUT;
    pthread_mutex_t lock;
} NFAPI_L1_PERF_COUNTERS;

typedef struct {
    NFAPI_L1_PERF_COUNTERS *counters[MAX_COUNTERS];
    int counter_count;
    pthread_mutex_t list_lock;
} CounterManager;

void initialize_counter(NFAPI_L1_PERF_COUNTERS *counter) {
    memset(counter, 0, sizeof(*counter));
    pthread_mutex_init(&counter->lock, NULL);
}

NFAPI_L1_PERF_COUNTERS* allocate_and_initialize_counter() {
    NFAPI_L1_PERF_COUNTERS *counter = (NFAPI_L1_PERF_COUNTERS*)malloc(sizeof(NFAPI_L1_PERF_COUNTERS));
    if (counter) {
        initialize_counter(counter);
    }
    return counter;
}

void increment_counter(NFAPI_L1_PERF_COUNTERS *counter, int type, int value) {
    pthread_mutex_lock(&counter->lock);
    switch (type) {
        case 0: // RX_GOODPUT
            counter->RX_GOODPUT += value;
            break;
        case 1: // RX_BADPUT
            counter->RX_BADPUT += value;
            break;
        case 2: // TX_GOODPUT
            counter->TX_GOODPUT += value;
            break;
        case 3: // TX_BADPUT
            counter->TX_BADPUT += value;
            break;
    }
    pthread_mutex_unlock(&counter->lock);
}

void smooth_counter(NFAPI_L1_PERF_COUNTERS *counter, int type, int threshold) {
    pthread_mutex_lock(&counter->lock);
    switch (type) {
        case 0: // RX_GOODPUT
            if (counter->RX_GOODPUT > threshold) {
                counter->RX_GOODPUT = threshold;
            }
            break;
        case 1: // RX_BADPUT
            if (counter->RX_BADPUT > threshold) {
                counter->RX_BADPUT = threshold;
            }
            break;
        case 2: // TX_GOODPUT
            if (counter->TX_GOODPUT > threshold) {
                counter->TX_GOODPUT = threshold;
            }
            break;
        case 3: // TX_BADPUT
            if (counter->TX_BADPUT > threshold) {
                counter->TX_BADPUT = threshold;
            }
            break;
    }
    pthread_mutex_unlock(&counter->lock);
}

void destroy_counter(NFAPI_L1_PERF_COUNTERS *counter) {
    pthread_mutex_destroy(&counter->lock);
    free(counter);
}
