#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000

typedef struct record {
    long offset;
    int key;
    pthread_mutex_t lock;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t records_lock;

void initialize_record_system() {
    pthread_mutex_init(&records_lock, NULL);
    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_init(&records[i].lock, NULL);
        records[i].offset = -1;
    }
}

long generate_offset(long seed) {
    return seed % MAX_RECORDS;
}

int insert_record(int key, int value, long seed) {
    long offset = generate_offset(seed);
    pthread_mutex_lock(&records_lock);
    if (record_count < MAX_RECORDS && records[offset].offset == -1) {
        records[offset].key = key;
        records[offset].offset = seed;
        records[offset].lock.lock();
        record_count++;
        pthread_mutex_unlock(&records_lock);
        return 0;
    }
    pthread_mutex_unlock(&records_lock);
    return -1;
}

int delete_record(long offset) {
    if (offset >= 0 && offset < MAX_RECORDS && records[offset].offset == offset) {
        pthread_mutex_lock(&records[offset].lock);
        records[offset].offset = -1;
        record_count--;
        pthread_mutex_unlock(&records[offset].lock);
        return 0;
    }
    return -1;
}

int get_record(long offset, int *value) {
    if (offset >= 0 && offset < MAX_RECORDS && records[offset].offset == offset) {
        pthread_mutex_lock(&records[offset].lock);
        *value = records[offset].key;
        pthread_mutex_unlock(&records[offset].lock);
        return 0;
    }
    return -1;
}

void serialize_records(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&records_lock);
    fwrite(records, sizeof(Record), MAX_RECORDS, file);
    pthread_mutex_unlock(&records_lock);
    fclose(file);
}

void deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    pthread_mutex_lock(&records_lock);
    fread(records, sizeof(Record), MAX_RECORDS, file);
    record_count = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].offset != -1) {
            record_count++;
        }
    }
    pthread_mutex_unlock(&records_lock);
    fclose(file);
}

void log_operation(const char *operation, int key, int status) {
    FILE *log_file = fopen("operation_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s %ld %d %d\n", ctime(&now), key, status, operation[0]);
    fclose(log_file);
}

void export_statistics(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing statistics");
        return;
    }
    fprintf(file, "Average access time: %f\n", 0.0); // Placeholder value
    fprintf(file, "Cache hit rate: %f\n", 0.0); // Placeholder value
    fprintf(file, "Memory usage: %zu bytes\n", sizeof(records));
    fclose(file);
}
