    private boolean isValidFile(Path file) {
        try {
            return Files.exists(file) && Files.isRegularFile(file);
        } catch (SecurityException e) {
            return false;
        }
    }

    private Optional<Integer> processFile(Path file) {
        try {
            if (!validateIntegrity(file)) {
                return Optional.empty();
            }
            String md5 = computeMD5Hash(file);
            if (cache.get(md5).isPresent()) {
                VersionedHashEntry entry = cache.get(md5).get();
                int sequenceNumber = extractSequenceNumber(file);
                if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
                    log(sequenceNumber, file.toString(), entry.getVersion());
                    callback.notifyIfThresholdExceeded(sequenceNumber);
                }
                return Optional.of(sequenceNumber);
            } else {
