                if (entry.getMD5().equals(md5)) {
                    int sequenceNumber = extractSequenceNumber(file);
                    if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
                        log(sequenceNumber, file.toString(), entry.getVersion());
                        callback.notifyIfThresholdExceeded(sequenceNumber);
                    }
                    return Optional.of(sequenceNumber);
                } else {
                    cache.put(md5, entry);
                }
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            handleException(e, file);
            return Optional.empty();
        }
        return Optional.empty();
    }

    private boolean validateIntegrity(Path file) throws IOException {
        try (MessageDigest digest = MessageDigest.getInstance("SHA-256")) {
            byte[] hash = Files.readAllBytes(file);
            digest.update(hash);
            String sha256 = bytesToHex(digest.digest());
            return verifySHA256(sha256); // Assume this method checks the SHA-256 against a trusted source
        }
    }

    private String computeMD5Hash(Path file) throws IOException, NoSuchAlgorithmException {
        try (MessageDigest digest = MessageDigest.getInstance("MD5")) {
            byte[] hash = Files.readAllBytes(file);
            digest.update(hash);
            return bytesToHex(digest.digest());
        }
    }

    private int extractSequenceNumber(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        String lastLine = lines.get(lines.size() - 1);
        // Assuming the sequence number is a numeric value at the end of the line
        return Integer.parseInt(lastLine.trim().replaceAll("\\D+", ""));
    }

