    private static class TimeBasedCache<K, V> {
        private Map<K, CacheEntry<V>> cache = new ConcurrentHashMap<>();
        private long expirationTime;

        public TimeBasedCache(long expirationTime) {
            this.expirationTime = expirationTime;
        }

        public Optional<VersionedHashEntry> get(K key) {
            CacheEntry<V> entry = cache.get(key);
            if (entry != null && !isExpired(entry)) {
                return Optional.ofNullable((VersionedHashEntry) entry.getValue());
            }
            return Optional.empty();
        }

        public void put(K key, VersionedHashEntry value) {
            cache.put(key, new CacheEntry<>(value));
        }

        private boolean isExpired(CacheEntry<?> entry) {
            return System.currentTimeMillis() - entry.getTimestamp() > expirationTime;
        }

        private static class CacheEntry<V> {
            private V value;
            private long timestamp;

            public CacheEntry(V value) {
                this.value = value;
                this.timestamp = System.currentTimeMillis();
            }

            public V getValue() {
                return value;
            }

            public long getTimestamp() {
                return timestamp;
            }
        }
    }
