import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class FileHashProcessor {

    private static final int MIN_SEQUENCE_NUMBER = 1000;
    private static final long CACHE_EXPIRATION_TIME = TimeUnit.MINUTES.toMillis(5);
    private static final int THREAD_POOL_SIZE = Runtime.getRuntime().availableProcessors();
    private final ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    private final Map<String, String> md5Cache = new ConcurrentHashMap<>();
    private final Set<HashEntry> knownHashes;
    private final CallbackHandler callbackHandler;

    public FileHashProcessor(Set<HashEntry> knownHashes, CallbackHandler callbackHandler) {
        this.knownHashes = knownHashes;
        this.callbackHandler = callbackHandler;
    }

    public void processFiles(List<Path> filePaths) {
        for (Path path : filePaths) {
            executorService.submit(() -> processFile(path));
        }
    }

    private void processFile(Path path) {
        try {
            String md5Hash = computeMd5Hash(path);
            if (isValidHash(md5Hash)) {
                long sequenceNumber = extractSequenceNumber(path, md5Hash);
                logSequenceNumber(sequenceNumber, path);
                if (sequenceNumber > callbackHandler.getThreshold()) {
                    notifyMonitoringSystem(sequenceNumber, path);
                }
            } else {
                System.out.println("Invalid SHA-256 checksum for file: " + path);
            }
        } catch (IOException | InterruptedException e) {
            handleException(e);
        }
    }

    private String computeMd5Hash(Path path) throws IOException, InterruptedException {
        return md5Cache.computeIfAbsent(path.toString(), k -> {
            try {
                return Files.readAllBytes(path).md5Digest();
            } catch (IOException e) {
                throw new UncheckedIOException("Failed to compute MD5 hash for file: " + path, e);
            }
        });
    }

    private boolean isValidHash(String md5Hash) {
        // Validate the SHA-256 checksum here
        return true;
    }

    private long extractSequenceNumber(Path path, String md5Hash) throws IOException {
        List<String> lines = Files.readAllLines(path);
        String lastLine = lines.get(lines.size() - 1);
        // Extract sequence number from the last line
        return Long.parseLong(lastLine.split(",")[1]);
    }

    private void logSequenceNumber(long sequenceNumber, Path path) {
        if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
            System.out.println("Sequence Number: " + sequenceNumber + ", File Path: " + path + ", Timestamp: " + new Date());
        }
    }

    private void notifyMonitoringSystem(long sequenceNumber, Path path) {
        // Notify monitoring system asynchronously
        callbackHandler.notify(sequenceNumber, path);
    }

