#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <string.h>
#include <stdlib.h>

RSA* generate_rsa_key() {
    RSA *key = RSA_new();
    if (key == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    BIGNUM *bn_e = BN_new();
    if (BN_set_word(bn_e, 65537) != 1) {
        ERR_print_errors_fp(stderr);
        RSA_free(key);
        BN_free(bn_e);
        return NULL;
    }

    int bits = 4096;
    if (!RSA_generate_key_ex(key, bits, bn_e, NULL)) {
        ERR_print_errors_fp(stderr);
        BN_free(bn_e);
        RSA_free(key);
        return NULL;
    }

    BN_free(bn_e);
    return key;
}

void cleanup_rsa_key(RSA *key) {
    if (key != NULL) {
        RSA_free(key);
    }
}
```

