        perror("Memory allocation failed");
        return NULL;
    }

    int current_rnti_sum = 0;
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        int RNTI = rand() % max_rnti_sum;
        if (current_rnti_sum + RNTI > max_rnti_sum) {
            RNTI = max_rnti_sum - current_rnti_sum;
        }
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = RNTI;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        current_rnti_sum += RNTI;
    }

    return array;
}

