#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

typedef struct {
    FILE *file;
    pthread_mutex_t mutex;
} Logger;

void initializeAndConfigureLoggingSystem(int numLoggers, char **logConfigs) {
    for (int i = 0; i < numLoggers; i++) {
        Logger *logger = malloc(sizeof(Logger));
        if (!logger) {
            perror("Failed to allocate memory for logger");
            continue;
        }

        // Parse logConfig and set up logger
        char *config = strdup(logConfigs[i]);
        char *token = strtok(config, ",");
        while (token != NULL) {
            if (strcmp(token, "file") == 0) {
                logger->file = fopen("log.txt", "a");
                if (!logger->file) {
                    perror("Failed to open log file");
                    free(logger);
                    continue;
                }
            } else if (strcmp(token, "mutex") == 0) {
                pthread_mutex_init(&logger->mutex, NULL);
            }
            token = strtok(NULL, ",");
        }

        // Initialize logger
        // ...

        // Add logger to logging system
        // ...
    }
}

void logMessage(Logger *logger, LogLevel level, const char *message) {
    pthread_mutex_lock(&logger->mutex);
    fprintf(logger->file, "[%s] %s: %s\n", logLevelToString(level), message);
    fflush(logger->file);
    pthread_mutex_unlock(&logger->mutex);
}

char *logLevelToString(LogLevel level) {
    switch (level) {
        case LOG_DEBUG:   return "DEBUG";
        case LOG_INFO:    return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR:   return "ERROR";
        case LOG_CRITICAL:return "CRITICAL";
        default:          return "UNKNOWN";
    }
}

void cleanupLoggingSystem(Logger **loggers, int numLoggers) {
    for (int i = 0; i < numLoggers; i++) {
        Logger *logger = loggers[i];
        if (logger->file) fclose(logger->file);
        pthread_mutex_destroy(&logger->mutex);
        free(logger);
    }
}
