using System;
using System.Collections.Generic;
using System.Linq;

public class AdvancedDataProcessor<T> where T : IComparable<T>
{
    private IEnumerable<T> _dataset;
    private int _size;

    public AdvancedDataProcessor(IEnumerable<T> dataset)
    {
        _dataset = EnsureNotNull(dataset);
        _size = _dataset.Count();
    }

    public IEnumerable<T> Filter(Func<T, bool> predicate)
    {
        return _dataset.Where(predicate).ToList();
    }

    public IEnumerable<TResult> Map<TResult>(Func<T, TResult> transformation)
    {
        return _dataset.Select(transformation).ToList();
    }

    public T Reduce(Func<T, T, T> reducer, T initial)
    {
        return _dataset.Aggregate(initial, reducer);
    }

    public override string ToString()
    {
        var avg = _size > 0 ? _dataset.Average() : default(T);
        return $"Size: {_size}, Average: {avg}";
    }

    public void Reset()
    {
        _dataset = Enumerable.Empty<T>();
        _size = 0;
    }

    public void Seed(int value)
    {
        _dataset = new List<T> { (T)Convert.ChangeType(value, typeof(T)) };
        _size = 1;
    }

    public static AdvancedDataProcessor<T> Process(AdvancedDataProcessor<T> processor, Func<IEnumerable<T>, IEnumerable<T>> operation)
    {
        return new AdvancedDataProcessor<T>(operation(processor._dataset));
    }

    private IEnumerable<T> EnsureNotNull(IEnumerable<T> dataset)
    {
        if (dataset == null) throw new ArgumentNullException(nameof(dataset), "Dataset cannot be null.");
        return dataset;
    }
}
