void process_jpeg(const char *filename, const char *command_line_option) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile;
    JSAMPARRAY buffer;
    int row_stride;

    // Initialize the JPEG decompression object
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    // Open the input file
    if ((infile = fopen(filename, "rb")) == NULL) {
        fprintf(stderr, "Error opening %s\n", filename);
        exit(1);
    }

    // Specify the source of the JPEG data
    jpeg_stdio_src(&cinfo, infile);

    // Read file header
    jpeg_read_header(&cinfo, TRUE);

    // Start decompression process
    jpeg_start_decompress(&cinfo);

    // Allocate memory for output buffer
    row_stride = cinfo.output_width * cinfo.output_components;
    buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, row_stride, 1);

    while (cinfo.output_scanline < cinfo.output_height) {
        // Read scanlines from the JPEG file
        jpeg_read_scanlines(&cinfo, buffer, 1);
        // Process each scanline here
    }

    // Finish decompression process
    jpeg_finish_decompress(&cinfo);

    // Close the input file
    fclose(infile);

    // Clean up
    jpeg_destroy_decompress(&cinfo);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <filename> <command_line_option>\n", argv[0]);
        return 1;
    }

    process_jpeg(argv[1], argv[2]);

    return 0;
}
