#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_and_fill_structures(int n) {
    if (n <= 0 || n > MAX_STRUCTURES) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** structure_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!structure_array) {
        perror("Failed to allocate memory for structure array");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < n; i++) {
        structure_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure_array[i]) {
            perror("Failed to allocate memory for individual structure");
            // Free previously allocated structures
            for (int j = 0; j < i; j++) {
                free(structure_array[j]);
            }
            free(structure_array);
            return NULL;
        }

        pthread_mutex_lock(&mutex);
        // Initialize the structure with valid values
        structure_array[i]->rx_ue_info = get_valid_rx_ue_info();
        structure_array[i]->rnti = get_valid_rnti();
        structure_array[i]->crc_indication = get_valid_crc_indication_rel8();
        pthread_mutex_unlock(&mutex);
    }

    return (void*)structure_array;
}

// Example usage
int main() {
    int n = 5000; // Number of structures to allocate
    void* result = allocate_and_fill_structures(n);

    if (result) {
        NFAPI_CRC_INDICATION_PDU_T** structures = (NFAPI_CRC_INDICATION_PDU_T**)result;
        // Use the allocated structures...

        // Free allocated memory when done
        for (int i = 0; i < n; i++) {
            free(structures[i]);
        }
        free(structures);
    }

    return 0;
}
