// Define the JavaScript Module Loader
class ModuleLoader {
  constructor() {
    this.modules = {};
    this.cachedModules = {};
    this.dependencies = {};
    this.loading = new Set();
  }

  // Load a module asynchronously
  loadModule(moduleName, src) {
    if (this.modules[moduleName]) return Promise.resolve(this.modules[moduleName]);
    if (this.cachedModules[moduleName]) return Promise.resolve(this.cachedModules[moduleName]);

    const script = document.createElement('script');
    script.src = src;
    script.async = true;

    return new Promise((resolve, reject) => {
      script.onload = () => {
        this.modules[moduleName] = window[moduleName];
        resolve(window[moduleName]);
      };
      script.onerror = (error) => {
        reject(new Error(`Failed to load module ${moduleName}: ${error.message}`));
      };

      document.head.appendChild(script);
    });
  }

  // Load a module with dependencies
  loadModuleWithDeps(moduleName, src, dependencies) {
    return this.loadDependencies(dependencies).then(() => this.loadModule(moduleName, src));
  }

  // Load multiple modules in sequence
  loadModulesSequentially(modules) {
    return modules.reduce((promise, { name, src }) => promise.then(() => this.loadModule(name, src)), Promise.resolve());
  }

  // Load dependencies for a module
  loadDependencies(dependencies) {
    const dependencyPromises = dependencies.map(depName => {
      if (this.modules[depName]) return Promise.resolve();
      if (this.cachedModules[depName]) return Promise.resolve();

      return this.loadModuleWithDeps(depName, depName + '.js', this.dependencies[depName]);
    });

    return Promise.all(dependencyPromises);
  }

  // Cache a module for future use
  cacheModule(moduleName) {
    if (this.modules[moduleName]) {
      this.cachedModules[moduleName] = this.modules[moduleName];
      delete this.modules[moduleName];
    }
  }

  // Check if a module is already loaded or cached
  isModuleLoaded(moduleName) {
    return !!this.modules[moduleName] || !!this.cachedModules[moduleName];
  }

  // Log loading and error events
  logEvent(event, details) {
    console.log(`${event}: ${details}`);
  }
}

// Usage example
const loader = new ModuleLoader();

loader.loadModule('exampleModule', 'path/to/example.js')
  .then(module => {
    module.doSomething();
  })
  .catch(error => {
    loader.logEvent('Error', error.message);
  });

loader.cacheModule('exampleModule');
