#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_LIST {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* create_crc_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdu_list);
        free(list);
    }
}

int add_crc_pdu(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    list->pdu_list[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int get_crc_pdu(NFAPI_CRC_LIST* list, size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!list || index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);
    *pdu = list->pdu_list[index];
    pthread_mutex_unlock(&list->lock);

    return 0;
}

size_t get_crc_count(NFAPI_CRC_LIST* list) {
    if (!list) return 0;

    return list->count;
}
