// Simulated weather API client class
class WeatherAPI {
public:
    struct Response {
        double temperature;
        int humidity;
        double windSpeed;
    };

    virtual Response GetWeather(double latitude, double longitude) = 0;
};

// High-priority weather service implementation
class HighPriorityWeatherService : public WeatherAPI {
public:
    Response GetWeather(double latitude, double longitude) override {
        // Simulate network delay and error handling
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        if (std::rand() % 2 == 0) {
            throw std::runtime_error("Service unavailable");
        }
        return {20.5, 85, 10};
    }
};

// Medium-priority weather service implementation
class MediumPriorityWeatherService : public WeatherAPI {
public:
    Response GetWeather(double latitude, double longitude) override {
        // Simulate network delay and error handling
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        if (std::rand() % 3 == 0) {
            throw std::runtime_error("Service unavailable");
        }
        return {21.0, 86, 9};
    }
};

// Low-priority weather service implementation
class LowPriorityWeatherService : public WeatherAPI {
public:
    Response GetWeather(double latitude, double longitude) override {
        // Simulate network delay and error handling
        std::this_thread::sleep_for(std::chrono::milliseconds(150));
        if (std::rand() % 4 == 0) {
            throw std::runtime_error("Service unavailable");
        }
        return {20.0, 84, 8};
    }
};

// Weather data processor class
class WeatherDataProcessor {
public:
    void Process(const std::vector<WeatherAPI*>& services, double latitude, double longitude, int timeInterval) {
        for (int i = 0; i < timeInterval; ++i) {
            try {
                double temperatureSum = 0.0;
                int humiditySum = 0;
                double windSpeedSum = 0.0;
                size_t count = 0;

                for (auto service : services) {
                    auto response = service->GetWeather(latitude, longitude);
                    temperatureSum += response.temperature;
                    humiditySum += response.humidity;
                    windSpeedSum += response.windSpeed;
                    ++count;
                }

                if (count > 0) {
                    double averageTemperature = temperatureSum / count;
                    int averageHumidity = humiditySum / count;
                    double averageWindSpeed = windSpeedSum / count;

                    std::cout << "Average Temperature: " << averageTemperature << "°C\n";
                    std::cout << "Average Humidity: " << averageHumidity << "%\n";
                    std::cout << "Average Wind Speed: " << averageWindSpeed << " m/s\n";
                }
            } catch (const std::exception& e) {
                std::cerr << "Error fetching weather data: " << e.what() << "\n";
            }

            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2 || (std::string(argv[1]) == "--help")) {
        std::cout << "Usage: weather_program <latitude> <longitude> <time_interval> [-v] [-s <api_endpoint>] [-h]\n";
        return 0;
    }

    double latitude = std::atof(argv[1]);
    double longitude = std::atof(argv[2]);
    int timeInterval = std::atoi(argv[3]);
    bool verboseMode = (argc > 4 && std::string(argv[4]) == "-v");
    std::string apiEndpoint;

    for (int i = 5; i < argc; ++i) {
        if (std::string(argv[i]) == "-s") {
            if (++i < argc) {
                apiEndpoint = argv[i];
            } else {
                std::cerr << "Error: Missing API endpoint after -s option\n";
                return 1;
            }
        }
    }

    std::vector<WeatherAPI*> services;
    services.push_back(new HighPriorityWeatherService());
    services.push_back(new MediumPriorityWeatherService());
    services.push_back(new LowPriorityWeatherService());

    WeatherDataProcessor processor;
    processor.Process(services, latitude, longitude, timeInterval);

    return 0;
}
