#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <curl/curl.h>

#define N 10
#define MIN_SEQ_NUMBER 1000
#define CACHE_TIMEOUT 60

typedef struct {
    int crcflag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned short rnti;
} RNTI;

typedef struct {
    unsigned long crc_indication_rel8_tag;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char file_path[256];
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    int sequence_number;
    time_t last_accessed;
} FileMetadata;

typedef struct {
    pthread_mutex_t lock;
    FileMetadata *data;
    int size;
    int capacity;
    time_t cache_timeout;
} Cache;

void init_cache(Cache *cache, int initial_capacity, time_t timeout) {
    cache->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    cache->data = (FileMetadata *)malloc(initial_capacity * sizeof(FileMetadata));
    memset(cache->data, 0, initial_capacity * sizeof(FileMetadata));
    cache->size = 0;
    cache->capacity = initial_capacity;
    cache->cache_timeout = timeout;
}

void free_cache(Cache *cache) {
    pthread_mutex_lock(&cache->lock);
    free(cache->data);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
}

int get_md5_from_cache(Cache *cache, const char *file_path, unsigned char *md5_hash) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; ++i) {
        if (strcmp(cache->data[i].file_path, file_path) == 0 && time(NULL) - cache->data[i].last_accessed < cache->cache_timeout) {
            memcpy(md5_hash, cache->data[i].md5_hash, MD5_DIGEST_LENGTH);
            pthread_mutex_unlock(&cache->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void set_md5_in_cache(Cache *cache, const char *file_path, unsigned char *md5_hash) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size >= cache->capacity) {
        // Resize the cache
        FileMetadata *new_data = (FileMetadata *)realloc(cache->data, cache->capacity * 2 * sizeof(FileMetadata));
        memset(new_data + cache->size, 0, cache->capacity * sizeof(FileMetadata));
        cache->data = new_data;
        cache->capacity *= 2;
    }
    strcpy(cache->data[cache->size].file_path, file_path);
    memcpy(cache->data[cache->size].md5_hash, md5_hash, MD5_DIGEST_LENGTH);
    time(&cache->data[cache->size].last_accessed);
    ++cache->size;
    pthread_mutex_unlock(&cache->lock);
}

int hash_file(const char *file_path, unsigned char *md5_hash) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return -1;

    MD5_CTX md5_context;
    MD5_Init(&md5_context);

    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5_context, buffer, bytes_read);
    }

    fclose(file);
    MD5_Final(md5_hash, &md5_context);

    return 0;
}

int compare_sequence_numbers(const void *a, const void *b) {
    int seq_a = ((FileMetadata *)a)->sequence_number;
    int seq_b = ((FileMetadata *)b)->sequence_number;
    if (seq_a < seq_b) return -1;
    if (seq_a > seq_b) return 1;
    return 0;
}

void *process_file(void *arg) {
    const char *file_path = (const char *)arg;
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    FileMetadata metadata;

    if (!get_md5_from_cache(&cache, file_path, md5_hash)) {
        if (hash_file(file_path, md5_hash) != 0) return NULL;
        set_md5_in_cache(&cache, file_path, md5_hash);
    }

    // Check known hashes against distributed cache
    if (check_known_hashes(md5_hash)) {
        char *file_content = read_file_contents(file_path);
        if (!file_content) return NULL;

        int sequence_number = extract_sequence_number(file_content);
        free(file_content);

        if (sequence_number >= MIN_SEQ_NUMBER) {
            log_sequence_number(file_path, sequence_number);
        }
    }

    return NULL;
}

void update_known_hashes(const char *new_hashes_url) {
    CURL *curl = curl_easy_init();
    if (curl) {
        struct MemoryStruct chunk;
        memset(&chunk, 0, sizeof(chunk));
        curl_easy_setopt(curl, CURLOPT_URL, new_hashes_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &chunk);
        CURLcode res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            // Parse and update known hashes atomically
            parse_and_update_hashes(chunk.memory);
        }
        free(chunk.memory);
        curl_easy_cleanup(curl);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T nfaipdu[N];
    Cache cache;
    init_cache(&cache, 100, CACHE_TIMEOUT);

    // Populate nfaipdu array with random data
    for (int i = 0; i < N; ++i) {
        nfaipdu[i].rx_ue_information_tag.crcflag = rand() % 2;
        nfaipdu[i].rnti.rnti = (unsigned short)(rand() % 65536);
        nfaipdu[i].crc_indication_rel8_tag.crc_indication_rel8_tag = (unsigned long)(rand() % 4294967296ULL);
    }

    // Process file paths asynchronously
    pthread_t threads[N];
    for (int i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, process_file, nfaipdu[i].rnti.rnti);
    }
    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Update known hashes
    update_known_hashes("http://example.com/new_hashes.json");

    free_cache(&cache);

    return 0;
}
