#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTable {
    NFAPI_CRC_INDICATION_PDU_T **buckets;
    size_t size;
} HashTable;

unsigned int hashFunction(unsigned short RNTI, size_t size) {
    return RNTI % size;
}

NFAPI_CRC_INDICATION_PDU_T* createNode(unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI, unsigned char CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) return NULL;
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRCFLAG = CRCFLAG;
    newNode->next = NULL;
    return newNode;
}

int insertIntoHashTable(HashTable *ht, unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI, unsigned char CRCFLAG) {
    if (ht->size >= MAX_SIZE) {
        printf("Hash table is full!\n");
        return -1;
    }
    unsigned int index = hashFunction(RNTI, ht->size);
    NFAPI_CRC_INDICATION_PDU_T *newNode = createNode(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    if (!newNode) {
        printf("Memory allocation failed!\n");
        return -1;
    }
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *temp = ht->buckets[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    return 0;
}

void initializeHashTable(HashTable *ht, size_t size) {
    ht->size = size;
    ht->buckets = (NFAPI_CRC_INDICATION_PDU_T**)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!ht->buckets) {
        printf("Memory allocation failed for hash table!\n");
        exit(1);
    }
}

void freeHashTable(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *temp = ht->buckets[i];
        while (temp != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(ht->buckets);
}

int main() {
    HashTable ht;
    initializeHashTable(&ht, MAX_SIZE);

    // Example usage
    if (insertIntoHashTable(&ht, 123456789, 101, 0x01) != 0) return 1;
    if (insertIntoHashTable(&ht, 987654321, 102, 0x00) != 0) return 1;

    freeHashTable(&ht);
    return 0;
}
```

This code snippet provides a basic implementation of a hash table to manage `NFAPI_CRC_INDICATION_PDU_T` structures based on the RNTI field. It includes functions for inserting elements into the hash table, initializing and freeing the hash table, and handling potential memory allocation errors. The hash function uses a simple modulo operation for simplicity, which may not be optimal for large datasets due to potential collisions.']

