#define CACHE_EXPIRY_SECONDS 3600

typedef struct {
    int sequence_number;
} FileData;

typedef struct {
    char hash[32];
    pthread_mutex_t lock;
    int accessed_time;
} HashCacheEntry;

HashCacheEntry hash_cache[MAX_FILES];

pthread_mutex_t cache_lock;

void init_hash_cache() {
    for (int i = 0; i < MAX_FILES; ++i) {
        pthread_mutex_init(&hash_cache[i].lock, NULL);
        memset(hash_cache[i].hash, 0, sizeof(hash_cache[i].hash));
        hash_cache[i].accessed_time = 0;
    }
    pthread_mutex_init(&cache_lock, NULL);
}

int get_cached_hash(const char* file_path) {
    int hash_index = hash(file_path) % MAX_FILES;
    pthread_mutex_lock(&hash_cache[hash_index].lock);
    if (strcmp(hash_cache[hash_index].hash, "") == 0 || 
        (time(NULL) - hash_cache[hash_index].accessed_time > CACHE_EXPIRY_SECONDS)) {
        // Fetch and cache the hash from the distributed cache
        strcpy(hash_cache[hash_index].hash, fetch_hash_from_distributed_cache(file_path));
        hash_cache[hash_index].accessed_time = time(NULL);
    }
    pthread_mutex_unlock(&hash_cache[hash_index].lock);
    return atoi(hash_cache[hash_index].hash);
}

void update_known_hashes(const char* new_hashes[]) {
    // Update the known hashes in a transactional manner
    for (int i = 0; new_hashes[i] != NULL; ++i) {
        int hash_index = hash(new_hashes[i]) % MAX_FILES;
        pthread_mutex_lock(&hash_cache[hash_index].lock);
        strcpy(hash_cache[hash_index].hash, new_hashes[i]);
        pthread_mutex_unlock(&hash_cache[hash_index].lock);
    }
}

void log_sequence_number(const char* file_path, int sequence_number) {
    // Log the sequence number with a timestamp
    time_t now = time(NULL);
    printf("%s: File %s has sequence number %d\n", ctime(&now), file_path, sequence_number);
}

void process_file(const char* file_path) {
    int hash_index = get_cached_hash(file_path);
    if (hash_index == known_hashes[0]) {
        // Extract the sequence number from the last line
        FileData data = extract_sequence_number_from_file(file_path);
        if (data.sequence_number >= MIN_SEQUENCE_NUMBER) {
            log_sequence_number(file_path, data.sequence_number);
        }
    }
}

void* thread_function(void* arg) {
    const char** file_paths = (const char**)arg;
    for (int i = 0; file_paths[i] != NULL; ++i) {
        process_file(file_paths[i]);
    }
    return NULL;
}

int main() {
    init_hash_cache();
    const char* file_paths[MAX_FILES];
    // Populate file_paths array with actual file paths
    pthread_t threads[N];
    for (int i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &file_paths);
    }
    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
