#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000
#define BUCKET_SIZE 10

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node** buckets;
    int size;
} LinkedList;

int hash(int RNTI, int bucketSize) {
    return abs(RNTI % bucketSize);
}

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        printf("Memory allocation failed for linked list.\n");
        exit(EXIT_FAILURE);
    }
    list->buckets = (Node**)calloc(BUCKET_SIZE, sizeof(Node*));
    if (list->buckets == NULL) {
        printf("Memory allocation failed for buckets.\n");
        free(list);
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    return list;
}

int isUnique(LinkedList* list, int RNTI) {
    int index = hash(RNTI, BUCKET_SIZE);
    Node* current = list->buckets[index];
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed for node.\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

int insert(LinkedList* list, NFAPI_CRC_INDICATION_PDU data) {
    if (list->size >= MAX_SIZE) {
        printf("Linked list has reached its maximum capacity.\n");
        return 0;
    }
    if (!isUnique(list, data.RNTI)) {
        printf("RNTI %d is not unique.\n", data.RNTI);
        return 0;
    }
    int index = hash(data.RNTI, BUCKET_SIZE);
    Node* newNode = createNode(data);
    newNode->next = list->buckets[index];
    list->buckets[index] = newNode;
    list->size++;
    return 1;
}

void freeLinkedList(LinkedList* list) {
    for (int i = 0; i < BUCKET_SIZE; i++) {
        Node* current = list->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(list->buckets);
    free(list);
}

int main() {
    LinkedList* list = createLinkedList();
    srand(time(0));
    for (int i = 0; i < MAX_SIZE + 1; i++) {
        NFAPI_CRC_INDICATION_PDU data = {
            .RX_UE_INFORMATION_TAG = i,
            .RNTI = rand() % 10000,
            .CRC_INDICATION_REL8_TAG = rand() % 256,
            .CRCFLAG = rand() % 2
        };
        if (!insert(list, data)) {
            printf("Insertion failed for RNTI %d.\n", data.RNTI);
            break;
        }
    }
    freeLinkedList(list);
    return 0;
}
