    pthread_mutex_lock(&mutex);
    if (new_size > MAX_STRUCTURES) {
        log_event("Allocation Failure: Exceeds max structures", new_size);
        return -1;
    }

    NfaPduList* new_list = realloc(nfa_list, new_size * sizeof(NfaPduList));
    if (!new_list) {
        log_event("Allocation Failure: Out of memory", new_size);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    nfa_list = new_list;
    current_size = new_size;
    log_event("Memory Allocated", new_size * sizeof(NfaPduList));
    pthread_mutex_unlock(&mutex);
    return 0;
}

void free_memory() {
    pthread_mutex_lock(&mutex);
    if (nfa_list) {
        free(nfa_list);
        nfa_list = NULL;
        current_size = 0;
        log_event("Memory Freed", 0);
    }
    pthread_mutex_unlock(&mutex);
}

int get_memory_stats(int* total, int* used, int* peak) {
    *total = MAX_STRUCTURES * sizeof(NfaPduList);
    *used = current_size * sizeof(NfaPduList);
    // Peak memory usage is not tracked in this simple example
    *peak = 0;
    return 0;
}

int serialize_structures(char** buffer, int* length) {
    pthread_mutex_lock(&mutex);
    if (!nfa_list || current_size == 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    *length = current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = malloc(*length);
    if (!*buffer) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < current_size; i++) {
        memcpy((*buffer) + (i * sizeof(NFAPI_CRC_INDICATION_PDU_T)), &nfa_list[i].pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int deserialize_structures(char* buffer, int length) {
    pthread_mutex_lock(&mutex);
    if (length % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    int new_size = length / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    allocate_memory(new_size);

    for (int i = 0; i < new_size; i++) {
        memcpy(&nfa_list[i].pdu, buffer + (i * sizeof(NFAPI_CRC_INDICATION_PDU_T)), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}
