#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1024

typedef struct TCP_PACKET_HEADER {
    unsigned int SRC_IP;
    unsigned int DST_IP;
    unsigned short TCP_FLAGS;
    unsigned int SEQ_NUMBER;
} TCP_PACKET_HEADER;

typedef struct Node {
    TCP_PACKET_HEADER data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
} LinkedList;

Node* create_node(TCP_PACKET_HEADER data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node != NULL) {
        new_node->data = data;
        new_node->next = NULL;
    }
    return new_node;
}

int insert(LinkedList* list, TCP_PACKET_HEADER data) {
    if (list->count >= MAX_SIZE) {
        // Handle capacity management (LRU eviction or fallback mechanism)
        printf("List is full. Evicting least recently used item.\n");
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }

    Node* new_node = create_node(data);
    if (new_node == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return -1;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    return 0;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    LinkedList list = { .head = NULL, .count = 0 };

    TCP_PACKET_HEADER packet1 = { .SRC_IP = 192.168.1.1, .DST_IP = 10.0.0.1, .TCP_FLAGS = 0x12, .SEQ_NUMBER = 1 };
    TCP_PACKET_HEADER packet2 = { .SRC_IP = 10.0.0.1, .DST_IP = 192.168.1.1, .TCP_FLAGS = 0x14, .SEQ_NUMBER = 2 };

    insert(&list, packet1);
    insert(&list, packet2);

    free_list(&list);

    return 0;
}
