typedef struct {
    // Define the NFAPI_CRC_INDICATION_PDU_T structure fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *ues[MAX_UEs];
    pthread_mutex_t lock;
} UEList;

int hash(int rnti, int size) {
    return rnti % size;
}

void insert(UEList *list, NFAPI_CRC_INDICATION_PDU_T *ue) {
    pthread_mutex_lock(&list->lock);
    int index = hash(ue->RNTI, MAX_UEs);
    while (list->ues[index] != NULL && list->ues[index]->RNTI != ue->RNTI) {
        index = (index + 1) % MAX_UEs;
    }
    if (list->ues[index] == NULL) {
        list->ues[index] = ue;
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* createUE() {
    NFAPI_CRC_INDICATION_PDU_T *ue = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (ue == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    ue->RX_UE_INFORMATION_TAG = rand();
    ue->RNTI = rand() % RNTI_RANGE;
    ue->CRC_INDICATION_REL8_TAG = rand();
    ue->CRCFLAG = rand() % 2;
    return ue;
}

void* generateUEs(void *arg) {
    UEList *list = (UEList*)arg;
    int numUEs = MAX_UEs; // Assuming we want to generate for all UEs
    for (int i = 0; i < numUEs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *ue = createUE();
        insert(list, ue);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    UEList list;
    pthread_t threads[10];

    pthread_mutex_init(&list.lock, NULL);
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, generateUEs, &list);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&list.lock);
    return 0;
}
