import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import redis.clients.jedis.*;

public class FileHashProcessor {

    private static final String CACHE_KEY_PREFIX = "file_md5_";
    private static final long CACHE_EXPIRY_SECONDS = 3600; // 1 hour
    private static JedisPool jedisPool;

    public static void initCache() {
        jedisPool = new JedisPool("localhost");
    }

    public static void shutdownCache() {
        if (jedisPool != null) {
            jedisPool.close();
        }
    }

    public static String computeMD5Hash(Path filePath, long minSequenceNumber) throws IOException, NoSuchAlgorithmException {
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("SEQNUMBER=")) {
                    int sequenceNumber = Integer.parseInt(line.substring("SEQNUMBER=".length()));
                    if (sequenceNumber >= minSequenceNumber) {
                        return md.digest(line.getBytes());
                    }
                }
                md.update(line.getBytes());
            }
            return bytesToHex(md.digest());
        }
    }

    public static boolean verifySHA256(Path filePath, byte[] sha256Hash) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream fis = Files.newInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return Arrays.equals(md.digest(), sha256Hash);
    }

    public static boolean checkCacheAndExtractSequenceNumber(String filePath, long minSequenceNumber) throws IOException {
        Jedis jedis = jedisPool.getResource();
        try {
            String cacheKey = CACHE_KEY_PREFIX + filePath.toString();
            if (jedis.exists(cacheKey)) {
                byte[] cachedMD5Hash = jedis.getBinary(cacheKey);
                byte[] sha256Hash = Files.readAllBytes(filePath);
                if (Arrays.equals(cachedMD5Hash, computeMD5Hash(filePath.toPath(), minSequenceNumber))) {
                    String sequenceNumberLine = new String(Files.readAllLines(filePath).stream()
                            .filter(line -> line.startsWith("SEQNUMBER="))
                            .findFirst().orElse(""));
                    int sequenceNumber = Integer.parseInt(sequenceNumberLine.substring("SEQNUMBER=".length()));
                    if (sequenceNumber >= minSequenceNumber) {
                        System.out.println("Cached MD5 hash matches, sequence number: " + sequenceNumber);
                        return true;
                    }
                } else {
                    jedis.del(cacheKey);
                }
            }
        } finally {
            jedis.close();
        }
        return false;
    }

    public static void main(String[] args) throws IOException, NoSuchAlgorithmException {
        initCache();

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Future<Boolean>> futures = new ArrayList<>();

        for (String filePath : args) {
            Path path = Paths.get(filePath);
            if (!Files.exists(path)) {
                continue;
            }
            futures.add(executor.submit(() -> {
                try {
                    return checkCacheAndExtractSequenceNumber(filePath, 100); // Example min sequence number
                } catch (IOException | NoSuchAlgorithmException e) {
                    e.printStackTrace();
                    return false;
                }
            }));
        }

        for (Future<Boolean> future : futures) {
            try {
                if (future.get()) {
                    System.out.println("File processed successfully.");
                }
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executor.shutdown();
        shutdownCache();
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
