        _transformers.Add(transformer);
    }

    public async Task ProcessDataAsync(IEnumerable<byte[]> dataStream)
    {
        foreach (var data in dataStream)
        {
            var transformedData = TransformData(data);
            await _performanceTracker.TrackLatency(async () =>
            {
                // Simulate data processing
                await Task.Delay(_minProcessingTime + new Random().Next(_maxProcessingTime - _minProcessingTime));
                ProcessTransformedData(transformedData);
            });
        }
    }

    private byte[] TransformData(byte[] data)
    {
        var result = data;
        foreach (var transformer in _transformers)
        {
            result = transformer.Transform(result);
        }
        return result;
    }

