    {
        // Process the transformed data here
    }

    public void Cleanup()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _transformers.Clear();
            _performanceTracker.Dispose();
        }
