#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CONCURRENT_IO 100

typedef struct {
    char *key;
    char *value;
} ConfigEntry;

typedef struct {
    ConfigEntry **entries;
    int count;
    pthread_mutex_t lock;
} ConfigStore;

ConfigStore *create_config_store(int max_entries) {
    ConfigStore *store = (ConfigStore *)malloc(sizeof(ConfigStore));
    store->entries = (ConfigEntry **)malloc(max_entries * sizeof(ConfigEntry *));
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void destroy_config_store(ConfigStore *store) {
    for (int i = 0; i < store->count; i++) {
        free(store->entries[i]->key);
        free(store->entries[i]->value);
        free(store->entries[i]);
    }
    free(store->entries);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

int get_config_value(ConfigStore *store, const char *key, char **value) {
    pthread_mutex_lock(&store->lock);
    for (int i = 0; i < store->count; i++) {
        if (strcmp(store->entries[i]->key, key) == 0) {
            *value = strdup(store->entries[i]->value);
            pthread_mutex_unlock(&store->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&store->lock);
    *value = NULL;
    return -1;
}

int update_config_value(ConfigStore *store, const char *key, const char *value) {
    pthread_mutex_lock(&store->lock);
    for (int i = 0; i < store->count; i++) {
        if (strcmp(store->entries[i]->key, key) == 0) {
            free(store->entries[i]->value);
            store->entries[i]->value = strdup(value);
            pthread_mutex_unlock(&store->lock);
            return 0;
        }
    }
    ConfigEntry *entry = (ConfigEntry *)malloc(sizeof(ConfigEntry));
    entry->key = strdup(key);
    entry->value = strdup(value);
    store->entries[store->count++] = entry;
    pthread_mutex_unlock(&store->lock);
    return 0;
}

int main() {
    ConfigStore *store = create_config_store(MAX_CONCURRENT_IO);

    // Example usage
    char *value;
    int result;

    // Get configuration value
    result = get_config_value(store, "example_key", &value);
    if (result == 0) {
        printf("Value for example_key: %s\n", value);
        free(value);
    } else {
        printf("Key not found or error occurred.\n");
    }

    // Update configuration value
    result = update_config_value(store, "example_key", "new_value");
    if (result == 0) {
        printf("Configuration updated successfully.\n");
    } else {
        printf("Error updating configuration.\n");
    }

    destroy_config_store(store);

    return 0;
}
