    // Define the structure for file metadata
} FILE_METADATA;

typedef struct {
    int node_id;
    FILE_METADATA metadata;
    sem_t lock;
} DISTRIBUTED_CACHE_ENTRY;

DISTRIBUTED_CACHE_ENTRY distributed_cache[MAX_NODES];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

int init_distributed_cache() {
    // Initialize the distributed cache entries
    for (int i = 0; i < MAX_NODES; i++) {
        distributed_cache[i].node_id = i;
        sem_init(&distributed_cache[i].lock, 0, 1);
    }
    return 0;
}

int get_metadata(int node_id, FILE_METADATA *metadata) {
    // Retrieve metadata for a given node
    pthread_mutex_lock(&cache_lock);
    if (node_id < 0 || node_id >= MAX_NODES) {
        pthread_mutex_unlock(&cache_lock);
        return -1; // Invalid node ID
    }
    sem_wait(&distributed_cache[node_id].lock);
    *metadata = distributed_cache[node_id].metadata;
    sem_post(&distributed_cache[node_id].lock);
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

int update_metadata(int node_id, FILE_METADATA metadata) {
    // Update metadata for a given node
    pthread_mutex_lock(&cache_lock);
    if (node_id < 0 || node_id >= MAX_NODES) {
        pthread_mutex_unlock(&cache_lock);
        return -1; // Invalid node ID
    }
    sem_wait(&distributed_cache[node_id].lock);
    distributed_cache[node_id].metadata = metadata;
    sem_post(&distributed_cache[node_id].lock);
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

int main() {
    init_distributed_cache();

    FILE_METADATA metadata;
    if (get_metadata(0, &metadata) == 0) {
        // Use the retrieved metadata
    }

    FILE_METADATA new_metadata = { /* Initialize with new values */ };
    if (update_metadata(0, new_metadata) == 0) {
        // Metadata updated successfully
    }

    return 0;
}
