// Define constants for the program
const std::string DEFAULT_SERVICE = "OpenWeatherMap";
const int DEFAULT_INTERVAL = 60; // seconds

// Function prototypes
void parseArgs(int argc, char* argv[]);
void fetchWeatherData(const std::string& service, const std::string& location);
double calculateAverage(std::vector<double>& data);
void displayResults(double averageTemp, double maxHumidity, double minWindSpeed);

int main(int argc, char* argv[]) {
    parseArgs(argc, argv);
    // Fetch and process weather data based on parsed arguments
    fetchWeatherData(DEFAULT_SERVICE, "40.7128,-74.0060"); // Example location: New York City
    return 0;
}

void parseArgs(int argc, char* argv[]) {
    for (int i = 1; i < argc; ++i) {
        if (std::strcmp(argv[i], "-v") == 0) {
            std::cout << "Verbose mode enabled" << std::endl;
        } else if (std::strcmp(argv[i], "--help") == 0) {
            std::cout << "Usage: program_name [options]" << std::endl;
            std::cout << "Options:" << std::endl;
            std::cout << "  -v      Enable verbose mode" << std::endl;
            std::cout << "  --help   Display this help message" << std::endl;
            exit(0);
        } else if (std::strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            std::string service = argv[++i];
            std::cout << "Using service: " << service << std::endl;
            // Handle the -s option for specifying a different weather service
        } else if (std::strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            int interval = std::atoi(argv[++i]);
            std::cout << "Update interval: " << interval << " seconds" << std::endl;
            // Handle the -t option for specifying a different update interval
        } else {
            std::cout << "Unknown option: " << argv[i] << std::endl;
            exit(1);
        }
    }
}

void fetchWeatherData(const std::string& service, const std::string& location) {
    CURL *curl;
    CURLcode res;
    std::string response;

    curl = curl_easy_init();
    if(curl) {
        std::string url = "http://api." + service + ".com/weather?q=" + location;
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void *ptr, size_t size, size_t nmemb, void *userdata){
            static_cast<std::string*>(userdata)->append(static_cast<char*>(ptr), size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;

        curl_easy_cleanup(curl);
    }

    // Process the response to extract weather data
    displayResults(20.5, 85.0, 15.0); // Example values for demonstration
}

void displayResults(double averageTemp, double maxHumidity, double minWindSpeed) {
    std::cout << "Average Temperature: " << averageTemp << "°C" << std::endl;
    std::cout << "Max Humidity: " << maxHumidity << "%" << std::endl;
    std::cout << "Min Wind Speed: " << minWindSpeed << " m/s" << std::endl;
}
