#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 16384

typedef struct {
    HTTP_REQUEST_HANDLE handle;
    char REMOTE_URL[256];
    int LOCAL_PORT;
    char REQUEST_METHOD[10];
    int RESPONSE_STATUS;
} HTTP_REQUEST_RECORD;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    HTTP_REQUEST_RECORD *requests;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications;
    int size;
    int max_size;
    pthread_mutex_t mutex;
} RequestPool;

int init_request_pool(RequestPool *pool, int initial_size) {
    pool->requests = malloc(initial_size * sizeof(HTTP_REQUEST_RECORD));
    if (pool->requests == NULL) return -1;

    pool->crc_indications = malloc(10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pool->crc_indications == NULL) {
        free(pool->requests);
        return -1;
    }

    pool->size = 0;
    pool->max_size = initial_size;
    pthread_mutex_init(&pool->mutex, NULL);
    return 0;
}

void destroy_request_pool(RequestPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    free(pool->requests);
    free(pool->crc_indications);
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
}

int add_request_to_pool(RequestPool *pool, HTTP_REQUEST_RECORD request) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->max_size) {
        // Resize the array
        int new_max_size = pool->max_size * 2;
        HTTP_REQUEST_RECORD *new_requests = realloc(pool->requests, new_max_size * sizeof(HTTP_REQUEST_RECORD));
        if (new_requests == NULL) {
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }
        pool->requests = new_requests;
        pool->max_size = new_max_size;
    }
    pool->requests[pool->size++] = request;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

int validate_request_pool(RequestPool *pool) {
    // Perform validation checks
    for (int i = 0; i < pool->size; i++) {
        if (strlen(pool->requests[i].REMOTE_URL) > 256 ||
            strlen(pool->requests[i].REQUEST_METHOD) > 10 ||
            pool->requests[i].LOCAL_PORT <= 0 ||
            pool->requests[i].RESPONSE_STATUS < 200 || pool->requests[i].RESPONSE_STATUS >= 600) {
            return -1;
        }
    }
    return 0;
}

int main() {
    RequestPool pool;
    init_request_pool(&pool, 100);

    HTTP_REQUEST_RECORD request = { /* Initialize with valid data */ };
    add_request_to_pool(&pool, request);

    if (validate_request_pool(&pool) == -1) {
        printf("Invalid request pool\n");
    }

    destroy_request_pool(&pool);
    return 0;
}
