#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE (1024 * 1024 * 5) // 5 MB buffer

void print_usage() {
    printf("Usage: program [options] filename\n");
    printf("Options:\n");
    printf("  -h, --help         Display this help message\n");
    printf("  -s, --case-sensitive Perform case-sensitive word counting\n");
}

int count_lines(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    char *buffer = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        close(fd);
        perror("mmap");
        return -1;
    }

    int line_count = 0;
    const char *p = buffer;
    while (*p) {
        if (*p == '\n') {
            line_count++;
        }
        p++;
    }

    munmap(buffer, BUFFER_SIZE);
    close(fd);
    return line_count;
}

void analyze_file(const char *filename, int case_sensitive) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return;
    }

    char *buffer = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        close(fd);
        perror("mmap");
        return;
    }

    int line_count = 0;
    size_t word_count = 0;
    double total_word_length = 0.0;
    char longest_line[MAX_LINE_LENGTH] = {0};
    char shortest_line[MAX_LINE_LENGTH] = {0};

    const char *p = buffer;
    while (*p) {
        if (*p == '\n') {
            line_count++;
            p++;
            continue;
        }

        // Skip whitespace and punctuation
        while (*p && !isalpha(*p)) {
            p++;
        }

        if (*p) {
            word_count++;
            size_t start = p - buffer;
            while (*p && isalpha(*p)) {
                p++;
            }
            size_t length = p - (buffer + start);
            total_word_length += length;

            if (length > strlen(longest_line)) {
                strncpy(longest_line, buffer + start, length);
                longest_line[length] = '\0';
            }

            if (!shortest_line[0] || length < strlen(shortest_line)) {
                strncpy(shortest_line, buffer + start, length);
                shortest_line[length] = '\0';
            }
        } else {
            p++;
        }
    }

    munmap(buffer, BUFFER_SIZE);
    close(fd);

    printf("Line count: %d\n", line_count);
    printf("Word count: %zu\n", word_count);
    if (word_count > 0) {
        double average_word_length = total_word_length / word_count;
        printf("Average word length: %.2f\n", average_word_length);
    }
    printf("Longest line: '%s'\n", longest_line);
    printf("Shortest line: '%s'\n", shortest_line);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    int case_sensitive = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--case-sensitive") == 0) {
            case_sensitive = 1;
        } else {
            analyze_file(argv[i], case_sensitive);
        }
    }

    return 0;
}
```

Note: The provided code snippet is a basic implementation and may require additional error checking and optimizations for production use.']

