NFAPI_CRC_INDICATION_PDU_T* generateUeData(int numUes) {
    if (numUes > MAX_UEs) {
        fprintf(stderr, "Too many UEs requested. Max is %d\n", MAX_UES);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* ueData = malloc(numUes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (ueData == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < numUes; i++) {
        ueData[i].rnti = rand() % MAX_UES + 1; // Ensure unique RNTI
        ueData[i].crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    return ueData;
}

void* threadFunction(void* arg) {
    int numUes = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* ueData = generateUeData(numUes);
    if (ueData != NULL) {
        printf("Successfully generated data for %d UEs\n", numUes);
        free(ueData);
    } else {
        printf("Failed to generate data for %d UEs\n", numUes);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_UES];
    int threadArgs[MAX_UES];

    for (int i = 0; i < MAX_UES; i++) {
        threadArgs[i] = i + 1; // Number of UEs
        if (pthread_create(&threads[i], NULL, threadFunction, &threadArgs[i]) != 0) {
            fprintf(stderr, "Failed to create thread for %d UEs\n", i + 1);
            break;
        }
    }

    for (int i = 0; i < MAX_UES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
