import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class FileProcessor {
    private static final int THREAD_POOL_SIZE = Runtime.getRuntime().availableProcessors();
    private static final Map<String, String> md5Cache = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRY = 3600L * 1000; // 1 hour

    public static void processFiles(List<String> filePaths) {
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        CompletionService<Void> completionService = new ExecutorCompletionService<>(executorService);

        for (String filePath : filePaths) {
            completionService.submit(() -> processFile(filePath), null);
        }

        try {
            for (int i = 0; i < filePaths.size(); i++) {
                completionService.take().get();
            }
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        executorService.shutdownNow();
    }

    private static void processFile(String filePath) {
        try {
            FileInputStream fis = new FileInputStream(filePath);
            MessageDigest md5Digest = MessageDigest.getInstance("MD5");
            MessageDigest sha256Digest = MessageDigest.getInstance("SHA-256");

            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md5Digest.update(buffer, 0, bytesRead);
                sha256Digest.update(buffer, 0, bytesRead);
            }

            String fileHash = bytesToHex(md5Digest.digest());
            String sha256Hash = bytesToHex(sha256Digest.digest());

            if (md5Cache.containsKey(fileHash)) {
                String cachedSequenceNumber = md5Cache.get(fileHash).split(",")[1];
                long sequenceNumber = Long.parseLong(cachedSequenceNumber);
                if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
                    System.out.println("Processed file: " + filePath + ", Sequence Number: " + sequenceNumber);
                }
            } else {
                String md5Result = fetchMd5HashFromCache(sha256Hash);
                if (md5Result != null) {
                    long sequenceNumber = Long.parseLong(md5Result.split(",")[1]);
                    if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
                        System.out.println("Processed file: " + filePath + ", Sequence Number: " + sequenceNumber);
                        md5Cache.put(fileHash, md5Result);
                    }
                }
            }

            fis.close();
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    private static String fetchMd5HashFromCache(String sha256Hash) {
        // Simulate fetching from distributed cache
        return "known_hash,12345";
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        List<String> filePaths = Arrays.asList("file1.txt", "file2.txt", "file3.txt");
        processFiles(filePaths);
    }
}
