#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_init_array(int N, int rnti_limit) {
    if (N <= 0 || rnti_limit <= 0) {
        fprintf(stderr, "Invalid input values\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    int sum_rnti = 0;

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example initialization
        array[i].RNTI = sum_rnti + rand() % rnti_limit;
        if (array[i].RNTI >= rnti_limit) {
            fprintf(stderr, "RNTI exceeds limit\n");
            free(array);
            return NULL;
        }
        sum_rnti = array[i].RNTI;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }

    return array;
}

int main() {
