#include <pthread.h>

#define MAX_UES 10000
#define PRIMARY_POOL_SIZE 1024
#define SECONDARY_POOL_SIZE 512
#define POOL_REFRESH_INTERVAL 60

typedef struct {
    int RNTI;
    char CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    // Define the NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    RX_UE_INFORMATION_TAG rnti_pool[PRIMARY_POOL_SIZE];
    int next_rnti_index;
    RX_UE_INFORMATION_TAG secondary_rnti_pool[SECONDARY_POOL_SIZE];
    int next_secondary_rnti_index;
} RNTI_Pool;

RNTI_Pool rnti_pool;

void init_rnti_pools() {
    pthread_mutex_init(&rnti_pool.lock, NULL);
    srand(time(NULL));
    for (int i = 0; i < PRIMARY_POOL_SIZE; ++i) {
        rnti_pool.rnti_pool[i].RNTI = rand() % 65535;
        rnti_pool.rnti_pool[i].CRCFLAG = rand() % 2 == 0 ? 'A' : 'B';
    }
    for (int i = 0; i < SECONDARY_POOL_SIZE; ++i) {
        rnti_pool.secondary_rnti_pool[i].RNTI = rand() % 65535;
        rnti_pool.secondary_rnti_pool[i].CRCFLAG = rand() % 2 == 0 ? 'A' : 'B';
    }
}

int get_unique_rnti() {
    pthread_mutex_lock(&rnti_pool.lock);
    if (rnti_pool.next_rnti_index < PRIMARY_POOL_SIZE) {
        int rnti = rnti_pool.rnti_pool[rnti_pool.next_rnti_index].RNTI;
        ++rnti_pool.next_rnti_index;
        pthread_mutex_unlock(&rnti_pool.lock);
        return rnti;
    } else if (rnti_pool.next_secondary_rnti_index < SECONDARY_POOL_SIZE) {
        int rnti = rnti_pool.secondary_rnti_pool[rnti_pool.next_secondary_rnti_index].RNTI;
        ++rnti_pool.next_secondary_rnti_index;
        pthread_mutex_unlock(&rnti_pool.lock);
        return rnti;
    } else {
        pthread_mutex_unlock(&rnti_pool.lock);
        // Handle RNTI exhaustion
        return -1;
    }
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_pdu(int num_ues) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_ues; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG.RNTI = get_unique_rnti();
        if (pdus[i].RX_UE_INFORMATION_TAG.RNTI == -1) {
            // Handle error
            free(pdus);
            return NULL;
        }
        pdus[i].RX_UE_INFORMATION_TAG.CRCFLAG = rand() % 2 == 0 ? 'A' : 'B';
    }

    return pdus;
}

void* refresh_rnti_pool(void* arg) {
    while (1) {
        sleep(POOL_REFRESH_INTERVAL);
        // Implement pool refresh logic here
    }
}

int main() {
    init_rnti_pools();
    pthread_t refresh_thread;
    pthread_create(&refresh_thread, NULL, refresh_rnti_pool, NULL);

    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_nfaapi_pdu(MAX_UES);
    if (pdus) {
        // Process the generated PDUs
        free(pdus);
    }

    return 0;
}
