#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_PDUS_ARRAY;

void generate_NFAPI_PDUs(NFAPI_PDUS_ARRAY* array) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= MAX_ELEMENTS) {
        // Handle error: Array is full
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    new_pdu.CRCFLAG = rand() % 2; // Randomize CRCFLAG value

    array->elements[array->count++] = new_pdu;

    pthread_mutex_unlock(&array->mutex);
}

int main() {
    NFAPI_PDUS_ARRAY my_array;
    my_array.elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    my_array.count = 0;
    pthread_mutex_init(&my_array.mutex, NULL);

    // Generate PDUs
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        generate_NFAPI_PDUs(&my_array);
    }

    // Clean up
    free(my_array.elements);
    pthread_mutex_destroy(&my_array.mutex);

    return 0;
}
