    if (!cache->records) return -1;
    cache->count = 0;
    cache->capacity = initialCapacity;
    pthread_mutex_init(&cache->lock, NULL);
    return 0;
}

void freeCache(METADATA_CACHE* cache) {
    pthread_mutex_lock(&cache->lock);
    free(cache->records);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
}

int addMetadataToCache(METADATA_CACHE* cache, const IMAGE_RECORD* newRecord) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count >= cache->capacity) {
        cache->records = realloc(cache->records, cache->capacity * 2 * sizeof(IMAGE_RECORD));
        if (!cache->records) {
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }
        cache->capacity *= 2;
    }
    memcpy(&cache->records[cache->count], newRecord, sizeof(IMAGE_RECORD));
    cache->count++;
    pthread_mutex_unlock(&cache->lock);
    return 0;
