public void processFilesAsynchronously(String... filePaths) {
    ExecutorService executorService = Executors.newFixedThreadPool(filePaths.length);
    for (String filePath : filePaths) {
        executorService.submit(() -> {
            try {
                File file = new File(filePath);
                if (!file.exists() || !file.isFile()) {
                    logError("File does not exist or is not a file: " + filePath);
                    return;
                }

                byte[] sha256Hash = computeSHA256(file);
                if (isKnownHash(sha256Hash)) {
                    int sequenceNumber = extractSequenceNumber(file);
                    if (sequenceNumber >= MIN_SEQUENCE_NUMBER) {
                        logSequenceNumber(sequenceNumber);
                    }
                }
            } catch (IOException | NoSuchAlgorithmException e) {
                handleException(e);
            }
        });
    }

    executorService.shutdown();
}

private byte[] computeSHA256(File file) throws IOException, NoSuchAlgorithmException {
    MessageDigest digest = MessageDigest.getInstance("SHA-256");
    FileInputStream fis = new FileInputStream(file);
    byte[] buffer = new byte[8192];
    int bytesRead;
    while ((bytesRead = fis.read(buffer)) != -1) {
        digest.update(buffer, 0, bytesRead);
    }
    fis.close();
    return digest.digest();
}

private boolean isKnownHash(byte[] hash) {
    // Check the distributed cache system for known hashes
    return false; // Placeholder
}

private int extractSequenceNumber(File file) throws IOException {
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("SEQUENCE_NUMBER:")) {
            return Integer.parseInt(line.split(":")[1].trim());
        }
    }
    reader.close();
    return -1; // Not found
}

private void handleException(Exception e) {
    logError("Exception occurred during file processing: " + e.getMessage());
}
