#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1024

typedef struct TCP_PACKET_HEADER {
    char SRC_IP[16];
    char DST_IP[16];
    unsigned int SEQ_NUMBER;
    unsigned short TCP_FLAGS;
} TCP_PACKET_HEADER;

typedef struct Node {
    TCP_PACKET_HEADER data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    unsigned int hashTable[MAX_SIZE];
} LinkedList;

unsigned int customHash(unsigned int key) {
    return key % MAX_SIZE;
}

int isUnique(LinkedList* list, unsigned int seqNumber) {
    for (int i = 0; i < MAX_SIZE; i++) {
        if (list->hashTable[i] == seqNumber) {
            return 0;
        }
    }
    return 1;
}

void addNode(LinkedList* list, TCP_PACKET_HEADER packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    newNode->data = packet;
    newNode->next = NULL;

    unsigned int index = customHash(packet.SEQ_NUMBER);
    if (isUnique(list, packet.SEQ_NUMBER)) {
        list->hashTable[index] = packet.SEQ_NUMBER;
        Node* temp = list->head;
        list->head = newNode;
        newNode->next = temp;
        list->size++;
    } else {
        printf("Duplicate sequence number found\n");
        free(newNode);
    }
}

void cleanup(LinkedList* list) {
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    memset(list->hashTable, 0, sizeof(list->hashTable));
    list->size = 0;
}

void resize(LinkedList* list) {
    int newSize = MAX_SIZE * 2;
    unsigned int newHashTable[newSize];
    memset(newHashTable, 0, sizeof(newHashTable));

    Node* current = list->head;
    while (current != NULL) {
        unsigned int index = customHash(current->data.SEQ_NUMBER);
        if (!newHashTable[index]) {
            newHashTable[index] = current->data.SEQ_NUMBER;
        } else {
            printf("Collision detected during resize\n");
        }
        current = current->next;
    }

    memcpy(list->hashTable, newHashTable, sizeof(newHashTable));
    MAX_SIZE = newSize;
}

int main() {
    LinkedList list;
    memset(&list, 0, sizeof(LinkedList));

    TCP_PACKET_HEADER packet1 = {"192.168.1.1", "192.168.1.2", 12345, 0x02};
    TCP_PACKET_HEADER packet2 = {"192.168.1.1", "192.168.1.2", 67890, 0x02};

    addNode(&list, packet1);
    addNode(&list, packet2);

    cleanup(&list);

    return 0;
}
