#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 100
#define TIMEOUT_SECONDS 30

typedef enum {
    CONN_IDLE,
    CONN_ACTIVE
} ConnectionState;

typedef struct {
    int socket_descriptor;
    struct sockaddr_in client_address;
    ConnectionState state;
} Connection;

Connection *connection_pool[MAX_CONNECTIONS];
int next_available_connection = 0;

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i] = (Connection *)malloc(sizeof(Connection));
        connection_pool[i]->socket_descriptor = -1;
        connection_pool[i]->state = CONN_IDLE;
    }
}

int get_available_connection(int client_socket, struct sockaddr_in *client_addr) {
    if (next_available_connection == MAX_CONNECTIONS) {
        return -1; // Pool is full
    }

    int index = next_available_connection++;
    connection_pool[index]->socket_descriptor = client_socket;
    memcpy(&connection_pool[index]->client_address, client_addr, sizeof(struct sockaddr_in));
    connection_pool[index]->state = CONN_ACTIVE;

    return index;
}

void release_connection(int index) {
    if (index >= 0 && index < MAX_CONNECTIONS) {
        close(connection_pool[index]->socket_descriptor);
        memset(connection_pool[index], 0, sizeof(Connection));
        next_available_connection--;
    }
}

int main() {
    initialize_connection_pool();

    // Simulate accepting connections
    for (int i = 0; i < 5; i++) {
        int client_socket;
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);

        client_socket = accept(0, (struct sockaddr *)&client_addr, &addr_len);
        if (client_socket == -1) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        int index = get_available_connection(client_socket, &client_addr);
        if (index != -1) {
            printf("Connection %d established\n", index);
        } else {
            close(client_socket);
            printf("No available connections in pool\n");
        }
    }

    // Simulate timeout mechanism
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i]->socket_descriptor != -1) {
            int flags = fcntl(connection_pool[i]->socket_descriptor, F_GETFL);
            fcntl(connection_pool[i]->socket_descriptor, F_SETFL, flags | O_NONBLOCK);

            fd_set read_fds;
            FD_ZERO(&read_fds);
            FD_SET(connection_pool[i]->socket_descriptor, &read_fds);

            struct timeval timeout;
            timeout.tv_sec = TIMEOUT_SECONDS;
            timeout.tv_usec = 0;

            int activity = select(connection_pool[i]->socket_descriptor + 1, &read_fds, NULL, NULL, &timeout);
            if (activity == -1) {
                perror("select");
                exit(EXIT_FAILURE);
            } else if (activity == 0) {
                printf("Connection %d timed out\n", i);
                release_connection(i);
            } else {
                char buffer[1024];
                int value = read(connection_pool[i]->socket_descriptor, buffer, sizeof(buffer));
                if (value <= 0) {
                    printf("Connection %d closed\n", i);
                    release_connection(i);
                }
            }
        }
    }

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        free(connection_pool[i]);
    }

    return 0;
}
