public class NetworkDeviceConfigProcessor {

    private static final String CONFIG_FILE_PATH = "path/to/config.properties";
    private static final int MAX_THREADS = 200;
    private static final long CLEANUP_THRESHOLD = 100;
    private static final int GLOBAL_POOL_SIZE = 1000;

    private Connection dbConnection;
    private ExecutorService fileProcessingPool;
    private ExecutorService macAddressPool;
    private AtomicInteger structureCounter;

    public NetworkDeviceConfigProcessor() throws IOException, SQLException {
        initializeDatabase();
        initializePools();
        structureCounter = new AtomicInteger(0);
    }

    private void initializeDatabase() throws IOException, SQLException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(CONFIG_FILE_PATH)) {
            properties.load(fis);
        }
        String url = properties.getProperty("db.url");
        String user = properties.getProperty("db.user");
        String password = properties.getProperty("db.password");
        dbConnection = DriverManager.getConnection(url, user, password);

        Statement stmt = dbConnection.createStatement();
        stmt.execute("CREATE INDEX IF NOT EXISTS idx_config_version ON NetworkDevices (configVersion)");
    }

    private void initializePools() {
        fileProcessingPool = Executors.newFixedThreadPool(MAX_THREADS);
        macAddressPool = Executors.newFixedThreadPool(GLOBAL_POOL_SIZE);
    }

    public void processNetworkData(String configVersion) throws SQLException, InterruptedException {
        String query = "SELECT * FROM NetworkDevices WHERE configVersion = ?";
        try (PreparedStatement pstmt = dbConnection.prepareStatement(query)) {
            pstmt.setString(1, configVersion);
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    processDeviceConfig(rs.getString("IP"), rs.getInt("portNumber"), rs.getString("status"));
                }
            }
        }
    }

    private void processDeviceConfig(String ip, int port, String status) {
        fileProcessingPool.submit(() -> {
            try {
                String hash = computeMD5(ip + ":" + port + ":" + status);
                logHashMatch(hash);
            } catch (NoSuchAlgorithmException e) {
                Thread.currentThread().interrupt();
            }
        });
    }

    private String computeMD5(String data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(data.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void logHashMatch(String hash) {
        // Log match against known hashes
    }

    public void processFiles(String[] filePaths) throws InterruptedException {
        for (String path : filePaths) {
            fileProcessingPool.submit(() -> {
                try {
                    processFile(path);
                } catch (IOException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }
    }

    private void processFile(String path) throws IOException {
        // Process file and compute MD5 hash
    }

    public void cleanup() {
        if (structureCounter.get() >= CLEANUP_THRESHOLD || structureCounter.get() > MAX_THREADS * 2) {
            // Cleanup network-related data structures
        }
    }

    public void shutdown() throws InterruptedException {
        fileProcessingPool.shutdown();
        macAddressPool.shutdown();
        dbConnection.close();
        fileProcessingPool.awaitTermination(10, TimeUnit.SECONDS);
        macAddressPool.awaitTermination(10, TimeUnit.SECONDS);
    }

    private static NetworkDeviceConfigProcessor getInstance() throws IOException, SQLException {
        return new NetworkDeviceConfigProcessor();
    }
}
