                while (rs.next()) {
                    processDevice(rs.getString("ip_address"), rs.getInt("port_number"), rs.getString("status"));
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException("Failed to retrieve network device configurations", e);
        }

        try {
            executorService.shutdown();
            if (!executorService.awaitTermination(MAX_WAIT_TIME, TimeUnit.MILLISECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private void processDevice(String ip, int port, String status) {
        Runnable task = () -> {
            try {
                File[] files = getFilesForDevice(ip, port);
                for (File file : files) {
                    processFile(file, status);
                }
            } catch (Exception e) {
                logError("Error processing device " + ip + ":" + port, e);
            }
        };
        executorService.submit(task);
