    private void processFile(File file, String status) {
        try {
            byte[] hash = computeMd5Hash(file);
            if (isKnownHash(hash)) {
                logMatch(file.getName(), hash, status);
            }
        } catch (IOException e) {
            logError("Failed to process file " + file.getAbsolutePath(), e);
        }
    }

    private byte[] computeMd5Hash(File file) throws IOException {
        try (FileInputStream fis = new FileInputStream(file)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            return md.digest();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }
    }

