#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 10000
#define SERVER_PORT 8080

typedef struct {
    int socket_desc;
    struct sockaddr_in client_addr;
    char connection_state[50];
    time_t last_activity;
} Connection;

Connection connection_pool[MAX_CONNECTIONS];

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i].socket_desc = -1;
        strcpy(connection_pool[i].connection_state, "idle");
        connection_pool[i].last_activity = time(NULL);
    }
}

int get_available_connection_index() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i].socket_desc == -1) {
            return i;
        }
    }
    return -1;
}

void handle_new_connection(int new_socket, struct sockaddr_in client_addr) {
    int index = get_available_connection_index();
    if (index != -1) {
        connection_pool[index].socket_desc = new_socket;
        connection_pool[index].client_addr = client_addr;
        strcpy(connection_pool[index].connection_state, "active");
        connection_pool[index].last_activity = time(NULL);
        printf("New connection handled at index %d\n", index);
    } else {
        printf("No available connections in the pool\n");
    }
}

void manage_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i].socket_desc != -1) {
            time_t current_time = time(NULL);
            if (current_time - connection_pool[i].last_activity > 300) { // Check for idle connections
                close(connection_pool[i].socket_desc);
                connection_pool[i].socket_desc = -1;
                strcpy(connection_pool[i].connection_state, "idle");
                printf("Connection at index %d timed out and closed\n", i);
            }
        }
    }
}

int main() {
    int server_socket;
    struct sockaddr_in server_addr;

    initialize_connection_pool();

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        printf("Failed to create socket\n");
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Bind failed\n");
        return 1;
    }

    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        printf("Listen failed\n");
        return 1;
    }

    while (1) {
        struct sockaddr_in client_addr;
        int client_len = sizeof(client_addr);
        int new_socket = accept(server_socket, (struct sockaddr *)&client_addr, (socklen_t*)&client_len);
        if (new_socket < 0) {
            printf("Accept failed\n");
            continue;
        }

        handle_new_connection(new_socket, client_addr);

        manage_connection_pool();
    }

    close(server_socket);
    return 0;
}
