#define MAX_UE_CONTEXTS 100
#define PDCP_PDU_SIZE 256

typedef struct LTE_RRC_UE_CONTEXT_T {
    void* mac_entity;
    int logical_channel_group_id;
    PDCP_PDU_T* pdcp_pdus[MAX_UE_CONTEXTS];
} LTE_RRC_UE_CONTEXT_T;

typedef struct PDCP_PDU_T {
    uint16_t pdcp_sn;
    // Other fields
} PDCP_PDU_T;

void initializeAndDecryptLTEContext(LTE_RRC_UE_CONTEXT_T* ue_contexts, int num_contexts, void** mac_entities) {
    for (int i = 0; i < num_contexts; i++) {
        ue_contexts[i].mac_entity = mac_entities[i];
        ue_contexts[i].logical_channel_group_id = i % MAX_UE_CONTEXTS;

        for (int j = 0; j < MAX_UE_CONTEXTS; j++) {
            ue_contexts[i].pdcp_pdus[j] = malloc(sizeof(PDCP_PDU_T));
            ue_contexts[i].pdcp_pdus[j]->pdcp_sn = i * MAX_UE_CONTEXTS + j;
        }
    }
}

void* decryptData(const unsigned char* ciphertext, size_t ciphertext_len, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char* plaintext = malloc(ciphertext_len);
    if (!plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int len, plaintext_len;
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    // Resize plaintext to actual length
    unsigned char* decrypted_plaintext = realloc(plaintext, plaintext_len);
    if (!decrypted_plaintext) {
        free(plaintext);
        return NULL;
    }

    return decrypted_plaintext;
}
