    // Simulate API update
    usleep(1000 * pref->offset); // Delay based on offset for simulation
    if (pref->offset > 2147483647L || pref->offset < -2147483648L) {
        log_event("Invalid offset value %ld for preference key %d\n", pref->offset, pref->key);
    } else {
        // Simulate success
        log_event("Updated preference with key %d and offset %ld\n", pref->key, pref->offset);
    }
    destroy_preference(pref);
    pthread_exit(NULL);
}

int main() {
    const char* apiEndpoint = "https://api.example.com/user/preferences";
    unsigned long seed = 12345;

    UserPreference** prefs = (UserPreference**)malloc(sizeof(UserPreference*) * 10);
