    prefs[0] = create_preference(1, 100, 3.14, "Example");
    prefs[1] = create_preference(2, 200, 2.71, "Test");

    manageUserPreferences(prefs, 2, apiEndpoint, seed);

    for (int i = 0; i < 2; ++i) {
        destroy_preference(prefs[i]);
    }
    free(prefs);

    return 0;
}
