#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t max_count;
} NFAPICRCArray;

void log_allocation(NFAPICRCArray *array, NFAPI_CRC_INDICATION_PDU_T *struct_ptr, int status) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    if (status == 0) {
        printf("Allocation successful at %ld by thread %lu\n", time(NULL), pthread_self());
    } else {
        printf("Allocation failed at %ld by thread %lu\n", time(NULL), pthread_self());
    }
    pthread_mutex_unlock(&log_lock);
}

int allocate_array(NFAPICRCArray *array, size_t N) {
    if (N > MAX_STRUCTURES) {
        return -1; // Error: Maximum structures limit exceeded
    }

    array->count = 0;
    array->max_count = N;
    pthread_mutex_init(&array->lock, NULL);

    array->array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->array == NULL) {
        return -1; // Error: Memory allocation failed
    }

    for (size_t i = 0; i < N; i++) {
        pthread_mutex_lock(&array->lock);
        array->array[i].RX_UE_INFORMATION_TAG = rand();
        array->array[i].RNTI = rand() % 65536;
        array->array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array->array[i].CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&array->lock);
    }

    log_allocation(array, NULL, 0); // Log successful allocation of the array itself
    return 0; // Success
}

void free_array(NFAPICRCArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->array);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    log_allocation(array, NULL, 1); // Log successful deallocation of the array itself
}

void* thread_function(void *arg) {
    NFAPICRCArray *array = (NFAPICRCArray *)arg;
    if (allocate_array(array, 50) == 0) {
        printf("Thread %lu allocated 50 structures\n", pthread_self());
    } else {
        printf("Thread %lu allocation failed\n", pthread_self());
    }
    return NULL;
}

int main() {
    NFAPICRCArray array;
    pthread_t threads[10];

    if (allocate_array(&array, 100) == 0) {
        printf("Main thread allocated 100 structures\n");
    } else {
        printf("Main thread allocation failed\n");
        return 1;
    }

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, &array);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_array(&array);

    return 0;
}
