LTE_RRC_UE_CONTEXT_T* initializeAndManageLTEContext(const char* config_file_path, int network_load) {
    LTE_RRC_UE_CONTEXT_T* ue_contexts = (LTE_RRC_UE_CONTEXT_T*)malloc(MAX_UE_CONTEXTS * sizeof(LTE_RRC_UE_CONTEXT_T));
    if (!ue_contexts) {
        perror("Failed to allocate memory for UE contexts");
        return NULL;
    }

    // Initialize each UE context
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ue_contexts[i].mac_entity = malloc(sizeof(MAC_ENTITY));
        if (!ue_contexts[i].mac_entity) {
            perror("Failed to allocate memory for MAC entity");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(ue_contexts[j].mac_entity);
            }
            free(ue_contexts);
            return NULL;
        }

        ue_contexts[i].logical_channel_group = malloc(sizeof(LOGICAL_CHANNEL_GROUP));
        if (!ue_contexts[i].logical_channel_group) {
            perror("Failed to allocate memory for logical channel group");
            // Free previously allocated memory
            free(ue_contexts[i].mac_entity);
            free(ue_contexts);
            return NULL;
        }

        int pdcp_instances_count = network_load * PDCP_SN_INCREMENT;
        ue_contexts[i].pdcp_instances = (PDCP_INSTANCE_T**)malloc(pdcp_instances_count * sizeof(PDCP_INSTANCE_T*));
        if (!ue_contexts[i].pdcp_instances) {
            perror("Failed to allocate memory for PDCP instances");
            // Free previously allocated memory
            free(ue_contexts[i].logical_channel_group);
            free(ue_contexts[i].mac_entity);
            free(ue_contexts);
            return NULL;
        }

        for (int j = 0; j < pdcp_instances_count; j++) {
            ue_contexts[i].pdcp_instances[j] = malloc(sizeof(PDCP_INSTANCE_T));
            if (!ue_contexts[i].pdcp_instances[j]) {
                perror("Failed to allocate memory for PDCP instance");
                // Free previously allocated memory
                for (int k = 0; k < j; k++) {
                    free(ue_contexts[i].pdcp_instances[k]);
                }
                free(ue_contexts[i].logical_channel_group);
                free(ue_contexts[i].mac_entity);
                free(ue_contexts);
                return NULL;
            }
        }
    }

    // Initialize configuration file caching
    FILE* config_file = fopen(config_file_path, "r");
    if (!config_file) {
        perror("Failed to open configuration file");
        // Free previously allocated memory
        for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
            free(ue_contexts[i].logical_channel_group);
            free(ue_contexts[i].mac_entity);
            for (int j = 0; j < network_load * PDCP_SN_INCREMENT; j++) {
                free(ue_contexts[i].pdcp_instances[j]);
            }
            free(ue_contexts[i].pdcp_instances);
        }
        free(ue_contexts);
        return NULL;
    }

    // Read configuration file and populate LTE contexts
    // ...

    fclose(config_file);

    // Return the initialized UE context array
    return ue_contexts;
}

int decryptData(const unsigned char* ciphertext, size_t ciphertext_len, const unsigned char* key, const unsigned char* iv, unsigned char* decrypted_data) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    int len;
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Decryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, decrypted_data, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption update failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int total_decrypted = len;

    if (1 != EVP_DecryptFinal_ex(ctx, decrypted_data + len, &len)) {
        fprintf(stderr, "Decryption final failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    total_decrypted += len;
    EVP_CIPHER_CTX_free(ctx);

    // Null-terminate the decrypted data
    decrypted_data[total_decrypted] = '\0';

    return total_decrypted;
}

