    if (!log) return NULL;

    log->records = calloc(initial_capacity, sizeof(TransactionRecord*));
    if (!log->records) {
        free(log);
        return NULL;
    }

    log->capacity = initial_capacity;
    log->count = 0;
    pthread_mutex_init(&log->mutex, NULL);

    return log;
}

void destroyTransactionLog(TransactionLog* log) {
    for (size_t i = 0; i < log->count; ++i) {
        free(log->records[i]->json_payload);
        free(log->records[i]->binary_blob);
        free(log->records[i]);
    }

    pthread_mutex_destroy(&log->mutex);
    free(log->records);
    free(log);
}

