    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t lock;
    size_t max_structures;
    int debug_level;
} NFAPICRCStructArray;

NFAPICRCStructArray* createNFAPICRCStructArray(size_t max_structures, int debug_level) {
    if (max_structures > MAX_STRUCTURES || max_structures == 0) {
        return NULL; // Invalid or too large a value for max structures
    }

    NFAPICRCStructArray *array = (NFAPICRCStructArray*)malloc(sizeof(NFAPICRCStructArray));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    array->max_structures = max_structures;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->debug_level = debug_level;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL; // Memory allocation failed
    }

    return array;
}

void destroyNFAPICRCStructArray(NFAPICRCStructArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->array);
    array->array = NULL;
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int allocateNFAPICRCStruct(NFAPICRCStructArray *array) {
    if (array->count >= array->max_structures) {
        return -1; // Max structures reached
    }

    pthread_mutex_lock(&array->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_struct = &array->array[array->count];
    new_struct->RX_UE_INFORMATION_TAG = rand() % 1000;
    new_struct->RNTI = rand() % 65535;
    new_struct->CRC_INDICATION_REL8_TAG = rand() % 1000;
    new_struct->CRCFLAG = (rand() % 2) ? 1 : 0;

    array->count++;

    pthread_mutex_unlock(&array->lock);

    // Log allocation details
    if (array->debug_level >= 1) {
        time_t now = time(NULL);
        printf("Allocated struct at time: %s, Thread ID: %lu, Status: Success\n", ctime(&now), pthread_self());
    }

    return 0;
}

int deallocateNFAPICRCStruct(NFAPICRCStructArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->count == 0) {
        pthread_mutex_unlock(&array->lock);
        // Log deallocation details
        if (array->debug_level >= 1) {
            time_t now = time(NULL);
            printf("Deallocating struct at time: %s, Thread ID: %lu, Status: No more structs to deallocate\n", ctime(&now), pthread_self());
        }
        return -1; // No structs to deallocate
    }

    array->count--;

    pthread_mutex_unlock(&array->lock);

    // Log deallocation details
    if (array->debug_level >= 1) {
        time_t now = time(NULL);
        printf("Deallocated struct at time: %s, Thread ID: %lu, Status: Success\n", ctime(&now), pthread_self());
    }

    return 0;
}
