#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static atomic_int session_counter = ATOMIC_VAR_INIT(0);
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* initialize_and_populate_array(size_t size, size_t data_size) {
    if (data_size == 0 || size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        // Handle mismatch between expected and actual data sizes
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(size);
    if (array == NULL) {
        // Handle out-of-memory condition gracefully
        perror("Failed to allocate memory");
        return NULL;
    }

    for (size_t i = 0; i < size / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        atomic_fetch_add(&session_counter, 1);
        uint32_t session_id = time(NULL) ^ uuid_generate_random() ^ session_counter;

        pthread_mutex_lock(&mutex);
        array[i].RX_UE_INFORMATION_TAG = (uint16_t)(session_id & 0xFFFF);
        array[i].RNTI = (uint16_t)((session_id >> 16) & 0xFFFF);

        // Simulate CRC flag generation with pseudo-random generator
        array[i].CRCFLAG = (uint8_t)(rand_r(&session_id) % 2);
        pthread_mutex_unlock(&mutex);
    }

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t size) {
    if (array != NULL) {
        free(array);
    }
}
