#define MAX_CONNECTIONS 10000
#define SERVER_POOL_SIZE 5

typedef struct {
    int fd;
    struct sockaddr_in client_addr;
    enum { NEW, ESTABLISHED, CLOSED } state;
    time_t last_activity;
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
} ConnectionPool;

typedef struct {
    char address[256];
    int port;
} Server;

Server server_pool[SERVER_POOL_SIZE] = {
    {"192.168.1.1", 80},
    {"192.168.1.2", 80},
    {"192.168.1.3", 80},
    {"192.168.1.4", 80},
    {"192.168.1.5", 80}
};

ConnectionPool connection_pool;

void initialize_connection_pool() {
    pthread_mutex_init(&connection_pool.lock, NULL);
    memset(connection_pool.connections, 0, sizeof(Connection) * MAX_CONNECTIONS);
    connection_pool.count = 0;
}

int get_available_server() {
    // Implement logic to find the least loaded server
    return rand() % SERVER_POOL_SIZE; // Placeholder for actual implementation
}

void* handle_connection(void* arg) {
    int fd = *(int*)arg;
    free(arg);

    Connection new_conn = {fd, {0}, ESTABLISHED, time(NULL)};
    pthread_mutex_lock(&connection_pool.lock);
    if (connection_pool.count < MAX_CONNECTIONS) {
        connection_pool.connections[connection_pool.count++] = new_conn;
    } else {
        printf("Connection pool is full\n");
        close(fd);
    }
    pthread_mutex_unlock(&connection_pool.lock);

    // Handle client requests
    while (1) {
        // Process client requests
        usleep(100000); // Simulate work
    }

    return NULL;
}

void start_server() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Failed to create socket");
        return;
    }

    struct sockaddr_in address = {0};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("Failed to bind");
        close(server_fd);
        return;
    }

    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Listen failed");
        close(server_fd);
        return;
    }

    printf("Server listening on port 8080\n");

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        pthread_t thread_id;
        int* fd_ptr = malloc(sizeof(int));
        *fd_ptr = client_fd;

        if (pthread_create(&thread_id, NULL, handle_connection, (void*)fd_ptr) != 0) {
            perror("Failed to create thread");
            free(fd_ptr);
        }
    }

    close(server_fd);
}

int main() {
    initialize_connection_pool();
    start_server();
    return 0;
}
