    private static final String RNTI_POOL_SIZE = "rnti_pool_size";
    private static final String MAX_WAIT_TIME = "max_wait_time";

    public static void processTask(int supervisorId, List<String> filePaths) {
        Properties dbProps = loadDbProperties();
        int rntiPoolSize = Integer.parseInt(dbProps.getProperty(RNTI_POOL_SIZE));
        long maxWaitTime = Long.parseLong(dbProps.getProperty(MAX_WAIT_TIME));

        ExecutorService executor = Executors.newFixedThreadPool(100);
        BlockingQueue<String> rntiPool = new ArrayBlockingQueue<>(rntiPoolSize);
        for (int i = 0; i < rntiPoolSize; i++) {
            rntiPool.offer("RNTI" + i);
        }

        try {
            List<Future<?>> futures = filePaths.stream()
                    .map(filePath -> executor.submit(() -> processFile(filePath, supervisorId, rntiPool)))
                    .collect(Collectors.toList());

            for (Future<?> future : futures) {
                future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
        } finally {
            executor.shutdownNow();
        }
    }

    private static Properties loadDbProperties() {
        Properties props = new Properties();
        try (InputStream input = Files.newInputStream(Paths.get(DB_CONFIG_FILE))) {
            props.load(input);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load database properties", e);
        }
        return props;
