#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

// Define data structures
typedef struct {
    int key;
    long offset;
    double value;
    char* stringPtr;
} Record;

typedef struct {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

// Function prototypes
void initRecordCollection(RecordCollection* collection, size_t initialCapacity);
void addRecord(RecordCollection* collection, Record record);
void freeRecordCollection(RecordCollection* collection);
void serializeRecords(RecordCollection* collection, char** buffer, size_t* bufferSize);
void deserializeRecords(char* buffer, size_t bufferSize, RecordCollection* collection);

// Implementations
void initRecordCollection(RecordCollection* collection, size_t initialCapacity) {
    collection->records = (Record**)malloc(initialCapacity * sizeof(Record*));
    memset(collection->records, 0, initialCapacity * sizeof(Record*));
    collection->count = 0;
    collection->capacity = initialCapacity;
    pthread_mutex_init(&collection->lock, NULL);
}

void addRecord(RecordCollection* collection, Record record) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        collection->records = realloc(collection->records, newCapacity * sizeof(Record*));
        memset(collection->records + collection->capacity, 0, newCapacity - collection->capacity);
        collection->capacity = newCapacity;
    }
    Record* newRecord = (Record*)malloc(sizeof(Record));
    memcpy(newRecord, &record, sizeof(Record));
    newRecord->stringPtr = strdup(record.stringPtr); // Deep copy string
    collection->records[collection->count++] = newRecord;
    pthread_mutex_unlock(&collection->lock);
}

void freeRecordCollection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->stringPtr); // Free deep copied string
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
}

void serializeRecords(RecordCollection* collection, char** buffer, size_t* bufferSize) {
    *bufferSize = collection->count * sizeof(Record);
    *buffer = (char*)malloc(*bufferSize);
    memcpy(*buffer, collection->records, *bufferSize);
}

void deserializeRecords(char* buffer, size_t bufferSize, RecordCollection* collection) {
    size_t count = bufferSize / sizeof(Record);
    for (size_t i = 0; i < count; ++i) {
        Record record;
        memcpy(&record, buffer + i * sizeof(Record), sizeof(Record));
        record.stringPtr = strdup(record.stringPtr); // Deep copy string
        addRecord(collection, record);
    }
}

// Example usage
int main() {
    RecordCollection collection;
    initRecordCollection(&collection, 1024);

    Record record;
    record.key = 1;
    record.offset = 100;
    record.value = 3.14;
    record.stringPtr = strdup("Test");
    addRecord(&collection, record);

    char* buffer;
    size_t bufferSize;
    serializeRecords(&collection, &buffer, &bufferSize);

    RecordCollection deserializedCollection;
    initRecordCollection(&deserializedCollection, 0);
    deserializeRecords(buffer, bufferSize, &deserializedCollection);

    free(buffer);
    freeRecordCollection(&collection);
    freeRecordCollection(&deserializedCollection);

    return 0;
}
```

This code provides a basic structure for managing records in a thread-safe manner, including initialization, adding records, serialization, and deserialization. It demonstrates memory management and synchronization using mutexes to ensure data integrity under concurrent access. The example usage shows how to create a record collection, add a record, serialize the collection, and deserialize it back into a new collection.']

