    RX_UE_INFORMATION_TAG *rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG *crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** allocate_structs(int n, int *error) {
    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T**) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        *error = 1;
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            *error = 2;
            return NULL;
        }
        array[i]->rx_tag = (RX_UE_INFORMATION_TAG*) malloc(sizeof(RX_UE_INFORMATION_TAG));
        array[i]->crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG*) malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!array[i]->rx_tag || !array[i]->crc_indication_rel8_tag) {
            *error = 3;
            return NULL;
        }
    }
    return array;
}

