#define COMPRESS_THRESHOLD 85

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
} Event;

typedef struct HashNode {
    Event event;
    struct HashNode* next;
} HashNode;

typedef struct EventQueue {
    HashNode** buckets;
    size_t bucket_count;
    size_t current_size;
    pthread_mutex_t mutex;
} EventQueue;

EventQueue* create_event_queue(size_t initial_bucket_count) {
    EventQueue* queue = malloc(sizeof(EventQueue));
    if (queue == NULL) {
        return NULL;
    }
    queue->buckets = malloc(initial_bucket_count * sizeof(HashNode*));
    if (queue->buckets == NULL) {
        free(queue);
        return NULL;
    }
    memset(queue->buckets, 0, initial_bucket_count * sizeof(HashNode*));
    queue->bucket_count = initial_bucket_count;
    queue->current_size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void destroy_event_queue(EventQueue* queue) {
    for (size_t i = 0; i < queue->bucket_count; i++) {
        HashNode* node = queue->buckets[i];
        while (node != NULL) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(queue->buckets);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

size_t hash_function(int id, size_t bucket_count) {
    return abs(id) % bucket_count;
}

void add_event(EventQueue* queue, Event event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->current_size >= MAX_EVENTS) {
        // Evict the oldest events to make space
        size_t bucket = hash_function(queue->buckets[0]->event.id, queue->bucket_count);
        HashNode* node = queue->buckets[bucket];
        Event evicted_event = node->event;
        remove_event(queue, evicted_event.id);
    }
    size_t bucket = hash_function(event.id, queue->bucket_count);
    HashNode* new_node = malloc(sizeof(HashNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return;
    }
    new_node->event = event;
    new_node->next = queue->buckets[bucket];
    queue->buckets[bucket] = new_node;
    queue->current_size++;
    pthread_mutex_unlock(&queue->mutex);
}

void remove_event(EventQueue* queue, int id) {
    pthread_mutex_lock(&queue->mutex);
    size_t bucket = hash_function(id, queue->bucket_count);
    HashNode* current = queue->buckets[bucket];
    HashNode* previous = NULL;
    while (current != NULL) {
        if (current->event.id == id) {
            if (previous == NULL) {
                queue->buckets[bucket] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            queue->current_size--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&queue->mutex);
}

int get_highest_priority(EventQueue* queue) {
    int highest_priority = -1;
    pthread_mutex_lock(&queue->mutex);
    for (size_t i = 0; i < queue->bucket_count; i++) {
        HashNode* current = queue->buckets[i];
        while (current != NULL) {
            if (current->event.priority > highest_priority) {
                highest_priority = current->event.priority;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&queue->mutex);
    return highest_priority;
}

