#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 30000
#define WINDOW_SIZE 60 * 60 // 60 minutes in seconds
#define HIGH_PRIORITY_LIMIT 500

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    char payload[1024];
    struct Event* next;
} Event;

typedef struct HashTable {
    Event** buckets;
    size_t size;
} HashTable;

typedef struct {
    HashTable table;
    pthread_mutex_t lock;
    time_t last_cleanup_time;
} EventManager;

EventManager event_manager;

void init_event_manager() {
    event_manager.table.size = 1000; // Initial bucket size
    event_manager.table.buckets = (Event**)malloc(event_manager.table.size * sizeof(Event*));
    memset(event_manager.table.buckets, 0, event_manager.table.size * sizeof(Event*));
    pthread_mutex_init(&event_manager.lock, NULL);
    event_manager.last_cleanup_time = time(NULL) - WINDOW_SIZE;
}

unsigned int hash_function(int id) {
    return abs(id) % event_manager.table.size;
}

void insert_event(EventManager* manager, Event* event) {
    pthread_mutex_lock(&manager->lock);
    size_t index = hash_function(event->id);
    if (manager->table.buckets[index] == NULL) {
        manager->table.buckets[index] = event;
    } else {
        Event* current = manager->table.buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = event;
    }
    pthread_mutex_unlock(&manager->lock);
}

Event* find_event(EventManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    Event* event = manager->table.buckets[hash_function(id)];
    while (event != NULL) {
        if (event->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return event;
        }
        event = event->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void evict_old_events() {
    time_t current_time = time(NULL);
    if (current_time - event_manager.last_cleanup_time >= WINDOW_SIZE) {
        pthread_mutex_lock(&event_manager.lock);
        for (size_t i = 0; i < event_manager.table.size; i++) {
            Event* current = event_manager.table.buckets[i];
            while (current != NULL) {
                if (difftime(current->timestamp, current_time) > WINDOW_SIZE) {
                    Event* next = current->next;
                    free(current);
                    current = next;
                } else {
                    break;
                }
            }
            event_manager.table.buckets[i] = current;
        }
        pthread_mutex_unlock(&event_manager.lock);
        event_manager.last_cleanup_time = current_time;
    }
}

void cleanup_event_manager() {
    for (size_t i = 0; i < event_manager.table.size; i++) {
        Event* current = event_manager.table.buckets[i];
        while (current != NULL) {
            Event* next = current->next;
            free(current);
            current = next;
        }
    }
    free(event_manager.table.buckets);
    pthread_mutex_destroy(&event_manager.lock);
}

int main() {
    init_event_manager();

    // Example usage
    for (int i = 0; i < MAX_EVENTS; i++) {
        Event* event = (Event*)malloc(sizeof(Event));
        event->id = i;
        event->timestamp = time(NULL);
        event->priority = rand() % 1000;
        snprintf(event->payload, sizeof(event->payload), "Payload %d", i);
        insert_event(&event_manager, event);
    }

    evict_old_events();
    cleanup_event_manager();

    return 0;
}
