#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 20000
#define SLIDING_WINDOW_MINUTES 30
#define MAX_HIGH_PRIORITY_EVENTS 300
#define PAYLOAD_LIMIT 1024
#define COMPRESS_THRESHOLD 0.85

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    char payload[PAYLOAD_LIMIT];
} Event;

typedef struct Node {
    Event event;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    int size;
} HashTable;

typedef struct {
    HashTable table;
    pthread_mutex_t mutex;
} EventManager;

EventManager* create_event_manager(int bucket_size) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    manager->table.buckets = (Node**)calloc(bucket_size, sizeof(Node*));
    manager->table.size = bucket_size;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void free_event_manager(EventManager* manager) {
    for (int i = 0; i < manager->table.size; i++) {
        Node* current = manager->table.buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(manager->table.buckets);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int hash_function(Event event, int size) {
    return abs(event.id % size);
}

void insert_event(EventManager* manager, Event event) {
    pthread_mutex_lock(&manager->mutex);
    int index = hash_function(event, manager->table.size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = manager->table.buckets[index];
    manager->table.buckets[index] = new_node;
    pthread_mutex_unlock(&manager->mutex);
}

void evict_old_events(EventManager* manager, time_t current_time) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->table.size; i++) {
        Node* current = manager->table.buckets[i];
        while (current != NULL && difftime(current->event.timestamp, current_time) > SLIDING_WINDOW_MINUTES * 60) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
        if (current == manager->table.buckets[i]) {
            break;
        }
        manager->table.buckets[i] = current;
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Additional functions for managing events, handling concurrency,
// integrating with external data sources, and optimizing performance
