#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_EVENTS 30 * 60 * 1000 // 30 minutes in milliseconds
#define MAX_HIGH_PRIORITY_EVENTS 300

typedef struct Event {
    uint32_t id;
    int64_t timestamp;
    int priority;
    struct Event* next;
} Event;

typedef struct Packet {
    char src_ip[16];
    char dst_ip[16];
    uint16_t src_port;
    uint16_t dst_port;
    char payload[1024];
    size_t payload_size;
} Packet;

Event* event_queue[MAX_EVENTS] = {NULL};
uint32_t event_count = 0;
int highest_priority_event_id = 0;

Packet** packet_pool = NULL;
size_t packet_pool_size = 0;
size_t total_payload_size = 0;
#define PAYLOAD_LIMIT (10 * 1024 * 1024) // 10 MB

void init_packet_pool(size_t pool_size) {
    packet_pool_size = pool_size;
    packet_pool = malloc(pool_size * sizeof(Packet*));
    for (size_t i = 0; i < pool_size; ++i) {
        packet_pool[i] = malloc(sizeof(Packet));
    }
}

Packet* get_packet() {
    if (!packet_pool || total_payload_size + PAYLOAD_LIMIT > PAYLOAD_LIMIT) {
        return NULL;
    }
    Packet* packet = packet_pool[total_payload_size % packet_pool_size];
    total_payload_size += packet->payload_size;
    return packet;
}

void free_packet(Packet* packet) {
    if (packet) {
        total_payload_size -= packet->payload_size;
        // Optionally reset packet fields to zero or NULL
    }
}

void add_event(uint32_t id, int64_t timestamp, int priority) {
    if (event_count >= MAX_EVENTS) {
        Event* old_event = event_queue[event_count % MAX_EVENTS];
        free(old_event);
    }
    Event* new_event = malloc(sizeof(Event));
    new_event->id = id;
    new_event->timestamp = timestamp;
    new_event->priority = priority;
    new_event->next = NULL;

    if (highest_priority_event_id > id) {
        highest_priority_event_id = id;
    }

    for (int i = 0; i < event_count; ++i) {
        Event* current = event_queue[i];
        if (current == NULL || current->timestamp < timestamp) {
            memmove(event_queue + i + 1, event_queue + i, (event_count - i) * sizeof(Event*));
            event_queue[i] = new_event;
            break;
        }
    }

    if (event_count < MAX_EVENTS) {
        ++event_count;
    }
}

void remove_old_events() {
    int64_t current_time = time(NULL);
    for (int i = 0; i < event_count; ++i) {
        Event* current = event_queue[i];
        if (current->timestamp + (30 * 60) <= current_time) {
            free(current);
            memmove(event_queue + i, event_queue + i + 1, --event_count * sizeof(Event*));
        } else {
            break;
        }
    }
}

void process_events() {
    for (int i = 0; i < event_count; ++i) {
        Event* current = event_queue[i];
        if (current->priority <= highest_priority_event_id && event_count > MAX_HIGH_PRIORITY_EVENTS) {
            continue;
        }

        Packet* packet = get_packet();
        if (!packet) {
            break;
        }

        // Populate packet with random data ensuring total payload size does not exceed limit
        snprintf(packet->src_ip, sizeof(packet->src_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        snprintf(packet->dst_ip, sizeof(packet->dst_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        packet->src_port = (rand() % 65535) + 1;
        packet->dst_port = (rand() % 65535) + 1;
        size_t payload_size = (rand() % 1024) + 1; // Random payload size up to 1 KB
        if (payload_size > sizeof(packet->payload)) {
            payload_size = sizeof(packet->payload);
        }
        for (size_t j = 0; j < payload_size; ++j) {
            packet->payload[j] = rand() % 256;
        }
        packet->payload_size = payload_size;

        // Simulate UDP packet sending
        int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
        server_addr.sin_port = htons(9876);

        sendto(sockfd, packet->payload, packet->payload_size, 0, (struct sockaddr*)&server_addr, sizeof(server_addr));
        close(sockfd);

        free_packet(packet);
    }
}

void save_packets_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    // Write packet data in a binary format
    fwrite(&total_payload_size, sizeof(total_payload_size), 1, file);
    for (size_t i = 0; i < total_payload_size / sizeof(Packet); ++i) {
        Packet* packet = &packet_pool[i];
        fwrite(packet->src_ip, sizeof(packet->src_ip), 1, file);
