typedef struct {
    int RadioResourceManagerId;
    int UEId;
    int SignalStrength;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} UEArray;

UEArray* init_UEArray(size_t initial_capacity) {
    UEArray *array = (UEArray *)malloc(sizeof(UEArray));
    array->contexts = (UEContext *)calloc(initial_capacity, sizeof(UEContext));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void update_signal_strength(UEArray *array, int UEId, int new_strength) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].UEId == UEId) {
            array->contexts[i].SignalStrength = new_strength;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void resize_UEArray(UEArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->mutex);
    UEContext *new_contexts = (UEContext *)realloc(array->contexts, new_capacity * sizeof(UEContext));
    if (new_contexts != NULL) {
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->mutex);
}

void free_UEArray(UEArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->contexts);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
