typedef struct {
    int radioResourceManagerId;
    int ueId;
    float signalStrength;
} UEContext;

typedef struct {
    UEContext* contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* array, size_t initialCapacity) {
    array->contexts = (UEContext*)malloc(initialCapacity * sizeof(UEContext));
    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void freeDynamicArray(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->contexts);
    array->contexts = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

int addUEContext(DynamicArray* array, int radioResourceManagerId, int ueId, float signalStrength) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity ? array->capacity * 2 : 1;
        UEContext* newContexts = (UEContext*)realloc(array->contexts, newCapacity * sizeof(UEContext));
        if (!newContexts) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->contexts = newContexts;
        array->capacity = newCapacity;
    }
    array->contexts[array->size].radioResourceManagerId = radioResourceManagerId;
    array->contexts[array->size].ueId = ueId;
    array->contexts[array->size].signalStrength = signalStrength;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

int updateSignalStrength(DynamicArray* array, int ueId, float newSignalStrength) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (array->contexts[i].ueId == ueId) {
            array->contexts[i].signalStrength = newSignalStrength;
            pthread_mutex_unlock(&array->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // UEContext not found
}
