class GameContext {
public:
    std::vector<int> recentAttacks;
    std::mutex contextMutex;
};

struct AttackRecord {
    int strategyIndex;
    std::time_t timestamp;
    std::thread::id threadId;
};

using StrategySelector = int (*)(GameContext*);

int selectAndRecordCombatStrategy(GameContext* gameContext, StrategySelector selector) {
    static const int maxRecentAttacks = 9;
    static const size_t stackThreshold = 1024; // Example threshold
    static std::atomic<AttackRecord*> recentRecords{nullptr};
    static std::mutex recordMutex;

    if (recentRecords == nullptr) {
        recentRecords.store(new AttackRecord[maxRecentAttacks]);
    }

    int strategyIndex = selector(gameContext);
    AttackRecord currentRecord = {strategyIndex, std::time(nullptr), std::this_thread::get_id()};

    std::lock_guard<std::mutex> lock(recordMutex);

    for (int i = 0; i < maxRecentAttacks; ++i) {
        if (recentRecords.load()->timestamp + 9 <= currentRecord.timestamp) {
            recentRecords.load()[i] = currentRecord;
            break;
        }
    }

    std::cout << "Selected strategy: " << strategyIndex << ", Timestamp: " << currentRecord.timestamp
              << ", Thread ID: " << currentRecord.threadId << std::endl;

    return strategyIndex;
}
