['```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <unordered_set>
#include <chrono>

struct GameContext {
    std::vector<std::string> recentAttacks;
};

using StrategySelector = int(*)(const GameContext&);

class CombatStrategyManager {
public:
    CombatStrategyManager(size_t maxRecentAttacks, size_t stackThreshold)
        : maxRecentAttacks(maxRecentAttacks), stackThreshold(stackThreshold) {}

    int selectAndRecordCombatStrategy(GameContext& context, StrategySelector selector) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return canSelectNewStrategy(); });

        int strategy = selector(context);

        recordStrategy(strategy, context);
        updateRecentAttacks(context);

        return strategy;
    }

private:
    bool canSelectNewStrategy() {
        auto now = std::chrono::steady_clock::now();
        while (!recentStrategies.empty()) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - recentStrategies.begin()->first).count() >= 9) {
                recentStrategies.erase(recentStrategies.begin());
            } else {
                break;
            }
        }

        return recentStrategies.size() < stackThreshold;
    }

    void recordStrategy(int strategy, GameContext& context) {
        std::lock_guard<std::mutex> lock(logMutex);
        auto now = std::chrono::steady_clock::now();
        logFile << "Thread: " << std::this_thread::get_id()
                 << ", Time: " << std::chrono::system_clock::to_time_t(now)
                 << ", Strategy: " << strategy
                 << std::endl;
    }

    void updateRecentAttacks(GameContext& context) {
        if (context.recentAttacks.size() >= maxRecentAttacks) {
            context.recentAttacks.erase(context.recentAttacks.begin());
        }
        context.recentAttacks.push_back("Attack " + std::to_string(recentStrategies.size()));
    }

    size_t maxRecentAttacks;
    size_t stackThreshold;
    std::mutex mutex;
    std::condition_variable condition;
    std::unordered_set<std::pair<std::chrono::steady_clock::time_point, int>, RecentStrategyHash> recentStrategies;
    std::ofstream logFile("strategy_log.txt");
    std::mutex logMutex;
};

struct RecentStrategyHash {
    size_t operator()(const std::pair<std::chrono::steady_clock::time_point, int>& strategy) const {
        return std::hash<std::chrono::steady_clock::time_point>()(strategy.first) ^ std::hash<int>()(strategy.second);
    }
};
