#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 30000
#define SLIDING_WINDOW_SECONDS 45
#define HIGH_PRIORITY_LIMIT 500

typedef struct {
    int id;
    time_t timestamp;
    int priority;
} Event;

typedef struct {
    Event *events;
    int count;
    pthread_mutex_t lock;
} EventQueue;

EventQueue event_queue = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void enqueue_event(int id, time_t timestamp, int priority) {
    pthread_mutex_lock(&event_queue.lock);
    if (event_queue.count >= MAX_EVENTS) {
        // Evict oldest event
        free(event_queue.events[0]);
        memmove(event_queue.events, event_queue.events + 1, sizeof(Event*) * (event_queue.count - 1));
        event_queue.count--;
    }
    Event *new_event = malloc(sizeof(Event));
    new_event->id = id;
    new_event->timestamp = timestamp;
    new_event->priority = priority;
    event_queue.events = realloc(event_queue.events, sizeof(Event*) * (event_queue.count + 1));
    event_queue.events[event_queue.count++] = new_event;
    pthread_mutex_unlock(&event_queue.lock);
}

void process_events() {
    pthread_mutex_lock(&event_queue.lock);
    for (int i = 0; i < event_queue.count; i++) {
        if (time(NULL) - event_queue.events[i]->timestamp > SLIDING_WINDOW_SECONDS) {
            free(event_queue.events[i]);
            memmove(event_queue.events + i, event_queue.events + i + 1, sizeof(Event*) * (--event_queue.count - i));
            i--;
        }
    }
    pthread_mutex_unlock(&event_queue.lock);
}

int main() {
    // Initialize and populate event queue
    // ...

    // Process events
    process_events();

    return 0;
}
```

