#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct NetworkNode {
    int NodeId;
    double BandwidthUtilization;
    double Latency;
} NetworkNode;

typedef struct DynamicList {
    NetworkNode *nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* init_dynamic_list() {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for dynamic list");
        return NULL;
    }
    list->nodes = malloc(INITIAL_CAPACITY * sizeof(NetworkNode));
    if (!list->nodes) {
        perror("Failed to allocate memory for nodes");
        free(list);
        return NULL;
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->nodes);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_node(DynamicList *list, int NodeId, double BandwidthUtilization, double Latency) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkNode *new_nodes = realloc(list->nodes, new_capacity * sizeof(NetworkNode));
        if (!new_nodes) {
            perror("Failed to reallocate memory for nodes");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->nodes = new_nodes;
        list->capacity = new_capacity;
    }
    list->nodes[list->size].NodeId = NodeId;
    list->nodes[list->size].BandwidthUtilization = BandwidthUtilization;
    list->nodes[list->size].Latency = Latency;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_node(DynamicList *list, int NodeId, double new_BandwidthUtilization, double new_Latency) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->nodes[i].NodeId == NodeId) {
            list->nodes[i].BandwidthUtilization = new_BandwidthUtilization;
            list->nodes[i].Latency = new_Latency;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    fprintf(stderr, "Node with ID %d not found\n", NodeId);
    return -1;
}
```

This code snippet provides a basic implementation of a dynamic list for managing `NetworkNode` structures. It includes functions for initializing, destroying, adding nodes, and updating node metrics while ensuring thread safety using mutexes. The initial capacity is set to 10, and the list doubles in size when it reaches its capacity. Error handling is included for memory allocation failures, and each operation locks and unlocks the mutex to protect shared data.']

