#include <openssl/sha.h>
#include <pqxx/pqxx>

struct NFAPI_FRAME_BUFFER_T {
    std::vector<uint8_t> data;
    uint64_t timestamp;
    std::string metadata;
};

class FrameProcessor {
public:
    FrameProcessor(const std::string& inputDir, const std::string& outputDir)
        : inputDir(inputDir), outputDir(outputDir), numFramesProcessed(0) {}

    void startProcessing() {
        for (int i = 0; i < MAX_THREADS; ++i) {
            threads.emplace_back(&FrameProcessor::processFrames, this);
        }
        for (auto& thread : threads) {
            thread.join();
        }
        std::cout << "Total frames processed: " << numFramesProcessed << std::endl;
    }

private:
    void processFrames() {
        while (true) {
            NFAPI_FRAME_BUFFER_T frame;
            {
                std::unique_lock<std::mutex> lock(mutex);
                if (framesToProcess.empty()) {
                    if (!shutdown) return;
                    continue;
                }
                frame = framesToProcess.front();
                framesToProcess.pop();
            }

            // Simulate frame processing
            processFrame(frame);

            {
                std::lock_guard<std::mutex> lock(mutex);
                ++numFramesProcessed;
            }
        }
    }

    void processFrame(const NFAPI_FRAME_BUFFER_T& frame) {
        // Simulate frame processing
        uint64_t start = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        // Process the frame data, timestamp, and metadata here
        uint64_t end = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        double elapsed = (end - start) / 1000.0; // Convert to milliseconds

        if (verboseLogging) {
            std::cout << "Frame processed in " << elapsed << " ms" << std::endl;
        }

        // Simulate checksum calculation
        uint32_t checksum = calculateChecksum(frame.data);

        // Write the processed frame to the output directory
        writeFrameToFile(frame, checksum);
    }

    uint32_t calculateChecksum(const std::vector<uint8_t>& data) {
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, data.data(), data.size());
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Final(hash, &sha256);

        uint32_t checksum = 0;
        for (int i = 0; i < sizeof(checksum); ++i) {
            checksum += static_cast<uint32_t>(hash[i]) << (i * 8);
        }

        return checksum;
    }

    void writeFrameToFile(const NFAPI_FRAME_BUFFER_T& frame, uint32_t checksum) {
        std::string outputPath = outputDir + "/frame_" + std::to_string(frame.timestamp) + ".bin";
        std::ofstream outFile(outputPath, std::ios::binary);
        if (outFile.is_open()) {
            outFile.write(reinterpret_cast<const char*>(frame.data.data()), frame.data.size());
            outFile.close();
            // Write checksum to a separate file or database
        } else {
            std::cerr << "Error opening output file: " << outputPath << std::endl;
        }
    }

    std::string inputDir;
    std::string outputDir;
    std::queue<NFAPI_FRAME_BUFFER_T> framesToProcess;
    std::vector<std::thread> threads;
    std::mutex mutex;
    std::condition_variable conditionVariable;
    bool shutdown = false;
    int numFramesProcessed;
    bool verboseLogging = false;

    static const int MAX_THREADS = 200;
};

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    std::string inputDir;
    std::string outputDir;
    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "-i") {
            inputDir = argv[++i];
        } else if (std::string(argv[i]) == "-o") {
            outputDir = argv[++i];
        } else if (std::string(argv[i]) == "-t") {
            verboseLogging = true;
        } else if (std::string(argv[i]) == "-h") {
            std::cout << "Usage: program -i input_directory -o output_directory [-t] [-h]" << std::endl;
            return 0;
        }
    }

    // Validate arguments
    if (inputDir.empty() || outputDir.empty()) {
        std::cerr << "Input and output directories must be specified." << std::endl;
        return 1;
    }

    // Create frame processor and start processing
    FrameProcessor processor(inputDir, outputDir);
    processor.startProcessing();

    return 0;
}
```

