// Function to encrypt plaintext data using AES-256-CBC
int encryptData(const unsigned char* plaintext, int plaintextLen, const unsigned char* encryptionKey, const unsigned char* iv, unsigned char* ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, encryptionKey, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintextLen) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertextLen = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ciphertextLen += len;
    EVP_CIPHER_CTX_free(ctx);

    return ciphertextLen;
}
