void initialize_ue_context(int logical_channel_group) {
    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i].logical_channel_group == -1) { // Assuming -1 means unallocated
            ue_contexts[i].logical_channel_group = logical_channel_group;
            pthread_mutex_unlock(&ue_context_lock);
            return;
        }
    }
    printf("Error: No available UE context\n");
    pthread_mutex_unlock(&ue_context_lock);
}

PDCP_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&ue_context_lock);
    if (pdcp_sn_index >= sizeof(pdcp_sn_pool) / sizeof(pdcp_sn_pool[0])) {
        printf("Error: PDCP SN pool exhausted\n");
        pthread_mutex_unlock(&ue_context_lock);
        return NULL;
    }
    PDCP_PDU_T* pdu = &pdcp_sn_pool[pdcp_sn_index++];
    pdu->pdcp_sn = pdcp_sn_index - 1; // Incremental value
    pthread_mutex_unlock(&ue_context_lock);
    return pdu;
}

