    pthread_mutex_lock(&ue_context_lock);
    for (int i = 0; i < pdcp_sn_index; i++) {
        if (pdcp_sn_pool[i].pdcp_sn == 0) { // Assuming 0 is unused
            pdcp_sn_index--;
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_lock);
