    if (!list) return NULL;

    list->nodes = (NetworkNode*)calloc(initial_capacity, sizeof(NetworkNode));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Initialize memory pool allocator and other necessary members

    return list;
}

void destroy_network_node_list(NetworkNodeList *list) {
    if (!list) return;

    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    free(list);

    // Destroy memory pool allocator and other necessary members
}

int add_network_node(NetworkNodeList *list, NetworkNode node) {
    if (!list || !node.NodeId || node.BandwidthUtilization < 0 || node.Latency < 0) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Resize the list
        NetworkNode *new_nodes = (NetworkNode*)realloc(list->nodes, list->capacity * 2 * sizeof(NetworkNode));
        if (!new_nodes) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->nodes = new_nodes;
        list->capacity *= 2;
    }

    list->nodes[list->size++] = node;

    pthread_mutex_unlock(&list->lock);

    // Update memory pool allocator and handle external dependencies

    return 0;
}

