    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->nodes[i].NodeId == NodeId) {
            list->nodes[i].BandwidthUtilization = new_utilization;
            list->nodes[i].Latency = new_latency;

            pthread_mutex_unlock(&list->lock);

            // Update memory pool allocator and handle external dependencies

            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Node not found
}

