typedef struct Metrics {
    double maxWeightedSum;
    int maxTransactionID;
} Metrics;

void processTransactions(Transaction *transactions, int numTransactions, Metrics *metrics) {
    // Initialize metrics
    if (numTransactions > 0) {
        metrics->maxWeightedSum = transactions[0].amount;
        metrics->maxTransactionID = transactions[0].id;
    }

    for (int i = 1; i < numTransactions; i++) {
        if (transactions[i].amount > metrics->maxWeightedSum) {
            metrics->maxWeightedSum = transactions[i].amount;
            metrics->maxTransactionID = transactions[i].id;
        }
    }
}

void filterTransactions(Transaction *transactions, int *numFiltered, Metrics *metrics) {
    // Filter transactions based on age and weighted sum
    // Example: Only consider transactions from the last 5 milliseconds
    clock_t currentTime = clock();
    *numFiltered = 0;

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transactions[i].timestamp > currentTime - 5) {
            (*numFiltered)++;
        }
    }

    processTransactions(transactions, *numFiltered, metrics);
}

void updateMetrics(Metrics *metrics) {
    // Update global metrics based on filtered transactions
    // Example: Log the max weighted sum and transaction ID to third-party analytics service
    printf("Max Weighted Sum: %f, Max Transaction ID: %d\n", metrics->maxWeightedSum, metrics->maxTransactionID);
}

int main() {
    Transaction transactions[MAX_TRANSACTIONS];
    Metrics metrics;
    int numFiltered;

    // Example transaction data
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i].id = i + 1;
        transactions[i].amount = rand() % 1000.0;
        transactions[i].timestamp = clock();
    }

    filterTransactions(transactions, &numFiltered, &metrics);
    updateMetrics(&metrics);

    return 0;
}
