    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TransactionQueue;

typedef struct {
    int maxWeightedSum;
    int maxID;
} FilterResult;

FilterResult filterTransactions(TransactionQueue* queue, float minAge, int max3SecCount, float minWeightedSum) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    FilterResult result = {0};
    for (int i = 0; i < queue->count; i++) {
        if ((time(NULL) - queue->transactions[i].timestamp) > minAge && 
            queue->transactions[i].weightedSum >= minWeightedSum) {
