        snprintf(queue.transactions[queue.count].deviceType, sizeof(queue.transactions[queue.count].deviceType), "Device%d", i % 5);
        snprintf(queue.transactions[queue.count].location, sizeof(queue.transactions[queue.count].location), "Location%d", i % 3);
        queue.count++;

        pthread_cond_signal(&queue.cond);
    }

    pthread_join(processorThread, NULL);

    pthread_mutex_destroy(&queue.lock);
    pthread_cond_destroy(&queue.cond);

