    size_t size;
    size_t capacity;
    int next_id;
} MessageQueue;

MessageQueue* create_message_queue() {
    MessageQueue *queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    if (!queue) return NULL;
    queue->messages = (MessagePacket*)calloc(1024, sizeof(MessagePacket));
    if (!queue->messages) {
        free(queue);
        return NULL;
    }
    queue->size = 0;
    queue->capacity = 1024;
    queue->next_id = 0;
    return queue;
}

void enqueue_message(MessageQueue *queue, MessagePacket message) {
    if (queue->size == queue->capacity) {
        // Resize the array
        queue->messages = (MessagePacket*)realloc(queue->messages, queue->capacity * 2 * sizeof(MessagePacket));
        if (!queue->messages) return;
        queue->capacity *= 2;
    }
    queue->messages[queue->size++] = message;
}

void dequeue_message(MessageQueue *queue) {
    if (queue->size == 0) return;
    memmove(queue->messages, &queue->messages[1], (queue->size - 1) * sizeof(MessagePacket));
    queue->size--;
}

MessagePacket* get_next_message(MessageQueue *queue) {
    if (queue->size == 0) return NULL;
    return &queue->messages[0];
}

void clean_up_expired_messages(MessageQueue *queue, time_t current_time) {
    while (queue->size > 0 && difftime(current_time, queue->messages[queue->size - 1].timestamp) > SLIDING_WINDOW_SIZE) {
        dequeue_message(queue);
    }
}

int main() {
    MessageQueue *queue = create_message_queue();
    if (!queue) {
        fprintf(stderr, "Failed to create message queue\n");
        return 1;
    }

    // Simulate message processing
    time_t current_time = time(NULL);

    while (1) {
        clean_up_expired_messages(queue, current_time);
        MessagePacket new_message;
        // Populate new_message with data
        enqueue_message(queue, new_message);
        if (queue->size >= MAX_CONCURRENT_MESSAGES) {
            // Handle concurrency limit exceeded
        }
        current_time = time(NULL);
    }

    free(queue->messages);
    free(queue);

    return 0;
}
