    RandomData *data;
    size_t count;
    pthread_mutex_t lock;
} DynamicRandomGenerator;

DynamicRandomGenerator* create_generator() {
    DynamicRandomGenerator *generator = (DynamicRandomGenerator*)malloc(sizeof(DynamicRandomGenerator));
    if (!generator) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    generator->data = (RandomData*)calloc(MAX_STRUCTS, sizeof(RandomData));
    if (!generator->data) {
        free(generator);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pthread_mutex_init(&generator->lock, NULL);
    return generator;
}

void destroy_generator(DynamicRandomGenerator *generator) {
    pthread_mutex_lock(&generator->lock);
    free(generator->data);
    pthread_mutex_unlock(&generator->lock);
    free(generator);
}

void generate_random_data(DynamicRandomGenerator *generator, size_t count) {
    if (count > MAX_STRUCTS) {
        fprintf(stderr, "Exceeds maximum structure limit\n");
        return;
    }
    pthread_mutex_lock(&generator->lock);
    for (size_t i = 0; i < count; ++i) {
        generator->data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        generator->data[i].RNTI = rand() % 65536;
        generator->data[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        generator->data[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }
    pthread_mutex_unlock(&generator->lock);
}

void* worker_thread(void *arg) {
    DynamicRandomGenerator *generator = (DynamicRandomGenerator*)arg;
    size_t count = MAX_STRUCTS / 4; // Example division for multiple threads
    generate_random_data(generator, count);
    return NULL;
}

int main() {
    srand(time(NULL));

    DynamicRandomGenerator *generator = create_generator();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, generator)) {
            fprintf(stderr, "Failed to create thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_generator(generator);

    return 0;
}
