#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <algorithm>

// Define DataChunk structure
struct DataChunk {
    std::string timestamp;
    double sensorReading;
    std::string metadataTag;
    bool processingFlag;
};

class FlexibleDataProcessor {
private:
    const size_t MAX_CHUNKS = 50000;
    std::vector<DataChunk*> chunks;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running;
    size_t chunkIndex;

public:
    FlexibleDataProcessor() : running(true), chunkIndex(0) {}

    ~FlexibleDataProcessor() {
        stop();
        for (auto& chunk : chunks) {
            delete[] chunk;
        }
    }

    void start() {
        std::thread([this]() {
            while (running.load()) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this]() { return !chunks.empty() || !running.load(); });
                if (!chunks.empty()) {
                    processChunk(chunks.back());
                    chunks.pop_back();
                }
            }
        }).detach();
    }

    void stop() {
        running.store(false);
        cv.notify_all();
    }

    bool addDataChunk(const DataChunk& dataChunk) {
        std::lock_guard<std::mutex> lock(mtx);
        if (chunks.size() >= MAX_CHUNKS) {
            return false;
        }
        chunks.push_back(new DataChunk[dataChunk]);
        cv.notify_one();
        return true;
    }

private:
    void processChunk(DataChunk* chunk) {
        // Simulate data processing
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed chunk: " << (*chunk).sensorReading << std::endl;
    }
};

int main() {
    FlexibleDataProcessor processor;
    processor.start();

    for (size_t i = 0; i < 50000; ++i) {
        DataChunk dataChunk = {"2023-10-01T00:00:00", i * 0.1, "tag" + std::to_string(i), false};
        if (!processor.addDataChunk(dataChunk)) {
            std::cerr << "Failed to add data chunk after " << i << " attempts." << std::endl;
            break;
        }
    }

    processor.stop();

    return 0;
}
```

