#define MAX_EVENTS 15000
#define SLIDING_WINDOW_MINUTES 30
#define MAX_HIGH_PRIORITY_EVENTS 300
#define REVIEWED_EVENTS_MAX 0.1 * MAX_HIGH_PRIORITY_EVENTS

typedef struct {
    int event_id;
    time_t timestamp;
    int priority_level;
} Event;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} LTE_Event;

typedef struct {
    Event *events[MAX_HIGH_PRIORITY_EVENTS];
    int count;
} Event_List;

typedef struct {
    pthread_mutex_t lock;
    Event_List high_priority_events;
    Event_List reviewed_events;
    time_t last_cleanup_time;
} Event_Manager;

void init_event_manager(Event_Manager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_cleanup_time = time(NULL);
}

void add_event(Event_Manager *manager, Event event) {
    pthread_mutex_lock(&manager->lock);
    // Add event to the appropriate list
    if (event.priority_level > 0 && manager->high_priority_events.count < MAX_HIGH_PRIORITY_EVENTS) {
        manager->high_priority_events.events[manager->high_priority_events.count++] = &event;
    } else if (event.priority_level <= 0 && manager->reviewed_events.count < REVIEWED_EVENTS_MAX) {
        manager->reviewed_events.events[manager->reviewed_events.count++] = &event;
    }
    pthread_mutex_unlock(&manager->lock);
}

void *cleanup_thread(void *arg) {
    Event_Manager *manager = (Event_Manager *)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        time_t current_time = time(NULL);
        if (current_time - manager->last_cleanup_time > SLIDING_WINDOW_MINUTES * 60) {
            // Remove expired events
            manager->high_priority_events.count = 0;
            manager->reviewed_events.count = 0;
            manager->last_cleanup_time = current_time;
        }
        pthread_mutex_unlock(&manager->lock);
        sleep(SLIDING_WINDOW_MINUTES * 59); // Check every minute less than the sliding window
    }
    return NULL;
}

int process_events(Event_Manager *manager) {
    int highest_priority = -1;
    int event_id = 0;
    int reviewed_count = 0;

    pthread_mutex_lock(&manager->lock);
    if (manager->high_priority_events.count > 0) {
        Event *event = manager->high_priority_events.events[0];
        highest_priority = event->priority_level;
        event_id = event->event_id;
        // Move the event to reviewed list or remove it
        manager->reviewed_events.events[manager->reviewed_events.count++] = event;
        if (manager->reviewed_events.count >= REVIEWED_EVENTS_MAX) {
            manager->high_priority_events.count--;
        }
    } else if (manager->reviewed_events.count > 0) {
        Event *event = manager->reviewed_events.events[0];
        highest_priority = event->priority_level;
        event_id = event->event_id;
        // Remove the reviewed event
        manager->reviewed_events.count--;
    }
    pthread_mutex_unlock(&manager->lock);

    return highest_priority, event_id, reviewed_count;
}

void create_lte_event(LTE_Event *lte_event) {
    lte_event->RX_UE_INFORMATION_TAG = rand() % 256;
    lte_event->RNTI = (uint16_t)(rand() % 4096);
    lte_event->CRC_INDICATION_REL8_TAG = (uint32_t)(rand() % 256);
}

int main() {
    Event_Manager manager;
    init_event_manager(&manager);

    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, &manager);

    // Example usage
    Event event = {1, time(NULL), 5};
    add_event(&manager, event);

    int priority, id, reviewed_count;
    while ((priority, id, reviewed_count = process_events(&manager)) != -1) {
        printf("Processed event ID: %d with priority: %d\n", id, priority);
    }

    pthread_join(cleanup_tid, NULL);
    return 0;
}
