class DynamicPacketProcessor {
public:
    DynamicPacketProcessor(size_t maxChunks = 50000) : maxChunks(maxChunks), dataChunks(maxChunks, nullptr) {}

    ~DynamicPacketProcessor() {
        for (auto& chunk : dataChunks) {
            delete[] chunk;
        }
    }

    DataChunk* allocateDataChunk() {
        if (chunkIndex >= maxChunks) {
            throw std::runtime_error("Maximum number of chunks reached");
        }
        return dataChunks[chunkIndex++] = new DataChunk();
    }

    void deallocateDataChunk(DataChunk* chunk) {
        delete[] chunk;
        // Find and set the pointer to nullptr
        for (size_t i = 0; i < maxChunks; ++i) {
            if (dataChunks[i] == chunk) {
                dataChunks[i] = nullptr;
                break;
            }
        }
    }

    void validateDataChunk(DataChunk* chunk) {
        // Add validation logic here
        if (!chunk) {
            throw std::invalid_argument("Invalid data chunk");
        }
    }

private:
    size_t maxChunks;
    DataChunk** dataChunks;
    size_t chunkIndex = 0;
};

int main() {
    DynamicPacketProcessor processor;

    try {
        DataChunk* newChunk = processor.allocateDataChunk();
        // Use the newChunk for processing
        processor.validateDataChunk(newChunk);
        processor.deallocateDataChunk(newChunk);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
