NFAPI_CRC_INDICATION_PDU_T rnti_pool[RNTI_POOL_SIZE];
UE_INFO_T secondary_rnti_pool[SECONDARY_RNTI_POOL_SIZE];

pthread_mutex_t rnti_pool_lock = PTHREAD_MUTEX_INITIALIZER;

uint16_t get_unique_rnti() {
    static uint16_t last_rnti = 0;
    pthread_mutex_lock(&rnti_pool_lock);
    if (last_rnti >= RNTI_POOL_SIZE) {
        // handle collision by refilling secondary pool and resetting
        for (int i = 0; i < SECONDARY_RNTI_POOL_SIZE; i++) {
            secondary_rnti_pool[i].RNTI = last_rnti;
            last_rnti++;
        }
    }
    uint16_t rnti = last_rnti;
    last_rnti++;
    pthread_mutex_unlock(&rnti_pool_lock);
    return rnti;
}

void generate_crc_indication_pdus(int num_ues) {
    if (num_ues > MAX_UEs) {
        // handle error
        return;
    }

    for (int i = 0; i < num_ues; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &rnti_pool[i % RNTI_POOL_SIZE];
        pdu->CRCFLAG = rand() % 2; // randomly set CRC flag
        // populate other fields as needed

        UE_INFO_T *ue_info = &secondary_rnti_pool[i % SECONDARY_RNTI_POOL_SIZE];
        ue_info->RX_UE_INFORMATION_TAG = i;
        ue_info->RNTI = get_unique_rnti();
    }
}

void* generate_crc_indication_pdus_thread(void* arg) {
    int num_ues = *(int*)arg;
    generate_crc_indication_pdus(num_ues);
    pthread_exit(NULL);
}
