#include <string.h>
#include <pthread.h>

#define MAX_CONCURRENT_MESSAGES 1000
#define SLIDING_WINDOW_SIZE (24 * 60 * 60) // 24 hours in seconds

typedef struct {
    uint32_t id;
    uint32_t sequence_number;
    time_t timestamp;
    char* payload_segments[10];
} MessagePacket;

typedef struct {
    MessagePacket* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketQueue;

void init_packet_queue(PacketQueue* queue, size_t initial_capacity) {
    queue->packets = malloc(initial_capacity * sizeof(MessagePacket));
    if (queue->packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_packet(PacketQueue* queue, MessagePacket packet) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == queue->capacity) {
        // Double the capacity
        size_t new_capacity = queue->capacity * 2;
        queue->packets = realloc(queue->packets, new_capacity * sizeof(MessagePacket));
        if (queue->packets == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        queue->capacity = new_capacity;
    }
    queue->packets[queue->size++] = packet;
    pthread_mutex_unlock(&queue->lock);
}

void dequeue_packet(PacketQueue* queue, MessagePacket* packet) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size > 0) {
        *packet = queue->packets[--queue->size];
    }
    pthread_mutex_unlock(&queue->lock);
}

void clean_up_expired_packets(PacketQueue* queue, time_t current_time) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size > 0 && difftime(queue->packets[queue->size - 1].timestamp, current_time) > SLIDING_WINDOW_SIZE) {
        --queue->size;
    }
    pthread_mutex_unlock(&queue->lock);
}

void* background_clean_up(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;
    while (1) {
        time_t current_time = time(NULL);
        clean_up_expired_packets(queue, current_time);
        sleep(60); // Clean up every minute
    }
    return NULL;
}

int main() {
    PacketQueue packet_queue;
    init_packet_queue(&packet_queue, 1024);

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, background_clean_up, &packet_queue) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(EXIT_FAILURE);
    }

    // Simulate message processing
    MessagePacket packet;
    enqueue_packet(&packet_queue, packet);

    pthread_join(cleanup_thread, NULL);

    return 0;
}
