        TSDRecord* newTsdArray = (TSDRecord*)realloc(tsdArray, (recordCount + 1) * sizeof(TSDRecord));
        if (newTsdArray == NULL) {
            pthread_mutex_unlock(&lock);
            return -1; // Memory allocation failed
        }
        tsdArray = newTsdArray;
