    FILE* manpage = fopen("manpage.txt", "r");
    if (manpage) {
        fclose(manpage);
        while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
            switch (opt) {
                case 'm':
                    // Display manpage
                    system("less manpage.txt");
                    break;
                case 'c':
                    if (!optarg) {
                        printf("Missing file for processing\n");
                        return EXIT_FAILURE;
                    }
                    process_file(optarg);
                    break;
                case 'o':
                    if (!optarg) {
                        printf("Missing output file\n");
                        return EXIT_FAILURE;
                    }
                    // Write to output file
                    FILE* output = fopen(optarg, "w");
                    if (output) {
                        fprintf(output, "Processing complete\n");
                        fclose(output);
                    } else {
                        perror("Failed to open output file");
                    }
                    break;
                default:
                    printf("Usage: %s [-m] [-c <file>] [-o <output_file>]\n", argv[0]);
                    return EXIT_FAILURE;
            }
        }
    } else {
        printf("No manpage available\n");
        while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
            switch (opt) {
                case 'c':
                    if (!optarg) {
                        printf("Missing file for processing\n");
                        return EXIT_FAILURE;
                    }
                    process_file(optarg);
                    break;
                default:
                    printf("Usage: %s [-m] [-c <file>] [-o <output_file>]\n", argv[0]);
                    return EXIT_FAILURE;
            }
        }
    }

    if (optind < argc) {
        printf("Unexpected argument(s): ");
        while (optind < argc)
            printf("%s ", argv[optind++]);
        putchar('\n');
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
