    // Process data points in the specified batch
    for (int i = batchIndex * MAX_DATA_POINTS / MAX_CONCURRENT_THREADS;
         i < (batchIndex + 1) * MAX_DATA_POINTS / MAX_CONCURRENT_THREADS; i++) {
        TSDRecord* record = tsdArray[i];
        if (record != NULL) {
            addTSDRecord(record);
        }
    }

    return NULL;
}

