    pthread_t threads[MAX_CONCURRENT_THREADS];
    int batchIndices[MAX_CONCURRENT_THREADS];

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        batchIndices[i] = i;
        pthread_create(&threads[i], NULL, processBatch, &batchIndices[i]);
    }

    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    float maxWeightedSum = processTSDRecords();
