#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 10000
#define WINDOW_SIZE 900 // 15 minutes in seconds

typedef struct {
    uint64_t rx_ue_information_tag;
    int rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T events[N];
int next_index = 0;
time_t last_event_time = time(NULL);
int high_priority_count = 0;
int priority_map[10000] = {0};

void addEvent(uint64_t tag, int rnti) {
    if (time(NULL) - last_event_time > WINDOW_SIZE) {
        next_index = 0;
        memset(events, 0, sizeof(events));
        high_priority_count = 0;
        memset(priority_map, 0, sizeof(priority_map));
    }

    NFAPI_CRC_INDICATION_PDU_T newEvent;
    newEvent.rx_ue_information_tag = tag;
    newEvent.rnti = rnti;
    newEvent.crc_indication_rel8_tag = (rand() % 256); // Random CRC flag

    events[next_index++] = newEvent;

    if (newEvent.crc_indication_rel8_tag == 1) {
        high_priority_count++;
        priority_map[newEvent.rx_ue_information_tag] = newEvent.rnti;
    }

    last_event_time = time(NULL);
}

void serializeEvents(const char* filename, int format) {
    FILE* file = fopen(filename, format == 0 ? "wb" : "w");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    for (int i = 0; i < next_index; i++) {
        fwrite(&events[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

void deserializeEvents(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    while (fread(&events[next_index], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        next_index++;
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 100000; i++) { // Simulate high concurrency
        addEvent(rand(), rand());
    }

    serializeEvents("events.bin", 0); // Serialize in binary format

    deserializeEvents("events.bin"); // Deserialize from binary file

    return 0;
}
