#define MAX_SESSIONS 10000

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crc_pdus[MAX_SESSIONS];
pthread_mutex_t session_lock;

void initialize_crc_pdus(int num_sessions) {
    if (num_sessions > MAX_SESSIONS) {
        fprintf(stderr, "Too many sessions requested.\n");
        exit(1);
    }

    for (int i = 0; i < num_sessions; i++) {
        crc_pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_pdus[i]) {
            perror("Failed to allocate memory for CRC PDU");
            exit(1);
        }
        pthread_mutex_init(&crc_pdus[i]->mutex, NULL);

        // Populate with valid values
        crc_pdus[i]->rx_ue_information_tag = i;
        crc_pdus[i]->rnti = rand() % 1000; // Example unique RNTI generation
        crc_pdus[i]->crc_indication_rel8_tag = rand() % 256; // Random CRCFLAG
    }
}

void report_crc_error(int session_id, int error_code) {
    pthread_mutex_lock(&session_lock);
    if (crc_pdus[session_id]) {
        // External API call to report error
        printf("Reporting CRC error for session %d with code %d\n", session_id, error_code);
    }
    pthread_mutex_unlock(&session_lock);
}

void cleanup_crc_pdus(int num_sessions) {
    for (int i = 0; i < num_sessions; i++) {
        if (crc_pdus[i]) {
            pthread_mutex_destroy(&crc_pdus[i]->mutex);
            free(crc_pdus[i]);
            crc_pdus[i] = NULL;
        }
    }
}

void *session_thread(void *arg) {
    int session_id = *(int *)arg;
    // Simulate data processing and error reporting
    report_crc_error(session_id, rand() % 10); // Example error code
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_SESSIONS];
    int session_ids[MAX_SESSIONS];

    initialize_crc_pdus(5000);

    for (int i = 0; i < 5000; i++) {
        session_ids[i] = i;
        if (pthread_create(&threads[i], NULL, session_thread, &session_ids[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < 5000; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_crc_pdus(5000);

    return 0;
}
