#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    // Define the structure for NFAPI_CRC_INDICATION_PDU_T here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    int size;
    int capacity;
} CRCArray;

void initializeCRCArray(CRCArray *crcArray, int initialCapacity) {
    pthread_mutex_init(&crcArray->mutex, NULL);
    crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    crcArray->size = 0;
    crcArray->capacity = initialCapacity;
}

void expandCRCArray(CRCArray *crcArray) {
    pthread_mutex_lock(&crcArray->mutex);
    int newCapacity = crcArray->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crcArray->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        perror("Failed to reallocate memory for CRC array");
        pthread_mutex_unlock(&crcArray->mutex);
        exit(EXIT_FAILURE);
    }
    crcArray->array = newArray;
    crcArray->capacity = newCapacity;
    pthread_mutex_unlock(&crcArray->mutex);
}

void addCRCIndication(CRCArray *crcArray, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (crcArray->size == crcArray->capacity) {
        expandCRCArray(crcArray);
    }
    crcArray->array[crcArray->size++] = pdu;
}

void cleanupCRCArray(CRCArray *crcArray) {
    pthread_mutex_lock(&crcArray->mutex);
    free(crcArray->array);
    pthread_mutex_unlock(&crcArray->mutex);
    pthread_mutex_destroy(&crcArray->mutex);
}

