['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define WINDOW_SIZE 300
#define MAX_CONCURRENT_EVENTS 50000

typedef struct Event {
    time_t timestamp;
    int transaction_id;
    char side[10];
    double price;
    int quantity;
} Event;

typedef struct Node {
    Event event;
    struct Node* next;
} Node;

Node* create_node(Event event) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    node->event = event;
    node->next = NULL;
    return node;
}

void free_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int hash_function(Event event, int size) {
    return (event.transaction_id % size + 1) % size;
}

Node** create_hash_table(int size) {
    Node** table = (Node**)calloc(size, sizeof(Node*));
    if (table == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        table[i] = NULL;
    }
    return table;
}

void insert_event(Node** hash_table, Event event, int size) {
    int index = hash_function(event, size);
    Node* new_node = create_node(event);
    if (hash_table[index] == NULL) {
        hash_table[index] = new_node;
    } else {
        Node* current = hash_table[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

int is_duplicate(Node** hash_table, Event event, int size) {
    int index = hash_function(event, size);
    Node* current = hash_table[index];
    while (current != NULL) {
        if (current->event.transaction_id == event.transaction_id) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void process_event(Node** hash_table, Event event, int size, double* average_price, int* total_volume, int limit) {
    if (!is_duplicate(hash_table, event, size)) {
        insert_event(hash_table, event, size);
        *average_price += (event.price - *average_price) / (*total_volume + 1);
        *total_volume += event.quantity;
        if (*total_volume >= limit) {
            printf("Total volume exceeds 90%% of the predefined limit\n");
        }
    }
}

int main() {
    Node** hash_table = create_hash_table(WINDOW_SIZE);
    double average_price = 0.0;
    int total_volume = 0;
    int limit = 50000;

    // Simulate processing events
    for (int i = 0; i < MAX_CONCURRENT_EVENTS; i++) {
        Event event = {time(NULL), i, "buy", 100.0 + rand() % 10 / 100.0, 1};
        process_event(hash_table, event, WINDOW_SIZE, &average_price, &total_volume, limit);
    }

    free_hash_table(hash_table, WINDOW_SIZE);
    return 0;
}
