#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_EVENTS 300
#define SLIDING_WINDOW_MINUTES 5

typedef struct {
    time_t timestamp;
    int transaction_id;
    char side[4];
    double price;
    int quantity;
} MarketEvent;

MarketEvent event_pool[MAX_EVENTS];
int next_event_index = 0;
atomic_int concurrent_events = 0;
atomic_double average_price = 0.0;
atomic_long total_volume = 0L;
double reference_price = 0.0;

void log_market_event(MarketEvent *event) {
    if (concurrent_events >= MAX_EVENTS || event->timestamp < time(NULL) - SLIDING_WINDOW_MINUTES * 60)
        return;

    atomic_fetch_add(&concurrent_events, 1);

    // Process the event
    double new_price = event->price;
    long new_volume = event->quantity;

    if (reference_price != 0 && fabs(new_price / reference_price - 1) > 0.01) {
        reference_price = new_price;
    }

    average_price = (average_price * total_volume + new_price * new_volume) / (total_volume + new_volume);
    total_volume += new_volume;

    if (total_volume >= 90L * (your_predefined_limit)) {
        printf("Total volume exceeded 90%% limit.\n");
    }

    atomic_fetch_sub(&concurrent_events, 1);
