#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Event {
    int id;
    long long timestamp;
    int frequency;
    float score;
    struct Event* next;
} Event;

Event* create_event(int id, long long timestamp, int frequency, float score) {
    Event* new_event = (Event*)malloc(sizeof(Event));
    new_event->id = id;
    new_event->timestamp = timestamp;
    new_event->frequency = frequency;
    new_event->score = score;
    new_event->next = NULL;
    return new_event;
}

void add_event(Event** window, int id, long long timestamp, int frequency, float score) {
    Event* new_event = create_event(id, timestamp, frequency, score);
    if (*window == NULL) {
        *window = new_event;
    } else {
        Event* current = *window;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_event;
    }
}

void remove_old_events(Event** window, long long current_timestamp, long long window_size) {
    if (*window == NULL) return;
    Event* current = *window;
    Event* prev = NULL;
    while (current != NULL && ((current->timestamp + window_size) < current_timestamp)) {
        prev = current;
        current = current->next;
        free(prev);
    }
    *window = current;
}

float process_events(Event** window, long long current_timestamp, long long window_size) {
    remove_old_events(window, current_timestamp, window_size);

    if (*window == NULL) return -1; // No events in the window

    float max_score = (*window)->score;
    int max_id = (*window)->id;
    Event* current = *window;
    while (current != NULL) {
        if (current->timestamp == (*window)->timestamp && current->frequency > 1) {
            return -2; // Duplicate event detected
        }
        if (current->score > max_score) {
            max_score = current->score;
            max_id = current->id;
        }
        current = current->next;
    }

    add_event(window, max_id, current_timestamp, (*window)->frequency + 1, max_score);
    return max_score;
}

int main() {
    Event* window = NULL;
    long long current_timestamp = 0;
    long long window_size = 60000; // 1 minute

    add_event(&window, 1, 50000, 1, 0.8);
    add_event(&window, 2, 100000, 1, 0.9);

    float max_score = process_events(&window, 120000, window_size);
    if (max_score == -1) {
        printf("No events in the window.\n");
    } else if (max_score == -2) {
        printf("Duplicate event detected.\n");
    } else {
        printf("Highest event score: %.2f, Event ID: %d\n", max_score, max_id);
    }

    while (*window != NULL) {
        Event* temp = *window;
        *window = (*window)->next;
        free(temp);
    }

    return 0;
}
