#include <openssl/evp.h>
#include <string.h>

EVP_CIPHER_CTX *performCipherOperation(const char *input, const char *commandLineOption) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error
    }

    int encrypt = 0;
    if (strcmp(commandLineOption, "encrypt") == 0) {
        encrypt = 1;
    } else if (strcmp(commandLineOption, "decrypt") != 0) {
        // Handle invalid command line option
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, encrypt)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    memset(key, 0, sizeof(key));
    memset(iv, 0, sizeof(iv));

    if (!EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, encrypt)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform the encryption/decryption operation
    int len;
    if (!EVP_CipherUpdate(ctx, NULL, &len, (unsigned char *)input, strlen(input))) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char *output = OPENSSL_malloc(len + 1);
    if (output == NULL) {
        // Handle memory allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int outputLen;
    if (!EVP_CipherFinal_ex(ctx, output, &outputLen)) {
        // Handle error
        OPENSSL_free(output);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    output[outputLen] = '\0';

    EVP_CIPHER_CTX_free(ctx);
    return ctx;
}
