#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_LOG_LENGTH 1024

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    char message[MAX_LOG_LENGTH];
    LogLevel level;
    time_t timestamp;
} LogEntry;

typedef void (*LogDestination)(const LogEntry *entry);

void log_message(const char *format, ...);
void add_log_destination(LogDestination dest);
void remove_log_destination(LogDestination dest);

// Implement the following functions
static void stdout_destination(const LogEntry *entry) {
    printf("[%s] %s\n", log_level_to_string(entry->level), entry->message);
}

static const char* log_level_to_string(LogLevel level) {
    switch (level) {
        case LOG_DEBUG: return "DEBUG";
        case LOG_INFO:  return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

// Add more destination functions as needed

static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
static LogDestination destinations[10] = {NULL};
static int num_destinations = 0;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    char buffer[MAX_LOG_LENGTH];
    snprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    LogEntry entry = {
        .message = buffer,
        .level = LOG_INFO,  // Set the desired log level
        .timestamp = time(NULL)
    };

    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < num_destinations; ++i) {
        if (destinations[i] != NULL) {
            destinations[i](&entry);
        }
    }
    pthread_mutex_unlock(&log_lock);
}

void add_log_destination(LogDestination dest) {
    pthread_mutex_lock(&log_lock);
    if (num_destinations < 10) {
        destinations[num_destinations++] = dest;
    } else {
        printf("Log destination limit reached.\n");
    }
    pthread_mutex_unlock(&log_lock);
}

void remove_log_destination(LogDestination dest) {
    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < num_destinations; ++i) {
        if (destinations[i] == dest) {
            destinations[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&log_lock);
}
