#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define EVENT_WINDOW_SECONDS 30 * 60

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    struct Event* next;
} Event;

typedef struct {
    Event** eventWindow;
    size_t windowSize;
    size_t currentIndex;
    pthread_mutex_t lock;
} EventManager;

EventManager* eventManagerInit(size_t initialSize) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) {
        perror("Failed to allocate memory for EventManager");
        return NULL;
    }
    manager->eventWindow = (Event**)calloc(initialSize, sizeof(Event*));
    if (!manager->eventWindow) {
        perror("Failed to allocate memory for event window");
        free(manager);
        return NULL;
    }
    manager->windowSize = initialSize;
    manager->currentIndex = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void eventManagerAddEvent(EventManager* manager, int id, int priority) {
    Event* newEvent = (Event*)malloc(sizeof(Event));
    if (!newEvent) {
        perror("Failed to allocate memory for new event");
        return;
    }
    newEvent->id = id;
    newEvent->timestamp = time(NULL);
    newEvent->priority = priority;
    newEvent->next = NULL;

    pthread_mutex_lock(&manager->lock);
    size_t index = (manager->currentIndex + manager->windowSize - 1) % manager->windowSize;
    if (manager->eventWindow[index]) {
        Event* current = manager->eventWindow[index];
        while (current->next) {
            current = current->next;
        }
        current->next = newEvent;
    } else {
        manager->eventWindow[index] = newEvent;
    }
    manager->currentIndex = index;
    pthread_mutex_unlock(&manager->lock);
}

int eventManagerGetHighestPriority(EventManager* manager) {
    int highestPriority = INT_MAX;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->windowSize; ++i) {
        Event* current = manager->eventWindow[i];
        while (current) {
            if (current->timestamp + EVENT_WINDOW_SECONDS > time(NULL)) {
                highestPriority = fmin(highestPriority, current->priority);
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return highestPriority;
}

void eventManagerFree(EventManager* manager) {
    for (size_t i = 0; i < manager->windowSize; ++i) {
        Event* current = manager->eventWindow[i];
        while (current) {
            Event* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(manager->eventWindow);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
