['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define WINDOW_SIZE 300
#define HIGH_PRIORITY_THRESHOLD 1.01
#define MAX_EVENTS_PER_SECOND 50000
#define CACHE_SIZE 1000

typedef struct Event {
    time_t timestamp;
    int transaction_id;
    char side[6];
    double price;
    int quantity;
    struct Event* next;
} Event;

typedef struct HashNode {
    Event* event;
    struct HashNode* next;
} HashNode;

typedef struct LogSystem {
    Event** sliding_window;
    int window_head;
    int window_size;
    HashNode** hash_table;
    int cache[CACHE_SIZE];
    double reference_price;
    int total_volume;
    int predefined_limit;
    pthread_mutex_t lock;
} LogSystem;

LogSystem* create_log_system(int window_size, int table_size, int limit) {
    LogSystem* system = (LogSystem*)malloc(sizeof(LogSystem));
    if (!system) return NULL;

    system->sliding_window = (Event**)calloc(window_size, sizeof(Event*));
    if (!system->sliding_window) {
        free(system);
        return NULL;
    }

    system->hash_table = (HashNode**)calloc(table_size, sizeof(HashNode*));
    if (!system->hash_table) {
        free(system->sliding_window);
        free(system);
        return NULL;
    }

    pthread_mutex_init(&system->lock, NULL);
    system->window_head = 0;
    system->window_size = window_size;
    system->reference_price = 0.0;
    system->total_volume = 0;
    system->predefined_limit = limit;

    return system;
}

void destroy_log_system(LogSystem* system) {
    for (int i = 0; i < system->window_size; ++i) {
        Event* event = system->sliding_window[i];
        while (event) {
            Event* next = event->next;
            free(event);
            event = next;
        }
    }

    for (int i = 0; i < table_size; ++i) {
        HashNode* node = system->hash_table[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&system->lock);
    free(system->sliding_window);
    free(system->hash_table);
    free(system);
}

void add_event(LogSystem* system, Event* event) {
    pthread_mutex_lock(&system->lock);

    // Evict events older than 5 minutes
    while (system->window_head < system->window_size && 
           difftime(time(NULL), system->sliding_window[system->window_head]->timestamp) > 300) {
        Event* evicted = system->sliding_window[system->window_head++];
        free(evicted);
    }

    // Check for duplicate events
    int hash_index = event->transaction_id % HASH_TABLE_SIZE;
    HashNode* node = system->hash_table[hash_index];
    while (node) {
        if (node->event->transaction_id == event->transaction_id) {
            pthread_mutex_unlock(&system->lock);
            return; // Duplicate event, discard
        }
        node = node->next;
    }

    // Add new event to sliding window and hash table
    system->sliding_window[system->window_head++] = event;
    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&system->lock);
        return; // Memory allocation failed, discard event
    }

    new_node->event = event;
    new_node->next = system->hash_table[hash_index];
