#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define WINDOW_SIZE 30 * 60

typedef struct {
    uint8_t CRCFLAG;
    // Add other members as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t RNTI;
    RX_UE_INFORMATION_TAG rx_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    int is_marked_for_review;
    struct Event *next;
} Event;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *structs[MAX_STRUCTS];
Event *event_queue = NULL;
int event_count = 0;
int highest_priority = -1;

void* allocate_and_populate_structs(void* arg) {
    srand(time(NULL));

    for (int i = 0; i < MAX_STRUCTS; i++) {
        structs[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structs[i]) {
            perror("Memory allocation failed");
            return NULL;
        }

        pthread_mutex_lock(&lock);
        structs[i]->rx_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

void enqueue_event(int id, int priority) {
    Event *new_event = malloc(sizeof(Event));
    if (!new_event) {
        perror("Memory allocation failed");
        return;
    }

    new_event->id = id;
    new_event->timestamp = time(NULL);
    new_event->priority = priority;
    new_event->is_marked_for_review = 0;
    new_event->next = NULL;

    pthread_mutex_lock(&lock);
    if (!event_queue) {
        event_queue = new_event;
    } else {
        Event *current = event_queue;
        while (current->next) {
            current = current->next;
        }
        current->next = new_event;
    }

    // Maintain sliding window
    time_t now = time(NULL);
    while (event_count > 0 && difftime(now, event_queue->timestamp) > WINDOW_SIZE) {
        Event *temp = event_queue;
        event_queue = event_queue->next;
        free(temp);
        event_count--;
    }

    // Limit high-priority events
    int current_high_priority_count = 0;
    Event *current = event_queue;
    while (current) {
        if (current->priority < highest_priority && !current->is_marked_for_review) {
            current_high_priority_count++;
        }
        current = current->next;
    }

    if (current_high_priority_count >= 300) {
        // Handle high-priority event limit exceeded
    }

    pthread_mutex_unlock(&lock);
}

int process_events() {
    int processed = 0;

    pthread_mutex_lock(&lock);
    Event *current = event_queue;
    while (current && current->is_marked_for_review) {
        // Process review events first
        printf("Processing high-priority event: %d\n", current->id);
        processed++;
        current = current->next;
    }

    while (current && processed < 10) {
        // Process remaining events
        if (!current->is_marked_for_review) {
            printf("Processing event: %d\n", current->id);
            processed++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);

    return processed;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, allocate_and_populate_structs, NULL);
    pthread_join(thread, NULL);

    enqueue_event(1, 5);
    enqueue_event(2, 3);
    enqueue_event(3, 4);

    int processed = process_events();
    printf("Processed %d events\n", processed);

    for (int i = 0; i < MAX_STRUCTS; i++) {
        free(structs[i]);
    }

    return 0;
}
