#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_MESSAGES 1000
#define SLIDING_WINDOW_SIZE 86400 // 24 hours in seconds
#define MAX_HASH_RETRIES 5

typedef struct {
    unsigned int message_id;
    unsigned long sequence_number;
    time_t timestamp;
    char **payload_segments;
    int payload_count;
} MessagePacket;

typedef struct {
    MessagePacket *messages;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MessageQueue;

MessageQueue *create_message_queue() {
    MessageQueue *queue = (MessageQueue *)malloc(sizeof(MessageQueue));
    if (!queue) return NULL;
    queue->messages = NULL;
    queue->size = 0;
    queue->capacity = 0;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void destroy_message_queue(MessageQueue *queue) {
    if (queue->messages) {
        for (size_t i = 0; i < queue->size; ++i) {
            for (int j = 0; j < queue->messages[i].payload_count; ++j) {
                free(queue->messages[i].payload_segments[j]);
            }
            free(queue->messages[i].payload_segments);
        }
        free(queue->messages);
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

void enqueue_message(MessageQueue *queue, MessagePacket packet) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == queue->capacity) {
        // Resize the queue
        queue->capacity = queue->capacity ? queue->capacity * 2 : 16;
        queue->messages = realloc(queue->messages, queue->capacity * sizeof(MessagePacket));
    }
    queue->messages[queue->size++] = packet;
    pthread_mutex_unlock(&queue->lock);
}

MessagePacket dequeue_message(MessageQueue *queue) {
    MessagePacket packet;
    memset(&packet, 0, sizeof(packet));
    pthread_mutex_lock(&queue->lock);
    if (queue->size > 0) {
        memcpy(&packet, &queue->messages[0], sizeof(MessagePacket));
        memmove(queue->messages, queue->messages + 1, (queue->size - 1) * sizeof(MessagePacket));
        --queue->size;
    }
    pthread_mutex_unlock(&queue->lock);
    return packet;
}

void *message_cleanup_thread(void *arg) {
    MessageQueue *queue = (MessageQueue *)arg;
    while (1) {
        time_t now = time(NULL);
        pthread_mutex_lock(&queue->lock);
        size_t i = 0;
        while (i < queue->size && difftime(now, queue->messages[i].timestamp) > SLIDING_WINDOW_SIZE) {
            for (int j = 0; j < queue->messages[i].payload_count; ++j) {
                free(queue->messages[i].payload_segments[j]);
            }
            free(queue->messages[i].payload_segments);
            memmove(&queue->messages[i], &queue->messages[i + 1], (queue->size - i - 1) * sizeof(MessagePacket));
            --queue->size;
        }
        pthread_mutex_unlock(&queue->lock);
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    MessageQueue *queue = create_message_queue();
    if (!queue) return -1;

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, message_cleanup_thread, queue);

    // Simulate enqueueing and dequeueing messages
    for (int i = 0; i < 100; ++i) {
        MessagePacket packet;
        packet.message_id = i;
        packet.sequence_number = time(NULL);
        packet.timestamp = time(NULL);
        packet.payload_count = 1;
        packet.payload_segments = (char **)malloc(sizeof(char *));
        packet.payload_segments[0] = strdup("example payload");
        enqueue_message(queue, packet);
    }

    for (int i = 0; i < 50; ++i) {
        MessagePacket packet = dequeue_message(queue);
        if (packet.message_id != 0) {
            printf("Dequeued message: ID %u, Sequence %lu\n", packet.message_id, packet.sequence_number);
            free(packet.payload_segments[0]);
            free(packet.payload_segments);
        }
    }

    pthread_join(cleanup_thread, NULL);
    destroy_message_queue(queue);

    return 0;
}
