using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DynamicRangeValueGenerator : IDisposable
{
    private readonly Random _random = new Random();
    private readonly object _lockObject = new object();
    private List<Range> _ranges;
    private NFAPI_CRC_INDICATION_PDU_T[] _crcIndications;

    public DynamicRangeValueGenerator(int numberOfStructures)
    {
        _ranges = new List<Range>();
        _crcIndications = new NFAPI_CRC_INDICATION_PDU_T[numberOfStructures];
        InitializeCrcIndications();
    }

    public void AddRange(double min, double max, bool inclusive = true, Distribution distribution = Distribution.Uniform)
    {
        lock (_lockObject)
        {
            if (_ranges.Any(r => r.Intersects(min, max)))
                throw new ArgumentException("Range overlaps with existing ranges.");

            _ranges.Add(new Range(min, max, inclusive, distribution));
        }
    }

    public void RemoveRange(double min, double max)
    {
        lock (_lockObject)
        {
            var rangeToRemove = _ranges.FirstOrDefault(r => r.Min == min && r.Max == max);
            if (rangeToRemove != null)
                _ranges.Remove(rangeToRemove);
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lockObject)
        {
            return GetRandomValue(Distribution.Uniform).ToSingle();
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lockObject)
        {
            return (int)GetRandomValue(Distribution.Uniform);
        }
    }

    public void ResetRanges(List<Range> newRanges)
    {
        lock (_lockObject)
        {
            _ranges = new List<Range>(newRanges.Where(r => !_ranges.Any(exists => exists.Intersects(r.Min, r.Max))));
        }
    }

    public override string ToString()
    {
        return $"Current Ranges: {_ranges.Select(r => r.ToString()).Aggregate((a, b) => a + ", " + b)}";
    }

    private double GetRandomValue(Distribution distribution)
    {
        var range = _ranges[_random.Next(_ranges.Count)];
        switch (distribution)
        {
            case Distribution.Uniform:
                return range.GetUniformRandom();
            case Distribution.Normal:
                return range.GetNormalRandom();
            default:
                throw new ArgumentOutOfRangeException(nameof(distribution), distribution, "Invalid distribution.");
        }
    }

    private void InitializeCrcIndications()
    {
        for (int i = 0; i < _crcIndications.Length; i++)
        {
            _crcIndications[i].RX_UE_INFORMATION_TAG = GenerateRandomInt();
            _crcIndications[i].RNTI = GenerateUniqueRnti(i);
            _crcIndications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (byte)(_random.Next(0, 2) == 1 ? 1 : 0);
        }
    }

    private int GenerateUniqueRnti(int index)
    {
        // Simplified logic for unique RNTI generation; actual implementation may vary based on requirements.
        return (int)((index * 31) % 65535);
    }

    public void Dispose()
    {
        _ranges.Clear();
        Array.Clear(_crcIndications, 0, _crcIndications.Length);
    }
}

public enum Distribution
{
    Uniform,
    Normal
}

public struct Range
{
    public double Min { get; }
    public double Max { get; }
    public bool Inclusive { get; }
    public Distribution Distribution { get; }

    public Range(double min, double max, bool inclusive = true, Distribution distribution = Distribution.Uniform)
    {
        Min = min;
        Max = max;
        Inclusive = inclusive;
        Distribution = distribution;
    }

    public double GetUniformRandom()
    {
        return Inclusive ? _random.NextDouble() * (Max - Min) + Min : _random.NextDouble() * (Max - Min);
    }

    public double GetNormalRandom()
    {
        // Simple normal distribution; may need adjustment for specific requirements.
        double mean = (Min + Max) / 2;
        double stdDev = Math.Abs(Max - Min) / 6;
        return _random.NextGaussian(mean, stdDev);
    }

    public bool Intersects(double min, double max)
    {
        if (Max < min || Min > max)
            return false;

        if ((Min >= min && Min <= max) ||
            (Max >= min && Max <= max))
            return true;

        if (Inclusive && (min == Min || max == Max))
            return true;

        return false;
    }

    public override string ToString()
    {
        return $"[{Min}, {Max}]";
    }
}

public struct NFAPI_CRC_INDICATION_PDU_T
{
    public int RX_UE_INFORMATION_TAG;
    public int RNTI;
    public CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;

    public struct CRC_INDICATION_REL8_TAG
    {
        public byte CRCFLAG;
    }
}
