#define MAX_TUNNEL_ID 1000
#define MIN_TUNNEL_ID 1

typedef struct {
    char SourceIPAddress[INET_ADDRSTRLEN];
    char DestinationIPAddress[INET_ADDRSTRLEN];
    int TunnelID;
} TrafficFlowConfiguration;

int isValidIP(char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

TrafficFlowConfiguration* initializeTrafficConfigurations(int count, int maxTunnelID, int minTunnelID) {
    if (maxTunnelID < minTunnelID || count <= 0) {
        printf("Invalid input parameters.\n");
        return NULL;
    }

    TrafficFlowConfiguration *configurations = (TrafficFlowConfiguration *)malloc(count * sizeof(TrafficFlowConfiguration));
    if (configurations == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        printf("Enter source IP address for configuration %d: ", i + 1);
        scanf("%s", configurations[i].SourceIPAddress);

        printf("Enter destination IP address for configuration %d: ", i + 1);
        scanf("%s", configurations[i].DestinationIPAddress);

        printf("Enter tunnel ID for configuration %d (between %d and %d): ", i + 1, minTunnelID, maxTunnelID);
        int tunnelID;
        while (1) {
            scanf("%d", &tunnelID);
            if (tunnelID >= minTunnelID && tunnelID <= maxTunnelID) {
                configurations[i].TunnelID = tunnelID;
                break;
            } else {
                printf("Invalid tunnel ID. Please enter a value between %d and %d.\n", minTunnelID, maxTunnelID);
            }
