#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int current_size = 0;

void* create_linked_list(int N) {
    if (N > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Maximum size limit exceeded\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return head;
        }
        // Populate the structure with random data
        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand() % 1024;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() & 1;
        new_node->next = head;
        head = new_node;
        current_size++;
    }
    pthread_mutex_unlock(&mutex);
    return head;
}

void log_creation(Node* node) {
    printf("Created new structure with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           node->data.RX_UE_INFORMATION_TAG, node->data.RNTI, node->data.CRC_INDICATION_REL8_TAG);
}

void* resize_linked_list(int new_size) {
    if (new_size < current_size || new_size > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Invalid new size\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    int i = 0;
    Node* current = head;
    while (current != NULL && i < new_size) {
        i++;
        current = current->next;
    }
    if (i < new_size) {
        fprintf(stderr, "Error: Not enough nodes to resize\n");
        pthread_mutex_unlock(&mutex);
        return head;
    }

    Node* new_head = current;
    while (new_head != NULL) {
        Node* next = new_head->next;
        free(new_head);
        new_head = next;
    }
    head = new_head;
    current_size = new_size;
    pthread_mutex_unlock(&mutex);
    return head;
}

void log_leak() {
    if (current_size > 0) {
        fprintf(stderr, "Memory leak detected: %d structures not freed\n", current_size);
    }
}

// Serialization and deserialization functions
void serialize(Node* node, FILE* file) {
    // Serialize the linked list to a binary file
}

Node* deserialize(FILE* file) {
    // Deserialize the linked list from a binary file
    return NULL;
}

// Performance profiling function
void profile_performance() {
    clock_t start = clock();
    // Call the function for performance testing
