#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_MESSAGES 1000
#define SLIDING_WINDOW_SECONDS 86400 // 24 hours in seconds
#define MESSAGE_ID_LENGTH 32
#define MAX_PAYLOAD_SEGMENTS 5

typedef struct {
    char id[MESSAGE_ID_LENGTH];
    unsigned int sequence_number;
    time_t timestamp;
    struct {
        unsigned char checksum;
        int priority_level;
    } payload[MAX_PAYLOAD_SEGMENTS];
} MessagePacket;

typedef struct {
    MessagePacket *messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MessageQueue;

MessageQueue *create_message_queue(size_t initial_capacity) {
    MessageQueue *queue = (MessageQueue *)malloc(sizeof(MessageQueue));
    if (!queue) return NULL;

    queue->messages = (MessagePacket *)malloc(initial_capacity * sizeof(MessagePacket));
    if (!queue->messages) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_message_queue(MessageQueue *queue) {
    pthread_mutex_destroy(&queue->lock);
    free(queue->messages);
    free(queue);
}

int enqueue_message(MessageQueue *queue, MessagePacket message) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        MessagePacket *new_messages = (MessagePacket *)realloc(queue->messages, new_capacity * sizeof(MessagePacket));
        if (!new_messages) {
            pthread_mutex_unlock(&queue->lock);
            return -1;
        }
        queue->messages = new_messages;
        queue->capacity = new_capacity;
    }
    memcpy(&queue->messages[queue->size], &message, sizeof(MessagePacket));
    queue->size++;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_message(MessageQueue *queue, MessagePacket *message) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    memcpy(message, &queue->messages[0], sizeof(MessagePacket));
    memmove(queue->messages, queue->messages + 1, (queue->size - 1) * sizeof(MessagePacket));
    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void *cleanup_thread(void *arg) {
    MessageQueue *queue = (MessageQueue *)arg;
    time_t now = time(NULL);
    while (1) {
        pthread_mutex_lock(&queue->lock);
        if (queue->size > 0 && difftime(now, queue->messages[queue->size - 1].timestamp) >= SLIDING_WINDOW_SECONDS) {
            memmove(queue->messages, queue->messages + 1, (queue->size - 1) * sizeof(MessagePacket));
            queue->size--;
        }
        pthread_mutex_unlock(&queue->lock);
        sleep(1); // Adjust the interval as needed
    }
    return NULL;
}

void process_message(MessageQueue *queue) {
    MessagePacket message;
    while (1) {
        if (dequeue_message(queue, &message) == 0) {
            // Process the message here
            printf("Processing message with ID: %s\n", message.id);
        }
        sleep(1); // Adjust the interval as needed
    }
}

int main() {
    MessageQueue *queue = create_message_queue(100);
    if (!queue) return -1;

    pthread_t cleanup_tid, process_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, queue);
    pthread_create(&process_tid, NULL, process_message, queue);

    // Simulate message enqueueing
    for (int i = 0; i < 200; i++) {
        MessagePacket msg;
        snprintf(msg.id, MESSAGE_ID_LENGTH, "msg%d", i);
        msg.sequence_number = i;
        time(&msg.timestamp);
        if (enqueue_message(queue, msg) != 0) {
            printf("Failed to enqueue message\n");
        }
    }

    pthread_join(cleanup_tid, NULL);
    pthread_join(process_tid, NULL);

    destroy_message_queue(queue);
    return 0;
}
```

This code provides a basic implementation of a message queue using a thread-safe structure. It includes functions for creating and destroying the queue, enqueuing and dequeuing messages, and running cleanup and processing threads. The `cleanup_thread` function removes messages older than 24 hours, while the `process_message` function simulates processing new messages from the queue. This example can be extended with additional features such as handling duplicates using a custom hash function and managing concurrent access to the queue.']

