#define MAX_TRANSACTIONS_PER_SECOND 1000
#define SLIDING_WINDOW_SIZE 10
#define TIME_WINDOW_SECONDS 3

typedef struct Transaction {
    int id;
    double amount;
    int priority_level;
    time_t timestamp;
} Transaction;

typedef struct SlidingWindow {
    Transaction transactions[SLIDING_WINDOW_SIZE];
    int count;
} SlidingWindow;

typedef struct TransactionHistory {
    SlidingWindow windows[MAX_TRANSACTIONS_PER_SECOND];
    time_t last_update_time;
} TransactionHistory;

int find_transaction_index(TransactionHistory *history, int id) {
    for (int i = 0; i < MAX_TRANSACTIONS_PER_SECOND; ++i) {
        if (history->windows[i].transactions[0].id == id) {
            return i;
        }
    }
    return -1;
}

void add_transaction(TransactionHistory *history, Transaction transaction) {
    int index = find_transaction_index(history, transaction.id);
    if (index != -1) {
        history->windows[index] = create_sliding_window();
    } else {
        index = history->last_update_time % MAX_TRANSACTIONS_PER_SECOND;
        init_sliding_window(&history->windows[index]);
    }
    add_to_sliding_window(&history->windows[index], transaction);
}

void update_transaction_history(TransactionHistory *history) {
    time_t current_time = time(NULL);
    if (current_time - history->last_update_time >= 1) {
        for (int i = 0; i < MAX_TRANSACTIONS_PER_SECOND; ++i) {
            SlidingWindow *window = &history->windows[i];
            if (current_time - window->transactions[0].timestamp > SLIDING_WINDOW_SIZE) {
                init_sliding_window(window);
            }
        }
        history->last_update_time = current_time;
    }
}

double calculate_weighted_sum(Transaction transaction) {
    return transaction.amount * transaction.priority_level;
}

void find_max_weighted_sum(TransactionHistory *history, double *max_sum, int *id) {
    time_t current_time = time(NULL);
    double max_local_sum = 0;
    int max_id = -1;

    for (int i = 0; i < MAX_TRANSACTIONS_PER_SECOND; ++i) {
        SlidingWindow *window = &history->windows[i];
        if (current_time - window->transactions[0].timestamp <= TIME_WINDOW_SECONDS) {
            double local_sum = 0;
            for (int j = 0; j < window->count; ++j) {
                Transaction transaction = window->transactions[j];
                if (current_time - transaction.timestamp <= SLIDING_WINDOW_SIZE) {
                    local_sum += calculate_weighted_sum(transaction);
                }
            }
            if (local_sum > max_local_sum) {
                max_local_sum = local_sum;
                max_id = i;
            }
        }
    }

    *max_sum = max_local_sum;
    *id = max_id;
}

int main() {
    TransactionHistory history = {0};
    init_transaction_history(&history);

    // Simulate transactions
    for (int i = 0; i < MAX_TRANSACTIONS_PER_SECOND; ++i) {
        Transaction transaction = {
            .id = i % 10,
            .amount = i * 1.0,
            .priority_level = rand() % 10 + 1,
            .timestamp = time(NULL)
        };
        add_transaction(&history, transaction);
    }

    update_transaction_history(&history);

    double max_sum;
    int id;
    find_max_weighted_sum(&history, &max_sum, &id);

    printf("Max Weighted Sum: %.2f\n", max_sum);
    printf("Corresponding Transaction ID: %d\n", id);

    return 0;
}
