#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define SLIDING_WINDOW_SIZE 10
#define MAX_PRIORITY 10
#define TIME_WINDOW 3

typedef struct Transaction {
    int id;
    long long timestamp;
    double amount;
    int priority_level;
} Transaction;

typedef struct SlidingWindow {
    Transaction transactions[SLIDING_WINDOW_SIZE];
    int head;
    int count;
} SlidingWindow;

typedef struct MaxWeightedSum {
    int transaction_id;
    double max_weighted_sum;
} MaxWeightedSum;

SlidingWindow* sliding_windows;
MaxWeightedSum* max_weighted_sums;
pthread_mutex_t mutex;

void initialize_transaction_processing() {
    sliding_windows = (SlidingWindow*)calloc(MAX_PRIORITY + 1, sizeof(SlidingWindow));
    max_weighted_sums = (MaxWeightedSum*)malloc(sizeof(MaxWeightedSum) * MAX_PRIORITY);
    pthread_mutex_init(&mutex, NULL);

    for (int i = 1; i <= MAX_PRIORITY; ++i) {
        sliding_windows[i].head = 0;
        sliding_windows[i].count = 0;
        max_weighted_sums[i].transaction_id = -1;
        max_weighted_sums[i].max_weighted_sum = 0.0;
    }
}

void update_sliding_window(int priority, Transaction* transaction) {
    pthread_mutex_lock(&mutex);

    int index = (sliding_windows[priority].head + sliding_windows[priority].count++) % SLIDING_WINDOW_SIZE;
    sliding_windows[priority].transactions[index] = *transaction;

    if (sliding_windows[priority].count > SLIDING_WINDOW_SIZE) {
        sliding_windows[priority].count = SLIDING_WINDOW_SIZE;
        sliding_windows[priority].head = (sliding_windows[priority].head + 1) % SLIDING_WINDOW_SIZE;
    }

    double weighted_sum = transaction->amount * transaction->priority_level;
    if (weighted_sum > max_weighted_sums[priority].max_weighted_sum) {
        max_weighted_sums[priority].transaction_id = transaction->id;
        max_weighted_sums[priority].max_weighted_sum = weighted_sum;
    }

    pthread_mutex_unlock(&mutex);
}

MaxWeightedSum get_max_weighted_sum(int priority) {
    MaxWeightedSum result;
    pthread_mutex_lock(&mutex);

    if (max_weighted_sums[priority].transaction_id == -1) {
        result.transaction_id = 0;
        result.max_weighted_sum = 0.0;
    } else {
        result = max_weighted_sums[priority];
    }

    pthread_mutex_unlock(&mutex);
    return result;
}

void validate_transaction(Transaction* transaction) {
    // Placeholder for external data source validation
    // Implement actual validation logic here
}

double process_transactions(Transaction* transactions, int count) {
    double total_weighted_sum = 0.0;

    initialize_transaction_processing();

    for (int i = 0; i < count; ++i) {
        validate_transaction(&transactions[i]);
        update_sliding_window(transactions[i].priority_level, &transactions[i]);
        MaxWeightedSum max_weighted = get_max_weighted_sum(transactions[i].priority_level);
        total_weighted_sum += max_weighted.max_weighted_sum;
    }

    pthread_mutex_destroy(&mutex);
    free(sliding_windows);
    free(max_weighted_sums);

    return total_weighted_sum;
}

int main() {
    // Example usage
    Transaction transactions[] = {
        {1, time(NULL), 100.0, 5},
        {2, time(NULL) + 1, 200.0, 7},
        // Add more transactions as needed
    };

    int count = sizeof(transactions) / sizeof(transactions[0]);
    double result = process_transactions(transactions, count);
    printf("Total weighted sum for last 3 seconds: %.2f\n", result);

    return 0;
}
