void process_events(Event** events, size_t* event_count, DynamicArray* reviewed_events) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < *event_count; ++i) {
        if (events[i]->timestamp + WINDOW_SIZE < current_time) {
            free(events[i]);
            events[i] = NULL;
            (*event_count)--;
            i--;
        } else if (strcmp(events[i]->hash, reviewed_events->elements[0]) == 0) {
            // Handle reviewed event first
            process_event(events[i]);
        }
    }

    for (size_t i = 0; i < *event_count; ++i) {
        if (!events[i]) continue;
        if (events[i]->priority > highest_priority) {
            highest_priority = events[i]->priority;
            highest_priority_id = events[i]->id;
        }
    }

    size_t reviewed_count = reviewed_events->count;
    for (size_t i = 0; i < *event_count && reviewed_count < MAX_REVIEWED_EVENTS; ++i) {
        if (!events[i]) continue;
        reviewed_events->elements[reviewed_count++] = events[i];
        events[i] = NULL;
        (*event_count)--;
    }
}

void cleanup_expired_events(Event** events, size_t* event_count) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < *event_count; ++i) {
        if (events[i]->timestamp + WINDOW_SIZE < current_time) {
            free(events[i]);
            events[i] = NULL;
            (*event_count)--;
            i--;
        }
    }
}

void* process_batch_of_strings(char** strings, size_t count, DynamicArray* reviewed_events) {
    Event** events = (Event**)malloc(count * sizeof(Event*));
    if (!events) return NULL;

    for (size_t i = 0; i < count; ++i) {
        Event* event = (Event*)malloc(sizeof(Event));
        if (!event) {
            free(events);
            return NULL;
        }
        event->id = generate_unique_id();
        event->timestamp = time(NULL);
        event->priority = calculate_priority(strings[i]);
        event->hash = hash_string(strings[i], 32); // Example hash length

        events[i] = event;
    }

    process_events(events, &count, reviewed_events);

    free(events);
    return NULL;
}

void* background_thread(void* arg) {
    DynamicArray* reviewed_events = create_dynamic_array(MAX_REVIEWED_EVENTS);
    Event** events = (Event**)malloc(MAX_EVENTS * sizeof(Event*));
    if (!events || !reviewed_events) {
        destroy_dynamic_array(reviewed_events);
        free(events);
        return NULL;
    }

    while (1) {
        size_t count = read_event_batch(events, MAX_EVENTS);
        process_batch_of_strings((char**)(void*)events, count, reviewed_events);
        cleanup_expired_events(events, &count);
        usleep(100000); // Sleep for 100ms
    }

    destroy_dynamic_array(reviewed_events);
    free(events);
    return NULL;
}

int main() {
    pthread_t tid;
    if (pthread_create(&tid, NULL, background_thread, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    // Wait for the background thread to finish
    pthread_join(tid, NULL);

    return 0;
}
