NFAPI_CRC_INDICATION_PDU_T** create_crc_indications(int N, int global_seed) {
    NFAPI_CRC_INDICATION_PDU_T** crc_indications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_indications) {
        log_error("Failed to allocate memory for CRC indications");
        return NULL;
    }

    srand(time(NULL) + global_seed);
    int rnti_count = 0;

    while (rnti_count < N) {
        RNTI new_rnti = generate_unique_rnti();
        if (new_rnti == INVALID_RNTI) {
            log_warning("Failed to generate unique RNTI");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            log_error("Failed to allocate memory for CRC indication PDU");
            free(crc_indications);
            return NULL;
        }

        new_pdu->ue_info = get_rx_ue_information(new_rnti);
        new_pdu->rnti = new_rnti;
        new_pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRC flag

        crc_indications[rnti_count] = new_pdu;
        rnti_count++;
    }

    if (rnti_count < N) {
        for (int i = 0; i < rnti_count; i++) {
            free(crc_indications[i]);
        }
        free(crc_indications);
        log_error("Failed to create sufficient unique RNTIs");
        return NULL;
    }

    return crc_indications;
}

void destroy_crc_indications(NFAPI_CRC_INDICATION_PDU_T** crc_indications, int N) {
    for (int i = 0; i < N; i++) {
        free(crc_indications[i]);
    }
    free(crc_indications);
}

CRC_Indications_Stats get_crc_indications_stats(NFAPI_CRC_INDICATION_PDU_T** crc_indications, int N) {
    CRC_Indications_Stats stats = {0};
    for (int i = 0; i < N; i++) {
        stats.total_count++;
        if (crc_indications[i]->crc_indication.crcflag) {
            stats.crc_set_count++;
        }
    }
    return stats;
}
