#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 10000
#define MAX_IP_ADDRESSES 256

typedef struct {
    unsigned int source_ip;
    unsigned int destination_ip;
    char *payload;
    size_t payload_size;
} NetworkDataPacket;

NetworkDataPacket **packet_array = NULL;
int packet_count = 0;
pthread_mutex_t packet_lock = PTHREAD_MUTEX_INITIALIZER;

int NetworkDataPacketAssembler(int source_ip, int destination_ip, const void *payload, size_t payload_size) {
    pthread_mutex_lock(&packet_lock);
    if (packet_count >= MAX_PACKETS) {
        fprintf(stderr, "Error: Maximum number of packets reached.\n");
        pthread_mutex_unlock(&packet_lock);
        return -1;
    }

    NetworkDataPacket *new_packet = (NetworkDataPacket *)malloc(sizeof(NetworkDataPacket));
    if (new_packet == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for new packet.\n");
        pthread_mutex_unlock(&packet_lock);
        return -2;
    }

    new_packet->source_ip = source_ip;
    new_packet->destination_ip = destination_ip;
    new_packet->payload_size = payload_size;
    new_packet->payload = (char *)malloc(payload_size);
    if (new_packet->payload == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for packet payload.\n");
        free(new_packet);
        pthread_mutex_unlock(&packet_lock);
        return -3;
    }

    memcpy(new_packet->payload, payload, payload_size);

    if (packet_array == NULL) {
        packet_array = (NetworkDataPacket **)malloc(MAX_IP_ADDRESSES * sizeof(NetworkDataPacket *));
        if (packet_array == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for packet array.\n");
            free(new_packet->payload);
            free(new_packet);
            pthread_mutex_unlock(&packet_lock);
            return -4;
        }
        memset(packet_array, 0, MAX_IP_ADDRESSES * sizeof(NetworkDataPacket *));
    }

    if (packet_array[source_ip] != NULL) {
        fprintf(stderr, "Error: Source IP already has a packet.\n");
        free(new_packet->payload);
        free(new_packet);
        pthread_mutex_unlock(&packet_lock);
        return -5;
    }

    packet_array[source_ip] = new_packet;
    packet_count++;

    pthread_mutex_unlock(&packet_lock);
    return 0;
}

void NetworkDataPacketDestructor() {
    pthread_mutex_lock(&packet_lock);
    if (packet_array != NULL) {
        for (int i = 0; i < MAX_IP_ADDRESSES; i++) {
            if (packet_array[i] != NULL) {
                free(packet_array[i]->payload);
                free(packet_array[i]);
            }
