#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
} List;

List* list_init() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int list_append(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }
    if (list->size == 0) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void list_free(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void log_creation(NFAPI_CRC_INDICATION_PDU_T data) {
    printf("Created: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRCFLAG);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_data() {
    NFAPI_CRC_INDICATION_PDU_T data;
    srand(time(NULL));
    data.RX_UE_INFORMATION_TAG = rand();
    data.RNTI = rand();
    data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    return data;
}

int main() {
    List* list = list_init();
    if (!list) {
        fprintf(stderr, "Failed to initialize list\n");
        return -1;
    }

    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data = generate_random_data();
        log_creation(data);
        if (list_append(list, data)) {
            fprintf(stderr, "Failed to append data to list\n");
            break;
        }
    }

    list_free(list);
    return 0;
}
