    }

    private void InitializeRequestPool()
    {
        lock (_lock)
        {
            _requestPool = new List<HTTP_REQUEST_RECORD>(_poolSize);
            for (int i = 0; i < _poolSize; i++)
            {
                var record = CreateHTTPRequestRecord();
                if (record != null)
                {
                    _requestPool.Add(record);
                }
                else
                {
                    Console.WriteLine("Failed to allocate HTTP_REQUEST_RECORD.");
                }
            }
        }
    }

    private HTTP_REQUEST_RECORD? CreateHTTPRequestRecord()
    {
        try
        {
            var record = new HTTP_REQUEST_RECORD
            {
                HTTP_REQUEST_HANDLE = Marshal.AllocHGlobal(16),
                REMOTE_URL = "http://example.com",
                LOCAL_PORT = 80,
                REQUEST_METHOD = "GET",
                RESPONSE_STATUS = 200,
                CRC_INDICATION_PDUS = new NFAPI_CRC_INDICATION_PDU_T[50000]
            };

            for (int i = 0; i < record.CRC_INDICATION_PDUS.Length; i++)
            {
                record.CRC_INDICATION_PDUS[i] = new NFAPI_CRC_INDICATION_PDU_T
                {
                    RX_UE_INFORMATION_TAG = _random.Next(),
                    RNTI = _random.Next(),
                    CRC_INDICATION_REL8_TAG = _random.Next(),
                    CRCFLAG = _random.Next(2) == 0
                };
            }

            return record;
        }
        catch (OutOfMemoryException)
        {
            Console.WriteLine("Out of memory while allocating HTTP_REQUEST_RECORD.");
            return null;
        }
    }

    public async Task<HTTP_REQUEST_RECORD?> GetRequestAsync()
    {
        lock (_lock)
        {
            if (!_requestPool.Any())
            {
                await ExpandPoolAsync();
            }

            var request = _requestPool.First();
            _requestPool.RemoveAt(0);
            return request;
        }
    }

    private async Task ExpandPoolAsync()
    {
        for (int i = 0; i < _poolSize; i++)
        {
            var record = CreateHTTPRequestRecord();
            if (record != null)
            {
                lock (_lock)
                {
                    _requestPool.Add(record);
                }
            }
            else
            {
                Console.WriteLine("Failed to allocate HTTP_REQUEST_RECORD during expansion.");
            }
        }
    }

    public void ReturnRequest(HTTP_REQUEST_RECORD record)
    {
        lock (_lock)
        {
            _requestPool.Add(record);
        }
    }

