#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_EVENTS 20000
#define SLIDING_WINDOW_MINUTES 60
#define MAX_HIGH_PRIORITY_EVENTS 400
#define REVIEWED_EVENT_LIMIT 0.15
#define MAX_HASH_RETRIES 4
#define MD5_DIGEST_LENGTH 16

typedef struct {
    unsigned int id;
    time_t timestamp;
    int priority;
    char* data;
} Event;

typedef struct Node {
    Event event;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned int hashFunction(const char* str) {
    unsigned int hash = 0;
    for (size_t i = 0; str[i] != '\0'; i++) {
        hash = hash * 31 + str[i];
    }
    return hash % capacity;
}

HashTable* createHashTable(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    return table;
}

void insertHashTable(HashTable* table, Event event) {
    unsigned int hash = hashFunction(event.data);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->event = event;
    newNode->next = NULL;

    if (table->buckets[hash] == NULL) {
        table->buckets[hash] = newNode;
    } else {
        Node* temp = table->buckets[hash];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    table->size++;
}

int searchHashTable(HashTable* table, const char* data) {
    unsigned int hash = hashFunction(data);
    Node* temp = table->buckets[hash];
    while (temp != NULL) {
        if (strcmp(temp->event.data, data) == 0) {
            return 1;
        }
        temp = temp->next;
    }
    return 0;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

void processEvents(Event* events, size_t count) {
    HashTable* hashTable = createHashTable(1000); // Initial capacity
    Event* reviewedEvents[MAX_EVENTS * REVIEWED_EVENT_LIMIT];
    size_t reviewedCount = 0;

    for (size_t i = 0; i < count; i++) {
        if (events[i].timestamp + SLIDING_WINDOW_MINUTES <= time(NULL)) continue;
        if (events[i].priority > MAX_HIGH_PRIORITY_EVENTS) continue;
        if (searchHashTable(hashTable, events[i].data)) {
            for (int j = 0; j < MAX_HASH_RETRIES; j++) {
                // Retry hashing logic here
            }
            printf("Duplicate event detected\n");
            continue;
        }

        if (events[i].priority == 1) { // Highest priority
            reviewedEvents[reviewedCount++] = &events[i];
        } else {
            insertHashTable(hashTable, events[i]);
        }
    }

    // Process reviewed events first
    for (size_t i = 0; i < reviewedCount; i++) {
        printf("Processing event ID %u\n", reviewedEvents[i]->id);
    }

    // Process other events
    for (size_t i = 0; i < count; i++) {
        if (events[i].priority > 1) {
            printf("Processing event ID %u\n", events[i].id);
        }
    }

    destroyHashTable(hashTable);
}

int main() {
    Event* events = (Event*)malloc(MAX_EVENTS * sizeof(Event));
    // Populate events array with data
    processEvents(events, MAX_EVENTS);
    free(events);
    return 0;
}
