// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_and_populate_list(int N, NFAPI_CRC_INDICATION_PDU_T** list) {
    // Initialize variables for error checking and logging
    int successful_allocations = 0;
    int failed_allocations = 0;
    FILE* log_file = fopen("audit_log.txt", "a");

    // Allocate memory for the list of structures
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        fprintf(log_file, "Failed to allocate memory for %d elements\n", N);
        fclose(log_file);
        return -1;
    }

    // Populate the list of structures concurrently using multi-threading
    pthread_t threads[N];
    struct thread_data {
        int index;
        NFAPI_CRC_INDICATION_PDU_T* list;
    } thread_data[N];

    for (int i = 0; i < N; i++) {
        thread_data[i].index = i;
        thread_data[i].list = *list;

        if (pthread_create(&threads[i], NULL, populate_structure, &thread_data[i]) != 0) {
            fprintf(log_file, "Failed to create thread for element %d\n", i);
            failed_allocations++;
        }
    }

    // Join the threads and handle any errors
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);

        if (thread_data[i].result == -1) {
            fprintf(log_file, "Failed to populate element %d\n", thread_data[i].index);
            failed_allocations++;
        } else {
            successful_allocations++;
        }
    }

    // Log the number of successful allocations and failures
    fprintf(log_file, "Successful allocations: %d\n", successful_allocations);
    fprintf(log_file, "Failed allocations: %d\n", failed_allocations);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Thread function to populate a single NFAPI_CRC_INDICATION_PDU_T structure
void* populate_structure(void* arg) {
    struct thread_data* data = (struct thread_data*)arg;

    NFAPI_CRC_INDICATION_PDU_T* pdu = &data->list[data->index];

