#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

typedef struct ip_address {
    char hostname[256];
    struct in_addr ip;
    struct ip_address *next;
} ip_address;

ip_address* resolve_dns(const char *hostname, int timeout) {
    ip_address *head = NULL, **tail = &head;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    p = res;
    while (p != NULL) {
        ip_address *new_node = (ip_address *)malloc(sizeof(ip_address));
        if (new_node == NULL) {
            perror("Memory allocation failed");
            freeaddrinfo(res);
            return head;
        }

        new_node->next = NULL;
        strncpy(new_node->hostname, hostname, sizeof(new_node->hostname) - 1);
        new_node->hostname[sizeof(new_node->hostname) - 1] = '\0';
        memcpy(&new_node->ip, &((struct sockaddr_in *)p->ai_addr)->sin_addr, sizeof(struct in_addr));

        *tail = new_node;
        tail = &new_node->next;

        p = p->ai_next;
    }

    freeaddrinfo(res);
    return head;
}

void print_ip_addresses(ip_address *list) {
    while (list != NULL) {
        printf("Hostname: %s, IP Address: %s\n", list->hostname, inet_ntoa(list->ip));
        list = list->next;
    }
}

int main() {
    ip_address *result = resolve_dns("example.com", 5);
    if (result != NULL) {
        print_ip_addresses(result);
        // Free the allocated memory
        while (result != NULL) {
            ip_address *temp = result;
            result = result->next;
            free(temp);
        }
    } else {
        printf("Failed to resolve DNS.\n");
    }
    return 0;
}
```

