        if (!ranges.TryGetValue(rangeId, out range))
            throw new ArgumentException("Range with the specified ID does not exist.");

        switch (range.Distribution)
        {
            case Distribution.Uniform:
                return inclusive ? random.NextSingle(range.Min, range.Max) : random.NextDouble(range.Min, range.Max);
            case Distribution.Normal:
                // Implement normal distribution generation
                break;
            default:
                throw new ArgumentException("Unsupported distribution.");
        }

        throw new NotImplementedException();
    }

    public int GenerateRandomInt(int rangeId, bool inclusive)
    {
        Range range;
        if (!ranges.TryGetValue(rangeId, out range))
            throw new ArgumentException("Range with the specified ID does not exist.");

        switch (range.Distribution)
        {
            case Distribution.Uniform:
                return inclusive ? random.Next((int)range.Min, (int)range.Max + 1) : random.Next((int)range.Min, (int)range.Max);
            case Distribution.Normal:
