#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 100000

typedef struct {
    // Define packet header structure here
    uint32_t src_ip;
    uint32_t dest_ip;
    uint16_t src_port;
    uint16_t dest_port;
    size_t payload_size;
} PacketHeader;

typedef struct {
    PacketHeader header;
    char* payload;
} UDPPacket;

UDPPacket** packet_pool = NULL;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

int init_packet_pool() {
    pthread_mutex_lock(&pool_mutex);
    if (packet_pool != NULL) {
        pthread_mutex_unlock(&pool_mutex);
        return -1; // Pool already initialized
    }

    packet_pool = (UDPPacket**)malloc(MAX_PACKETS * sizeof(UDPPacket*));
    if (packet_pool == NULL) {
        pthread_mutex_unlock(&pool_mutex);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < MAX_PACKETS; i++) {
        packet_pool[i] = (UDPPacket*)malloc(sizeof(UDPPacket));
        if (packet_pool[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free(packet_pool[j]);
            }
            free(packet_pool);
            packet_pool = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return -3; // Memory allocation failed
        }

        packet_pool[i]->payload = (char*)malloc(MAX_PAYLOAD_SIZE); // Define MAX_PAYLOAD_SIZE
        if (packet_pool[i]->payload == NULL) {
            for (int j = 0; j <= i; j++) {
                free(packet_pool[j]->payload);
                free(packet_pool[j]);
            }
            free(packet_pool);
            packet_pool = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return -4; // Memory allocation failed
        }
    }

    pthread_mutex_unlock(&pool_mutex);
    return 0; // Success
}

UDPPacket* allocate_packet() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packet_pool[i] != NULL) {
            UDPPacket* packet = packet_pool[i];
            packet_pool[i] = NULL;
            pthread_mutex_unlock(&pool_mutex);
            return packet;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return NULL; // No available packets
}

void free_packet(UDPPacket* packet) {
    pthread_mutex_lock(&pool_mutex);
    int found = 0;
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packet_pool[i] == NULL) {
            packet_pool[i] = packet;
            found = 1;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);

    if (!found) {
        // Handle the case when no space in pool is available
    }

    free(packet->payload);
    free(packet);
}

int main() {
    if (init_packet_pool() != 0) {
        return -1; // Initialization failed
    }

    // Example usage
    UDPPacket* packet = allocate_packet();
    if (packet != NULL) {
        // Initialize packet header and payload
        memset(&packet->header, 0, sizeof(PacketHeader));
        strcpy(packet->payload, "Hello, world!");

        // Use the packet...

        free_packet(packet);
    }

    return 0;
}
```

This code snippet provides a basic framework for managing a pool of UDP packets in a C program. It includes functions to initialize the packet pool, allocate a packet from the pool, and free a packet back to the pool. The use of mutexes ensures thread safety when accessing the packet pool. Error handling is implemented to manage memory allocation failures gracefully. This code can be integrated into an existing network server with minimal changes.']

