#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <unistd.h>

typedef struct ip_node {
    char hostname[NI_MAXHOST];
    char ip_address[INET6_ADDRSTRLEN];
    struct ip_node *next;
} IPNode;

typedef struct {
    pthread_mutex_t lock;
    int max_concurrent_queries;
    int current_queries;
    IPNode *cache;
} DNSResolver;

DNSResolver* create_dns_resolver(int max_queries) {
    DNSResolver *resolver = (DNSResolver*) malloc(sizeof(DNSResolver));
    pthread_mutex_init(&resolver->lock, NULL);
    resolver->max_concurrent_queries = max_queries;
    resolver->current_queries = 0;
    resolver->cache = NULL;
    return resolver;
}

void destroy_dns_resolver(DNSResolver *resolver) {
    IPNode *node = resolver->cache;
    while (node) {
        IPNode *next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&resolver->lock);
    free(resolver);
}

int resolve_hostname(DNSResolver *resolver, const char *hostname, char ip_address[INET6_ADDRSTRLEN], int timeout) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    pthread_mutex_lock(&resolver->lock);
    if (resolver->current_queries >= resolver->max_concurrent_queries) {
        pthread_mutex_unlock(&resolver->lock);
        return -EAGAIN;
    }
    resolver->current_queries++;
    pthread_mutex_unlock(&resolver->lock);

    status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        pthread_mutex_lock(&resolver->lock);
        resolver->current_queries--;
        pthread_mutex_unlock(&resolver->lock);
        return -ENXIO;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET || p->ai_family == AF_INET6) {
            void *addr;
            char ip_str[INET6_ADDRSTRLEN];
            if (p->ai_family == AF_INET)
                addr = &((struct sockaddr_in*)p->ai_addr)->sin_addr;
            else
                addr = &((struct sockaddr_in6*)p->ai_addr)->sin6_addr;

            inet_ntop(p->ai_family, addr, ip_str, sizeof(ip_str));
            strcpy(ip_address, ip_str);
            freeaddrinfo(res);
            return 0;
        }
    }

    freeaddrinfo(res);
    pthread_mutex_lock(&resolver->lock);
    resolver->current_queries--;
    pthread_mutex_unlock(&resolver->lock);
    return -ENXIO;
}

void log_resolution(const char *hostname, const char *ip_address, int status) {
    if (status == 0)
        printf("Resolved %s to %s\n", hostname, ip_address);
    else
        printf("Failed to resolve %s: Error %d\n", hostname, status);
}
