#define MAX_EVENTS 10000
#define WINDOW_SIZE_SEC (15 * 60)
#define MAX_HIGH_PRIORITY_EVENTS 200

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    int priority;
    int id;
    struct Event *next;
} Event;

typedef struct {
    Event **buckets;
    size_t bucket_count;
} HashTable;

int hash_function(int rnti, size_t bucket_count) {
    return abs(rnti) % bucket_count;
}

void add_event_to_hash_table(HashTable *hash_table, Event *event) {
    int index = hash_function(event->pdu.RNTI, hash_table->bucket_count);
    event->next = hash_table->buckets[index];
    hash_table->buckets[index] = event;
}

Event* find_event_in_hash_table(HashTable *hash_table, int rnti) {
    int index = hash_function(rnti, hash_table->bucket_count);
    Event *current = hash_table->buckets[index];
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void initialize_event_feed(HashTable *hash_table, int bucket_count) {
    hash_table->buckets = (Event **)malloc(bucket_count * sizeof(Event *));
    if (hash_table->buckets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < bucket_count; ++i) {
        hash_table->buckets[i] = NULL;
    }
}

void add_event(HashTable *hash_table, NFAPI_CRC_INDICATION_PDU_T pdu, int priority, int id) {
    if (id >= MAX_EVENTS || priority > MAX_HIGH_PRIORITY_EVENTS) {
        return;
    }

    Event *new_event = (Event *)malloc(sizeof(Event));
    if (new_event == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_event->pdu = pdu;
    new_event->timestamp = time(NULL);
    new_event->priority = priority;
    new_event->id = id;

    add_event_to_hash_table(hash_table, new_event);
}

void evict_old_events(HashTable *hash_table) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < hash_table->bucket_count; ++i) {
        Event **current = &hash_table->buckets[i];
        while (*current != NULL) {
            if (difftime(current_time, (*current)->timestamp) > WINDOW_SIZE_SEC) {
                Event *to_delete = *current;
                *current = to_delete->next;
                free(to_delete);
            } else {
                current = &(*current)->next;
            }
        }
    }
}

void serialize_to_file(HashTable *hash_table, const char *filename, const char *format) {
    // Implement serialization logic here
}

int main() {
    HashTable hash_table;
    initialize_event_feed(&hash_table, 1024);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3};
    add_event(&hash_table, pdu, 5, 0);
    evict_old_events(&hash_table);

    serialize_to_file(&hash_table, "events.bin", "binary");

    return 0;
}
