    memcpy(&node->packet, packet, sizeof(UDPPacket));
    memcpy(&node->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Check if total RNTI exceeds 90% limit
    if (total_rnti.fetch_add(node->pdu.RNTI) > MAX_PACKETS * 0.9 * node->pdu.RNTI) {
