    pthread_t threads[MAX_PACKETS];
    UDPPacket packets[MAX_PACKETS];

    // Populate packets with data and create threads to process them concurrently
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (pthread_create(&threads[i], NULL, process_packet, &packets[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(1);
        }
    }

    // Wait for all threads to finish
