    current_stat->crc_indication_pdu.RNTI = /* Set a valid RNTI */;
    current_stat->crc_indication_pdu.crc_indication_pdu.CRCFLAG = rand() % 2; // Random CRC flag

    generator->used_size++;
    pthread_mutex_unlock(&generator->lock);
}

void cleanup(StatisticGenerator* generator) {
    if (generator->stats_array && generator->allocated_size > STACK_THRESHOLD) {
        free(generator->stats_array);
    }
    pthread_mutex_destroy(&generator->lock);
}

int main() {
    StatisticGenerator generator;
