typedef struct {
    int cell_identifier;
    time_t timestamp;
    RRC_CONNECTION_INFORMATION* rrc_info_list;
    int rrc_info_count;
    char nas_message_tag[64];
} LTE_PHY_METRICS;

void* generate_lte_phy_metrics(int num_metrics) {
    if (num_metrics <= 0 || num_metrics > MAX_METRICS) {
        fprintf(stderr, "Invalid number of metrics.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    LTE_PHY_METRICS* metrics_array;
    if (num_metrics <= STACK_ALLOC_THRESHOLD) {
        metrics_array = alloca(num_metrics * sizeof(LTE_PHY_METRICS));
    } else {
        metrics_array = malloc(num_metrics * sizeof(LTE_PHY_METRICS));
        if (!metrics_array) {
            perror("Failed to allocate memory for LTE PHY Metrics array.");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    for (int i = 0; i < num_metrics; ++i) {
        metrics_array[i].cell_identifier = rand() % 1024;
        metrics_array[i].timestamp = time(NULL);

        int rrc_count = rand() % 5 + 1;
        metrics_array[i].rrc_info_list = malloc(rrc_count * sizeof(RRC_CONNECTION_INFORMATION));
        if (!metrics_array[i].rrc_info_list) {
            perror("Failed to allocate memory for RRC Connection Information list.");
            for (int j = 0; j < i; ++j) {
                free(metrics_array[j].rrc_info_list);
            }
            if (num_metrics > STACK_ALLOC_THRESHOLD) {
                free(metrics_array);
            }
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (int j = 0; j < rrc_count; ++j) {
            metrics_array[i].rrc_info_list[j].mme_id = rand() % 128;
            metrics_array[i].rrc_info_list[j].eps_bearer_id = rand() % 32;
            snprintf(metrics_array[i].rrc_info_list[j].srb_state, sizeof(metrics_array[i].rrc_info_list[j].srb_state), "SRB%d", rand() % 4);
        }

        metrics_array[i].rrc_info_count = rrc_count;
        snprintf(metrics_array[i].nas_message_tag, sizeof(metrics_array[i].nas_message_tag), "MSG%d_%d", i, rand() % 100);
    }

    pthread_mutex_unlock(&mutex);

    // Log generation details
    printf("Generated %d LTE PHY Metrics.\n", num_metrics);

    return metrics_array;
}

int main() {
    int num_metrics = 15;
    LTE_PHY_METRICS* metrics = (LTE_PHY_METRICS*)generate_lte_phy_metrics(num_metrics);
    if (metrics) {
        for (int i = 0; i < num_metrics; ++i) {
            printf("Cell Identifier: %d, Timestamp: %ld\n", metrics[i].cell_identifier, metrics[i].timestamp);
            for (int j = 0; j < metrics[i].rrc_info_count; ++j) {
                printf("  MME ID: %d, EPS Bearer ID: %d, SRB State: %s\n", 
                       metrics[i].rrc_info_list[j].mme_id, 
                       metrics[i].rrc_info_list[j].eps_bearer_id, 
                       metrics[i].rrc_info_list[j].srb_state);
            }
            free(metrics[i].rrc_info_list);
        }
        if (num_metrics > STACK_ALLOC_THRESHOLD) {
            free(metrics);
        }
    }

    return 0;
}
