#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define PACKET_AGE_THRESHOLD 1000 // 1 second in milliseconds
#define WINDOW_SIZE 10 // 10 milliseconds

typedef struct {
    int packet_id;
    time_t timestamp;
    int score;
} Packet;

typedef struct {
    Packet packets[WINDOW_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PacketQueue;

void init_queue(PacketQueue *queue) {
    queue->head = 0;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue_packet(PacketQueue *queue, Packet packet) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == WINDOW_SIZE) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    queue->packets[(queue->head + queue->count) % WINDOW_SIZE] = packet;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

Packet dequeue_packet(PacketQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    Packet packet = queue->packets[queue->head];
    queue->head = (queue->head + 1) % WINDOW_SIZE;
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

void *process_packets(void *arg) {
    PacketQueue *queue = (PacketQueue *)arg;
    int max_score = INT_MIN;
    int max_id = -1;

    while (1) {
        Packet packet = dequeue_packet(queue);

        if (time(NULL) - packet.timestamp > PACKET_AGE_THRESHOLD) {
            continue; // Skip packets that are too old
        }

        if (packet.score > max_score) {
            max_score = packet.score;
            max_id = packet.packet_id;
        }
    }

    return NULL;
}

int main() {
    PacketQueue queue;
    init_queue(&queue);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, process_packets, &queue);
    pthread_create(&thread2, NULL, process_packets, &queue);

    // Simulate adding packets to the queue
    for (int i = 0; i < 50; i++) {
        Packet packet = {i, time(NULL), rand() % 100};
        enqueue_packet(&queue, packet);
        sleep(1); // Simulate time passing between packets
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
