    size_t payload_size;
    // Add other essential metadata here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    atomic_int rnti;
    atomic_bool crc_flag;
} PacketPoolEntry;

PacketPoolEntry* packet_pool = NULL;
size_t pool_size = 0;
atomic_size_t used_entries = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void init_packet_pool(size_t size) {
    pool_size = size;
    packet_pool = (PacketPoolEntry*)malloc(pool_size * sizeof(PacketPoolEntry));
    if (!packet_pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void destroy_packet_pool() {
    free(packet_pool);
}

int allocate_packet() {
    pthread_mutex_lock(&pool_lock);
    size_t index = atomic_load(&used_entries);
    if (index < pool_size) {
        packet_pool[index].rnti = 0;
        packet_pool[index].crc_flag = false;
        atomic_fetch_add(&used_entries, 1);
        pthread_mutex_unlock(&pool_lock);
        return index;
    }
    pthread_mutex_unlock(&pool_lock);
    return -1;
}

void free_packet(size_t index) {
    if (index < pool_size) {
        packet_pool[index].rnti = 0;
        packet_pool[index].crc_flag = false;
        atomic_fetch_sub(&used_entries, 1);
    }
}

void* process_packet(void* arg) {
    size_t index = *(size_t*)arg;
    // Process the packet here
    free_packet(index);
    return NULL;
}

int main() {
    init_packet_pool(100000);

    pthread_t threads[10];
    for (size_t i = 0; i < 10; ++i) {
        size_t* index = malloc(sizeof(size_t));
        *index = allocate_packet();
        if (*index != -1) {
            pthread_create(&threads[i], NULL, process_packet, index);
        } else {
            fprintf(stderr, "Failed to allocate packet\n");
            free(index);
        }
    }

    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_packet_pool();
    return 0;
}
