// Define a simple memory pool structure
typedef struct MemoryPool {
    void* memory_block;
    size_t block_size;
    int free_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, int num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool)
        return NULL;

    pool->memory_block = malloc(block_size * num_blocks);
    if (!pool->memory_block) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->free_count = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_count > 0) {
        void* ptr = pool->memory_block + ((pool->block_size * (--pool->free_count)));
        pthread_mutex_unlock(&pool->lock);
        return ptr;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    int index = ((char*)ptr - (char*)pool->memory_block) / pool->block_size;
    if (index >= 0 && index < pool->free_count) {
        pool->free_count++;
    }
    pthread_mutex_unlock(&pool->lock);
}

