#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    double max_weight;
    int max_id;
    time_t last_reset;
    int duplicate_count;
} FilterContext;

void initFilterContext(FilterContext *ctx) {
    ctx->count = 0;
    ctx->max_weight = 0.0;
    ctx->max_id = -1;
    ctx->last_reset = time(NULL);
    ctx->duplicate_count = 0;
}

int isDuplicate(Transaction *tx, FilterContext *ctx, double threshold) {
    for (int i = 0; i < ctx->count; i++) {
        if (abs(tx->id - ctx->transactions[i].id) <= threshold && tx->timestamp == ctx->transactions[i].timestamp) {
            return 1;
        }
    }
    return 0;
}

void addTransaction(Transaction *tx, FilterContext *ctx, double threshold, int logService(int id, const char *event)) {
    if (isDuplicate(tx, ctx, threshold)) {
        ctx->duplicate_count++;
        logService(tx->id, "DUPLICATE");
        return;
    }

    ctx->transactions[ctx->count++] = *tx;

    double weighted_sum = 0.0;
    for (int i = 0; i < ctx->count; i++) {
        weighted_sum += ctx->transactions[i].weight;
    }

    if (weighted_sum > ctx->max_weight) {
        ctx->max_weight = weighted_sum;
        ctx->max_id = tx->id;
    }

    time_t current_time = time(NULL);
    if (current_time - ctx->last_reset > 5) {
        initFilterContext(ctx);
    }
}

double getMaxWeight(FilterContext *ctx) {
    return ctx->max_weight;
}

int getMaxId(FilterContext *ctx) {
    return ctx->max_id;
}

int logService(int id, const char *event) {
    printf("Transaction %d: %s\n", id, event);
    return 0;
}

int main() {
    FilterContext ctx;
    initFilterContext(&ctx);

    Transaction tx1 = {1, 2.5, time(NULL)};
    addTransaction(&tx1, &ctx, 10.0, logService);

    Transaction tx2 = {2, 3.0, time(NULL)};
    addTransaction(&tx2, &ctx, 10.0, logService);

    printf("Max Weight: %.2f\n", getMaxWeight(&ctx));
    printf("Max ID: %d\n", getMaxId(&ctx));

    return 0;
}
```

