public class CustomRandomGenerator
{
    private Random _random;
    private long _seed;

    public CustomRandomGenerator(long seed = 0)
    {
        _seed = seed;
        _random = new Random(_seed);
    }

    public void SetSeed(long seed)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public int Next(int minValue, int maxValue)
    {
        return _random.Next(minValue, maxValue);
    }

    public double Next(double minValue, double maxValue)
    {
        return _random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public T[] NextArray<T>(int length, Func<T> valueGenerator)
    {
        var array = new T[length];
        for (int i = 0; i < length; i++)
        {
            array[i] = valueGenerator();
        }
        return array;
    }
}

public class HTTPRequestPool
{
    private int _poolSize;
    private ConcurrentQueue<HTTP_REQUEST_RECORD> _requestQueue;
    private CustomRandomGenerator _randomGenerator;

    public HTTPRequestPool(int poolSize)
    {
        _poolSize = poolSize;
        _requestQueue = new ConcurrentQueue<HTTP_REQUEST_RECORD>();
        _randomGenerator = new CustomRandomGenerator();
    }

    public void AddRequest(HTTP_REQUEST_RECORD request)
    {
        // Add a request to the queue
    }

    public async Task ProcessRequestsAsync()
    {
        while (true)
        {
            if (_requestQueue.TryDequeue(out var request))
            {
                await ProcessRequestAsync(request);
            }
            else
            {
                // Wait for new requests
                await Task.Delay(_randomGenerator.Next(100, 500));
            }
        }
    }

    private async Task ProcessRequestAsync(HTTP_REQUEST_RECORD request)
    {
        using (var client = new HttpClient())
        {
            try
            {
                var response = await client.SendAsync(new HttpRequestMessage
                {
                    Method = new HttpMethod(request.REQUEST_METHOD),
                    RequestUri = new Uri(request.REMOTE_URL)
                });

                if (response.IsSuccessStatusCode)
                {
                    request.RESPONSE_STATUS = (int)response.StatusCode;
                }
                else
                {
                    request.RESPONSE_STATUS = (int)response.StatusCode;
                }
            }
            catch (Exception ex)
            {
                // Handle exceptions and logging
            }
        }
    }

    public void Resize(int newSize)
    {
        _poolSize = newSize;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var poolSize = 10; // Define pool size dynamically
        var requestPool = new HTTPRequestPool(poolSize);

        for (int i = 0; i < poolSize; i++)
