        strcpy(cache[cache_size].file_name, "example.txt");
        cache[cache_size].metadata = 12345;
        cache_size++;
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

int get_metadata(const char* file_name) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].file_name, file_name) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return cache[i].metadata;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1; // File not found
}

int update_metadata(const char* file_name, int new_metadata) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].file_name, file_name) == 0) {
            cache[i].metadata = new_metadata;
            pthread_mutex_unlock(&cache_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1; // File not found
}

int main() {
    pthread_t threads[MAX_CONCURRENT_IO];
    int i;

    if (pthread_mutex_init(&cache_lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return 1;
    }

    for (i = 0; i < MAX_CONCURRENT_IO; i++) {
        if (pthread_create(&threads[i], NULL, load_metadata, NULL) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    for (i = 0; i < MAX_CONCURRENT_IO; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Metadata for example.txt: %d\n", get_metadata("example.txt"));
    update_metadata("example.txt", 54321);
    printf("Updated metadata for example.txt: %d\n", get_metadata("example.txt"));

    pthread_mutex_destroy(&cache_lock);

    return 0;
}
