#include "NR_PDU_H_T.h"

typedef struct {
    NR_PDU_H_T *pdu_list;
    int list_size;
    int successful_allocations;
    int failed_allocations;
    FILE *log_file;
    pthread_mutex_t allocation_lock;
} NR_PDU_MANAGER;

int create_NR_pdu_manager(NR_PDU_MANAGER *manager, int N, const char *log_filename) {
    manager->list_size = N;
    manager->pdu_list = (NR_PDU_H_T *)malloc(sizeof(NR_PDU_H_T) * N);
    if (!manager->pdu_list) {
        return -1; // Memory allocation failed
    }
    manager->successful_allocations = 0;
    manager->failed_allocations = 0;
    manager->log_file = fopen(log_filename, "w");
    if (!manager->log_file) {
        free(manager->pdu_list);
        return -2; // Log file open failed
    }
    pthread_mutex_init(&manager->allocation_lock, NULL);
    return 0;
}

void *allocate_pdu(void *arg) {
    NR_PDU_MANAGER *manager = (NR_PDU_MANAGER *)arg;
    for (int i = manager->successful_allocations + manager->failed_allocations; i < manager->list_size; i++) {
        if (pthread_mutex_lock(&manager->allocation_lock)) {
            perror("Failed to lock allocation mutex");
            continue;
        }
        NR_PDU_H_T *pdu = (NR_PDU_H_T *)malloc(sizeof(NR_PDU_H_T));
        if (!pdu) {
            manager->failed_allocations++;
            pthread_mutex_unlock(&manager->allocation_lock);
            continue;
        }
        // Initialize pdu fields here
        manager->successful_allocations++;
        manager->pdu_list[i] = *pdu;
        free(pdu); // Free the temporary allocation since it's copied to the list
        if (pthread_mutex_unlock(&manager->allocation_lock)) {
            perror("Failed to unlock allocation mutex");
        }
    }
    return NULL;
}

int populate_pdu_list(NR_PDU_MANAGER *manager, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, allocate_pdu, manager)) {
            perror("Failed to create thread");
            return -3;
        }
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}

void validate_pdu_list(NR_PDU_MANAGER *manager) {
    // Implement validation logic here
}

void free_NR_pdu_manager(NR_PDU_MANAGER *manager) {
    for (int i = 0; i < manager->successful_allocations; i++) {
        // Free dynamically allocated fields in manager->pdu_list[i]
    }
    pthread_mutex_destroy(&manager->allocation_lock);
    fclose(manager->log_file);
    free(manager->pdu_list);
}

// Example usage
int main() {
    NR_PDU_MANAGER manager;
    if (create_NR_pdu_manager(&manager, 100, "allocation_log.txt") != 0) {
        return -1;
    }
    populate_pdu_list(&manager, 4);
    validate_pdu_list(&manager);
    free_NR_pdu_manager(&manager);
    return 0;
}
