public class CustomRandomGenerator
{
    private Random random;

    public CustomRandomGenerator(long seed)
    {
        random = new Random(seed);
    }

    public int NextInt(int min, int max, bool inclusive = false)
    {
        if (inclusive) return random.Next(min, max + 1);
        else return random.Next(min, max);
    }

    public double NextDouble(double min, double max, bool inclusive = false)
    {
        if (inclusive) return random.NextDouble() * (max - min) + min;
        else return random.NextDouble() * (max - min);
    }

    public T[] NextArray<T>(int length, Func<T> generator)
    {
        var array = new T[length];
        for (int i = 0; i < length; i++)
        {
            array[i] = generator();
        }
        return array;
    }

    public void SetSeed(long seed)
    {
        random = new Random(seed);
    }
}

public class HTTPRequestPool
{
    private List<HTTP_REQUEST_RECORD> pool;
    private int maxPayloadSize;

    public HTTPRequestPool(int size, int payloadSize)
    {
        pool = new List<HTTP_REQUEST_RECORD>(size);
        maxPayloadSize = payloadSize;
    }

    public bool AddRequest(HTTP_REQUEST_RECORD request)
    {
        if (request.Payloads.Length > maxPayloadSize) return false;
        lock (pool)
        {
            pool.Add(request);
        }
        return true;
    }

    public HTTP_REQUEST_RECORD GetRequest()
    {
        lock (pool)
        {
            if (pool.Count == 0) return default(HTTP_REQUEST_RECORD);
            var request = pool[0];
            pool.RemoveAt(0);
            return request;
        }
    }

    // Add other methods as per requirements
}

public class NetworkManager
{
    private HttpClient client;

    public NetworkManager()
    {
        client = new HttpClient();
    }

    public async Task<string> SendRequestAsync(HTTP_REQUEST_RECORD request)
    {
        var response = await client.SendAsync(new HttpRequestMessage(new HttpMethod(request.REQUEST_METHOD), request.REMOTE_URL));
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsStringAsync();
        }
        else
        {
            throw new Exception($"Request failed with status code: {response.StatusCode}");
        }
    }

    // Add other methods as per requirements
}

public class LogManager
{
    private Queue<string> logQueue;

    public LogManager()
    {
        logQueue = new Queue<string>();
    }

    public void Log(string message)
    {
        lock (logQueue)
        {
            logQueue.Enqueue(message);
        }
    }

    // Add other methods as per requirements
}

