#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_FD_POOL 1024

typedef struct {
    int fd;
    int protocol; // TCP or UDP
} FileDescriptor;

FileDescriptor fd_pool[MAX_FD_POOL];
int pool_size = 0;
int max_concurrent_allocations = 10;

void init_fd_pool() {
    for (int i = 0; i < MAX_FD_POOL; i++) {
        fd_pool[i].fd = -1;
    }
}

int get_available_fd(int protocol) {
    if (pool_size == 0 || max_concurrent_allocations <= 0) {
        return -1; // Resource exhaustion or concurrent allocation limit reached
    }

    for (int i = 0; i < MAX_FD_POOL; i++) {
        if (fd_pool[i].fd == -1) {
            int fd = socket(AF_INET, protocol == TCP ? SOCK_STREAM : SOCK_DGRAM, 0);
            if (fd == -1) {
                return -1; // Error creating socket
            }

            setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &(int){1}, sizeof(int));
            setsockopt(fd, IPPROTO_TCP, TCP_KEEPALIVE, &(int){1}, sizeof(int));

            fd_pool[i].fd = fd;
            fd_pool[i].protocol = protocol;
            pool_size--;
            max_concurrent_allocations--;

            return i; // Return index of the allocated file descriptor
        }
    }

    return -1; // No available file descriptors in the pool
}

int release_fd(int idx) {
    if (idx < 0 || idx >= MAX_FD_POOL || fd_pool[idx].fd == -1) {
        return -1; // Invalid index or already released
    }

    close(fd_pool[idx].fd);
    fd_pool[idx].fd = -1;
    pool_size++;
    max_concurrent_allocations++;

    return 0; // File descriptor released successfully
}

void log_fd_pool_performance() {
    // Implement performance logging logic here
}

int main() {
    init_fd_pool();

    int tcp_fd_index = get_available_fd(TCP);
    if (tcp_fd_index != -1) {
        printf("Allocated TCP file descriptor: %d\n", tcp_fd_index);
    } else {
        printf("Failed to allocate TCP file descriptor\n");
    }

    int udp_fd_index = get_available_fd(UDP);
    if (udp_fd_index != -1) {
        printf("Allocated UDP file descriptor: %d\n", udp_fd_index);
    } else {
        printf("Failed to allocate UDP file descriptor\n");
    }

    release_fd(tcp_fd_index);
    release_fd(udp_fd_index);

    return 0;
}
