    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->packets = realloc(array->packets, sizeof(MessageProtocolPacket) * array->capacity);
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
