// Function to perform DNS resolution for a given hostname
int resolveHostname(const char *hostname, u_char *ipAddress) {
    static struct timeval lastQueryTime;
    static int queryCount = 0;
    struct timeval now;
    gettimeofday(&now, NULL);

    // Rate limiting
    if (queryCount >= MAX_QUERIES_PER_INTERVAL && (now.tv_sec - lastQueryTime.tv_sec) < 1) {
        return -1; // Exceeded rate limit
    }

    if ((now.tv_sec - lastQueryTime.tv_sec) > 1 || queryCount == 0) {
        lastQueryTime = now;
        queryCount = 1;
    } else {
        queryCount++;
    }

    // Simulated DNS resolution (replace with actual DNS resolver)
    char *result = gethostbyname(hostname);
    if (!result) {
        return -2; // DNS lookup failed
    }

    // Convert the result to IP address and store in ipAddress array
    struct sockaddr_in *addr = (struct sockaddr_in *)gethostbyname(hostname)->h_addr_list[0];
    memcpy(ipAddress, &addr->sin_addr.s_addr, 4);

    return 0; // Success
}

// Example usage
