#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_URL_LENGTH 256
#define MAX_CONTENT_SIZE 1024 * 1024
#define RATE_LIMIT_INTERVAL 5  // seconds

typedef struct {
    CURL *handle;
    u_char *content;
    size_t size;
} FetchContext;

size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    FetchContext *context = (FetchContext *)userp;
    context->content = realloc(context->content, context->size + realsize + 1);
    if (!context->content) {
        return 0; // Handle memory allocation failure
    }
    memcpy(&(context->content[context->size]), contents, realsize);
    context->size += realsize;
    context->content[context->size] = '\0';
    return realsize;
}

int fetchFileContent(const char *url, u_char **content, size_t *size) {
    CURLcode res;
    static time_t last_request_time = 0;

    if (time(NULL) - last_request_time < RATE_LIMIT_INTERVAL) {
        return -1; // Rate limit exceeded
    }
    last_request_time = time(NULL);

    FetchContext context = {curl_easy_init(), NULL, 0};
    if (!context.handle) {
        return -2; // Failed to initialize CURL handle
    }

    curl_easy_setopt(context.handle, CURLOPT_URL, url);
    curl_easy_setopt(context.handle, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(context.handle, CURLOPT_WRITEDATA, &context);

    res = curl_easy_perform(context.handle);
    if (res != CURLE_OK) {
        curl_easy_cleanup(context.handle);
        free(context.content);
        return -3; // CURL error
    }

    *content = context.content;
    *size = context.size;

    curl_easy_cleanup(context.handle);
    return 0; // Success
}
