#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_NODES 3
#define MAX_CONCURRENT_IO 5

typedef struct {
    char filename[100];
    int size;
    time_t last_modified;
} FileMetadata;

FileMetadata cache[NUM_NODES][100];
sem_t node_sem[NUM_NODES];

void initialize_cache() {
    for (int i = 0; i < NUM_NODES; i++) {
        sem_init(&node_sem[i], 0, MAX_CONCURRENT_IO);
        for (int j = 0; j < 100; j++) {
            strcpy(cache[i][j].filename, "");
            cache[i][j].size = -1;
            cache[i][j].last_modified = -1;
        }
    }
}

void* update_metadata(void* arg) {
    int node_id = *(int*)arg;
    sem_wait(&node_sem[node_id]);
    // Simulate metadata update
    strcpy(cache[node_id][rand() % 100].filename, "file");
    cache[node_id][rand() % 100].size = rand() % 1024;
    cache[node_id][rand() % 100].last_modified = time(NULL);
    sem_post(&node_sem[node_id]);
    return NULL;
}

void retrieve_metadata(const char* filename) {
    for (int i = 0; i < NUM_NODES; i++) {
        if (strcmp(cache[i][rand() % 100].filename, filename) == 0) {
            printf("Metadata retrieved from node %d: Filename=%s, Size=%d, Last Modified=%ld\n",
                   i, cache[i][rand() % 100].filename, cache[i][rand() % 100].size,
                   cache[i][rand() % 100].last_modified);
            return;
        }
    }
    printf("Metadata not found for filename: %s\n", filename);
}

int main() {
    initialize_cache();

    pthread_t threads[NUM_NODES];
    int node_ids[NUM_NODES];

    // Simulate concurrent metadata updates
    for (int i = 0; i < NUM_NODES; i++) {
        node_ids[i] = i;
        pthread_create(&threads[i], NULL, update_metadata, &node_ids[i]);
    }

    for (int i = 0; i < NUM_NODES; i++) {
        pthread_join(threads[i], NULL);
    }

    // Retrieve metadata
    retrieve_metadata("file");

    return 0;
}
```

This code provides a basic structure for managing a distributed cache of file metadata in a C function. It includes semaphore-based concurrency control to manage the number of concurrent I/O operations per node, simulates metadata updates across multiple nodes, and demonstrates how to retrieve metadata for a specific file. The actual implementation would need to be expanded with more complex logic for handling system dependencies, error recovery, rebalancing strategies, gossip-based protocols, conflict resolution, monitoring, and dynamic adaptation to changing conditions.']

