typedef struct {
    CURL *curl;
    char *response_data;
} HttpClient;

HttpClient* create_http_client(const char *url) {
    HttpClient *client = (HttpClient *)malloc(sizeof(HttpClient));
    if (!client) return NULL;

    client->curl = curl_easy_init();
    if (!client->curl) {
        free(client);
        return NULL;
    }

    curl_easy_setopt(client->curl, CURLOPT_URL, url);
    curl_easy_setopt(client->curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(client->curl, CURLOPT_WRITEDATA, client);

    return client;
}

int execute_http_request(HttpClient *client) {
    CURLcode res = curl_easy_perform(client->curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
        return -1;
    }
    return 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    HttpClient *client = (HttpClient *)userp;
    size_t total_size = size * nmemb;

    client->response_data = realloc(client->response_data, strlen(client->response_data) + total_size + 1);
    if (!client->response_data) return 0;

    strcat(client->response_data, contents);
    return total_size;
}

void destroy_http_client(HttpClient *client) {
    if (client) {
        curl_easy_cleanup(client->curl);
        free(client->response_data);
        free(client);
    }
}

int main() {
    const char *url = "https://api.example.com/data";
    HttpClient *client = create_http_client(url);

    if (!client) return -1;

    if (execute_http_request(client) != 0) {
        destroy_http_client(client);
        return -1;
    }

    printf("Response: %s\n", client->response_data);

    destroy_http_client(client);
    return 0;
}
