NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, const char* log_file) {
    FILE* log = fopen(log_file, "w");
    if (!log) {
        return NULL; // Log file could not be opened
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fclose(log);
        return NULL; // Memory allocation failed for the list
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int successful_allocations = 0;
    int failed_allocations = 0;

    #define ALLOCATE_AND_CHECK(tag, type) \
        do { \
            if (!(tag = (type*)malloc(sizeof(type)))) { \
                failed_allocations++; \
                pthread_mutex_lock(&mutex); \
                fprintf(log, "Failed to allocate memory for %s\n", #type); \
                pthread_mutex_unlock(&mutex); \
            } else { \
                successful_allocations++; \
                pthread_mutex_lock(&mutex); \
                fprintf(log, "Successfully allocated memory for %s\n", #type); \
                pthread_mutex_unlock(&mutex); \
            } \
        } while (0)

    for (int i = 0; i < N; i++) {
        ALLOCATE_AND_CHECK(list[i].rx_ue_information_tag, RX_UE_INFORMATION_TAG);
