        list[i].crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_destroy(&mutex);

    fclose(log);

    if (failed_allocations > 0) {
        free(list);
        return NULL; // Return null if any allocations failed
    }

    return list;
}

