using System.Threading.Tasks;

public class AsyncDNSResolver
{
    private int _maxConcurrentQueries = 10;
    private readonly SemaphoreSlim _semaphore;

    public AsyncDNSResolver(int maxConcurrentQueries = 10)
    {
        _maxConcurrentQueries = maxConcurrentQueries;
        _semaphore = new SemaphoreSlim(maxConcurrentQueries);
    }

    public void SetMaxConcurrentQueries(int maxConcurrentQueries)
    {
        if (maxConcurrentQueries <= 0) throw new ArgumentException("Max concurrent queries must be greater than zero.");
        _maxConcurrentQueries = maxConcurrentQueries;
        _semaphore.Release(_semaphore.CurrentCount);
        _semaphore.Wait(); // Wait to reset the semaphore
    }

    public async Task<List<LinkedListNode<string>>> ResolveAsync(string[] hostnames, int timeoutMilliseconds = 5000)
    {
        var results = new List<LinkedListNode<string>>();
        var tasks = hostnames.Select(hostname => ResolveHostnameAsync(hostname, timeoutMilliseconds)).ToList();

        await Task.WhenAll(tasks);

        foreach (var task in tasks)
        {
            if (task.Result != null)
                results.Add(new LinkedListNode<string>(task.Result));
        }

        return results;
    }

    private async Task<string> ResolveHostnameAsync(string hostname, int timeoutMilliseconds)
    {
        try
        {
            await _semaphore.WaitAsync(timeoutMilliseconds);
            using (var client = new DnsClient(Dns.GetHostName()))
            {
                var result = await client.QueryAsync(hostname, QueryType.A);
                if (result != null && result.Answers.Any())
                    return result.Answers.First().Address.ToString();
            }
        }
        catch (TaskCanceledException)
        {
            Console.WriteLine("DNS resolution timed out for hostname: " + hostname);
        }
        finally
        {
            _semaphore.Release();
        }

        return null;
    }
}

public class DnsClient
{
    private readonly string _server;

    public DnsClient(string server)
    {
        _server = server;
    }

    public async Task<DnsResponse> QueryAsync(string hostname, QueryType queryType)
