        var response = new DnsResponse();
        try
        {
            using (var socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp))
            {
                socket.Bind(new IPEndPoint(IPAddress.Any, 0));
                await socket.ConnectAsync(_server, 53);

                var query = GenerateDnsQuery(hostname, queryType);
                await socket.SendAsync(query.ToArray(), SocketFlags.None);

                var buffer = new byte[1024];
                int bytesReceived = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), SocketFlags.None);
                response.Parse(buffer.Take(bytesReceived).ToArray());
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("DNS query failed: " + ex.Message);
        }

        return response;
    }

    private byte[] GenerateDnsQuery(string hostname, QueryType queryType)
