typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data, size_t alignment) {
    size_t total_size = sizeof(Node) + alignment - 1;
    void* aligned_memory = malloc(total_size);
    if (!aligned_memory) return NULL;

    Node* node = (Node*)((uintptr_t)(aligned_memory + alignment - 1) & ~(alignment - 1));
    memcpy(&node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&node->lock, NULL);
    node->next = NULL;

    return node;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;

    return list;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data, size_t alignment) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data, alignment);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current);
        current = next;
    }
    free(list);
}
