#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure as per your requirements
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    int memory_boundary; // To ensure alignment
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
    size_t total_nodes;
    size_t allocated_memory;
} LinkedList;

LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)aligned_alloc(64, sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->total_nodes = 0;
    list->allocated_memory = sizeof(LinkedList);

    return list;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data, int memory_boundary) {
    if (!list || !data.RX_UE_INFORMATION_TAG || !data.RNTI || !data.CRC_INDICATION_REL8_TAG) return -1;

    Node* new_node = (Node*)aligned_alloc(memory_boundary, sizeof(Node));
    if (!new_node) return -2;

    pthread_mutex_lock(&list->lock);
    new_node->data = data;
    new_node->next = list->head;
    new_node->memory_boundary = memory_boundary;
    list->head = new_node;
    list->total_nodes++;
    list->allocated_memory += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || !data.RX_UE_INFORMATION_TAG || !data.RNTI || !data.CRC_INDICATION_REL8_TAG) return -1;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data == data) {
            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;
            free(current);
            list->total_nodes--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -2; // Node not found
}

void destroy_linked_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void monitor_performance(LinkedList* list) {
    if (!list) return;

    printf("Total Nodes: %zu\n", list->total_nodes);
    printf("Allocated Memory: %zu bytes\n", list->allocated_memory);
}
