#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>
#include <random>
#include <string>

class AsyncFileProcessor {
public:
    struct ProcessedData {
        std::string section;
        std::vector<std::string> lines;
        std::vector<std::string> tokens;
        std::vector<std::string> substrings;
        std::exception_ptr error;
    };

    using ResultQueue = std::queue<ProcessedData>;
    using LockGuard = std::lock_guard<std::mutex>;

    AsyncFileProcessor(size_t max_concurrent_reads) : maxConcurrentReads(max_concurrent_reads) {}

    void addFile(const std::string& filename, size_t start, size_t end) {
        fileQueue.push({filename, start, end});
        condition.notify_one();
    }

    ProcessedData getResult() {
        LockGuard lock(mutex);
        while (results.empty()) {
            if (fileQueue.empty() && processingThreads == 0) {
                throw std::runtime_error("No results available and no files left to process.");
            }
            condition.wait(lock, [this] { return !results.empty() || fileQueue.empty(); });
        }
        ProcessedData result = std::move(results.front());
        results.pop();
        return result;
    }

    void setMaxConcurrentReads(size_t max_concurrent_reads) {
        LockGuard lock(mutex);
        if (processingThreads < maxConcurrentReads && !fileQueue.empty()) {
            condition.notify_all();
        }
        maxConcurrentReads = max_concurrent_reads;
    }

private:
    struct FileTask {
        std::string filename;
        size_t start;
        size_t end;
    };

    ResultQueue results;
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<FileTask> fileQueue;
    size_t processingThreads = 0;
    size_t maxConcurrentReads;

    void worker() {
        while (true) {
            FileTask task;
            {
                LockGuard lock(mutex);
                if (fileQueue.empty()) {
                    break;
                }
                task = std::move(fileQueue.front());
                fileQueue.pop();
            }

            ProcessedData data;
            try {
                std::ifstream file(task.filename, std::ios::in | std::ios::binary);
                if (!file) {
                    throw std::runtime_error("Failed to open file.");
                }

                file.seekg(task.start, std::ios::beg);
                data.section = "Section from " + task.filename + " between " + std::to_string(task.start) + " and " + std::to_string(task.end);

                std::string line;
                while (std::getline(file, line)) {
                    if (file.tellg() > static_cast<long>(task.end)) break;
                    data.lines.push_back(line);
                }

                // Process lines to extract tokens and substrings
            } catch (...) {
                data.error = std::current_exception();
            }

            {
                LockGuard lock(mutex);
                results.push(data);
                processingThreads--;
                condition.notify_all();
            }
        }
    }

    void startWorkers() {
        for (size_t i = 0; i < maxConcurrentReads; ++i) {
            std::thread([this] { this->worker(); }).detach();
        }
    }

public:
    AsyncFileProcessor(size_t max_concurrent_reads) : maxConcurrentReads(max_concurrent_reads) {
        startWorkers();
    }
};

class RandomValueGenerator {
private:
    std::mt19937 generator;
    std::uniform_int_distribution<> intDistribution;
    std::uniform_real_distribution<double> doubleDistribution;

public:
    RandomValueGenerator(unsigned seed = std::random_device{}()) : generator(seed) {}

    template <typename T>
    T generate(T min, T max) {
        if (min > max) {
            throw std::invalid_argument("Invalid range");
        }
        if (std::is_integral<T>::value) {
            intDistribution.param(std::uniform_int_distribution<>::param_type(min, max));
            return intDistribution(generator);
        } else if (std::is_floating_point<T>::value) {
            doubleDistribution.param(std::uniform_real_distribution<>::param_type(static_cast<double>(min), static_cast<double>(max)));
            return static_cast<T>(doubleDistribution(generator));
        }
    }

    template <typename T>
    std::vector<T> generateArray(size_t size, T min, T max) {
        if (size == 0 || min > max) {
            throw std::invalid_argument("Invalid array size or range");
        }
        std::vector<T> array(size);
        for (auto& value : array) {
            value = generate(min, max);
        }
        return array;
    }

    void setSeed(unsigned seed) {
        generator.seed(seed);
    }
};
