#define MAX_READINGS 10000
#define MAX_CONNECTIONS 1000
#define PAYLOAD_LIMIT 5000
#define WINDOW_SIZE 3600

typedef struct Reading {
    int id;
    time_t timestamp;
    int quality_level;
} Reading;

typedef struct Node {
    Reading data;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    int size;
} HashTable;

typedef struct Connection {
    char client_ip[16];
    char server_ip[16];
    unsigned short port;
    char payload[PAYLOAD_LIMIT];
} Connection;

typedef struct TrafficStats {
    long connections_established;
    long connections_closed;
    double avg_latency;
    int payload_distribution[64]; // Assuming payloads are up to 64 bytes
} TrafficStats;

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    table->size = size;
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

unsigned int hash_function(int id, int size) {
    return abs(id) % size;
}

void insert_reading(HashTable* table, Reading reading) {
    unsigned int index = hash_function(reading.id, table->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = reading;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
}

Reading* find_reading(HashTable* table, int id) {
    unsigned int index = hash_function(id, table->size);
    Node* node = table->buckets[index];
    while (node != NULL) {
        if (node->data.id == id)
            return &node->data;
        node = node->next;
    }
    return NULL;
}

void remove_reading(HashTable* table, int id) {
    unsigned int index = hash_function(id, table->size);
    Node* prev = NULL;
    Node* node = table->buckets[index];
    while (node != NULL) {
        if (node->data.id == id) {
            if (prev == NULL)
                table->buckets[index] = node->next;
            else
                prev->next = node->next;
            free(node);
            return;
        }
        prev = node;
        node = node->next;
    }
}

void process_readings(HashTable* table, int num_readings) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_readings; ++i) {
        Reading reading;
        // Simulate reading data
        reading.id = rand() % MAX_READINGS;
        reading.timestamp = time(NULL);
        reading.quality_level = rand() % 100;

        pthread_mutex_lock(&lock);
        insert_reading(table, reading);
        pthread_mutex_unlock(&lock);
    }
}

void* network_traffic_monitor(void* args) {
    TrafficStats stats = {0};
    // Simulate monitoring logic
    while (1) {
        sleep(1); // Simulate 1-second intervals
        printf("Connections Established: %ld\n", stats.connections_established);
        printf("Connections Closed: %ld\n", stats.connections_closed);
        printf("Average Latency: %.2f ms\n", stats.avg_latency);
    }
    return NULL;
}

int main() {
    HashTable* table = create_hash_table(MAX_READINGS);

    pthread_t traffic_thread;
    pthread_create(&traffic_thread, NULL, network_traffic_monitor, NULL);

    process_readings(table, MAX_READINGS);

    destroy_hash_table(table);

    pthread_join(traffic_thread, NULL);
    return 0;
}
