// Function to compute MD5 hash of a file
void compute_md5(char *file_path, char *output_buffer) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    md5_state_t state;
    md5_init(&state);

    char buffer[1024];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        md5_append(&state, (unsigned char *)buffer, bytes_read);
    }

    fclose(fp);
    md5_finish(&state, (unsigned char *)output_buffer);
}

// Function to check if MD5 hash matches known hashes
int check_known_hashes(char *md5_hash) {
    // Assume a function exists to query the distributed database
    return is_md5_in_database(md5_hash);
}

// Thread function to process individual files
void* file_processing_thread(void *arg) {
    char **file_paths = (char **)arg;
    int num_files = strlen(file_paths) / sizeof(char *);

    for (int i = 0; i < num_files; ++i) {
        char md5_hash[33];
        compute_md5(file_paths[i], md5_hash);

        if (check_known_hashes(md5_hash)) {
            // Extract sequence number and log
            extract_and_log_sequence_number(file_paths[i]);
        }
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s <input_files> <output_file> <transformation_rules> <aggregated_stats_flag> <real_time_monitoring_flag> <timeout>\n", argv[0]);
        return 1;
    }

    char **file_paths = (char **)argv + 1;
    int num_files = argc - 6;

    pthread_t threads[num_files];
    for (int i = 0; i < num_files; ++i) {
        pthread_create(&threads[i], NULL, file_processing_thread, &file_paths);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
