        if (*current == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
