#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/time.h>
#include <arpa/inet.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN INET_ADDRSTRLEN
#define DNS_CACHE_SIZE 100
#define CONCURRENT_QUERY_LIMIT 5

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    char ip[MAX_IP_LEN];
    int performance_metric;
} DnsEntry;

DnsEntry dns_cache[DNS_CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t concurrent_query_sem;

void init_dns_cache() {
    sem_init(&concurrent_query_sem, 0, CONCURRENT_QUERY_LIMIT);
}

char* get_ip_from_hostname(const char* hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[i].ip;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    sem_wait(&concurrent_query_sem);

    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Use IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        sem_post(&concurrent_query_sem);
        return NULL;
    }

    char ip[MAX_IP_LEN];
    inet_ntop(res->ai_family, res->ai_addr, ip, sizeof(ip));

    pthread_mutex_lock(&cache_lock);
    if (cache_index < DNS_CACHE_SIZE) {
        strcpy(dns_cache[cache_index].hostname, hostname);
        strcpy(dns_cache[cache_index].ip, ip);
        dns_cache[cache_index].performance_metric = // Calculate performance metric
        cache_index++;
    }
    pthread_mutex_unlock(&cache_lock);

    freeaddrinfo(res);
    sem_post(&concurrent_query_sem);

    return ip;
}

int main() {
    init_dns_cache();

    char hostname[MAX_HOSTNAME_LEN];
    printf("Enter hostname to resolve: ");
    fgets(hostname, MAX_HOSTNAME_LEN, stdin);
    hostname[strcspn(hostname, "\n")] = 0; // Remove newline

    char* ip = get_ip_from_hostname(hostname);
    if (ip != NULL) {
        printf("IP address for %s is %s\n", hostname, ip);
    } else {
        printf("Failed to resolve IP address for %s\n", hostname);
    }

    return 0;
}
```

This code snippet provides a basic implementation of a DNS resolver with caching and concurrency control. It includes a `DnsEntry` structure to store resolved IP addresses and their performance metrics, a cache array to store the entries, and mutexes and semaphores to manage concurrent access. The `get_ip_from_hostname` function first checks if the IP address is in the cache. If not, it acquires a semaphore, performs a DNS lookup using `getaddrinfo`, and stores the result in the cache before releasing the semaphore. The main function demonstrates how to use the resolver by prompting the user for a hostname and displaying the resolved IP address.']

