#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} DoublyLinkedList;

void initList(DoublyLinkedList* list, int capacity) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void enqueue(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    while (list->tail && list->tail->next != NULL) {
        pthread_cond_wait(&list->not_full, &list->lock);
    }
    Node* newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (!list->head) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
}

void dequeue(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    while (list->head == NULL) {
        pthread_cond_wait(&list->not_empty, &list->lock);
    }
    Node* node = list->head;
    *data = node->data;
    if (node->next) {
        list->head = node->next;
        node->next->prev = NULL;
    } else {
        list->head = NULL;
        list->tail = NULL;
    }
    free(node);
    pthread_cond_signal(&list->not_full);
    pthread_mutex_unlock(&list->lock);
}

void destroyList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_cond_destroy(&list->not_full);
    pthread_cond_destroy(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
