public class DynamicRangeValueGenerator
{
    private readonly Random _random = new Random();
    private readonly object _lockObject = new object();
    private List<RangeSettings> _ranges;
    private NFAPI_CRC_INDICATION_PDU_T[] _nfapiCrcIndicationPduArray;

    public DynamicRangeValueGenerator()
    {
        _ranges = new List<RangeSettings>();
        _nfapiCrcIndicationPduArray = null;
    }

    public void AddRange(int min, int max)
    {
        lock (_lockObject)
        {
            var overlappingRanges = _ranges.Where(r => r.Max > min && r.Min < max).ToList();
            if (overlappingRanges.Any())
            {
                throw new ArgumentException("New range overlaps with existing ranges.");
            }

            _ranges.Add(new RangeSettings { Min = min, Max = max });
            ResetNfapiCrcIndicationPduArray();
        }
    }

    public void RemoveRange(int min, int max)
    {
        lock (_lockObject)
        {
            var rangeToRemove = _ranges.FirstOrDefault(r => r.Min == min && r.Max == max);
            if (rangeToRemove != null)
            {
                _ranges.Remove(rangeToRemove);
                ResetNfapiCrcIndicationPduArray();
            }
        }
    }

    public float GenerateRandomFloat(int rangeIndex, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        lock (_lockObject)
        {
            if (rangeIndex < 0 || rangeIndex >= _ranges.Count)
                throw new ArgumentOutOfRangeException(nameof(rangeIndex));

            var range = _ranges[rangeIndex];
            float minValue = inclusiveMin ? range.Min : range.Min + 1;
            float maxValue = inclusiveMax ? range.Max : range.Max - 1;

            return (float)(_random.NextDouble() * (maxValue - minValue) + minValue);
        }
    }

    public int GenerateRandomInt(int rangeIndex, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        lock (_lockObject)
        {
            if (rangeIndex < 0 || rangeIndex >= _ranges.Count)
                throw new ArgumentOutOfRangeException(nameof(rangeIndex));

            var range = _ranges[rangeIndex];
            int minValue = inclusiveMin ? range.Min : range.Min + 1;
            int maxValue = inclusiveMax ? range.Max : range.Max - 1;

            return _random.Next(minValue, maxValue + 1);
        }
    }

    public void ResetNfapiCrcIndicationPduArray()
    {
        lock (_lockObject)
        {
            int totalSize = _ranges.Sum(r => r.Max - r.Min + 1);
            if (totalSize > 0)
            {
                _nfapiCrcIndicationPduArray = new NFAPI_CRC_INDICATION_PDU_T[totalSize];
                PopulateNfapiCrcIndicationPduArray();
            }
        }
    }

    private void PopulateNfapiCrcIndicationPduArray()
    {
        int index = 0;
        foreach (var range in _ranges)
        {
            for (int i = range.Min; i <= range.Max; i++)
            {
                var pdu = new NFAPI_CRC_INDICATION_PDU_T
                {
                    RX_UE_INFORMATION_TAG = GenerateRandomInt(0, false),
                    RNTI = GenerateUniqueRnti(),
                    CRC_INDICATION_REL8_TAG = GenerateRandomBool()
                };
                _nfapiCrcIndicationPduArray[index++] = pdu;
            }
        }
    }

    private int GenerateUniqueRnti()
    {
        // Implement logic to generate unique RNTIs across sessions
        return _random.Next(1, 65536);
    }

    private bool GenerateRandomBool()
    {
        return _random.Next(2) == 0;
    }

    public override string ToString()
    {
        lock (_lockObject)
        {
            var rangesString = string.Join(", ", _ranges.Select(r => $"[{r.Min}, {r.Max}]"));
            return $"DynamicRangeValueGenerator - Ranges: {rangesString}";
        }
    }

    private class RangeSettings
    {
        public int Min { get; set; }
        public int Max { get; set; }
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct NFAPI_CRC_INDICATION_PDU_T
    {
        public int RX_UE_INFORMATION_TAG;
        public int RNTI;
        public bool CRC_INDICATION_REL8_TAG;
    }
}
