#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
} DynamicList;

void initializeDynamicList(DynamicList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* createNewStruct() {
    NFAPI_CRC_INDICATION_PDU_T *newStruct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newStruct == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    newStruct->RX_UE_INFORMATION_TAG = rand() % 1000; // Example random initialization
    newStruct->RNTI = rand() % 1000; // Example random initialization
    newStruct->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newStruct->prev = newStruct->next = NULL;
    return newStruct;
}

void addToDynamicList(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&list->mutex);
    if (list->tail == NULL) {
        list->head = list->tail = newStruct;
    } else {
        list->tail->next = newStruct;
        newStruct->prev = list->tail;
        list->tail = newStruct;
    }
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

void validateStruct(NFAPI_CRC_INDICATION_PDU_T *structPtr) {
    if (structPtr == NULL) {
        fprintf(stderr, "Invalid structure pointer\n");
        return;
    }
    // Example validation: Ensure tags are within a valid range
    if (structPtr->RX_UE_INFORMATION_TAG < 0 || structPtr->RNTI < 0 || structPtr->CRCFLAG < 0 || structPtr->CRCFLAG > 1) {
        fprintf(stderr, "Invalid data in structure\n");
    }
}

int main() {
    DynamicList list;
    initializeDynamicList(&list);

    for (int i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *newStruct = createNewStruct();
        if (newStruct != NULL) {
            validateStruct(newStruct);
            addToDynamicList(&list, newStruct);
        } else {
            break;
        }
    }

    // Cleanup
    pthread_mutex_destroy(&list.mutex);
    pthread_cond_destroy(&list.cond);
    while (list.head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list.head;
        list.head = list.head->next;
        free(temp);
    }

    return 0;
}
