typedef struct FSA_StateNode {
    int stateIndex;
    struct FSA_StateNode *next;
    int *transitionRules; // Array of target states for each input symbol
} FSA_StateNode;

typedef struct {
    pthread_mutex_t mutex;
    FSA_StateNode *currentNode;
    FSA_StateNode **stateList;
    int currentStateCount;
} FiniteStateAutomaton;

FSA_StateNode* createStateNode(int stateIndex, int transitionRulesSize) {
    FSA_StateNode *newNode = (FSA_StateNode *)malloc(sizeof(FSA_StateNode));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    newNode->stateIndex = stateIndex;
    newNode->next = NULL;
    newNode->transitionRules = (int *)malloc(transitionRulesSize * sizeof(int));
    if (newNode->transitionRules == NULL) {
        free(newNode);
        perror("Memory allocation failed");
        return NULL;
    }
    // Example initialization: Random transition rules
    for (int i = 0; i < transitionRulesSize; ++i) {
        newNode->transitionRules[i] = rand() % stateIndex + 1;
    }
    return newNode;
}

FSA_StateNode** createDynamicStateList(int *states, int numStates, FiniteStateAutomaton *fsa, int lastStateIdx, int *currentStateListSize) {
    pthread_mutex_lock(&fsa->mutex);
    *currentStateListSize = numStates;
    FSA_StateNode **newStateList = (FSA_StateNode **)malloc(numStates * sizeof(FSA_StateNode *));
    if (newStateList == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&fsa->mutex);
        return NULL;
    }

    for (int i = 0; i < numStates; ++i) {
        newStateList[i] = createStateNode(states[i], lastStateIdx + 2); // Assuming one more state for demonstration
        if (newStateList[i] == NULL) {
            for (int j = 0; j < i; ++j) {
                free(newStateList[j]->transitionRules);
                free(newStateList[j]);
            }
            free(newStateList);
            pthread_mutex_unlock(&fsa->mutex);
            return NULL;
        }

        if (i > 0) {
            newStateList[i - 1]->next = newStateList[i];
        } else {
            fsa->currentNode = newStateList[0];
        }
    }

    pthread_mutex_unlock(&fsa->mutex);
    return newStateList;
}

int main() {
    // Example usage
    int states[] = {0, 1, 2}; // Example state list
    int numStates = sizeof(states) / sizeof(states[0]);
    FiniteStateAutomaton fsa;
    pthread_mutex_init(&fsa.mutex, NULL);
    int currentStateListSize;

    FSA_StateNode **newStateList = createDynamicStateList(states, numStates, &fsa, 2, &currentStateListSize);

    if (newStateList != NULL) {
        // Use the state list as needed
        for (int i = 0; i < currentStateListSize; ++i) {
            free(newStateList[i]->transitionRules);
            free(newStateList[i]);
        }
        free(newStateList);
    }

    pthread_mutex_destroy(&fsa.mutex);

    return 0;
}
