#include <time.h>

#define WINDOW_SIZE 900 // 15 minutes in seconds
#define MAX_CONCURRENT_HIGH_PRIORITY_EVENTS 200
#define MAX_EVENTS_PER_SECOND 10000

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
    struct Event* next;
} Event;

typedef struct HashBucket {
    Event* head;
} HashBucket;

typedef struct EventManager {
    HashBucket buckets[1024]; // Assuming a hash table size of 1024
    Event** slidingWindow;
    int windowStartIndex;
    int currentPriority;
    int currentEventId;
} EventManager;

EventManager* createEventManager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    for (int i = 0; i < 1024; ++i) {
        manager->buckets[i].head = NULL;
    }
    manager->slidingWindow = (Event**)malloc(WINDOW_SIZE * sizeof(Event*));
    for (int i = 0; i < WINDOW_SIZE; ++i) {
        manager->slidingWindow[i] = NULL;
    }
    manager->windowStartIndex = 0;
    manager->currentPriority = -1;
    manager->currentEventId = -1;
    return manager;
}

void destroyEventManager(EventManager* manager) {
    for (int i = 0; i < 1024; ++i) {
        Event* current = manager->buckets[i].head;
        while (current != NULL) {
            Event* next = current->next;
            free(current);
            current = next;
        }
    }
    free(manager->slidingWindow);
    free(manager);
}

int hashFunction(int id) {
    return abs(id) % 1024; // Simplified hash function for demonstration
}

void addEvent(EventManager* manager, int id, time_t timestamp, int priority) {
    if (timestamp - manager->slidingWindow[manager->windowStartIndex]->timestamp > WINDOW_SIZE) {
        free(manager->slidingWindow[manager->windowStartIndex]);
        manager->slidingWindow[manager->windowStartIndex] = NULL;
        manager->windowStartIndex = (manager->windowStartIndex + 1) % WINDOW_SIZE;
    }

    int bucketIndex = hashFunction(id);
    Event* newEvent = (Event*)malloc(sizeof(Event));
    newEvent->id = id;
    newEvent->timestamp = timestamp;
    newEvent->priority = priority;
    newEvent->next = manager->buckets[bucketIndex].head;
    manager->buckets[bucketIndex].head = newEvent;

    if (newEvent->priority > manager->currentPriority || 
        (newEvent->priority == manager->currentPriority && newEvent->id < manager->currentEventId)) {
        manager->currentPriority = newEvent->priority;
        manager->currentEventId = newEvent->id;
    }
}

void processEvents(EventManager* manager) {
    time_t now = time(NULL);
    for (int i = 0; i < WINDOW_SIZE; ++i) {
        if (manager->slidingWindow[i] != NULL && 
            (now - manager->slidingWindow[i]->timestamp > WINDOW_SIZE)) {
            free(manager->slidingWindow[i]);
            manager->slidingWindow[i] = NULL;
        }
    }
}

int getHighestPriorityEvent(EventManager* manager) {
    processEvents(manager);
    return manager->currentPriority == -1 ? -1 : manager->currentEventId;
}
