int num_readings = 0;
sem_t reading_semaphore;
sem_t allocation_semaphore;
FILE *log_file = NULL;
pthread_mutex_t log_mutex;

void initialize_sensor_buffer() {
    sensor_buffer = (SensorReading *)malloc(buffer_size * sizeof(SensorReading));
    if (!sensor_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    sem_init(&reading_semaphore, 0, 0);
    sem_init(&allocation_semaphore, 0, buffer_size);
}

void free_sensor_buffer() {
    sem_destroy(&reading_semaphore);
    sem_destroy(&allocation_semaphore);
    if (sensor_buffer) {
        free(sensor_buffer);
        sensor_buffer = NULL;
    }
}

void *process_readings(void *arg) {
