    for (int i = 0; i < num_readings; ++i) {
        sem_wait(&allocation_semaphore);
        sensor_buffer[i].sensor_value = rand() % 1000;
        sensor_buffer[i].timestamp = time(NULL);
        sem_post(&reading_semaphore);

        // Log allocation
        pthread_mutex_lock(&log_mutex);
        fprintf(log_file, "Allocated at %ld: Value=%d\n", time(NULL), sensor_buffer[i].sensor_value);
        fflush(log_file);
        pthread_mutex_unlock(&log_mutex);
    }
    return NULL;
}

void calculate_average() {
    int total = 0;
    sem_wait(&reading_semaphore);
    for (int i = 0; i < num_readings; ++i) {
        total += sensor_buffer[i].sensor_value;
    }
    sem_post(&reading_semaphore);

    double average = (double)total / num_readings;
    printf("Average Sensor Value: %.2f\n", average);
}

void *health_check(void *arg) {
    while (1) {
        // Simulate health check
        sem_wait(&reading_semaphore);
        for (int i = 0; i < num_readings; ++i) {
            if ((time(NULL) - sensor_buffer[i].timestamp) > 60) { // Check if data is stale
                printf("Data Stale at index %d\n", i);
                // Handle data staleness
            }
        }
        sem_post(&reading_semaphore);

        sleep(30); // Perform health check every 30 seconds
    }
}

int main(int argc, char *argv[]) {
    initialize_sensor_buffer();
    log_file = fopen("sensor_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    pthread_t reader_thread;
    pthread_t health_thread;

    pthread_mutex_init(&log_mutex, NULL);

    num_readings = 500; // Example value

    if (pthread_create(&reader_thread, NULL, process_readings, NULL) != 0) {
        fprintf(stderr, "Failed to create reader thread\n");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&health_thread, NULL, health_check, NULL) != 0) {
        fprintf(stderr, "Failed to create health check thread\n");
        exit(EXIT_FAILURE);
    }

    pthread_join(reader_thread, NULL);
    pthread_join(health_thread, NULL);

    calculate_average();

    free_sensor_buffer();
    fclose(log_file);
    pthread_mutex_destroy(&log_mutex);

    return 0;
