#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1024
#define LOG_BUFFER_SIZE 4096

typedef enum {
    INFO,
    WARNING,
    ERROR
} LogLevel;

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    size_t length;
} LogBuffer;

typedef struct {
    pthread_mutex_t lock;
    LogBuffer *buffers[MAX_LOG_ENTRIES];
    int count;
    int max_concurrent_entries;
    int current_entries;
} DistributedLogger;

DistributedLogger *create_logger(int max_concurrent_entries) {
    DistributedLogger *logger = (DistributedLogger *)malloc(sizeof(DistributedLogger));
    pthread_mutex_init(&logger->lock, NULL);
    logger->count = 0;
    logger->max_concurrent_entries = max_concurrent_entries;
    logger->current_entries = 0;
    return logger;
}

void destroy_logger(DistributedLogger *logger) {
    for (int i = 0; i < logger->count; i++) {
        free(logger->buffers[i]);
    }
    pthread_mutex_destroy(&logger->lock);
    free(logger);
}

void log_message(DistributedLogger *logger, LogLevel level, const char *message) {
    if (logger->current_entries >= logger->max_concurrent_entries) {
        return; // Log rate limiting
    }

    LogBuffer *buffer = (LogBuffer *)malloc(sizeof(LogBuffer));
    buffer->length = snprintf(buffer->buffer, LOG_BUFFER_SIZE, "[%s] %s\n", level == INFO ? "INFO" : (level == WARNING ? "WARNING" : "ERROR"), message);

    pthread_mutex_lock(&logger->lock);
    logger->buffers[logger->count++] = buffer;
    logger->current_entries++;
    pthread_mutex_unlock(&logger->lock);
}

void flush_logs(DistributedLogger *logger) {
    for (int i = 0; i < logger->count; i++) {
        LogBuffer *buffer = logger->buffers[i];
        // Code to persist the log entry to remote storage
        free(buffer);
    }
    pthread_mutex_lock(&logger->lock);
    logger->count = 0;
    logger->current_entries = 0;
    pthread_mutex_unlock(&logger->lock);
}

int main() {
    DistributedLogger *logger = create_logger(100);

    log_message(logger, INFO, "This is an info message");
    log_message(logger, WARNING, "This is a warning message");
    log_message(logger, ERROR, "This is an error message");

    flush_logs(logger);

    destroy_logger(logger);
    return 0;
}
