    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

void appendNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure

    newNode->pdu = pdu;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    ++list->count;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

