#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N 100

typedef struct {
    HTTP_REQUEST_HANDLE handle;
    REMOTE_URL url;
    LOCAL_PORT port;
    REQUEST_METHOD method;
    RESPONSE_STATUS status;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications;
} HTTP_REQUEST_RECORD;

HTTP_REQUEST_RECORD* request_pool[N];
int allocation_count = 0;
int failure_count = 0;
pthread_mutex_t pool_lock;

void log_allocation(int success) {
    FILE *log_file = fopen("allocation_log.txt", "a");
    if (log_file != NULL) {
        if (success) {
            fprintf(log_file, "Allocation successful\n");
        } else {
            fprintf(log_file, "Allocation failed\n");
        }
        fclose(log_file);
    }
}

HTTP_REQUEST_RECORD* create_request_pool(int N) {
    pthread_mutex_lock(&pool_lock);

    for (int i = 0; i < N; i++) {
        HTTP_REQUEST_RECORD *record = malloc(sizeof(HTTP_REQUEST_RECORD));
        if (record == NULL) {
            failure_count++;
            log_allocation(0);
            continue;
        }
        record->crc_indications = malloc(50000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (record->crc_indications == NULL) {
            free(record);
            failure_count++;
            log_allocation(0);
            continue;
        }

        // Initialize fields with valid data
        record->handle = get_valid_handle();
        record->url = get_valid_url();
        record->port = get_valid_port();
        record->method = get_valid_method();
        record->status = get_valid_status();

        for (int j = 0; j < 50000; j++) {
            NFAPI_CRC_INDICATION_PDU_T *indication = &record->crc_indications[j];
            indication->RX_UE_INFORMATION_TAG = get_valid_rx_ue_information_tag();
            indication->RNTI = get_valid_rnti();
            indication->CRC_INDICATION_REL8_TAG = get_valid_crc_indication_rel8_tag();
            indication->CRCFLAG = rand() % 2;
        }

        request_pool[i] = record;
    }

    allocation_count = N - failure_count;
    pthread_mutex_unlock(&pool_lock);

    return *request_pool;
}

void* worker_thread(void *arg) {
    int index = *(int*)arg;
    HTTP_REQUEST_RECORD *record = request_pool[index];

    // Process the request
    process_request(record);

    free(record->crc_indications);
    free(record);
    pthread_exit(NULL);
}

void start_processing(int N) {
    pthread_t threads[N];
    int indices[N];

    for (int i = 0; i < N; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &indices[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    int pool_size = N;

    HTTP_REQUEST_RECORD *pool = create_request_pool(pool_size);
    if (pool != NULL) {
        start_processing(pool_size);
    }

    return 0;
}
