NFAPI_CRC_INDICATION_PDU_T* generate_nfa_crc_indications(int num_ues, FILE* log_file) {
    if (num_ues > MAX_UES) {
        fprintf(log_file, "Error: Number of UEs exceeds maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(log_file, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_ues; i++) {
        pthread_mutex_lock(&lock);
        indications[i].RNTI = generate_unique_rnti(i);
        indications[i].CRCFLAG = rand() % 2 == 0;
        pthread_mutex_unlock(&lock);
        fprintf(log_file, "Allocation successful for UE %d\n", i);
    }

    pthread_mutex_destroy(&lock);
    return indications;
}

int generate_unique_rnti(int index) {
    // Simulate generating a unique RNTI based on the index
    return index * 10 + rand() % 256;
