#include <curl/curl.h>

// Define constants for rate limiting and retry logic
#define MAX_REQUESTS_PER_MINUTE 100
#define RETRY_DELAY_SECONDS 5

// Function to download image metadata from a remote service
int downloadImageMetadata(const char *image_id, const char *server_endpoint, char **metadata_json) {
    CURL *curl;
    CURLcode res;

    // Initialize curl
    curl = curl_easy_init();
    if(curl) {
        // Set the URL and other options for the request
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Accept: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_URL, server_endpoint);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, image_id);

        // Perform the request
        res = curl_easy_perform(curl);

        // Check for errors and handle retries
        int retry_count = 0;
        while(res != CURLE_OK && retry_count < RETRY_COUNT) {
            printf("Request failed with error: %s. Retrying...\n", curl_easy_strerror(res));
            sleep(RETRY_DELAY_SECONDS);
            res = curl_easy_perform(curl);
            retry_count++;
        }

        // Check if the request was successful
        if(res != CURLE_OK) {
            fprintf(stderr, "Failed to download metadata for image %s: %s\n", image_id, curl_easy_strerror(res));
            *metadata_json = NULL;
            curl_easy_cleanup(curl);
            return -1; // Error code indicating failure
        }

        // Get the response as JSON
        long response_code;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        if(response_code != 200) {
            fprintf(stderr, "Unexpected HTTP response code: %ld\n", response_code);
            *metadata_json = NULL;
            curl_easy_cleanup(curl);
            return -1; // Error code indicating failure
        }

        // Allocate memory for the JSON response and copy it
        size_t response_size;
        curl_easy_getinfo(curl, CURLINFO_SIZE_DOWNLOAD_T, &response_size);
        *metadata_json = (char *)malloc(response_size + 1);
        if(*metadata_json == NULL) {
            fprintf(stderr, "Failed to allocate memory for metadata\n");
            curl_easy_cleanup(curl);
            return -1; // Error code indicating failure
        }
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            free(*metadata_json);
            *metadata_json = NULL;
            fprintf(stderr, "Failed to download metadata for image %s: %s\n", image_id, curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            return -1; // Error code indicating failure
        }

        // Null-terminate the JSON string
        (*metadata_json)[response_size] = '\0';

        // Clean up
        curl_easy_cleanup(curl);

        // Return success
        return 0; // Success code indicating metadata was downloaded successfully
    }

    // Clean up if curl initialization fails
    *metadata_json = NULL;
    return -1; // Error code indicating failure
}
