#include <sys/time.h>

#define MAX_LOG_SIZE 1024
#define LOG_FILE "error.log"
#define DEFAULT_THRESHOLD 10
#define NUM_RECENT_FILES 5

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct {
    pthread_mutex_t lock;
    FILE *file;
    int message_count;
    time_t last_log_time;
    int log_threshold;
} Logger;

Logger logger = { .lock = PTHREAD_MUTEX_INITIALIZER };

void init_logger() {
    pthread_mutex_lock(&logger.lock);
    if (logger.file == NULL) {
        logger.file = fopen(LOG_FILE, "a");
        if (logger.file == NULL) {
            perror("Failed to open log file");
            exit(1);
        }
        logger.message_count = 0;
        time_t now;
        time(&now);
        logger.last_log_time = now;
        logger.log_threshold = DEFAULT_THRESHOLD;
    }
    pthread_mutex_unlock(&logger.lock);
}

void log_message(LogLevel level, const char *format, ...) {
    pthread_mutex_lock(&logger.lock);
    if (time(NULL) - logger.last_log_time >= 1 && logger.message_count >= logger.log_threshold) {
        // Throttle logging
        pthread_mutex_unlock(&logger.lock);
        return;
    }
    va_list args;
    va_start(args, format);
    char buffer[MAX_LOG_SIZE];
    vsnprintf(buffer, MAX_LOG_SIZE, format, args);
    va_end(args);

    struct tm *tm_info = localtime(&time(NULL));
    fprintf(logger.file, "[%02d:%02d:%02d] [%s] %s\n", 
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            level == CRITICAL ? "CRITICAL" : 
            (level == ERROR ? "ERROR" : 
             (level == WARNING ? "WARNING" : 
              (level == INFO ? "INFO" : "DEBUG"))),
            buffer);
    fflush(logger.file);

    logger.message_count++;
    time_t now;
    time(&now);
    logger.last_log_time = now;

    pthread_mutex_unlock(&logger.lock);
}

void log_rotate() {
    // Implement log rotation logic here
}

// Example usage:
int main() {
    init_logger();
    log_message(CRITICAL, "This is a critical error message");
    log_message(INFO, "This is an informational message");
    return 0;
}
```

