    TCPConnectionState* state = get_connection_state("192.168.1.1", 8080, 30);
    if (state != NULL) {
        printf("Connection added: %s:%d\n", state->remote_ip, state->port);
        // Use the connection
        release_connection_state(state);
        printf("Connection released\n");
    }

    pthread_join(thread, NULL);
    destroy_connection_pool();
    return 0;
}
