void* read_network_stream(void* arg) {
    // Simulate network stream reading
    for (int i = 0; i < *(int*)arg; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            printf("Memory allocation failed\n");
            continue;
