        new_pdu->rnti = rand() % 50;
        new_pdu->crc_indication_rel8_tag = rand() % 20;
        new_pdu->crcflag = rand() % 2;

        pthread_mutex_lock(&thread_lock);
        if (shared_resource.size >= MAX_THREADS) {
            printf("Shared resource overflow\n");
            free(new_pdu);
        } else {
            shared_resource.data[shared_resource.size++] = *new_pdu;
            sem_post(&shared_resource.mutex);
        }
        pthread_mutex_unlock(&thread_lock);

        // Simulate packet loss or high latency
        if (rand() % 5 == 0) {
            sleep(1); // Delay to simulate network delay
        }

