    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    pthread_join(health_thread, NULL);

    free(shared_resource.data);

    sem_destroy(&shared_resource.mutex);

    return 0;
}
