#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define LOG_FILE "app.log"

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

void log_message(LogLevel level, const char* format, ...) {
    static LogLevel current_level = DEBUG;
    static FILE* log_file = fopen(LOG_FILE, "a");
    static size_t file_size = 0;
    va_list args;

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
    }

    va_start(args, format);

    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    size_t message_size = strlen(buffer) + 1;
    if (file_size + message_size > MAX_LOG_SIZE) {
        fclose(log_file);
        rename(LOG_FILE, "app.log.old");
        log_file = fopen(LOG_FILE, "w");
        file_size = 0;
    }

    fprintf(log_file, "%s\n", buffer);
    fflush(log_file);

    file_size += message_size;

    if (level >= current_level) {
        printf("%s\n", buffer);
    }
}

int main() {
    log_message(INFO, "This is an info message.");
    log_message(WARNING, "This is a warning message.");
    log_message(ERROR, "This is an error message.");

    return 0;
}
