#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKETS 100000

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    size_t payload_size;
    time_t last_updated;
} PacketHeader;

typedef struct {
    PacketHeader header;
    char *payload;
} Packet;

Packet *packet_pool[MAX_PACKETS];
int pool_index = 0;
pthread_mutex_t pool_lock;

int allocate_packet(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port, size_t payload_size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= MAX_PACKETS) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }
    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        pthread_mutex_unlock(&pool_lock);
        return -2;
    }
    packet->header.src_ip = src_ip;
    packet->header.dst_ip = dst_ip;
    packet->header.src_port = src_port;
    packet->header.dst_port = dst_port;
    packet->header.payload_size = payload_size;
    packet->header.last_updated = time(NULL);
    packet->payload = (char *)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        pthread_mutex_unlock(&pool_lock);
        return -3;
    }
    memset(packet->payload, 0, payload_size);
    packet_pool[pool_index++] = packet;
    pthread_mutex_unlock(&pool_lock);
    return pool_index - 1;
}

void free_packet(int index) {
    if (index < 0 || index >= pool_index) {
        return;
    }
    pthread_mutex_lock(&pool_lock);
    Packet *packet = packet_pool[index];
    free(packet->payload);
    free(packet);
    packet_pool[index] = NULL;
    pool_index--;
    pthread_mutex_unlock(&pool_lock);
}

void reclaim_unused_packets() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_index; i++) {
        if (!packet_pool[i]) {
            continue;
        }
        Packet *packet = packet_pool[i];
        time_t now = time(NULL);
        if ((now - packet->header.last_updated) > 3600) { // reclaim packets older than 1 hour
            free_packet(i);
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void initialize_packet_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

void destroy_packet_pool() {
    for (int i = 0; i < pool_index; i++) {
        if (packet_pool[i]) {
            free_packet(i);
        }
    }
    pthread_mutex_destroy(&pool_lock);
}
