#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T_SIZE 128

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    unsigned int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    void* data;
    struct Node* prev;
    struct Node* next;
    size_t alignment;
} Node;

Node* create_node(void* data, size_t alignment) {
    size_t padding = (alignment - (sizeof(Node) + strlen(data))) % alignment;
    size_t total_size = sizeof(Node) + strlen(data) + padding;
    Node* node = (Node*)aligned_alloc(alignment, total_size);
    if (!node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    node->alignment = alignment;
    return node;
}

void free_node(Node* node) {
    aligned_free(node);
}

Node* create_doubly_linked_list(size_t N, size_t alignment) {
    Node* head = NULL;
    Node* tail = NULL;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(alignment, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Failed to allocate memory for PDU");
            return head;
        }

        // Populate the structure with random values
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = (unsigned short)(rand() % 65536);
        pdu->CRC_INDICATION_REL8_TAG = (unsigned char)rand();

        Node* new_node = create_node(pdu, alignment);
        if (!new_node) {
            free(pdu);
            return head;
        }

        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    return head;
}

void free_doubly_linked_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
}
