NFAPI_DYNAMIC_LIST_T* nfapi_dynamic_list_init(int max_size) {
    if (max_size <= 0) max_size = 10000;
    NFAPI_DYNAMIC_LIST_T* list = malloc(sizeof(NFAPI_DYNAMIC_LIST_T));
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->max_size = max_size;
    list->current_size = 0;
    return list;
}

void nfapi_dynamic_list_add(NFAPI_DYNAMIC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return; // Limit reached, gracefully degrade
    }
    NFAPI_LIST_NODE_T* new_node = malloc(sizeof(NFAPI_LIST_NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return; // Memory allocation failed, handle gracefully
