    pthread_mutex_unlock(&list->mutex);
}

void nfapi_dynamic_list_destroy(NFAPI_DYNAMIC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_LIST_NODE_T* current = list->head;
    while (current) {
        NFAPI_LIST_NODE_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->current_size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
