DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->data = realloc(NULL, initial_capacity * sizeof(Mobile_Cellular_Connection_Request));
    if (array->data == NULL) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_entry(DynamicArray* array, const Mobile_Cellular_Connection_Request* new_entry) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        array->data = realloc(array->data, 2 * array->capacity * sizeof(Mobile_Cellular_Connection_Request));
        if (array->data == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->capacity *= 2;
    }

    array->data[array->size++] = *new_entry;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_entry(DynamicArray* array, const char* user_id) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->data[i].user_id, user_id) == 0) {
            memmove(&array->data[i], &array->data[i + 1], (array->size - i - 1) * sizeof(Mobile_Cellular_Connection_Request));
            array->size--;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // User ID not found
}

