    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->data[i].user_id, user_id) == 0) {
            strcpy(array->data[i].service_provider, new_service_provider);
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // User ID not found
}

