#define MAX_EVENTS 20000
#define WINDOW_SECONDS 1800

typedef struct Event {
    int id;
    time_t timestamp;
    int priority;
} Event;

typedef struct HashNode {
    int key;
    Event event;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    int size;
} HashTable;

Event* events[MAX_EVENTS];
int event_count = 0;
HashTable hash_table;

void init_hash_table(int size) {
    hash_table.size = size;
    hash_table.buckets = (HashNode**)malloc(size * sizeof(HashNode*));
    for (int i = 0; i < size; i++) {
        hash_table.buckets[i] = NULL;
    }
}

unsigned int custom_hash(int key, int size) {
    // Implement your custom hash function here
    return key % size;
}

void insert_event(Event event, int(*hash_func)(int, int)) {
    unsigned int index = hash_func(event.id, hash_table.size);
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->key = event.id;
    node->event = event;
    node->next = hash_table.buckets[index];
    hash_table.buckets[index] = node;

    // Evict oldest events if necessary
    if (event_count >= MAX_EVENTS) {
        free(events[event_count - 1]);
        event_count--;
    }
    events[event_count++] = (Event*)malloc(sizeof(Event));
    *events[event_count - 1] = event;
}

int find_largest_integer(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void process_events() {
    time_t current_time = time(NULL);
    while (event_count > 0 && difftime(current_time, events[event_count - 1]->timestamp) > WINDOW_SECONDS) {
        free(events[event_count - 1]);
        event_count--;
    }

    HashNode* node;
    for (int i = 0; i < hash_table.size; i++) {
        node = hash_table.buckets[i];
        while (node != NULL) {
            if (difftime(current_time, node->event.timestamp) > WINDOW_SECONDS) {
                free(node);
                hash_table.buckets[i] = node->next;
                continue;
            }
            node = node->next;
        }
    }
}

int main() {
    init_hash_table(1000); // Adjust size as needed

    int n;
    scanf("%d", &n);
    int arr[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    int largest = find_largest_integer(arr, n);
    printf("Largest integer: %d\n", largest);

    // Simulate event processing
    for (int i = 0; i < n; i++) {
        Event event = { arr[i], time(NULL), rand() % 10 }; // Random priority for demonstration
        insert_event(event, custom_hash);
    }

    process_events();

    return 0;
}
