typedef struct {
    int Customer_ID;
    time_t Call_Start_Time;
    time_t Call_End_Time;
    char Calling_Number[20];
    char Receiving_Number[20];
} CDR;

typedef struct Node {
    CDR data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} CDRLinkedList;

CDRLinkedList* createCDRList() {
    CDRLinkedList* list = (CDRLinkedList*)malloc(sizeof(CDRLinkedList));
    list->head = NULL;
    list->size = 0;
    return list;
}

void addCDREntry(CDRLinkedList* list, CDR cdr) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = cdr;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
}

void removeCDREntry(CDRLinkedList* list, int customerID) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.Customer_ID == customerID) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->size--;
            break;
        }
        previous = current;
        current = current->next;
    }
}

void updateCDR(CDRLinkedList* list, int customerID, time_t newStartTime, time_t newEndTime) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.Customer_ID == customerID) {
            current->data.Call_Start_Time = newStartTime;
            current->data.Call_End_Time = newEndTime;
            break;
        }
        current = current->next;
    }
}

void calculateTotalDuration(CDRLinkedList* list, int customerID, time_t startTime, time_t endTime, double* totalDuration) {
    *totalDuration = 0.0;
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.Customer_ID == customerID && current->data.Call_Start_Time >= startTime && current->data.Call_End_Time <= endTime) {
            *totalDuration += difftime(current->data.Call_End_Time, current->data.Call_Start_Time);
        }
        current = current->next;
    }
}

void freeCDRList(CDRLinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    free(list);
}
```
This code defines a dynamic linked list to manage `Call Detail Record` entries efficiently. It includes functions to add, remove, update CDR entries, and calculate the total call duration for a customer within a specified time period. Memory management is handled by dynamically allocating and deallocating nodes as needed.']

