#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000

typedef enum {
    CONNECTION_ACTIVE,
    CONNECTION_IDLE
} ConnectionStatus;

typedef struct {
    char ip[INET_ADDRSTRLEN];
    int port;
    ConnectionStatus status;
} Connection;

Connection connection_pool[MAX_CONNECTIONS];

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int active_connections = 0;

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i].status = CONNECTION_IDLE;
    }
}

Connection* allocate_connection(const char* ip, int port) {
    Connection* conn = NULL;
    pthread_mutex_lock(&pool_lock);
    if (active_connections < MAX_CONNECTIONS) {
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            if (connection_pool[i].status == CONNECTION_IDLE) {
                strcpy(connection_pool[i].ip, ip);
                connection_pool[i].port = port;
                connection_pool[i].status = CONNECTION_ACTIVE;
                conn = &connection_pool[i];
                active_connections++;
                break;
            }
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return conn;
}

void free_connection(Connection* conn) {
    if (conn != NULL) {
        pthread_mutex_lock(&pool_lock);
        int index = conn - connection_pool;
        if (index >= 0 && index < MAX_CONNECTIONS && connection_pool[index].status == CONNECTION_ACTIVE) {
            connection_pool[index].status = CONNECTION_IDLE;
            active_connections--;
        }
        pthread_mutex_unlock(&pool_lock);
    }
}

void log_connection_status(Connection* conn, const char* action) {
    if (conn != NULL) {
        printf("%s: IP=%s, Port=%d, Status=%s\n", action, conn->ip, conn->port, 
               conn->status == CONNECTION_ACTIVE ? "Active" : "Idle");
    }
}

int main() {
    initialize_connection_pool();

    // Example usage
    Connection* new_conn = allocate_connection("192.168.1.1", 5000);
    if (new_conn != NULL) {
        log_connection_status(new_conn, "Connection Allocated");
        free_connection(new_conn);
        log_connection_status(new_conn, "Connection Freed");
    }

    return 0;
}
