#define MAX_LOG_MESSAGE_LENGTH 1024

typedef struct {
    FILE* file;
    pthread_mutex_t mutex;
} ErrorLog;

ErrorLog error_log = {NULL, PTHREAD_MUTEX_INITIALIZER};

void init_error_logger(const char* filename) {
    error_log.file = fopen(filename, "a");
    if (!error_log.file) {
        perror("Failed to open error log file");
        exit(EXIT_FAILURE);
    }
}

void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&error_log.mutex);

    time_t now = time(NULL);
    fprintf(error_log.file, "%s ", ctime(&now));

    vfprintf(error_log.file, format, args);
    fprintf(error_log.file, "\n");

    fflush(error_log.file);

    pthread_mutex_unlock(&error_log.mutex);

    va_end(args);
}

void close_error_logger() {
    if (error_log.file) {
        fclose(error_log.file);
        error_log.file = NULL;
    }
}
