// Define structures for configuration, market data, and log settings
typedef struct {
    int N;
    size_t bufferSize;
    char *logFile;
} Config;

typedef struct {
    double priceChange;
    // Add other fields as needed
} MarketData;

typedef struct {
    pthread_mutex_t mutex;
    FILE *logfp;
    int successfulAllocations;
    int failedAllocations;
} MemoryLog;

// Function prototypes
void *readAndProcessData(void *arg);
void logAllocation(MemoryLog *log, size_t size, int success);
double calculateAveragePriceChange(MarketData *data, int N);
void healthCheck(MarketData *data, int N, time_t lastChecked);

int main(int argc, char **argv) {
    // Parse command-line arguments to configure the system
    Config config;
    MemoryLog memoryLog;
    pthread_t thread;

    // Initialize logging and synchronization structures
    pthread_mutex_init(&memoryLog.mutex, NULL);
    memoryLog.logfp = fopen(config.logFile, "a");
    memoryLog.successfulAllocations = 0;
    memoryLog.failedAllocations = 0;

    // Create a new thread to handle the market data processing
    if (pthread_create(&thread, NULL, readAndProcessData, &config) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Periodically perform health checks and log memory allocations
    time_t lastChecked = time(NULL);
    while (1) {
        healthCheck(data, config.N, lastChecked);
        sleep(60);  // Perform health check every minute
    }

    // Clean up resources before exiting the program
    pthread_join(thread, NULL);
    fclose(memoryLog.logfp);
    pthread_mutex_destroy(&memoryLog.mutex);

    return EXIT_SUCCESS;
}

void *readAndProcessData(void *arg) {
    Config *config = (Config *)arg;
    MarketData *data = malloc(config->N * sizeof(MarketData));
    if (data == NULL) {
        logAllocation(&memoryLog, config->N * sizeof(MarketData), 0);
        return NULL;
    }
    logAllocation(&memoryLog, config->N * sizeof(MarketData), 1);

    // Simulate reading and processing data
    for (int i = 0; i < config->N; i++) {
        // Read data from source
        data[i].priceChange = calculateAveragePriceChange(data, i + 1);
    }

    // Free the allocated memory when done
    free(data);

    return NULL;
}

void logAllocation(MemoryLog *log, size_t size, int success) {
    pthread_mutex_lock(&log->mutex);
    if (success) {
        log->successfulAllocations++;
    } else {
        log->failedAllocations++;
    }
    time_t now = time(NULL);
    fprintf(log->logfp, "Allocation of %zu bytes at %s%s\n", size, ctime(&now), success ? " successful" : " failed");
    fflush(log->logfp);
    pthread_mutex_unlock(&log->mutex);
}

double calculateAveragePriceChange(MarketData *data, int N) {
    double sum = 0.0;
    for (int i = 1; i < N; i++) {
        if (data[i].priceChange != data[i - 1].priceChange) {
            sum += fabs(data[i].priceChange - data[i - 1].priceChange);
        }
    }
    return sum / N;
}

void healthCheck(MarketData *data, int N, time_t lastChecked) {
    // Check for data staleness and network anomalies
    if (time(NULL) - lastChecked > 60) {  // Assuming a minute interval
        printf("Health check: Data is stale. Last checked at %s", ctime(&lastChecked));
    }
}
