#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define N 10000000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* memory_block;
    size_t block_size;
    size_t num_elements;
    size_t element_size;
    size_t free_index;
} MemoryPool;

NFAPI_CRC_INDICATION_PDU_T* create_node(MemoryPool* pool) {
    if (pool->free_index == pool->num_elements) {
        return NULL; // No more memory available
    }
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)((char*)pool->memory_block + pool->element_size * pool->free_index);
    memset(node, 0, pool->element_size); // Initialize the node
    pool->free_index++;
    return node;
}

void free_node(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* node) {
    node->next = NULL;
    node->prev = NULL;
    memset(node, 0, pool->element_size); // Clear the node to avoid memory leaks
    pool->free_index--;
}

int main() {
    MemoryPool pool;
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool.block_size = N * element_size;
    pool.element_size = element_size;
    pool.num_elements = N;
    pool.free_index = 0;

    // Allocate memory for the memory pool
    pool.memory_block = malloc(pool.block_size);
    if (pool.memory_block == NULL) {
        return -1; // Memory allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL, *tail = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* node = create_node(&pool);
        if (node == NULL) {
            break; // Not enough memory
        }
        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free all nodes and the memory pool
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        free_node(&pool, temp);
    }
    free(pool.memory_block);

    return 0;
}
