typedef struct {
    int id;
    time_t lastAccess;
    int accessCount;
    double latencySum;
} Session;

Session* findHighLatencySession(Session sessions[], int count, int *highestLatencyId) {
    if (count == 0) return NULL;

    *highestLatencyId = -1;
    double highestLatency = 0.0;
    for (int i = 0; i < count; i++) {
        if (sessions[i].accessCount > 0) {
            sessions[i].latencySum /= sessions[i].accessCount;
            if (sessions[i].latencySum > highestLatency) {
                highestLatency = sessions[i].latencySum;
                *highestLatencyId = sessions[i].id;
            }
        }
    }

    for (int i = 0; i < count; i++) {
        if (i != *highestLatencyId && sessions[i].lastAccess > time(NULL) - 3600) {
            return &sessions[i];
        }
    }

    return &sessions[*highestLatencyId];
}

void updateSessionMetrics(Session *session, double requestLatency) {
    session->lastAccess = time(NULL);
    session->accessCount++;
    session->latencySum += requestLatency;
}
