        failed_count++;
        return NULL;
    }
    allocated_count++;
    memset(record->pdus, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
    pthread_mutex_lock(&pool_lock);
    request_pool = (HTTP_REQUEST_RECORD *)realloc(request_pool, (pool_size + 1) * sizeof(HTTP_REQUEST_RECORD));
    if (!request_pool) {
        free(record);
        failed_count++;
        return NULL;
    }
    request_pool[pool_size++] = *record;
    pthread_mutex_unlock(&pool_lock);
    log_message("Request allocated successfully");
    return record;
}

