        new_pdu->CRC_INDICATION_REL8_TAG = rand();
        new_pdu->CRCFLAG = rand() % 2;
        if (manager->logging_enabled) {
            log_structure_creation(new_pdu); // Assuming a logging function is defined
        }
        pthread_mutex_unlock(&manager->mutex);
        return new_pdu;
