public class DynamicRangeValueGenerator
{
    private readonly object _lock = new object();
    private readonly List<(double Min, double Max)> _ranges;
    private readonly Random _random;
    private NFAPI_CRC_INDICATION_PDU_T[] _crcPduArray;

    public DynamicRangeValueGenerator()
    {
        _ranges = new List<(double Min, double Max)>();
        _random = new Random();
    }

    public void AddRange(double min, double max)
    {
        lock (_lock)
        {
            if (Interlocked.CompareExchange(ref _ranges.Count, 0, 0) > 0 && _ranges.Any(r => r.Min < max || r.Max > min))
                throw new ArgumentException("Overlapping range detected.");

            _ranges.Add((min, max));
        }
    }

    public void RemoveRange(double min, double max)
    {
        lock (_lock)
        {
            var toRemove = _ranges.FirstOrDefault(r => r.Min == min && r.Max == max);
            if (toRemove != default)
                _ranges.Remove(toRemove);
        }
    }

    public float GenerateRandomFloat(double rangeMin, double rangeMax, bool includeBounds = true)
    {
        lock (_lock)
        {
            return (float)_random.NextDouble() * (rangeMax - rangeMin) + rangeMin;
        }
    }

    public int GenerateRandomInt(double rangeMin, double rangeMax, bool includeBounds = true)
    {
        lock (_lock)
        {
            return _random.Next((int)Math.Ceiling(rangeMin), (int)Math.Floor(rangeMax) + 1);
        }
    }

    public void InitializeCrcPduArray(int n)
    {
        lock (_lock)
        {
            _crcPduArray = new NFAPI_CRC_INDICATION_PDU_T[n];
            for (int i = 0; i < n; i++)
