    public NFAPI_CRC_INDICATION_PDU_T GetCrcPdu(int index)
    {
        lock (_lock)
        {
            if (index >= 0 && index < _crcPduArray.Length)
                return _crcPduArray[index];
            throw new IndexOutOfRangeException("Invalid index.");
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            var rangeStrings = _ranges.Select(r => $"[{r.Min}, {r.Max}]").ToArray();
            return $"DynamicRangeValueGenerator: Ranges={string.Join(", ", rangeStrings)}";
