#define MAX_FILES 1000

typedef struct {
    char path[256];
    int status; // 0 for free, 1 for in use
    time_t last_activity;
} FileDescriptor;

FileDescriptor file_pool[MAX_FILES];

void init_file_pool() {
    for (int i = 0; i < MAX_FILES; i++) {
        strcpy(file_pool[i].path, "");
        file_pool[i].status = 0;
        file_pool[i].last_activity = time(NULL);
    }
}

int allocate_file(const char *filename) {
    int i;
    for (i = 0; i < MAX_FILES; i++) {
        if (file_pool[i].status == 0) {
            strcpy(file_pool[i].path, filename);
            file_pool[i].status = 1;
            file_pool[i].last_activity = time(NULL);
            return i;
        }
    }
    // Handle no free slots
    fprintf(stderr, "No available file descriptors\n");
    return -1;
}

void release_file(int fd) {
    if (fd >= 0 && fd < MAX_FILES && file_pool[fd].status == 1) {
        file_pool[fd].status = 0;
        strcpy(file_pool[fd].path, "");
        // Optionally reset last_activity or add other cleanup logic
    }
}

int main() {
    init_file_pool();

    int fd = allocate_file("example.txt");
    if (fd != -1) {
        printf("File descriptor allocated: %d\n", fd);
        release_file(fd);
        printf("File descriptor released.\n");
    }

    return 0;
}
