void updateMetrics(int sessionId, double latency) {
    totalLatency += (clock_t)(latency * CLOCKS_PER_SEC);
    if (activeSessions > peakConcurrentAccess)
        peakConcurrentAccess = activeSessions;
}

void handleSessionExpiration() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].id != 0 && time(NULL) > sessions[i].expirationTime) {
            sessions[i].id = 0;
            activeSessions--;
        }
    }
}

void manageConcurrentAccess(int userId, int requestId) {
    // Implement fair access mechanism here
    // Example: Round-robin or token bucket algorithm
}

int getSessionWithHighestLatency() {
    int highestLatencyId = -1;
    double highestLatency = 0.0;

    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].id != 0) {
            double latency = ((double)(clock() - sessions[i].startTime)) / CLOCKS_PER_SEC;
            if (latency > highestLatency) {
                highestLatencyId = sessions[i].id;
                highestLatency = latency;
            }
        }
    }

    return highestLatencyId;
}

void getSessionMetrics(int *totalActive, int *peakConcurrent, double *averageLatency) {
    *totalActive = activeSessions;
    *peakConcurrent = peakConcurrentAccess;
    if (activeSessions == 0)
        *averageLatency = 0.0;
    else
        *averageLatency = ((double)totalLatency) / CLOCKS_PER_SEC / activeSessions;
}

void startSession(int userId, int sessionId, time_t expirationTime) {
    sessions[sessionId].id = userId;
    sessions[sessionId].expirationTime = expirationTime;
    sessions[sessionId].startTime = clock();
    activeSessions++;
}

void endSession(int sessionId) {
    sessions[sessionId].id = 0;
    activeSessions--;
}

// Example usage
int main() {
    time_t now = time(NULL);
    startSession(1, 0, now + 3600); // User 1 starts session 0 with an expiration of 1 hour

    manageConcurrentAccess(1, 1);

    handleSessionExpiration();

    int highestLatencyId;
    getSessionWithHighestLatency(&highestLatencyId);

    int totalActive, peakConcurrent;
    double averageLatency;
    getSessionMetrics(&totalActive, &peakConcurrent, &averageLatency);

    printf("Total Active Sessions: %d\n", totalActive);
    printf("Peak Concurrent Access: %d\n", peakConcurrent);
    printf("Average Latency: %.2f seconds\n", averageLatency);

    endSession(0); // User 1 ends session 0

    return 0;
}
