    REMOTE_URL url;
    LOCAL_PORT port;
    REQUEST_METHOD method;
    RESPONSE_STATUS status;
    NFAPI_CRC_INDICATION_PDU_T crc_indications[MAX_CRC_INDICATIONS];
} HTTP_REQUEST_RECORD;

typedef struct {
    pthread_mutex_t lock;
    HTTP_REQUEST_RECORD **pool;
    size_t size;
    size_t capacity;
    FILE *log_file;
    ExternalCachingService *cache;
} RequestPoolManager;

void initializeRequestPoolManager(RequestPoolManager *manager, size_t initial_capacity, FILE *log_file) {
    manager->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    manager->pool = malloc(initial_capacity * sizeof(HTTP_REQUEST_RECORD *));
    if (!manager->pool) {
        perror("Failed to allocate memory for request pool");
        exit(EXIT_FAILURE);
    }
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->log_file = log_file;
    manager->cache = initializeExternalCachingService();
}

void addRequestToPool(RequestPoolManager *manager, HTTP_REQUEST_RECORD *request) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        manager->pool = realloc(manager->pool, manager->capacity * 2 * sizeof(HTTP_REQUEST_RECORD *));
        if (!manager->pool) {
            perror("Failed to allocate memory for request pool");
            exit(EXIT_FAILURE);
        }
        manager->capacity *= 2;
    }
    manager->pool[manager->size++] = request;
    pthread_mutex_unlock(&manager->lock);
}

void manageHttpRequestPoolAndProcessData(RequestPoolManager *manager, HTTP_REQUEST_RECORD **requests, size_t num_requests) {
    for (size_t i = 0; i < num_requests; ++i) {
        addRequestToPool(manager, requests[i]);
    }
    // Process and validate data here
}

void cleanupRequestPoolManager(RequestPoolManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->pool[i]);
    }
    free(manager->pool);
    closeExternalCachingService(manager->cache);
    fclose(manager->log_file);
    pthread_mutex_unlock(&manager->lock);
}
