    std::string Connection_Status;
};

// Define NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
};

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures
void generateNFAPICRCIndicationPDUs(uint32_t numUEs, std::vector<NFAPI_CRC_INDICATION_PDU_T>& pool) {
    std::mutex mtx;
    std::condition_variable cv;
    bool ready = false;

    auto worker = [&mtx, &cv, &ready, &pool](uint32_t start, uint32_t end) {
        for (uint32_t i = start; i < end; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = i;
            pdu.RNTI = rand() % 65536; // Random RNTI
            pdu.CRC_INDICATION_REL8_TAG = (rand() & 1) ? 0x81 : 0x80; // Random CRCFLAG
            std::lock_guard<std::mutex> lock(mtx);
            pool.push_back(pdu);
        }
        ready = true;
        cv.notify_all();
    };

    const uint32_t numThreads = std::thread::hardware_concurrency() > 1 ? std::thread::hardware_concurrency() - 1 : 1;
    std::vector<std::thread> threads(numThreads);

    uint32_t chunkSize = numUEs / numThreads;
    for (uint32_t i = 0; i < numThreads; ++i) {
        uint32_t start = i * chunkSize;
        uint32_t end = (i == numThreads - 1) ? numUEs : start + chunkSize;
        threads[i] = std::thread(worker, start, end);
    }

    cv.wait(lock, [&ready]() { return ready; });

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    // Logging mechanism
    std::cout << "Generated " << pool.size() << " NFAPI_CRC_INDICATION_PDU_T structures." << std::endl;
}

// Main function
int main(int argc, char* argv[]) {
    uint32_t numUEs = 1000; // Example number of UEs

    if (argc > 1) {
        // Parse command line arguments
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "--num-ues") == 0 && i + 1 < argc) {
                numUEs = std::atoi(argv[++i]);
            }
        }
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pool;

    auto start = std::chrono::high_resolution_clock::now();
    generateNFAPICRCIndicationPDUs(numUEs, pool);
    auto end = std::chrono::high_resolution_clock::now();

    std::cout << "Total size of generated structures: " << pool.size() * sizeof(NFAPI_CRC_INDICATION_PDU_T) / 1024 / 1024 << " MB." << std::endl;
    std::cout << "Time taken to generate and populate the list: " 
              << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms." << std::endl;

    return 0;
}
```

