int add_packet_to_pool(PacketPool* pool, NicpPacket packet) {
    if (pool->used_size >= pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        NicpPacket* new_packets = (NicpPacket*)realloc(pool->packets, new_size * sizeof(NicpPacket));
        if (!new_packets) {
            return -1; // Memory allocation failure
        }
        pool->packets = new_packets;
        pool->allocated_size = new_size;
    }
    pool->packets[pool->used_size++] = packet;
    return 0;
}

