            }
            attempts++;
        }

        if (attempts == 3) {
            fprintf(stderr, "Error: Duplicate MD5 hash detected for string %s\n", input_strings[i]);
            continue;
        }

        pthread_mutex_lock(&lock);
        int result = add_packet_to_pool(packet_pool, packet);
        pthread_mutex_unlock(&lock);

        if (result != 0) {
            fprintf(stderr, "Error: Failed to add packet to pool\n");
            return -1;
        }
    }

    pthread_mutex_destroy(&lock);
    return 0;
