#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <pthread.h>

#define MAX_SOCKETS 1024
#define PAYLOAD_STACK_SIZE 512

typedef enum {
    SOCKET_STATE_ACTIVE,
    SOCKET_STATE_INACTIVE
} SOCKET_STATE;

typedef struct {
    int payload_size;
    char stack_payload[PAYLOAD_STACK_SIZE];
    void* heap_payload;
} SOCKET_HEADER;

typedef struct {
    pthread_mutex_t lock;
    int id;
    SOCKET_HEADER header;
    SOCKET_STATE state;
    struct timespec timeout;
} SOCKET_CONTEXT;

SOCKET_CONTEXT sockets[MAX_SOCKETS];
int socket_count = 0;
pthread_mutex_t socket_lock;

void init_socket_context(int id, int payload_size) {
    pthread_mutex_init(&sockets[id].lock, NULL);
    sockets[id].id = id;
    sockets[id].header.payload_size = payload_size;
    if (payload_size <= PAYLOAD_STACK_SIZE) {
        sockets[id].header.heap_payload = NULL;
    } else {
        sockets[id].header.heap_payload = malloc(payload_size);
    }
    sockets[id].state = SOCKET_STATE_INACTIVE;
}

void* manage_sockets(void* arg) {
    while (1) {
        pthread_mutex_lock(&socket_lock);
        for (int i = 0; i < socket_count; i++) {
            if (sockets[i].state == SOCKET_STATE_ACTIVE && 
                clock_gettime(CLOCK_REALTIME, &sockets[i].timeout) < 0) {
                sockets[i].state = SOCKET_STATE_INACTIVE;
            }
        }
        pthread_mutex_unlock(&socket_lock);
        sleep(1); // Simulate periodic cleanup
    }
    return NULL;
}

void* process_socket(void* arg) {
    int id = *(int*)arg;
    if (id < 0 || id >= MAX_SOCKETS) {
        fprintf(stderr, "Invalid socket ID\n");
        return NULL;
    }

    pthread_mutex_lock(&socket_lock);
    if (sockets[id].state == SOCKET_STATE_INACTIVE) {
        sockets[id].state = SOCKET_STATE_ACTIVE;
        // Simulate processing
        sleep(1);
        sockets[id].state = SOCKET_STATE_INACTIVE;
    }
    pthread_mutex_unlock(&socket_lock);

    return NULL;
}

int main() {
    pthread_t cleanup_thread;

    // Initialize socket contexts
    for (int i = 0; i < MAX_SOCKETS; i++) {
        init_socket_context(i, 128); // Example payload size
    }
    socket_count = MAX_SOCKETS / 2; // Simulate half of the sockets in use

    // Start cleanup thread
    pthread_create(&cleanup_thread, NULL, manage_sockets, NULL);

    // Process some sockets asynchronously
    int ids[] = {0, 1, 2};
    for (int i = 0; i < sizeof(ids) / sizeof(int); i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_socket, &ids[i]);
    }

    pthread_join(cleanup_thread, NULL);
    return 0;
}
