void add_event_to_window(int id, int priority) {
    if(time(NULL) - sliding_window_start_time > WINDOW_SIZE_SECONDS) {
        sliding_window_start_time = time(NULL);
        // Clear old events
        for(int i = 0; i < MAX_HASH_SIZE; i++) {
            Event* current = event_hash_table[i];
            while(current != NULL) {
                Event* next = current->next;
                free(current);
                current = next;
            }
            event_hash_table[i] = NULL;
        }
    }

    int hash_index = id % MAX_HASH_SIZE;
    Event* new_event = (Event*)malloc(sizeof(Event));
    new_event->id = id;
    new_event->timestamp = time(NULL);
    new_event->priority = priority;
    new_event->next = event_hash_table[hash_index];
    event_hash_table[hash_index] = new_event;

    if(priority > highest_priority || (priority == highest_priority && id < highest_priority_id)) {
        highest_priority = priority;
        highest_priority_id = id;
    }
}

int find_largest_integer(int* array, int size) {
    int largest = array[0];
    for(int i = 1; i < size; i++) {
        if(array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void process_event_feed() {
    initialize_event_system();
    while(1) {
        // Simulate reading events from external source
        int event_id, priority;
        scanf("%d %d", &event_id, &priority);
        add_event_to_window(event_id, priority);

        if(time(NULL) - sliding_window_start_time > WINDOW_SIZE_SECONDS) {
            printf("Highest Priority Event ID: %d\n", highest_priority_id);
            break; // Exit after processing events for 30 minutes
        }
    }
}

int main() {
    int array[] = {10, 20, 5, 30, 40};
    int size = sizeof(array) / sizeof(array[0]);
    printf("Largest Integer: %d\n", find_largest_integer(array, size));
    process_event_feed();
    return 0;
}
