#include <mutex>
#include <unordered_map>
#include <string>

class AccountManager {
public:
    struct Account {
        int id;
        std::string username;
        std::string email;
        std::string role;

        Account(int id, const std::string& username, const std::string& email, const std::string& role)
            : id(id), username(username), email(email), role(role) {}
    };

private:
    std::vector<Account> accounts_;
    std::unordered_map<int, size_t> idIndexMap_;
    std::unordered_map<std::string, size_t> emailIndexMap_;
    std::mutex mutex_;

public:
    void addAccount(const Account& account) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (idIndexMap_.find(account.id) != idIndexMap_.end() ||
            emailIndexMap_.find(account.email) != emailIndexMap_.end()) {
            throw std::runtime_error("Duplicate ID or Email");
        }
        accounts_.push_back(account);
        idIndexMap_[account.id] = accounts_.size() - 1;
        emailIndexMap_[account.email] = accounts_.size() - 1;
    }

    void updateAccount(int id, const Account& updatedAccount) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = idIndexMap_.find(id);
        if (it == idIndexMap_.end()) {
            throw std::runtime_error("Account not found");
        }
        size_t index = it->second;
        if (updatedAccount.email != accounts_[index].email) {
            emailIndexMap_.erase(accounts_[index].email);
            emailIndexMap_[updatedAccount.email] = index;
        }
        accounts_[index] = updatedAccount;
    }

    Account* findAccountById(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = idIndexMap_.find(id);
        if (it == idIndexMap_.end()) {
            return nullptr;
        }
        return &accounts_[it->second];
    }

    Account* findAccountByUsername(const std::string& username) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& acc : accounts_) {
            if (acc.username == username) {
                return &acc;
            }
        }
        return nullptr;
    }

    void checkIntegrity() {
        std::unordered_set<std::string> seenEmails;
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& acc : accounts_) {
            if (!seenEmails.insert(acc.email).second) {
                throw std::runtime_error("Duplicate Email found");
            }
        }
    }

    void iterateAccounts(const std::function<void(const Account&)>& func) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& acc : accounts_) {
            func(acc);
        }
    }
};
