class UserAccountManager {
public:
    struct Account {
        int id;
        std::string username;
        std::string email;
        std::string role;
    };

private:
    std::vector<Account> accounts;
    std::map<int, size_t> idIndexMap;
    std::map<std::string, size_t> usernameIndexMap;
    mutable std::mutex mtx;

public:
    void addUserAccount(const Account& account) {
        std::lock_guard<std::mutex> lock(mtx);
        if (idIndexMap.find(account.id) != idIndexMap.end()) {
            throw std::runtime_error("Duplicate user ID");
        }
        if (usernameIndexMap.find(account.username) != usernameIndexMap.end()) {
            throw std::runtime_error("Duplicate username");
        }
        accounts.push_back(account);
        idIndexMap[account.id] = accounts.size() - 1;
        usernameIndexMap[account.username] = accounts.size() - 1;
    }

    void updateAccount(int id, const Account& newAccount) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = idIndexMap.find(id);
        if (it == idIndexMap.end()) {
            throw std::runtime_error("User ID not found");
        }
        if (newAccount.id != id && idIndexMap.find(newAccount.id) != idIndexMap.end()) {
            throw std::runtime_error("Duplicate user ID");
        }
        if (usernameIndexMap.find(newAccount.username) != usernameIndexMap.end() &&
            usernameIndexMap[newAccount.username] != it->second) {
            throw std::runtime_error("Duplicate username");
        }
        accounts[it->second] = newAccount;
        if (newAccount.id != id) {
            idIndexMap.erase(id);
            idIndexMap[newAccount.id] = it->second;
        }
        if (accounts[it->second].username != newAccount.username) {
            usernameIndexMap.erase(accounts[it->second].username);
            usernameIndexMap[newAccount.username] = it->second;
        }
    }

    Account findAccountByID(int id) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = idIndexMap.find(id);
        if (it == idIndexMap.end()) {
            throw std::runtime_error("User ID not found");
        }
        return accounts[it->second];
    }

    Account findAccountByUsername(const std::string& username) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = usernameIndexMap.find(username);
        if (it == usernameIndexMap.end()) {
            throw std::runtime_error("Username not found");
        }
        return accounts[it->second];
    }

    void checkDuplicateEmails() const {
        std::lock_guard<std::mutex> lock(mtx);
        std::map<std::string, size_t> emailCount;
        for (const auto& account : accounts) {
            if (emailCount.find(account.email) != emailCount.end()) {
                throw std::runtime_error("Duplicate email found");
            }
            emailCount[account.email]++;
        }
    }

    int getSequenceNumberFromLastLine(const std::string& filePath) const {
        std::lock_guard<std::mutex> lock(mtx);
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }
        int sequenceNumber = 0;
        std::string line;
        while (std::getline(file, line)) {}
        if (!line.empty()) {
            try {
                sequenceNumber = std::stoi(line);
            } catch (...) {
                throw std::runtime_error("Invalid sequence number format in file");
            }
        }
        return sequenceNumber;
    }

    void sortAccountsByRole() {
        std::lock_guard<std::mutex> lock(mtx);
        std::sort(accounts.begin(), accounts.end(), [](const Account& a, const Account& b) {
            return a.role < b.role;
        });
        idIndexMap.clear();
        usernameIndexMap.clear();
        for (size_t i = 0; i < accounts.size(); ++i) {
            idIndexMap[accounts[i].id] = i;
            usernameIndexMap[accounts[i].username] = i;
        }
    }

    void printAllAccounts() const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& account : accounts) {
            std::cout << "ID: " << account.id << ", Username: " << account.username
                      << ", Email: " << account.email << ", Role: " << account.role << std::endl;
        }
    }
};
