#include <stdlib.h>
#include <string.h>

typedef struct {
    int Customer_ID;
    time_t Call_Start_Time;
    time_t Call_End_Time;
    char Calling_Number[15];
    char Receiving_Number[15];
} CDR;

typedef struct Node {
    CDR data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node** cache;
    int cache_size;
    int cache_count;
    pthread_mutex_t lock;
} DynamicCDRArray;

DynamicCDRArray* create_dynamic_cdr_array(int cache_size) {
    DynamicCDRArray* array = (DynamicCDRArray*)malloc(sizeof(DynamicCDRArray));
    array->head = NULL;
    array->cache_size = cache_size;
    array->cache_count = 0;
    array->cache = (Node**)malloc(cache_size * sizeof(Node*));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void add_cdr(DynamicCDRArray* array, CDR cdr) {
    pthread_mutex_lock(&array->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = cdr;
    new_node->next = array->head;
    array->head = new_node;

    if (array->cache_count < array->cache_size) {
        array->cache[array->cache_count++] = new_node;
    } else {
        // Replace least recently used cache entry
        Node* lru = array->cache[0];
        for (int i = 1; i < array->cache_size; i++) {
            if (array->cache[i]->data.Call_End_Time < lru->data.Call_End_Time) {
                lru = array->cache[i];
            }
        }
        int index;
        for (index = 0; index < array->cache_size; index++) {
            if (array->cache[index] == lru) break;
        }
        array->cache[index] = new_node;
    }

    pthread_mutex_unlock(&array->lock);
}

void remove_cdr(DynamicCDRArray* array, int customer_id) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.Customer_ID == customer_id) {
            if (previous == NULL) {
                array->head = current->next;
            } else {
                previous->next = current->next;
            }

            for (int i = 0; i < array->cache_count; i++) {
                if (array->cache[i] == current) {
                    // Replace with last cache entry
                    array->cache[i] = array->cache[array->cache_count - 1];
                    array->cache_count--;
                    break;
                }
            }

            free(current);
        } else {
            previous = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void update_cdr(DynamicCDRArray* array, int customer_id, time_t new_start_time, time_t new_end_time) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;

    while (current != NULL) {
        if (current->data.Customer_ID == customer_id) {
            current->data.Call_Start_Time = new_start_time;
            current->data.Call_End_Time = new_end_time;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void calculate_total_duration(DynamicCDRArray* array, int customer_id, time_t start_period, time_t end_period) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    time_t total_duration = 0;

    while (current != NULL) {
        if (current->data.Customer_ID == customer_id && current->data.Call_Start_Time >= start_period && current->data.Call_End_Time <= end_period) {
            total_duration += difftime(current->data.Call_End_Time, current->data.Call_Start_Time);
        }
        current = current->next;
    }

    printf("Total Duration for Customer %d from %ld to %ld: %ld seconds\n", customer_id, start_period, end_period, total_duration);

    pthread_mutex_unlock(&array->lock);
}

void destroy_dynamic_cdr_array(DynamicCDRArray* array) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&array->lock);

    free(array->cache);
    free(array);
}
