typedef struct {
    int rx_ue_info_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct memory_pool_t {
    void* pool;
    size_t size;
    size_t block_size;
    size_t free_count;
    pthread_mutex_t lock;
} memory_pool_t;

memory_pool_t memory_pool;

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.free_count > 0) {
        void* block = memory_pool.pool + ((memory_pool.size - memory_pool.block_size * memory_pool.free_count) / memory_pool.block_size * memory_pool.block_size);
        memory_pool.free_count--;
        pthread_mutex_unlock(&memory_pool.lock);
        return block;
    } else {
        pthread_mutex_unlock(&memory_pool.lock);
        return malloc(size);
    }
}

void deallocate_memory(void* ptr, size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.size - memory_pool.block_size * memory_pool.free_count < memory_pool.block_size) {
        free(ptr);
    } else {
        // Assuming the pool is large enough to handle deallocations
        // This part of the code assumes a circular buffer approach for simplicity
        size_t block_index = ((char*)ptr - (char*)memory_pool.pool) / memory_pool.block_size;
        char* next_block = (char*)memory_pool.pool + ((block_index + 1) * memory_pool.block_size);
        memcpy(next_block, ptr, size);
        memory_pool.free_count++;
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

