#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define HTTP_REQUEST_RECORD structure
typedef struct {
    char *filePath;
    int fileSize;
} HTTP_REQUEST_RECORD;

// Define cache node structure for distributed cache
typedef struct CacheNode {
    char *fileHash;
    long lastModified;
    int size;
    char **tags;
    struct CacheNode *next;
} CacheNode;

// Define cache structure
typedef struct {
    CacheNode *head;
    pthread_mutex_t lock;
} DistributedCache;

// Function to initialize distributed cache
void init_cache(DistributedCache *cache) {
    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

// Function to add or update metadata in the cache
void update_metadata(DistributedCache *cache, const char *fileHash, long lastModified, int size, char **tags) {
    pthread_mutex_lock(&cache->lock);
    CacheNode *current = cache->head;
    while (current != NULL) {
        if (strcmp(current->fileHash, fileHash) == 0) {
            current->lastModified = lastModified;
            current->size = size;
            current->tags = tags;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }
    CacheNode *newNode = (CacheNode *)malloc(sizeof(CacheNode));
    newNode->fileHash = strdup(fileHash);
    newNode->lastModified = lastModified;
    newNode->size = size;
    newNode->tags = tags;
    newNode->next = cache->head;
    cache->head = newNode;
    pthread_mutex_unlock(&cache->lock);
}

// Function to retrieve metadata from the cache
void *retrieve_metadata(DistributedCache *cache, const char *fileHash) {
    pthread_mutex_lock(&cache->lock);
    CacheNode *current = cache->head;
    while (current != NULL) {
        if (strcmp(current->fileHash, fileHash) == 0) {
            void *result = malloc(sizeof(void *));
            memcpy(result, &current, sizeof(CacheNode));
            pthread_mutex_unlock(&cache->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Function to clean up the cache
void cleanup_cache(DistributedCache *cache) {
    CacheNode *current = cache->head;
    while (current != NULL) {
        CacheNode *temp = current;
        free(temp->fileHash);
        for (int i = 0; temp->tags[i] != NULL; i++) {
            free(temp->tags[i]);
        }
        free(temp->tags);
        free(temp);
        current = temp->next;
    }
    pthread_mutex_destroy(&cache->lock);
}

// Example usage
int main() {
    DistributedCache cache;
    init_cache(&cache);

    // Simulate retrieving metadata for a file
    void *result = retrieve_metadata(&cache, "some_file_hash");
    if (result != NULL) {
        CacheNode *node = (CacheNode *)result;
        printf("File Size: %d\n", node->size);
        printf("Last Modified: %ld\n", node->lastModified);
        // Free the result when done
        free(result);
    } else {
        printf("Metadata not found.\n");
    }

    cleanup_cache(&cache);
    return 0;
}
