#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_THREADS 16
#define MEMORY_THRESHOLD (1024 * 1024 * 500) // 500MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* memory;
    size_t size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t size) {
    pool->memory = malloc(size);
    pool->size = size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    pool->used_size = 0;
    pthread_mutex_unlock(&pool->lock);
    free(pool->memory);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size + size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* addr = (char*)pool->memory + pool->used_size;
    pool->used_size += size;
    pthread_mutex_unlock(&pool->lock);
    return addr;
}

void log_memory_usage(MemoryPool* pool, FILE* log_file) {
    fprintf(log_file, "Memory usage: %zu/%zu\n", pool->used_size, pool->size);
}

void generate_nfaapi_list(int N, MemoryPool* pool, FILE* log_file) {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];
    size_t total_allocated = 0;

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, generate_nfaapi_thread_func, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    log_memory_usage(pool, log_file);

    if (total_allocated > MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded. Terminating gracefully.\n");
        exit(EXIT_FAILURE);
    }
}

void* generate_nfaapi_thread_func(void* arg) {
