#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define CDR structure
typedef struct {
    int Customer_ID;
    time_t Call_Start_Time;
    time_t Call_End_Time;
    char Calling_Number[15];
    char Receiving_Number[15];
} CDR;

// Define CDR list structure
typedef struct CDRNode {
    CDR cdr;
    struct CDRNode* next;
} CDRNode;

// Define CDR cache structure
typedef struct {
    int Customer_ID;
    time_t Total_Duration;
    pthread_mutex_t lock;
} CDRCache;

// Define global variables
CDRNode* cdr_list = NULL;
pthread_mutex_t cdr_list_lock = PTHREAD_MUTEX_INITIALIZER;
int max_cache_size = 1000; // Maximum size of the cache
CDRCache** cdr_cache = (CDRCache**)calloc(max_cache_size, sizeof(CDRCache*));
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add new CDR entry
void add_cdr(CDRcdr) {
    pthread_mutex_lock(&cdr_list_lock);
    CDRNode* newNode = malloc(sizeof(CDRNode));
    newNode->cdr = cdr;
    newNode->next = cdr_list;
    cdr_list = newNode;
    pthread_mutex_unlock(&cdr_list_lock);

    // Update cache
    update_cache(cdr.Customer_ID, cdr.Call_Start_Time, cdr.Call_End_Time);
}

// Function to remove CDR entry based on Customer ID
void remove_cdr(int customer_id) {
    pthread_mutex_lock(&cdr_list_lock);
    CDRNode* current = cdr_list;
    CDRNode* previous = NULL;

    while (current != NULL) {
        if (current->cdr.Customer_ID == customer_id) {
            if (previous == NULL) {
                cdr_list = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&cdr_list_lock);

            // Remove from cache
            remove_from_cache(customer_id);

            return;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&cdr_list_lock);
}

// Function to update CDR details such as start or end time
void update_cdr(int customer_id, time_t new_start_time, time_t new_end_time) {
    pthread_mutex_lock(&cdr_list_lock);
    CDRNode* current = cdr_list;

    while (current != NULL) {
        if (current->cdr.Customer_ID == customer_id) {
            current->cdr.Call_Start_Time = new_start_time;
            current->cdr.Call_End_Time = new_end_time;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cdr_list_lock);

    // Update cache
    update_cache(customer_id, new_start_time, new_end_time);
}

// Function to calculate total duration of calls for each customer over a specified period
time_t get_total_duration(int customer_id) {
    pthread_mutex_lock(&cache_lock);
    CDRCache* cache_entry = cdr_cache[customer_id % max_cache_size];

    if (cache_entry != NULL) {
        time_t current_time = time(NULL);
        if ((current_time - cache_entry->Total_Duration) > 60) { // Cache entry is older than 1 minute
            update_cache(customer_id, 0, current_time); // Update cache with new total duration
            pthread_mutex_unlock(&cache_lock);
            return cache_entry->Total_Duration;
        }
        pthread_mutex_unlock(&cache_lock);
        return cache_entry->Total_Duration;
    }

    pthread_mutex_unlock(&cache_lock);

    time_t total_duration = 0;

    pthread_mutex_lock(&cdr_list_lock);
    CDRNode* current = cdr_list;

    while (current != NULL) {
        if (current->cdr.Customer_ID == customer_id) {
            total_duration += difftime(current->cdr.Call_End_Time, current->cdr.Call_Start_Time);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cdr_list_lock);

    // Update cache
    update_cache(customer_id, 0, time(NULL));

    return total_duration;
}

// Function to update cache with new total duration for a customer
void update_cache(int customer_id, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&cache_lock);
    CDRCache* cache_entry = cdr_cache[customer_id % max_cache_size];

    if (cache_entry == NULL) {
        cache_entry = malloc(sizeof(CDRCache));
        cache_entry->Customer_ID = customer_id;
        pthread_mutex_init(&cache_entry->lock, NULL);
        cdr_cache[customer_id % max_cache_size] = cache_entry;
    }

    time_t new_total_duration = 0;

    if (start_time != 0 && end_time != 0) {
        new_total_duration += difftime(end_time, start_time);
    } else {
        pthread_mutex_lock(&cdr_list_lock);
        CDRNode* current = cdr_list;

        while (current != NULL) {
            if (current->cdr.Customer_ID == customer_id) {
                new_total_duration += difftime(current->cdr.Call_End_Time, current->cdr.Call_Start_Time);
            }
            current = current->next;
        }

        pthread_mutex_unlock(&cdr_list_lock);
    }

    cache_entry->Total_Duration = new_total_duration;

    pthread_mutex_unlock(&cache_lock);
}

// Function to remove a customer's entry from the cache
void remove_from_cache(int customer_id) {
    pthread_mutex_lock(&cache_lock);
    CDRCache* cache_entry = cdr_cache[customer_id % max_cache_size];

    if (cache_entry != NULL) {
        free(cache_entry);
        cdr_cache[customer_id % max_cache_size] = NULL;
    }

    pthread_mutex_unlock(&cache_lock);
}

// Function to handle bulk processing of CDRs
void process_bulk_cdr(CDR* cdrr, int count) {
    for (int i = 0; i < count; i++) {
        switch (cdrr[i].Action) {
            case ADD:
                add_cdr(cdrr[i]);
                break;
            case REMOVE:
                remove_cdr(cdrr[i].Customer_ID);
                break;
            case UPDATE:
                update_cdr(cdrr[i].Customer_ID, cdrr[i].Call_Start_Time, cdrr[i].Call_End_Time);
                break;
        }
    }
}
