#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define MAX_TASKS 1024
#define MAX_CONCURRENT_TASKS 50

typedef enum { PRIORITY_HIGH, PRIORITY_MEDIUM, PRIORITY_LOW } task_priority;
typedef enum { STATUS_PENDING, STATUS_RUNNING, STATUS_COMPLETED, STATUS_FAILED } task_status;

typedef struct {
    int id;
    task_priority priority;
    task_status status;
    void (*task_func)();
} Task;

Task task_queue[MAX_TASKS];
int task_count = 0;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
int running_tasks = 0;
pthread_mutex_t concurrency_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t stop_flag = 0;

void enqueue_task(Task *task) {
    pthread_mutex_lock(&queue_mutex);
    if (task_count < MAX_TASKS) {
        task_queue[task_count++] = *task;
        pthread_cond_signal(&queue_cond);
    }
    pthread_mutex_unlock(&queue_mutex);
}

void* worker_thread(void* arg) {
    while (!stop_flag) {
        Task current_task;
        pthread_mutex_lock(&queue_mutex);
        while (task_count == 0 && !stop_flag) {
            pthread_cond_wait(&queue_cond, &queue_mutex);
        }
        if (stop_flag) break;

        current_task = task_queue[--task_count];
        pthread_mutex_unlock(&queue_mutex);

        pthread_mutex_lock(&concurrency_mutex);
        if (running_tasks < MAX_CONCURRENT_TASKS) {
            running_tasks++;
            pthread_mutex_unlock(&concurrency_mutex);

            current_task.task_func();

            pthread_mutex_lock(&concurrency_mutex);
            running_tasks--;
        } else {
            pthread_mutex_unlock(&concurrency_mutex);
            // Handle task queueing or retry logic
        }
    }
    return NULL;
}

void init_scheduler(int num_threads) {
    for (int i = 0; i < num_threads; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, worker_thread, NULL);
    }
    signal(SIGTERM, [](int signum) { stop_flag = 1; });
}

void schedule_task(Task *task, int delay_ms) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    now.tv_sec += delay_ms / 1000;
    now.tv_nsec += (delay_ms % 1000) * 1000000;

    pthread_mutex_lock(&queue_mutex);
    task_queue[task_count++] = *task;
    pthread_cond_timedwait(&queue_cond, &queue_mutex, &now);
    pthread_mutex_unlock(&queue_mutex);
}

void cancel_task(int task_id) {
    pthread_mutex_lock(&queue_mutex);
    for (int i = 0; i < task_count; i++) {
        if (task_queue[i].id == task_id) {
            // Mark task as canceled or remove it from the queue
            break;
        }
    }
    pthread_mutex_unlock(&queue_mutex);
}

void finalize_scheduler() {
    stop_flag = 1;
    pthread_cond_broadcast(&queue_cond);

    for (int i = 0; i < MAX_CONCURRENT_TASKS; i++) {
        void* result;
        pthread_join(worker_threads[i], &result);
    }
}
