    RandomValueGenerator(int min, int max) : generator(std::random_device()()), distribution(min, max) {}

    int generateRandomInt(bool inclusive = true) {
        return inclusive ? distribution(generator) : distribution(generator) - 1;
    }

    double generateRandomFloat(bool inclusive = true) {
        std::uniform_real_distribution<> floatDistribution(0.0, 1.0);
        double randomValue = floatDistribution(generator);
        return inclusive ? randomValue * (distribution.max() - distribution.min()) + distribution.min() : randomValue * (distribution.max() - distribution.min());
    }

    std::vector<int> generateUniqueRandomInts(int count) {
        if (count > (distribution.max() - distribution.min())) {
            throw std::invalid_argument("Count exceeds the range size.");
        }
        std::vector<int> uniqueValues;
        while (uniqueValues.size() < count) {
            int value = generateRandomInt();
            if (std::find(uniqueValues.begin(), uniqueValues.end(), value) == uniqueValues.end()) {
                uniqueValues.push_back(value);
            }
        }
        return uniqueValues;
    }

    std::string ToString() const {
        return "Range: [" + std::to_string(distribution.min()) + ", " + std::to_string(distribution.max()) + "]";
    }
};

class DynamicNfadbManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> pool;
    std::mutex poolMutex;
    RandomValueGenerator randomGenerator;
    int maxStructures;

public:
    DynamicNfadbManager(int maxStructures = 10000) : maxStructures(maxStructures), randomGenerator(0, maxStructures) {}

    NFAPI_CRC_INDICATION_PDU_T* createStructure() {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (pool.empty()) {
            pool.push_back(new NFAPI_CRC_INDICATION_PDU_T());
        }
        NFAPI_CRC_INDICATION_PDU_T* newStruct = pool.back();
        pool.pop_back();

        newStruct->RX_UE_INFORMATION_TAG = randomGenerator.generateRandomInt();
        newStruct->RNTI = randomGenerator.generateRandomInt();
        newStruct->CRC_INDICATION_REL8_TAG = randomGenerator.generateRandomInt();
        newStruct->CRCFLAG = randomGenerator.generateRandomInt() % 2 == 0;

        // Log creation for auditing
        std::cout << "Structure created: RX_UE_INFORMATION_TAG=" << newStruct->RX_UE_INFORMATION_TAG 
                  << ", RNTI=" << newStruct->RNTI 
                  << ", CRC_INDICATION_REL8_TAG=" << newStruct->CRC_INDICATION_REL8_TAG 
                  << ", CRCFLAG=" << newStruct->CRCFLAG << std::endl;

        return newStruct;
    }

    ~DynamicNfadbManager() {
        std::lock_guard<std::mutex> lock(poolMutex);
        for (auto& structPtr : pool) {
            delete structPtr;
        }
    }
};

int main() {
    DynamicNfadbManager manager(5000);
    NFAPI_CRC_INDICATION_PDU_T* newStruct = manager.createStructure();
    std::cout << "New structure created: " << newStruct->RX_UE_INFORMATION_TAG 
              << ", " << newStruct->RNTI 
              << ", " << newStruct->CRC_INDICATION_REL8_TAG 
              << ", " << newStruct->CRCFLAG << std::endl;
    delete newStruct; // Remember to properly manage memory
    return 0;
}
