#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define fields as per the requirement
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void appendToLinkedList(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_LIST_SIZE) {
        Node* oldHead = list->head;
        list->head = oldHead->next;
        free(oldHead);
        list->count--;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newNode->data = data;
    newNode->next = NULL;
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void serializeLinkedList(LinkedList* list, FILE* file) {
    pthread_mutex_lock(&list->mutex);
    fwrite(&list->count, sizeof(size_t), 1, file);
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void deserializeLinkedList(LinkedList* list, FILE* file) {
    pthread_mutex_lock(&list->mutex);
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        appendToLinkedList(list, data);
    }
    pthread_mutex_unlock(&list->mutex);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
