        return -1;
    }

    size_t written = fwrite(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    if (written != list->count) {
        log_message("Error during serialization");
        fclose(file);
        return -1;
    }

    fclose(file);
    log_message("Serialization successful");
    return 0;
}

int deserialize_list(CRC_Indication_List *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t total_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (total_size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        log_message("Invalid file format");
        fclose(file);
        return -1;
    }

    size_t element_count = total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->array, element_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message("Memory reallocation failed");
        fclose(file);
        return -1;
    }
    list->array = new_array;
    list->allocated_count = element_count;

    size_t read_count = fread(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), element_count, file);
    if (read_count != element_count) {
        log_message("Error during deserialization");
        fclose(file);
        return -1;
    }

    list->count = element_count;
    fclose(file);
    log_message("Deserialization successful");
    return 0;
}

int main() {
    CRC_Indication_List crc_list;
    if (allocate_memory(&crc_list, MAX_ALLOC_SIZE) != 0) {
        return -1;
    }

    for (size_t i = 0; i < 500; ++i) {
