#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t RNTI;
    PHY_RX_PDU pdu;
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T *buffer;
    size_t front, rear;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} Queue;

Queue* queue_create(size_t capacity) {
    Queue *q = (Queue*)malloc(sizeof(Queue));
    q->buffer = (NFAPI_RX_PDU_T*)malloc(capacity * sizeof(NFAPI_RX_PDU_T));
    q->front = q->rear = 0;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    return q;
}

void queue_destroy(Queue *q) {
    free(q->buffer);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
    free(q);
}

int enqueue(Queue *q, NFAPI_RX_PDU_T item) {
    pthread_mutex_lock(&q->lock);
    while (q->size == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    q->buffer[q->rear] = item;
    q->rear = (q->rear + 1) % MAX_QUEUE_SIZE;
    q->size++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
    return 0; // Success
}

int dequeue(Queue *q, NFAPI_RX_PDU_T *item) {
    pthread_mutex_lock(&q->lock);
    while (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    *item = q->buffer[q->front];
    q->front = (q->front + 1) % MAX_QUEUE_SIZE;
    q->size--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return 0; // Success
}

// Serialization and deserialization functions would go here
