#define MAX_ENTRIES 100

typedef struct UEIdentifier {
    int id;
} UEIdentifier;

typedef struct CellIdentity {
    int identity;
} CellIdentity;

typedef struct SignalStrength {
    float strength;
} SignalStrength;

typedef struct NetworkEntityStatus {
    UEIdentifier ueId;
    CellIdentity cellId;
    SignalStrength signalStrength;
    struct NetworkEntityStatus *next;
} NetworkEntityStatus;

NetworkEntityStatus* initializeLinkedList() {
    NetworkEntityStatus *head = NULL;
    NetworkEntityStatus *current = NULL;
    for (int i = 0; i < MAX_ENTRIES; i++) {
        NetworkEntityStatus *newEntry = malloc(sizeof(NetworkEntityStatus));
        if (newEntry == NULL) {
            printf("Memory allocation failed.\n");
            return head;
        }
        newEntry->ueId.id = i + 1;
        newEntry->cellId.identity = i * 100;
        newEntry->signalStrength.strength = (float)(i * 5);
        newEntry->next = NULL;

        if (head == NULL) {
            head = newEntry;
            current = newEntry;
        } else {
            current->next = newEntry;
            current = newEntry;
        }
    }

    return head;
}

void printLinkedList(NetworkEntityStatus *head) {
    NetworkEntityStatus *current = head;
    while (current != NULL) {
        printf("UE ID: %d, Cell ID: %d, Signal Strength: %.2f\n",
               current->ueId.id, current->cellId.identity, current->signalStrength.strength);
        current = current->next;
    }
}

void freeLinkedList(NetworkEntityStatus *head) {
    NetworkEntityStatus *current = head;
    while (current != NULL) {
        NetworkEntityStatus *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    NetworkEntityStatus *list = initializeLinkedList();
    printLinkedList(list);
    freeLinkedList(list);
    return 0;
