    int UEIdentifier;
    int CellIdentity;
    float SignalStrength;
    struct NetworkEntityStatus *prev, *next;
} NetworkEntityStatus;

typedef struct DoublyLinkedList {
    NetworkEntityStatus *head, *tail;
    pthread_mutex_t lock;
    float averageSignalStrength;
    int count;
} DoublyLinkedList;

DoublyLinkedList* initNetworkList() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL; // Handle memory allocation failure

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->averageSignalStrength = 0.0f;
    list->count = 0;

    return list;
}

void addNetworkEntity(DoublyLinkedList *list, int UEIdentifier, int CellIdentity, float SignalStrength) {
    pthread_mutex_lock(&list->lock);

    NetworkEntityStatus *newEntry = (NetworkEntityStatus*)malloc(sizeof(NetworkEntityStatus));
    if (!newEntry) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }

    newEntry->UEIdentifier = UEIdentifier;
    newEntry->CellIdentity = CellIdentity;
    newEntry->SignalStrength = SignalStrength;
    newEntry->prev = list->tail;
    newEntry->next = NULL;

    if (list->tail) {
        list->tail->next = newEntry;
    } else {
        list->head = newEntry;
    }
    list->tail = newEntry;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void updateSignalStrength(DoublyLinkedList *list, int UEIdentifier, float SignalStrength) {
    pthread_mutex_lock(&list->lock);

    NetworkEntityStatus *current = list->head;
    while (current) {
        if (current->UEIdentifier == UEIdentifier) {
            current->SignalStrength = SignalStrength;
            break;
        }
        current = current->next;
    }

    // Recalculate average signal strength
    float totalStrength = 0.0f;
    current = list->head;
    while (current) {
        totalStrength += current->SignalStrength;
        current = current->next;
    }
    list->averageSignalStrength = totalStrength / list->count;

    pthread_mutex_unlock(&list->lock);
}

void freeNetworkList(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    NetworkEntityStatus *current = list->head;
    while (current) {
        NetworkEntityStatus *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
