#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_EVENTS 20000
#define WINDOW_SIZE_SECONDS (30 * 60)
#define INITIAL_ARRAY_SIZE 1000

typedef struct {
    int id;
    time_t timestamp;
    int priority;
} Event;

typedef struct HashNode {
    Event event;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t size;
} HashTable;

typedef struct {
    Event events[MAX_EVENTS];
    int count;
    int highestPriority;
    int highestPriorityId;
} EventManager;

void initHashTable(HashTable* table, size_t size) {
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    table->size = size;
}

int hashFunction(int id, size_t size) {
    return abs(id % size);
}

void insertEvent(EventManager* manager, Event event, HashTable* table) {
    int index = hashFunction(event.id, table->size);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->event = event;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    // Update highest priority
    if (event.priority > manager->highestPriority || 
        (event.priority == manager->highestPriority && event.id < manager->highestPriorityId)) {
        manager->highestPriority = event.priority;
        manager->highestPriorityId = event.id;
    }
}

void removeOldEvents(EventManager* manager, HashTable* table) {
    time_t currentTime = time(NULL);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        if (manager->events[i].id != -1 && difftime(currentTime, manager->events[i].timestamp) > WINDOW_SIZE_SECONDS) {
            int index = hashFunction(manager->events[i].id, table->size);
            HashNode* current = table->buckets[index];
            HashNode* prev = NULL;
            while (current != NULL) {
                if (current->event.id == manager->events[i].id) {
                    if (prev == NULL) {
                        table->buckets[index] = current->next;
                    } else {
                        prev->next = current->next;
                    }
                    free(current);
                    break;
                }
                prev = current;
                current = current->next;
            }
            manager->events[i].id = -1; // Mark as removed
        }
    }
}

void findAndPrintLargestInteger(int* array, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

int main() {
    EventManager manager;
    for (int i = 0; i < MAX_EVENTS; ++i) {
        manager.events[i].id = -1; // Initialize all events as removed
    }

    HashTable table;
    initHashTable(&table, INITIAL_ARRAY_SIZE);

    int arraySize;
    printf("Enter the number of integers: ");
    scanf("%d", &arraySize);
    int* array = (int*)malloc(arraySize * sizeof(int));
    printf("Enter the integers:\n");
    for (int i = 0; i < arraySize; ++i) {
        scanf("%d", &array[i]);
    }

    findAndPrintLargestInteger(array, arraySize);
    free(array);

    return 0;
}
