#define MAX_LOG_FILES 5
#define LOG_FILE_SIZE_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int tag_id;
    void* data;
} Tag;

typedef struct {
    Tag rx_ue_info_tag;
    Tag rnti_tag;
    Tag crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_and_log(struct NFAPI_CRC_INDICATION_PDU_T** p, int budget, FILE* log_fd) {
    if (budget <= 0 || !p || !log_fd) {
        return -1; // Invalid input
    }

    *p = NULL;
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int count = budget / total_size;

    if (count == 0) {
        return -2; // Not enough budget for allocation
    }

    *p = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(count * total_size);
    if (!*p) {
        return -3; // Allocation failed
    }

    size_t log_file_size = 0;
    char log_filename[256];
    int log_count = 1;

    for (int i = 0; i < count; ++i) {
        (*p)[i].rx_ue_info_tag.tag_id = /* Set valid tag ID */;
        (*p)[i].rnti_tag.tag_id = /* Set valid RNTI */;
        (*p)[i].crc_ind_rel8_tag.tag_id = /* Set CRC_INDICATION_REL8_TAG */;
        (*p)[i].crc_ind_rel8_tag.data = malloc(sizeof(int));
        if (!(*p)[i].crc_ind_rel8_tag.data) {
            // Handle allocation failure gracefully
            for (int j = 0; j < i; ++j) {
                free((*p)[j].crc_ind_rel8_tag.data);
            }
            free(*p);
            *p = NULL;
            return -3; // Allocation failed
        }

        // Randomly set CRCFLAG
        int* crc_flag = (*p)[i].crc_ind_rel8_tag.data;
        *crc_flag = (rand() % 2) == 0 ? 1 : 0;

        // Log information
        snprintf(log_filename, sizeof(log_filename), "log_%d.txt", log_count);
        FILE* current_log_fd = fopen(log_filename, "a");
        if (!current_log_fd) {
            return -4; // Failed to open log file
        }

        fprintf(current_log_fd, "Tag IDs: RX_UE_INFO_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", 
                (*p)[i].rx_ue_info_tag.tag_id, (*p)[i].rnti_tag.tag_id, (*p)[i].crc_ind_rel8_tag.tag_id);
        fprintf(current_log_fd, "CRC Status: %s\n", *crc_flag == 1 ? "Detected" : "Not Detected");

        fclose(current_log_fd);

        log_file_size += sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(int);

        if (log_file_size >= LOG_FILE_SIZE_LIMIT) {
            // Rotate logs
            for (int j = MAX_LOG_FILES - 1; j > 0; --j) {
                snprintf(log_filename, sizeof(log_filename), "log_%d.txt", j);
                char next_log_filename[256];
                snprintf(next_log_filename, sizeof(next_log_filename), "log_%d.txt", j + 1);
                rename(log_filename, next_log_filename);
            }
            log_count = 1;
        } else {
            ++log_count;
        }
    }

    return count; // Number of successfully allocated structures
}
