#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_FILES 10

typedef struct {
    char SourceAddress[256];
    char DestinationAddress[256];
    unsigned char Payload[1024];
    unsigned short Checksum;
} NetworkPacket;

int calculateChecksum(NetworkPacket *packet) {
    // Simplified checksum calculation for demonstration
    int sum = 0;
    for (int i = 0; i < sizeof(packet->Payload); i++) {
        sum += packet->Payload[i];
    }
    return sum & 0xFFFF;
}

void logPacket(FILE **logFiles, int *currentFileIndex, NetworkPacket *packet) {
    // Log packet details to a file with rotation
    if (*currentFileIndex >= MAX_LOG_FILES) {
        fclose(logFiles[*currentFileIndex]);
        for (int i = 1; i < MAX_LOG_FILES; i++) {
            logFiles[i - 1] = logFiles[i];
        }
        *currentFileIndex--;
    }

    char fileName[50];
    snprintf(fileName, sizeof(fileName), "log%d.txt", *currentFileIndex + 1);
    if (*logFiles[*currentFileIndex] == NULL) {
        *logFiles[*currentFileIndex] = fopen(fileName, "w");
    }
    fprintf(*logFiles[*currentFileIndex], "Source: %s, Dest: %s, Payload: ..., Checksum: %u\n",
            packet->SourceAddress, packet->DestinationAddress, packet->Checksum);
    (*currentFileIndex)++;
}

NetworkPacket* allocatePackets(int budget, int *count, FILE **logFiles, int *currentFileIndex) {
    NetworkPacket *packets = NULL;
    while (budget > 0 && packets == NULL) {
        int packetSize = sizeof(NetworkPacket);
        if (budget >= packetSize) {
            // Attempt to allocate memory
            packets = malloc(packetSize);
            if (packets != NULL) {
                // Initialize and validate checksum
                strcpy(packets->SourceAddress, "192.168.1.1");
                strcpy(packets->DestinationAddress, "10.0.0.1");
                memset(packets->Payload, 0xFF, sizeof(packets->Payload));
                packets->Checksum = calculateChecksum(packets);
                if (packets->Checksum == 0) {
                    // Invalid checksum, retry allocation
                    free(packets);
                    packets = NULL;
                }
            } else {
                // Allocation failed, try calloc as a fallback
                packets = calloc(1, packetSize);
                if (packets != NULL) {
                    strcpy(packets->SourceAddress, "192.168.1.1");
                    strcpy(packets->DestinationAddress, "10.0.0.1");
                    memset(packets->Payload, 0xFF, sizeof(packets->Payload));
                    packets->Checksum = calculateChecksum(packets);
                    if (packets->Checksum == 0) {
                        free(packets);
                        packets = NULL;
                    }
                } else {
                    // Both allocation attempts failed, handle error
                    fprintf(stderr, "Memory allocation failed\n");
                    return NULL;
                }
            }
        } else {
            break;
        }
        budget -= packetSize;
        (*count)++;
        logPacket(logFiles, currentFileIndex, packets);
    }
    return packets;
}

int main() {
    int budget = 10240; // Example budget
    int count = 0;
    FILE *logFiles[MAX_LOG_FILES] = {NULL};
    int currentFileIndex = 0;

    NetworkPacket *packets = allocatePackets(budget, &count, logFiles, &currentFileIndex);

    if (packets != NULL) {
        printf("Allocated %d packets\n", count);
        // Free allocated memory
        free(packets);
    }

    for (int i = 0; i < currentFileIndex; i++) {
        if (logFiles[i] != NULL) {
            fclose(logFiles[i]);
        }
    }

    return 0;
}
