} TCP_SESSION_INFO_T;

typedef struct cache_entry {
    TCP_SESSION_INFO_T data;
    struct cache_entry* next;
    struct cache_entry* prev;
} CACHE_ENTRY_T;

typedef struct {
    CACHE_ENTRY_T** entries;
    int size;
    int capacity;
    pthread_mutex_t lock;
} TCP_CACHE_T;

TCP_CACHE_T* create_cache() {
    TCP_CACHE_T* cache = (TCP_CACHE_T*)malloc(sizeof(TCP_CACHE_T));
    cache->entries = (CACHE_ENTRY_T**)calloc(MAX_CACHE_SIZE, sizeof(CACHE_ENTRY_T*));
    cache->size = 0;
    cache->capacity = MAX_CACHE_SIZE;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(TCP_CACHE_T* cache) {
    for (int i = 0; i < cache->size; i++) {
        free(cache->entries[i]);
    }
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_session_info(TCP_CACHE_T* cache, TCP_SESSION_INFO_T* session_info) {
    pthread_mutex_lock(&cache->lock);
