        // Evict the least recently used entry
        CACHE_ENTRY_T* lru_entry = find_lru_entry(cache);
        free(lru_entry);
        cache->entries[lru_entry->data.session_id % MAX_CACHE_SIZE] = NULL;
        cache->size--;
