    new_entry->data = *session_info;
    new_entry->next = NULL;
    new_entry->prev = NULL;
    int index = session_info->session_id % MAX_CACHE_SIZE;
    if (cache->entries[index] != NULL) {
        cache->entries[index]->next = new_entry;
        new_entry->prev = cache->entries[index];
    }
    cache->entries[index] = new_entry;
    cache->size++;
    pthread_mutex_unlock(&cache->lock);
}

TCP_SESSION_INFO_T* get_session_info(TCP_CACHE_T* cache, int session_id) {
    pthread_mutex_lock(&cache->lock);
    TCP_SESSION_INFO_T* info = NULL;
    CACHE_ENTRY_T* entry = find_entry_by_session_id(cache, session_id);
    if (entry != NULL) {
        // Move the accessed entry to the front of the LRU list
        detach_entry(cache, entry);
        attach_to_front(cache, entry);
        info = &entry->data;
    }
    pthread_mutex_unlock(&cache->lock);
    return info;
}

void serialize_cache(TCP_CACHE_T* cache, const char* filename) {
    pthread_mutex_lock(&cache->lock);
    // Implement serialization logic here
    // Use file handling functions like fopen, fwrite, fclose to write data to disk
    pthread_mutex_unlock(&cache->lock);
}

void deserialize_cache(TCP_CACHE_T* cache, const char* filename) {
    pthread_mutex_lock(&cache->lock);
    // Implement deserialization logic here
    // Use file handling functions like fopen, fread, fclose to read data from disk
    pthread_mutex_unlock(&cache->lock);
}
