typedef struct {
    FILE *logFiles[MAX_LOG_FILES];
    time_t lastLogTime;
    int allocationCount[32]; // Assuming up to 32 days of logs
    int currentLogFileIndex;
} LoggingContext;

void rotateLogs(LoggingContext *context) {
    for (int i = context->currentLogFileIndex - 1; i >= 0; --i) {
        if (ftell(context->logFiles[i]) > LOG_SIZE_LIMIT) {
            fclose(context->logFiles[i]);
            time_t now = time(NULL);
            char filename[256];
            strftime(filename, sizeof(filename), "%Y-%m-%d_%H%M%S.log", localtime(&now));
            context->logFiles[i] = fopen(filename, "a");
        }
    }
}

void logAllocation(LoggingContext *context, NFAPI_CRC_INDICATION_PDU_T *allocation) {
    time_t now = time(NULL);
    if (now != context->lastLogTime) {
        context->currentLogFileIndex = 0;
        rotateLogs(context);
        fclose(context->logFiles[context->currentLogFileIndex]);
        time_t now = time(NULL);
        char filename[256];
        strftime(filename, sizeof(filename), "%Y-%m-%d_%H%M%S.log", localtime(&now));
        context->logFiles[context->currentLogFileIndex] = fopen(filename, "a");
        context->lastLogTime = now;
    }
    fprintf(context->logFiles[context->currentLogFileIndex], "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
            allocation->RX_UE_INFORMATION_TAG, allocation->RNTI, allocation->CRCFLAG);
}

NFAPI_CRC_INDICATION_PDU_T* allocateStructures(int N, int budget, LoggingContext *context) {
    if (N <= 0 || budget <= 0) return NULL;

    size_t structureSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t totalRequiredMemory = N * structureSize;
    if (totalRequiredMemory > budget) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* allocations = malloc(totalRequiredMemory);
    if (!allocations) return NULL;

    for (int i = 0; i < N; ++i) {
        allocations[i].RX_UE_INFORMATION_TAG = rand();
        allocations[i].RNTI = rand() % 1024;
        allocations[i].CRCFLAG = rand() % 2;
        logAllocation(context, &allocations[i]);
    }

    return allocations;
}

void initLoggingContext(LoggingContext *context) {
    context->lastLogTime = time(NULL);
    for (int i = 0; i < MAX_LOG_FILES; ++i) {
        char filename[256];
        strftime(filename, sizeof(filename), "%Y-%m-%d_%H%M%S.log", localtime(&context->lastLogTime));
        context->logFiles[i] = fopen(filename, "a");
    }
}

void freeLoggingContext(LoggingContext *context) {
