    pthread_mutex_lock(&list->mutex);
    DoublyLinkedListNode *current = list->head;
    while (current) {
        DoublyLinkedListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
