using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HighThroughputTransactionProcessor
{
    private readonly ConcurrentDictionary<string, TransactionWindow> _transactionWindows = new();
    private readonly ILogger _logger;
    private readonly IEncryptionService _encryptionService;

    public HighThroughputTransactionProcessor(ILogger logger, IEncryptionService encryptionService)
    {
        _logger = logger;
        _encryptionService = encryptionService;
    }

    public void ProcessTransactions(IEnumerable<Transaction> transactions)
    {
        var maxWeightedSum = 0.0;
        foreach (var transaction in transactions)
        {
            if (!_transactionWindows.TryGetValue(transaction.Id, out var window))
            {
                window = new TransactionWindow();
                _transactionWindows[transaction.Id] = window;
            }

            window.AddTransaction(transaction);
            var weightedSum = transaction.Amount * transaction.PriorityLevel;

            Interlocked.CompareExchange(ref maxWeightedSum, Math.Max(maxWeightedSum, weightedSum), 0);

            if (window.Count > 10)
            {
                _transactionWindows.TryRemove(transaction.Id, out _);
            }
        }

        _logger.Log($"Max Weighted Sum in Last 3 Seconds: {maxWeightedSum}");
    }
}

public class Transaction
{
    public string Id { get; set; }
    public double Amount { get; set; }
    public int PriorityLevel { get; set; }
}

public class TransactionWindow
{
    private readonly ConcurrentQueue<Transaction> _transactions = new();
    public int Count => _transactions.Count;

    public void AddTransaction(Transaction transaction)
    {
        _transactions.Enqueue(transaction);
    }

    public Transaction Dequeue()
    {
        return _transactions.Dequeue();
    }
}

public interface ILogger
{
    void Log(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}

public interface IEncryptionService
{
    byte[] Decrypt(byte[] encryptedData, string algorithmName, byte[] key, byte[] iv);
}

public class AesEncryptionService : IEncryptionService
{
    public byte[] Decrypt(byte[] encryptedData, string algorithmName, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create(algorithmName))
        {
            aes.Key = key;
            aes.IV = iv;
            using (var decryptor = aes.CreateDecryptor())
            {
                return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
            }
        }
    }
}
