typedef struct cache_entry {
    TCP_SESSION_INFO_T data;
    struct cache_entry *next, *prev;
} CACHE_ENTRY_T;

typedef struct {
    CACHE_ENTRY_T *entries[MAX_CACHE_SIZE];
    pthread_mutex_t lock;
    size_t size;
} SESSION_CACHE_T;

SESSION_CACHE_T session_cache = { .lock = PTHREAD_MUTEX_INITIALIZER };

void init_session_cache() {
    memset(session_cache.entries, 0, sizeof(session_cache.entries));
}

CACHE_ENTRY_T* get_or_create_entry(unsigned int session_id) {
    pthread_mutex_lock(&session_cache.lock);
    CACHE_ENTRY_T *entry = NULL;
    for (size_t i = 0; i < MAX_CACHE_SIZE && !entry; i++) {
        if (!session_cache.entries[i]) {
            entry = malloc(sizeof(CACHE_ENTRY_T));
            entry->data.session_id = session_id;
            strcpy(entry->data.client_ip, "127.0.0.1");
            strcpy(entry->data.server_ip, "127.0.0.1");
            entry->data.timestamp = time(NULL);
            entry->next = entry->prev = NULL;
            session_cache.entries[i] = entry;
        }
    }
    pthread_mutex_unlock(&session_cache.lock);
    return entry;
}

void cache_session_info(unsigned int session_id, const TCP_SESSION_INFO_T *info) {
    CACHE_ENTRY_T *entry = get_or_create_entry(session_id);
    if (entry) {
        memcpy(&entry->data, info, sizeof(TCP_SESSION_INFO_T));
    }
}

TCP_SESSION_INFO_T* fetch_session_info(unsigned int session_id) {
    pthread_mutex_lock(&session_cache.lock);
    CACHE_ENTRY_T *entry = NULL;
    for (size_t i = 0; i < MAX_CACHE_SIZE && !entry; i++) {
        if (session_cache.entries[i] && session_cache.entries[i]->data.session_id == session_id) {
            entry = session_cache.entries[i];
        }
    }
    pthread_mutex_unlock(&session_cache.lock);
    return entry ? &entry->data : NULL;
}

void evict_lru_entry() {
    // Implement LRU eviction logic here
}

void maintain_cache_size() {
    if (session_cache.size > MAX_CACHE_SIZE) {
        evict_lru_entry();
    }
