using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class FileProcessor
{
    private const int MaxUes = 10000;
    private static readonly Random random = new Random();
    private static readonly object lockObject = new object();

    public (string md5Checksum, NFAPI_CRC_INDICATION_PDU_T[] crcIndications) ProcessFileAndComputeChecksum(string filePath, string key, byte[] iv)
    {
        byte[] fileData;
        try
        {
            fileData = File.ReadAllBytes(filePath);
        }
        catch (Exception ex)
        {
            LogError($"Failed to read file: {ex.Message}");
            return (null, null);
        }

        byte[] decryptedData;
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = Encoding.UTF8.GetBytes(key);
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            using (MemoryStream msDecrypt = new MemoryStream(fileData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    decryptedData = csDecrypt.ToArray();
                }
            }
        }

        string md5Checksum = ComputeMd5Checksum(decryptedData);

        NFAPI_CRC_INDICATION_PDU_T[] crcIndications = GenerateCrcIndications(MaxUes);
        LogInfo($"Processed file: {filePath}, MD5 checksum: {md5Checksum}");

        return (md5Checksum, crcIndications);
    }

    private string ComputeMd5Checksum(byte[] data)
    {
        using (MD5 md5 = MD5.Create())
        {
