            return sb.ToString();
        }
    }

    private NFAPI_CRC_INDICATION_PDU_T[] GenerateCrcIndications(int count)
    {
        NFAPI_CRC_INDICATION_PDU_T[] crcIndications = new NFAPI_CRC_INDICATION_PDU_T[count];
        for (int i = 0; i < count; i++)
        {
            lock (lockObject)
            {
                int rnti;
                do
                {
                    rnti = random.Next(1, MaxUes + 1);
                } while (!IsRntiUnique(rnti, crcIndications));
