public class FileProcessorJava {
    private static final int MAX_UEs = 10000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public CompletableFuture<String> processFileAndComputeChecksum(String filePath, String key, byte[] iv) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                byte[] fileData = Files.readAllBytes(Paths.get(filePath));
                byte[] decryptedData = decryptFile(fileData, key, iv);
                String md5Checksum = computeMd5Checksum(decryptedData);
                NFAPI_CRC_INDICATION_PDU_T[] crcIndications = generateCrcIndications(MAX_UEs);
                return new FileProcessorResult(md5Checksum, crcIndications);
            } catch (IOException e) {
                System.err.println("Failed to read file: " + e.getMessage());
                return null;
            }
        }, executorService);
    }

    private byte[] decryptFile(byte[] data, String key, byte[] iv) throws IOException {
        try (Cipher cipher = Cipher.getInstance("DESede/CBC/PKCS5Padding")) {
            SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), "DESede");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivSpec);
            return cipher.doFinal(data);
        } catch (Exception e) {
            throw new IOException("Failed to decrypt file: " + e.getMessage());
        }
    }

    private String computeMd5Checksum(byte[] data) throws IOException {
        try (MessageDigest md = MessageDigest.getInstance("MD5")) {
            byte[] hashBytes = md.digest(data);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes)
                sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new IOException("Failed to compute MD5 checksum: " + e.getMessage());
        }
    }

