        for (int i = 0; i < count; i++) {
            int rnti;
            do {
                rnti = ThreadLocalRandom.current().nextInt(1, MAX_UEs + 1);
            } while (!isRntiUnique(rnti, crcIndications));
            crcIndications[i] = new NFAPI_CRC_INDICATION_PDU_T(rnti, ThreadLocalRandom.current().nextBoolean());
        }
        return crcIndications;
    }

    private boolean isRntiUnique(int rnti, NFAPI_CRC_INDICATION_PDU_T[] crcIndications) {
        for (int i = 0; i < crcIndications.length; i++) {
            if (crcIndications[i].rnti == rnti) return false;
        }
