    char CLIENT_IP[16];
    char SERVER_IP[16];
    time_t TIMESTAMP;
} TCP_SESSION_INFO_T;

typedef struct cache_entry {
    TCP_SESSION_INFO_T data;
    struct cache_entry *next, *prev;
} CACHE_ENTRY_T;

typedef struct {
    CACHE_ENTRY_T **table;
    int size;
    int count;
    pthread_mutex_t lock;
} CACHE_T;

CACHE_T *create_cache(int size) {
    CACHE_T *cache = malloc(sizeof(CACHE_T));
    cache->table = calloc(size, sizeof(CACHE_ENTRY_T *));
    cache->size = size;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(CACHE_T *cache) {
    for (int i = 0; i < cache->size; ++i) {
        CACHE_ENTRY_T *entry = cache->table[i];
        while (entry != NULL) {
            CACHE_ENTRY_T *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache->table);
    free(cache);
}

void add_to_cache(CACHE_T *cache, TCP_SESSION_INFO_T *data) {
    pthread_mutex_lock(&cache->lock);
    // Add implementation here
    pthread_mutex_unlock(&cache->lock);
}

TCP_SESSION_INFO_T *get_from_cache(CACHE_T *cache, int session_id) {
    pthread_mutex_lock(&cache->lock);
    // Get implementation here
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void evict_lru(CACHE_T *cache) {
    pthread_mutex_lock(&cache->lock);
    // Evict LRU implementation here
    pthread_mutex_unlock(&cache->lock);
}

