    TCP_SESSION_INFO_T session;
    session.SESSION_ID = 12345;
    strcpy(session.CLIENT_IP, "192.168.1.1");
    strcpy(session.SERVER_IP, "172.16.1.1");
    time(&session.TIMESTAMP);

    add_to_cache(cache, &session);
    TCP_SESSION_INFO_T *retrieved = get_from_cache(cache, 12345);

    if (retrieved != NULL) {
        printf("Session ID: %d\n", retrieved->SESSION_ID);
        printf("Client IP: %s\n", retrieved->CLIENT_IP);
        printf("Server IP: %s\n", retrieved->SERVER_IP);
        printf("Timestamp: %ld\n", retrieved->TIMESTAMP);
    }

    destroy_cache(cache);

