#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t memory_usage;
    size_t current_size;
    pthread_mutex_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->memory_usage = 0;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->current_size < MAX_LIST_SIZE && list->memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= MEMORY_LIMIT) {
        if (list->head == NULL) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            list->tail->next = new_node;
            list->tail = new_node;
        }
        list->memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        list->current_size++;
    } else {
        free(new_node); // Free the allocated memory if conditions are not met
    }
    pthread_mutex_unlock(&list->lock);
}

void collect_garbage(List* list) {
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        pthread_mutex_lock(&list->lock);
        if (list->memory_usage > MEMORY_LIMIT && current != list->tail) {
            list->memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            list->current_size--;
            Node* temp = current;
            current = current->next;
            if (prev == NULL) {
                list->head = current;
            } else {
                prev->next = current;
            }
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
        pthread_mutex_unlock(&list->lock);
    }
}

void cleanup_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}
