#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 100
#define BATCH_SIZE 1000
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_SUMMARY 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    sem_t elements_available;
    int log_level;
} DynamicList;

void dynamic_list_init(DynamicList *list, int initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->elements_available, 0, 0);
}

void dynamic_list_add(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    // Populate the new structure with random data
    NFAPI_CRC_INDICATION_PDU_T new_item = {rand(), rand() % 65536, (rand() & 1) != 0};
    list->data[list->size++] = new_item;
    sem_post(&list->elements_available);
    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_process_batch(DynamicList *list) {
    int count = 0;
    while (count < BATCH_SIZE && sem_wait(&list->elements_available) == 0) {
        NFAPI_CRC_INDICATION_PDU_T item = list->data[--list->size];
        // Process the item
        count++;
    }
}

void dynamic_list_clear(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
    sem_destroy(&list->elements_available);
    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_set_log_level(DynamicList *list, int level) {
    pthread_mutex_lock(&list->lock);
    list->log_level = level;
    pthread_mutex_unlock(&list->lock);
}
