    char CLIENT_IP[16];
    char SERVER_IP[16];
    time_t TIMESTAMP;
} TCP_SESSION_INFO_T;

typedef struct cache_entry {
    TCP_SESSION_INFO_T data;
    struct cache_entry *next, *prev;
} CACHE_ENTRY_T;

typedef struct {
    size_t max_size;
    double eviction_threshold;
    size_t current_size;
    CACHE_ENTRY_T **cache_array;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} LRU_CACHE_T;

LRU_CACHE_T* create_cache(size_t max_size, double eviction_threshold) {
    LRU_CACHE_T *cache = (LRU_CACHE_T*) malloc(sizeof(LRU_CACHE_T));
    cache->max_size = max_size;
    cache->eviction_threshold = eviction_threshold;
    cache->current_size = 0;
    cache->cache_array = (CACHE_ENTRY_T**) malloc(max_size * sizeof(CACHE_ENTRY_T*));
    for (size_t i = 0; i < max_size; i++) {
        cache->cache_array[i] = NULL;
    }
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond, NULL);
    return cache;
}

void destroy_cache(LRU_CACHE_T *cache) {
    for (size_t i = 0; i < cache->max_size; i++) {
        CACHE_ENTRY_T *entry = cache->cache_array[i];
        while (entry != NULL) {
            CACHE_ENTRY_T *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->cond);
    free(cache->cache_array);
    free(cache);
}

