void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        list->data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity = new_capacity;
    }
    list->data[list->size++] = element;
    pthread_mutex_unlock(&list->mutex);
}

void clear_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
