#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 100

typedef struct UEIdentifier {
    char id[50];
} UEIdentifier;

typedef struct CellIdentity {
    char id[20];
} CellIdentity;

typedef struct SignalStrength {
    int value;
} SignalStrength;

typedef struct NetworkEntityStatus {
    UEIdentifier ueId;
    CellIdentity cellId;
    SignalStrength signalStrength;
    struct NetworkEntityStatus* prev;
    struct NetworkEntityStatus* next;
} NetworkEntityStatus;

typedef struct {
    NetworkEntityStatus* head;
    NetworkEntityStatus* tail;
    int size;
    float averageSignalStrength;
} DoublyLinkedList;

void initializeList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->averageSignalStrength = 0.0;
}

NetworkEntityStatus* createNode(UEIdentifier ueId, CellIdentity cellId, SignalStrength signalStrength) {
    NetworkEntityStatus* newNode = (NetworkEntityStatus*)malloc(sizeof(NetworkEntityStatus));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strcpy(newNode->ueId.id, ueId.id);
    strcpy(newNode->cellId.id, cellId.id);
    newNode->signalStrength.value = signalStrength.value;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void addEntry(DoublyLinkedList* list, UEIdentifier ueId, CellIdentity cellId, SignalStrength signalStrength) {
    NetworkEntityStatus* newNode = createNode(ueId, cellId, signalStrength);
    if (list->size < MAX_ENTRIES) {
        if (list->head == NULL) {
            list->head = newNode;
            list->tail = newNode;
        } else {
            list->tail->next = newNode;
            newNode->prev = list->tail;
            list->tail = newNode;
        }
        list->size++;
    } else {
        printf("List is full, cannot add more entries\n");
    }
}

void updateSignalStrength(DoublyLinkedList* list, UEIdentifier ueId, SignalStrength newSignalStrength) {
    NetworkEntityStatus* current = list->head;
    while (current != NULL) {
        if (strcmp(current->ueId.id, ueId.id) == 0) {
            current->signalStrength.value = newSignalStrength.value;
            return;
        }
        current = current->next;
    }
    printf("UEIdentifier not found\n");
}

void deleteEntry(DoublyLinkedList* list, UEIdentifier ueId) {
    NetworkEntityStatus* current = list->head;
    while (current != NULL) {
        if (strcmp(current->ueId.id, ueId.id) == 0) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->size--;
            return;
        }
        current = current->next;
    }
    printf("UEIdentifier not found\n");
}

int exists(DoublyLinkedList* list, UEIdentifier ueId) {
    NetworkEntityStatus* current = list->head;
    while (current != NULL) {
        if (strcmp(current->ueId.id, ueId.id) == 0) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void printList(DoublyLinkedList* list) {
    NetworkEntityStatus* current = list->head;
    while (current != NULL) {
        printf("UEID: %s, CellID: %s, SignalStrength: %d\n", current->ueId.id, current->cellId.id, current->signalStrength.value);
        current = current->next;
    }
}

void sortList(DoublyLinkedList* list) {
    // Implement sorting algorithm here
}

int main() {
    DoublyLinkedList list;
    initializeList(&list);

    UEIdentifier ue1 = {"UE001", ""};
    CellIdentity cell1 = {"Cell001", ""};
    SignalStrength signal1 = {50};

    addEntry(&list, ue1, cell1, signal1);
    printList(&list);

    updateSignalStrength(&list, ue1, (SignalStrength){60});
    printList(&list);

    deleteEntry(&list, ue1);
    printList(&list);

    return 0;
}
