    if (records == NULL) {
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].key = i;
        records[i].offset = i * 100L;
    }
    return records;
}

void free_records(Record* records, int num_records) {
    if (records != NULL) {
        free(records);
    }
}
