using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecryptionManager
{
    private readonly List<DESedeKey> _keys = new List<DESedeKey>();
    private int _currentKeyIndex = 0;
    private Timer _keyRotationTimer;
    private string _logFilePath = "decryption_log.txt";

    public TripleDESDecryptionManager(List<string> base64Keys, TimeSpan rotationInterval)
    {
        foreach (var key in base64Keys)
        {
            _keys.Add(new DESedeKey(Convert.FromBase64String(key)));
        }

        if (_keys.Count > 0)
        {
            _keyRotationTimer = new Timer(RotateKey, null, rotationInterval, TimeSpan.Zero);
        }
    }

    public string DecryptMessage(string base64EncodedMessage)
    {
        var key = _keys[_currentKeyIndex];
        try
        {
            var decryptedBytes = TripleDESDecrypt(Convert.FromBase64String(base64EncodedMessage), key.Key);
            LogDecryptionSuccess(base64EncodedMessage);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            LogDecryptionFailure(base64EncodedMessage, ex);
            throw;
        }
    }

    private byte[] TripleDESDecrypt(byte[] encryptedData, byte[] key)
    {
        using (var des = new TripleDESCryptoServiceProvider { Key = key, Mode = CipherMode.ECB })
        {
            var decryptor = des.CreateDecryptor();
            return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
        }
    }

    private void RotateKey(object state)
    {
        _currentKeyIndex = (_currentKeyIndex + 1) % _keys.Count;
    }

    private void LogDecryptionSuccess(string base64EncodedMessage)
    {
        LogToFile($"{DateTime.Now}: Decryption successful for message {base64EncodedMessage}");
    }

    private void LogDecryptionFailure(string base64EncodedMessage, Exception ex)
    {
        LogToFile($"{DateTime.Now}: Decryption failed for message {base64EncodedMessage} - Error: {ex.Message}");
    }

    private void LogToFile(string logEntry)
    {
        try
        {
            File.AppendAllText(_logFilePath, logEntry + Environment.NewLine);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to write log entry: {ex.Message}");
        }
    }
}

public class DESedeKey
{
    public byte[] Key { get; }

    public DESedeKey(byte[] key)
    {
        if (key.Length != 24)
        {
            throw new ArgumentException("DES3 key must be exactly 24 bytes long.");
        }
        Key = key;
    }
}
```

