#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FILES 1000

typedef struct {
    char path[256];
    int status;
    time_t last_activity;
    pthread_mutex_t lock;
} FileDescriptor;

FileDescriptor fd_pool[MAX_FILES];

void init_fd_pool() {
    for (int i = 0; i < MAX_FILES; i++) {
        memset(&fd_pool[i], 0, sizeof(FileDescriptor));
        pthread_mutex_init(&fd_pool[i].lock, NULL);
    }
}

int get_next_available_fd() {
    for (int i = 0; i < MAX_FILES; i++) {
        if (pthread_mutex_trylock(&fd_pool[i].lock) == 0) {
            fd_pool[i].last_activity = time(NULL);
            return i;
        }
    }
    return -1;
}

void free_fd(int fd) {
    pthread_mutex_unlock(&fd_pool[fd].lock);
}

int open_file(const char *path, int priority) {
    if (priority > 0 && priority <= MAX_FILES) {
        for (int i = 0; i < priority - 1; i++) {
            free_fd(i);
        }
    }

    int fd = get_next_available_fd();
    if (fd != -1) {
        strcpy(fd_pool[fd].path, path);
        fd_pool[fd].status = 1;
        pthread_mutex_unlock(&fd_pool[fd].lock);
    }
    return fd;
}

void close_file(int fd) {
    if (fd >= 0 && fd < MAX_FILES) {
        fd_pool[fd].status = 0;
        free_fd(fd);
    }
}

void process_files() {
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_mutex_lock(&fd_pool[i].lock);
        if (fd_pool[i].status == 1) {
            // Perform file processing
            printf("Processing file: %s\n", fd_pool[i].path);
            fd_pool[i].last_activity = time(NULL);
        }
        pthread_mutex_unlock(&fd_pool[i].lock);
    }
}
