typedef struct {
    time_t LAST_SEEN_TIMESTAMP;
    int CURRENTLY_ACTIVE_FLAG;
    double TOTAL_DATA_SENT_MB;
    int LAST_ERROR_CODE;
} NETWORK_CONNECTION_STATS_T;

typedef struct {
    NETWORK_CONNECTION_STATS_T *connections;
    size_t capacity;
    size_t count;
    size_t active_connection_count;
    pthread_mutex_t lock;
} NETWORK_CONNECTION_MANAGER_T;

NETWORK_CONNECTION_MANAGER_T *network_connection_manager_create() {
    NETWORK_CONNECTION_MANAGER_T *manager = (NETWORK_CONNECTION_MANAGER_T *)malloc(sizeof(NETWORK_CONNECTION_MANAGER_T));
    if (!manager) {
        perror("Failed to allocate memory for network connection manager");
        return NULL;
    }
    manager->connections = (NETWORK_CONNECTION_STATS_T *)malloc(CHUNK_SIZE * NETWORK_CONNECTION_STATS_T_SIZE);
    if (!manager->connections) {
        perror("Failed to allocate initial chunk of connections");
        free(manager);
        return NULL;
    }
    manager->capacity = CHUNK_SIZE;
    manager->count = 0;
    manager->active_connection_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void network_connection_manager_add(NETWORK_CONNECTION_MANAGER_T *manager, NETWORK_CONNECTION_STATS_T *stats) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        NETWORK_CONNECTION_STATS_T *new_connections = (NETWORK_CONNECTION_STATS_T *)realloc(manager->connections, (manager->capacity + CHUNK_SIZE) * NETWORK_CONNECTION_STATS_T_SIZE);
        if (!new_connections) {
            perror("Failed to reallocate memory for connections");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->connections = new_connections;
        manager->capacity += CHUNK_SIZE;
    }
    memcpy(&manager->connections[manager->count], stats, NETWORK_CONNECTION_STATS_T_SIZE);
    if (stats->CURRENTLY_ACTIVE_FLAG) {
        manager->active_connection_count++;
        manager->active_connection_count %= 2147483647; // Assuming a limit of 2^31 - 1 active connections
    }
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

