#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_HOSTNAMES 100
#define MAX_IP_LENGTH INET6_ADDRSTRLEN
#define MAX_METADATA 256

typedef struct {
    char ip[MAX_IP_LENGTH];
    char hostname[NI_MAXHOST];
    char metadata[MAX_METADATA];
} DNSResult;

typedef struct {
    DNSResult *results;
    int count;
} DNSQueryResults;

typedef struct {
    pthread_mutex_t mutex;
    int max_concurrent_queries;
    int current_queries;
    pthread_cond_t cond_var;
} DNSQueryManager;

DNSQueryManager query_manager;

void init_dns_query_manager(int max_concurrent_queries) {
    query_manager.max_concurrent_queries = max_concurrent_queries;
    query_manager.current_queries = 0;
    pthread_mutex_init(&query_manager.mutex, NULL);
    pthread_cond_init(&query_manager.cond_var, NULL);
}

int acquire_dns_query_slot() {
    pthread_mutex_lock(&query_manager.mutex);
    while (query_manager.current_queries >= query_manager.max_concurrent_queries) {
        pthread_cond_wait(&query_manager.cond_var, &query_manager.mutex);
    }
    query_manager.current_queries++;
    pthread_mutex_unlock(&query_manager.mutex);
    return 0;
}

void release_dns_query_slot() {
    pthread_mutex_lock(&query_manager.mutex);
    query_manager.current_queries--;
    pthread_cond_signal(&query_manager.cond_var);
    pthread_mutex_unlock(&query_manager.mutex);
}

int resolve_hostname(const char *hostname, DNSResult *result) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr *sa = res->ai_addr;
    char ip[MAX_IP_LENGTH];

    if (sa->sa_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)sa;
        inet_ntop(AF_INET, &ipv4->sin_addr, ip, sizeof(ip));
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)sa;
        inet_ntop(AF_INET6, &ipv6->sin6_addr, ip, sizeof(ip));
    }

    strncpy(result->ip, ip, MAX_IP_LENGTH);
    strncpy(result->hostname, hostname, NI_MAXHOST);

    freeaddrinfo(res);
    return 0;
}

void *dns_query_thread(void *arg) {
    char **hostnames = (char **)arg;
    DNSQueryResults *results = malloc(sizeof(DNSQueryResults));
    results->count = 0;

    for (int i = 0; hostnames[i] != NULL; i++) {
        if (acquire_dns_query_slot() == -1) {
            fprintf(stderr, "Failed to acquire DNS query slot\n");
            free(results);
            return NULL;
        }

        DNSResult result;
        if (resolve_hostname(hostnames[i], &result) == 0) {
            results->results = realloc(results->results, (results->count + 1) * sizeof(DNSResult));
            memcpy(&results->results[results->count], &result, sizeof(DNSResult));
            results->count++;
        }

        release_dns_query_slot();
    }

    *(DNSQueryResults **)arg = results;
    return NULL;
}

int resolve_hostnames(char **hostnames, DNSQueryResults *results) {
    int num_threads = 0;
    for (char **h = hostnames; *h != NULL; h++) {
        num_threads++;
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, dns_query_thread, &hostnames) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return -1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], (void **)&results->results) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            free(results->results);
            return -1;
        }
    }

    results->count = 0;
    for (int i = 0; hostnames[i] != NULL; i++) {
        results->count += ((DNSQueryResults *)hostnames[i])->count;
    }

    results->results = realloc(results->results, results->count * sizeof(DNSResult));
    int index = 0;
    for (int i = 0; hostnames[i] != NULL; i++) {
        DNSQueryResults *query_results = (DNSQueryResults *)hostnames[i];
        memcpy(&results->results[index], query_results->results, query_results->count * sizeof(DNSResult));
        index += query_results->count;
        free(query_results->results);
        free(query_results);
    }

    return 0;
}

int main() {
    init_dns_query_manager(5);

    char *hostnames[] = {"google.com", "example.com", NULL};
    DNSQueryResults results;

    if (resolve_hostnames(hostnames, &results) == 0) {
        printf("Resolved %d hostnames\n", results.count);
        for (int i = 0; i < results.count; i++) {
            printf("IP: %s, Hostname: %s, Metadata: %s\n",
                   results.results[i].ip,
                   results.results[i].hostname,
                   results.results[i].metadata);
        }
    } else {
        fprintf(stderr, "Failed to resolve hostnames\n");
    }

    free(results.results);
    return 0;
}
```

This code provides a basic implementation of a DNS resolver function in C that supports asynchronous resolution using threads. It includes mechanisms for limiting resource consumption, handling errors, and managing concurrent queries. The `resolve_hostnames` function demonstrates how to use the `dns_query_thread` worker functions to perform DNS resolution for multiple hostnames concurrently.

Please note that this code is a simplified example and may need to be adapted and extended based on specific requirements and constraints of your project.']

