void init_session_list(SessionList* list, size_t initial_capacity, void (*alloc_func)(void**, size_t, size_t)) {
    list->sessions = NULL;
    list->capacity = 0;
    list->size = 0;
    list->allocator = alloc_func;
    resize_session_list(list, initial_capacity);
}

void resize_session_list(SessionList* list, size_t new_capacity) {
    if (new_capacity == 0) return;

    UserSession* new_sessions = NULL;
    list->allocator((void**)&new_sessions, new_capacity * sizeof(UserSession), list->size);

    if (!new_sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    memcpy(new_sessions, list->sessions, list->size * sizeof(UserSession));
    free(list->sessions);
    list->sessions = new_sessions;
    list->capacity = new_capacity;
}

void add_user_session(SessionList* list, UserSession session) {
    if (list->size >= list->capacity) {
        resize_session_list(list, list->capacity == 0 ? 1 : list->capacity * 2);
    }
    list->sessions[list->size++] = session;
}

