using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class DynamicRangeValueGenerator
{
    private readonly ConcurrentDictionary<string, (int min, int max, Random random)> _ranges;
    private readonly Random _globalRandom;

    public DynamicRangeValueGenerator()
    {
        _ranges = new ConcurrentDictionary<string, (int min, int max, Random random)>();
        _globalRandom = new Random();
    }

    public void AddRange(string name, int min, int max)
    {
        if (_ranges.Any(r => r.Value.min >= min && r.Value.max <= max))
            throw new ArgumentException("Range overlaps with existing ranges.");

        var random = new Random(_globalRandom.Next());
        _ranges.TryAdd(name, (min, max, random));
    }

    public void RemoveRange(string name)
    {
        _ranges.TryRemove(name, out _);
    }

    public double GenerateRandomDouble(string rangeName, bool inclusive = false)
    {
        if (!_ranges.TryGetValue(rangeName, out var range))
            throw new ArgumentException("Range not found.");

        double min = inclusive ? range.min : (double)range.min + 0.5;
        double max = inclusive ? (double)range.max - 0.5 : range.max;

        return min + (max - min) * range.random.NextDouble();
    }

    public int GenerateRandomInt(string rangeName, bool inclusive = false)
    {
        if (!_ranges.TryGetValue(rangeName, out var range))
            throw new ArgumentException("Range not found.");

        int min = inclusive ? range.min : range.min + 1;
        int max = inclusive ? range.max - 1 : range.max;

        return range.random.Next(min, max + 1);
    }

    public void PopulateNFAPIArray(ref NFAPI_CRC_INDICATION_PDU_T[] array, string rangeName)
    {
        if (!_ranges.TryGetValue(rangeName, out var range))
            throw new ArgumentException("Range not found.");

        Parallel.For(0, array.Length, i =>
        {
            array[i].RX_UE_INFORMATION_TAG = GenerateRandomInt(rangeName);
            array[i].RNTI = GenerateRandomInt(rangeName);
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (uint)GenerateRandomDouble(rangeName, true);
        });
    }

    public override string ToString()
    {
        return string.Join(", ", _ranges.Select(r => $"{r.Key}: {r.Value.min}-{r.Value.max}"));
    }
}

[StructLayout(LayoutKind.Sequential)]
public struct NFAPI_CRC_INDICATION_PDU_T
{
    public uint RX_UE_INFORMATION_TAG;
    public uint RNTI;
    public CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
}

[StructLayout(LayoutKind.Explicit)]
public struct CRC_INDICATION_REL8_TAG
{
    [FieldOffset(0)] public uint CRCFLAG;
}
