#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "job_queue.h"
#include "message_broker.h"
#include "logging_library.h"

#define MAX_CONSUMERS 100

typedef struct {
    JobRequest **requests;
    int size;
    int capacity;
    pthread_mutex_t lock;
} JobQueue;

JobQueue *initialize_job_queue() {
    JobQueue *queue = (JobQueue *)malloc(sizeof(JobQueue));
    queue->requests = (JobRequest **)malloc(MAX_CONSUMERS * sizeof(JobRequest *));
    queue->size = 0;
    queue->capacity = MAX_CONSUMERS;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_job(JobQueue *queue, JobRequest *request) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) {
        queue->requests = realloc(queue->requests, 2 * queue->capacity * sizeof(JobRequest *));
        queue->capacity *= 2;
    }
    queue->requests[queue->size++] = request;
    pthread_mutex_unlock(&queue->lock);
}

JobRequest *dequeue_job(JobQueue *queue) {
    JobRequest *request = NULL;
    pthread_mutex_lock(&queue->lock);
    if (queue->size > 0) {
        request = queue->requests[--queue->size];
    }
    pthread_mutex_unlock(&queue->lock);
    return request;
}

void destroy_job_queue(JobQueue *queue) {
    for (int i = 0; i < queue->size; i++) {
        free(queue->requests[i]);
    }
    free(queue->requests);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
