class MessageQueue {
private:
    struct Message {
        int priority;
        std::string id;
        // other fields...
    };

    std::priority_queue<Message> queue;
    std::unordered_map<std::string, Message> recentMessages;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void enqueue(int priority, const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (recentMessages.find(id) == recentMessages.end() || priority > recentMessages[id].priority) {
            Message msg = {priority, id};
            queue.push(msg);
            recentMessages[id] = msg;
        }
        cv.notify_one();
    }

    void dequeue() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !queue.empty(); });
        queue.pop();
    }

    // other methods...
};
