#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryNode* next;
} MemoryNode;

MemoryNode* pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int allocated_count = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&pool_lock);
    if (allocated_count < MAX_STRUCTS) {
        MemoryNode* node = pool;
        if (node != NULL) {
            pool = node->next;
            memset(&node->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            allocated_count++;
            pthread_mutex_unlock(&pool_lock);
            return &node->data;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Fallback mechanism: Return NULL when pool is exhausted
}

void free_structure(NFAPI_CRC_INDICATION_PDU_T* ptr) {
    MemoryNode* node = (MemoryNode*)ptr - 1;
    pthread_mutex_lock(&pool_lock);
    if (allocated_count > 0 && allocated_count < MAX_STRUCTS) {
        node->next = pool;
        pool = node;
        allocated_count--;
    }
    pthread_mutex_unlock(&pool_lock);
}

void initialize_pool() {
    for (int i = 0; i < MAX_STRUCTS; i++) {
        MemoryNode* new_node = (MemoryNode*)malloc(sizeof(MemoryNode));
        if (new_node != NULL) {
            new_node->next = pool;
            pool = new_node;
        }
    }
}

void finalize_pool() {
    while (pool != NULL) {
        MemoryNode* next = pool->next;
        free(pool);
        pool = next;
    }
}

// Example usage
int main() {
    initialize_pool();

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_structure();
    if (pdu != NULL) {
        // Use the structure here
        free_structure(pdu);
    }

    finalize_pool();
    return 0;
}
```

This code provides a basic framework for managing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures using a memory pool and thread synchronization. It includes functions to allocate, free, initialize, and finalize the memory pool. The allocation function (`allocate_structure`) uses a mutex to ensure thread safety, while the free function returns nodes back to the pool. The `initialize_pool` function pre-allocates all memory for efficiency, and the `finalize_pool` function cleans up resources when no longer needed. This approach minimizes memory fragmentation and overhead associated with dynamic memory allocation, making it suitable for high-throughput systems that require concurrent access from multiple threads.']

