} ScalableList;

void initScalableList(ScalableList *list, int initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroyScalableList(ScalableList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

int addElement(ScalableList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->data) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }
    list->data[list->size++] = element;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int getElement(ScalableList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    while (list->size == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    *element = list->data[--list->size];
    pthread_mutex_unlock(&list->lock);
    return 0;
}

