// Define JobRequest structure
typedef struct {
    int id;
    char *data;
    // Add other fields as needed
} JobRequest;

// Define QueueNode structure for the distributed queue
typedef struct QueueNode {
    JobRequest job;
    struct QueueNode *next;
} QueueNode;

// Define DistributedQueue structure
typedef struct {
    QueueNode *head, *tail;
    pthread_mutex_t mutex;
    // Add other fields as needed
} DistributedQueue;

// Initialize the distributed queue
void initDistributedQueue(DistributedQueue *queue) {
    queue->head = queue->tail = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
}

// Enqueue a job request to the distributed queue
void enqueueJobRequest(DistributedQueue *queue, JobRequest job) {
    QueueNode *newNode = (QueueNode *)malloc(sizeof(QueueNode));
    newNode->job = job;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->tail == NULL) {
        queue->head = queue->tail = newNode;
    } else {
        queue->tail->next = newNode;
        queue->tail = newNode;
    }
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue a job request from the distributed queue
JobRequest dequeueJobRequest(DistributedQueue *queue) {
    JobRequest result;
    pthread_mutex_lock(&queue->mutex);
    if (queue->head == NULL) {
        // Handle empty queue scenario
        result.id = -1;
        result.data = NULL;
    } else {
        QueueNode *temp = queue->head;
        result = temp->job;
        queue->head = queue->head->next;
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
        free(temp);
    }
    pthread_mutex_unlock(&queue->mutex);
    return result;
}

