#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_SESSIONS 1000
#define SESSION_ID_SIZE 32
#define IP_ADDRESS_SIZE 46

typedef struct TCP_SESSION_INFO_T {
    char session_id[SESSION_ID_SIZE];
    char client_ip[IP_ADDRESS_SIZE];
    char server_ip[IP_ADDRESS_SIZE];
    time_t timestamp;
    int session_state; // Active, Inactive, Terminated
} TCP_SESSION_INFO;

typedef struct CacheEntry {
    TCP_SESSION_INFO *session_info;
    struct CacheEntry *next;
    struct CacheEntry *prev;
    int frequency;
} CacheEntry;

typedef struct LRUCache {
    CacheEntry **cache;
    CacheEntry *head;
    CacheEntry *tail;
    int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* create_cache(int max_size) {
    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->cache = (CacheEntry**)calloc(max_size, sizeof(CacheEntry*));
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void delete_cache(LRUCache *cache) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        CacheEntry *entry = cache->cache[i];
        if (entry != NULL) {
            free(entry->session_info);
            free(entry);
        }
    }
    free(cache->cache);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_cache(LRUCache *cache, TCP_SESSION_INFO *session_info) {
    pthread_mutex_lock(&cache->lock);
    CacheEntry *entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->session_info = session_info;
    entry->next = NULL;
    entry->prev = cache->tail;
    if (cache->tail != NULL)
        cache->tail->next = entry;
    cache->tail = entry;
    if (cache->head == NULL)
        cache->head = entry;
    entry->frequency = 0;

    // Evict least recently used item
    if (cache->size >= MAX_SESSIONS) {
        CacheEntry *to_evict = cache->head;
        cache->head = to_evict->next;
        if (to_evict->next != NULL)
            to_evict->next->prev = NULL;
        free(to_evict->session_info);
        free(to_evict);
    } else {
        cache->size++;
    }

    pthread_mutex_unlock(&cache->lock);
}

TCP_SESSION_INFO* get_cache(LRUCache *cache, const char *session_id) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        CacheEntry *entry = cache->cache[i];
        if (entry != NULL && strcmp(entry->session_info->session_id, session_id) == 0) {
            entry->frequency++;
            // Move to the end to mark it as recently used
            if (entry != cache->tail) {
                if (entry->prev != NULL)
                    entry->prev->next = entry->next;
                if (entry->next != NULL)
                    entry->next->prev = entry->prev;
                entry->prev = cache->tail;
                cache->tail->next = entry;
                cache->tail = entry;
            }
            pthread_mutex_unlock(&cache->lock);
            return entry->session_info;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void delete_cache_item(LRUCache *cache, const char *session_id) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        CacheEntry *entry = cache->cache[i];
        if (entry != NULL && strcmp(entry->session_info->session_id, session_id) == 0) {
            if (entry->prev != NULL)
                entry->prev->next = entry->next;
            if (entry->next != NULL)
                entry->next->prev = entry->prev;
            if (cache->head == entry)
                cache->head = entry->next;
            if (cache->tail == entry)
                cache->tail = entry->prev;
            free(entry->session_info);
            free(entry);
            cache->size--;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Additional functions for serialization, deserialization, monitoring, logging, etc.
